const RULE_ID_PREFIXES: &[&str] = &["codex.", "claude_code.", "gemini.", "wezterm."];
const SUBMIT_PROFILE_FIXTURE_STATES: &[&str] = &[
    "composer_nonempty",
    "composer_cleared",
    "working_state",
    "queued_behind_operation",
    "crash_to_shell",
];

fn collect_fixture_rule_ids(
    dir: &Path,
    rules_with_fixtures: &mut HashSet<String>,
    total_fixtures: &mut usize,
) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect_fixture_rule_ids(&path, rules_with_fixtures, total_fixtures);
        } else if path.extension().is_some_and(|ext| ext == "json")
            && path.to_string_lossy().contains(".expect.")
        {
            *total_fixtures += 1;
            if let Ok(content) = std::fs::read_to_string(&path) {
                if let Ok(val) = serde_json::from_str::<serde_json::Value>(&content) {
                    if let Some(arr) = val.as_array() {
                        for item in arr {
                            if let Some(rule_id) =
                                item.get("rule_id").and_then(serde_json::Value::as_str)
                            {
                                rules_with_fixtures.insert(rule_id.to_string());
                            }
                        }
                    }
                }
            }
        }
    }
}

fn collect_submit_profile_fixture_ids(
    dir: &Path,
    profile_fixture_states: &mut HashMap<String, BTreeSet<String>>,
    total_fixtures: &mut usize,
) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect_submit_profile_fixture_ids(&path, profile_fixture_states, total_fixtures);
        } else if path.extension().is_some_and(|ext| ext == "json")
            && path.to_string_lossy().contains(".submit-profile.")
        {
            *total_fixtures += 1;
            if let Ok(content) = std::fs::read_to_string(&path) {
                if let Ok(val) = serde_json::from_str::<serde_json::Value>(&content) {
                    let Some(profile_id) = val
                        .get("profile_id")
                        .and_then(serde_json::Value::as_str)
                        .map(str::to_string)
                    else {
                        continue;
                    };
                    let covered = val
                        .get("covered_states")
                        .and_then(serde_json::Value::as_array)
                        .into_iter()
                        .flatten()
                        .filter_map(serde_json::Value::as_str)
                        .map(str::to_string)
                        .collect::<BTreeSet<_>>();
                    profile_fixture_states
                        .entry(profile_id)
                        .or_default()
                        .extend(covered);
                }
            }
        }
    }
}

#[derive(Debug)]
