fn approval_actor_kind(actor_kind: &str) -> frankenterm_core::policy::ActorKind {
    match actor_kind {
        "robot" => frankenterm_core::policy::ActorKind::Robot,
        "mcp" => frankenterm_core::policy::ActorKind::Mcp,
        "workflow" => frankenterm_core::policy::ActorKind::Workflow,
        _ => frankenterm_core::policy::ActorKind::Human,
    }
}

fn audit_target_action_kind(action_kind: &str) -> frankenterm_core::policy::ActionKind {
    serde_json::from_str(&format!("\"{action_kind}\""))
        .unwrap_or(frankenterm_core::policy::ActionKind::ExecCommand)
}

fn plan_audit_surface(
    action: frankenterm_core::policy::ActionKind,
) -> frankenterm_core::policy::PolicySurface {
    match action {
        frankenterm_core::policy::ActionKind::SendText => {
            frankenterm_core::policy::PolicySurface::Mux
        }
        frankenterm_core::policy::ActionKind::WorkflowRun => {
            frankenterm_core::policy::PolicySurface::Workflow
        }
        _ => frankenterm_core::policy::PolicySurface::default_for_actor(
            frankenterm_core::policy::ActorKind::Human,
        ),
    }
}

fn build_approval_decision_context(
    actor_kind: &str,
    workspace_id: &str,
    action_kind: &str,
    pane_id: Option<u64>,
    timestamp_ms: i64,
) -> Option<String> {
    let actor = approval_actor_kind(actor_kind);
    let action = audit_target_action_kind(action_kind);
    let surface = match action {
        frankenterm_core::policy::ActionKind::SendText
        | frankenterm_core::policy::ActionKind::SendCtrlC
        | frankenterm_core::policy::ActionKind::SendCtrlD
        | frankenterm_core::policy::ActionKind::SendCtrlZ
        | frankenterm_core::policy::ActionKind::SendControl
        | frankenterm_core::policy::ActionKind::Spawn
        | frankenterm_core::policy::ActionKind::Split
        | frankenterm_core::policy::ActionKind::Activate
        | frankenterm_core::policy::ActionKind::Close
        | frankenterm_core::policy::ActionKind::BrowserAuth
        | frankenterm_core::policy::ActionKind::ReadOutput
        | frankenterm_core::policy::ActionKind::SearchOutput => {
            frankenterm_core::policy::PolicySurface::Mux
        }
        frankenterm_core::policy::ActionKind::WorkflowRun => {
            frankenterm_core::policy::PolicySurface::Workflow
        }
        frankenterm_core::policy::ActionKind::ReservePane
        | frankenterm_core::policy::ActionKind::ReleasePane => {
            frankenterm_core::policy::PolicySurface::Swarm
        }
        _ => frankenterm_core::policy::PolicySurface::default_for_actor(actor),
    };
    let mut context = frankenterm_core::policy::DecisionContext::new_audit(
        timestamp_ms,
        action,
        actor,
        surface,
        pane_id,
        None,
        Some(format!("approval consume for {action_kind}")),
        None,
    );
    context.record_rule(
        "approval.allow_once.consume",
        true,
        Some("allow"),
        Some("approval code validated and consumed".to_string()),
    );
    context.set_determining_rule("approval.allow_once.consume");
    context.add_evidence("stage", "approval");
    context.add_evidence("workspace_id", workspace_id);
    context.add_evidence("approval_actor", actor_kind);
    context.add_evidence("approval_surface", surface.as_str());
    context.add_evidence("approval_action_kind", action_kind);
    if let Some(pane_id) = pane_id {
        context.add_evidence("approval_pane_id", pane_id.to_string());
    }
    serde_json::to_string(&context).ok()
}

fn build_inline_approval_retry_command(command_name: &str, code: &str) -> String {
    format!("Retry the original {command_name} command with --approval-code {code}")
}

// Approval resolution keeps the policy decision, storage, actor, command, and retry inputs explicit.
#[allow(clippy::too_many_arguments)]
async fn resolve_inline_send_approval(
    decision: frankenterm_core::policy::PolicyDecision,
    storage: &frankenterm_core::storage::StorageHandle,
    approval_config: frankenterm_core::config::ApprovalConfig,
    workspace_id: &str,
    input: &frankenterm_core::policy::PolicyInput,
    summary: &str,
    approval_code: Option<&str>,
    actor_kind: &str,
    command_name: &str,
) -> std::result::Result<frankenterm_core::policy::PolicyDecision, String> {
    if !decision.requires_approval() {
        return Ok(decision);
    }

    let store = frankenterm_core::approval::ApprovalStore::new(
        storage,
        approval_config,
        workspace_id.to_string(),
    );

    if let Some(code) = approval_code {
        let mut approval_context = frankenterm_core::approval::ApprovalAuditContext::default();
        if let Some(dc) = build_approval_decision_context(
            actor_kind,
            workspace_id,
            input.action.as_str(),
            input.pane_id,
            now_ms_i64(),
        ) {
            approval_context = approval_context.with_decision_context(dc);
        }

        // ft-xbnl0.2.3 tick 274: cx-first approval consume.
        let approval_cx =
            frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
        return match store
            .consume_with_context_with_cx(&approval_cx, code, input, Some(approval_context))
            .await
        {
            Ok(Some(_)) => Ok(frankenterm_core::policy::PolicyDecision::allow_with_rule(
                "approval.allow_once",
            )),
            Ok(None) => Err(
                "Invalid or expired approval code for this action. Use the exact code issued for this retry."
                    .to_string(),
            ),
            Err(e) => Err(format!("Failed to consume approval token: {e}")),
        };
    }

    // ft-xbnl0.2.3 tick 274: cx-first approval issue.
    let issue_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    let mut approval = store
        .issue_with_cx(&issue_cx, input, Some(summary.to_string()))
        .await
        .map_err(|e| format!("Failed to issue approval token: {e}"))?;
    approval.command = build_inline_approval_retry_command(command_name, &approval.allow_once_code);
    Ok(decision.with_approval(approval))
}

// Event mutation audit context maps directly to the serialized policy evidence fields.
#[allow(clippy::too_many_arguments)]
fn build_event_mutation_decision_context(
    actor_kind: &str,
    interface: &str,
    action_kind: &str,
    event_id: i64,
    operation: &str,
    actor_id: Option<&str>,
    input_summary: &str,
    changed: Option<bool>,
    state: Option<&str>,
    label: Option<&str>,
    timestamp_ms: i64,
) -> Option<String> {
    let actor = approval_actor_kind(actor_kind);
    let surface = match interface {
        "ft.events" => frankenterm_core::policy::PolicySurface::Mux,
        "ft.robot.events" => frankenterm_core::policy::PolicySurface::Robot,
        _ => frankenterm_core::policy::PolicySurface::default_for_actor(actor),
    };
    let mut context = frankenterm_core::policy::DecisionContext::new_audit(
        timestamp_ms,
        frankenterm_core::policy::ActionKind::ExecCommand,
        actor,
        surface,
        None,
        None,
        Some(input_summary.to_string()),
        None,
    );
    let determining_rule = format!("audit.{action_kind}");
    context.record_rule(
        &determining_rule,
        true,
        Some("allow"),
        Some("event metadata mutation recorded".to_string()),
    );
    context.set_determining_rule(&determining_rule);
    context.add_evidence("stage", "event_mutation");
    context.add_evidence("interface", interface);
    context.add_evidence("event_action_kind", action_kind);
    context.add_evidence("event_id", event_id.to_string());
    context.add_evidence("operation", operation);
    context.add_evidence("event_surface", surface.as_str());
    if let Some(actor_id) = actor_id {
        context.add_evidence("actor_id", actor_id);
    }
    if let Some(changed) = changed {
        context.add_evidence("changed", changed.to_string());
    }
    if let Some(state) = state {
        context.add_evidence("state", state);
    }
    if let Some(label) = label {
        context.add_evidence("label", label);
    }
    serde_json::to_string(&context).ok()
}

fn build_ipc_rpc_decision_context(
    actor_kind: &str,
    summary: &str,
    result: &str,
    request_id: Option<&str>,
    timestamp_ms: i64,
) -> Option<String> {
    let actor = approval_actor_kind(actor_kind);
    let mut context = frankenterm_core::policy::DecisionContext::new_audit(
        timestamp_ms,
        frankenterm_core::policy::ActionKind::ExecCommand,
        actor,
        frankenterm_core::policy::PolicySurface::Ipc,
        None,
        None,
        Some(summary.to_string()),
        None,
    );
    context.record_rule(
        "audit.ipc.rpc",
        true,
        Some("allow"),
        Some("ipc rpc request recorded in audit trail".to_string()),
    );
    context.set_determining_rule("audit.ipc.rpc");
    context.add_evidence("stage", "ipc_rpc");
    context.add_evidence("interface", "ft.ipc.rpc");
    context.add_evidence("ipc_action_kind", "ipc.rpc");
    context.add_evidence("ipc_surface", "ipc");
    context.add_evidence("ipc_actor_kind", actor.as_str());
    context.add_evidence("ipc_result", result);
    if let Some(request_id) = request_id {
        context.add_evidence("request_id", request_id);
    }
    serde_json::to_string(&context).ok()
}

#[derive(Debug, Clone, Copy)]
enum InterventionVerb {
    Pause,
    Resume,
    Quarantine,
    Takeover,
}

impl InterventionVerb {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Pause => "pause",
            Self::Resume => "resume",
            Self::Quarantine => "quarantine",
            Self::Takeover => "takeover",
        }
    }

    const fn audit_action_kind(self) -> &'static str {
        match self {
            Self::Pause => "intervene.pause",
            Self::Resume => "intervene.resume",
            Self::Quarantine => "intervene.quarantine",
            Self::Takeover => "intervene.takeover",
        }
    }

    const fn policy_action(self) -> frankenterm_core::policy::ActionKind {
        match self {
            Self::Resume => frankenterm_core::policy::ActionKind::ReleasePane,
            Self::Pause | Self::Quarantine | Self::Takeover => {
                frankenterm_core::policy::ActionKind::ReservePane
            }
        }
    }

    const fn owner_id(self) -> &'static str {
        match self {
            Self::Pause => "intervene:pause",
            Self::Resume => "intervene:resume",
            Self::Quarantine => "intervene:quarantine",
            Self::Takeover => "intervene:takeover",
        }
    }

    const fn default_reason(self) -> &'static str {
        match self {
            Self::Pause => "operator pause",
            Self::Resume => "operator resume",
            Self::Quarantine => "operator quarantine",
            Self::Takeover => "operator manual takeover",
        }
    }

    fn action(
        self,
        pane_id: u64,
        reason: &str,
    ) -> frankenterm_core::intervention_console::InterventionAction {
        use frankenterm_core::intervention_console::InterventionAction;
        match self {
            Self::Pause => InterventionAction::PausePane { pane_id },
            Self::Resume => InterventionAction::ResumePane { pane_id },
            Self::Quarantine => InterventionAction::QuarantinePane {
                pane_id,
                reason: reason.to_string(),
            },
            Self::Takeover => InterventionAction::TakeoverPane { pane_id },
        }
    }

    fn release_action_for_owner(
        owner_id: &str,
        pane_id: u64,
    ) -> frankenterm_core::intervention_console::InterventionAction {
        use frankenterm_core::intervention_console::InterventionAction;
        match owner_id {
            "intervene:takeover" => InterventionAction::ReleaseTakeover { pane_id },
            "intervene:quarantine" => InterventionAction::ReleaseQuarantine { pane_id },
            _ => InterventionAction::ResumePane { pane_id },
        }
    }
}

fn reservation_info_from_record(
    r: frankenterm_core::storage::PaneReservation,
) -> RobotReservationInfo {
    RobotReservationInfo {
        id: r.id,
        pane_id: r.pane_id,
        owner_kind: r.owner_kind,
        owner_id: r.owner_id,
        reason: r.reason,
        created_at: r.created_at,
        expires_at: r.expires_at,
        released_at: r.released_at,
        status: r.status,
    }
}

fn approval_token_status(
    token: &frankenterm_core::storage::ApprovalTokenRecord,
    now_ms: i64,
) -> &'static str {
    if token.used_at.is_some() {
        "consumed"
    } else if token.expires_at < now_ms {
        "expired"
    } else {
        "pending"
    }
}

fn approval_code_hash_prefix(code_hash: &str) -> String {
    const PREFIX_LEN: usize = 19;
    code_hash.chars().take(PREFIX_LEN).collect()
}

fn approval_queue_item_from_token(
    token: frankenterm_core::storage::ApprovalTokenRecord,
    now_ms: i64,
) -> ApprovalQueueItem {
    ApprovalQueueItem {
        id: token.id,
        status: approval_token_status(&token, now_ms).to_string(),
        action_kind: token.action_kind,
        pane_id: token.pane_id,
        created_at: token.created_at,
        expires_at: token.expires_at,
        used_at: token.used_at,
        expires_in_ms: token.expires_at.saturating_sub(now_ms),
        code_hash_prefix: approval_code_hash_prefix(&token.code_hash),
        plan_hash: token.plan_hash,
        plan_version: token.plan_version,
        risk_summary: token.risk_summary,
    }
}

fn intervention_plain_output(data: &InterveneCliData) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "Intervention {} pane {}: {}\n",
        data.verb, data.pane_id, data.policy_decision
    ));
    if let Some(reason) = &data.decision_reason {
        out.push_str(&format!("  policy_reason: {reason}\n"));
    }
    out.push_str(&format!("  result: {}\n", data.result.message));
    if let Some(reservation) = &data.reservation {
        out.push_str(&format!(
            "  reservation: id={} owner={} expires_at={}\n",
            reservation.id,
            reservation.owner_id,
            format_epoch_ms(reservation.expires_at)
        ));
    }
    for released in &data.released_reservations {
        out.push_str(&format!(
            "  released_reservation: id={} owner={}\n",
            released.id, released.owner_id
        ));
    }
    if let Some(audit_id) = data.audit_id {
        out.push_str(&format!("  audit_id: {audit_id}\n"));
    }
    if data.dry_run {
        out.push_str("  dry_run: true\n");
    }
    out
}

fn approvals_list_plain_output(data: &ApprovalsListData) -> String {
    if data.approvals.is_empty() {
        return "No approval tokens.\n".to_string();
    }
    let mut out = String::new();
    out.push_str(&format!(
        "{:<6} {:<9} {:<18} {:<8} {:<12} HASH\n",
        "ID", "STATUS", "ACTION", "PANE", "EXPIRES_IN"
    ));
    for item in &data.approvals {
        let pane = item
            .pane_id
            .map(|value| value.to_string())
            .unwrap_or_else(|| "-".to_string());
        let expires = if item.expires_in_ms <= 0 {
            "expired".to_string()
        } else {
            format!("{}s", item.expires_in_ms / 1000)
        };
        out.push_str(&format!(
            "{:<6} {:<9} {:<18} {:<8} {:<12} {}\n",
            item.id, item.status, item.action_kind, pane, expires, item.code_hash_prefix
        ));
    }
    out.push_str(&format!(
        "\n{} approval token(s), {} active.\n",
        data.total, data.active
    ));
    out
}

fn approval_consume_plain_output(data: &ApprovalConsumeData) -> String {
    let action = &data.approval.action_kind;
    let pane = data
        .approval
        .pane_id
        .map(|value| value.to_string())
        .unwrap_or_else(|| "-".to_string());
    if data.dry_run {
        return format!(
            "Approval token {} is {} for action={} pane={}.\n",
            data.approval.id, data.approval.status, action, pane
        );
    }
    format!(
        "Approval token {} consumed for action={} pane={}.\n",
        data.approval.id, action, pane
    )
}

async fn evaluate_approve(
    storage: &frankenterm_core::storage::StorageHandle,
    workspace_id: &str,
    code: &str,
    pane: Option<u64>,
    fingerprint: Option<&str>,
    dry_run: bool,
    _actor_kind: &str,
) -> Result<RobotApproveData, RobotApproveError> {
    let code_hash = frankenterm_core::approval::hash_allow_once_code(code);

    // ft-xbnl0.2.3 tick 246: cx-first storage read.
    let storage_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    let token = match storage
        .get_approval_token_with_cx(&storage_cx, &code_hash)
        .await
    {
        Ok(Some(t)) => t,
        Ok(None) => {
            return Err(RobotApproveError::new(
                "E_APPROVAL_NOT_FOUND",
                format!("No approval found with code: {code}"),
                Some(
                    "Approval codes are issued when policy requires approval. \
                     Check that you have the correct code."
                        .to_string(),
                ),
            ));
        }
        Err(e) => {
            return Err(RobotApproveError::new(
                ROBOT_ERR_STORAGE,
                format!("Failed to look up approval: {e}"),
                None,
            ));
        }
    };

    // Workspace scope check (explicit to provide E_WRONG_WORKSPACE)
    if token.workspace_id != workspace_id {
        return Err(RobotApproveError::new(
            "E_WRONG_WORKSPACE",
            format!(
                "Approval code is scoped to workspace '{}', but current workspace is '{}'",
                token.workspace_id, workspace_id
            ),
            Some("Use the approval code in the workspace where it was issued.".to_string()),
        ));
    }

    let now_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_millis() as i64);

    if token.used_at.is_some() {
        return Err(RobotApproveError::new(
            "E_APPROVAL_CONSUMED",
            "Approval code has already been used".to_string(),
            Some(
                "Approval codes can only be used once. Request a new approval if needed."
                    .to_string(),
            ),
        ));
    }

    if token.expires_at < now_ms {
        return Err(RobotApproveError::new(
            "E_APPROVAL_EXPIRED",
            format!(
                "Approval code expired at {} (now: {})",
                token.expires_at, now_ms
            ),
            Some(
                "Approval codes have a limited validity period. Request a new approval."
                    .to_string(),
            ),
        ));
    }

    if let Some(expected_pane) = pane {
        if token.pane_id != Some(expected_pane) {
            return Err(RobotApproveError::new(
                "E_WRONG_PANE",
                format!(
                    "Approval was for pane {:?}, but --pane {} was specified",
                    token.pane_id, expected_pane
                ),
                Some("Use the correct pane ID or omit --pane.".to_string()),
            ));
        }
    }

    if let Some(expected_fingerprint) = fingerprint {
        if token.action_fingerprint != expected_fingerprint {
            return Err(RobotApproveError::new(
                "E_FINGERPRINT_MISMATCH",
                "Approval fingerprint does not match the requested action".to_string(),
                Some(
                    "The approval was issued for a different action. Request a new approval."
                        .to_string(),
                ),
            ));
        }
    }

    Ok(RobotApproveData {
        code: code.to_string(),
        valid: true,
        created_at: Some(token.created_at as u64),
        action_kind: Some(token.action_kind),
        pane_id: token.pane_id,
        expires_at: Some(token.expires_at as u64),
        consumed_at: None,
        action_fingerprint: Some(token.action_fingerprint),
        dry_run: if dry_run { Some(true) } else { None },
    })
}

const SEND_OSC_SEGMENT_LIMIT: usize = 200;

struct CapabilityResolution {
    capabilities: frankenterm_core::policy::PaneCapabilities,
    warnings: Vec<String>,
}

/// Resolve prompt / alt-screen / gap evidence for every pane a tx contract
/// references, so the CLI prepare gates see the same capability chain the
/// MCP tx surface uses (ft-zhwa6, mirrors `mcp_tools::resolve_tx_prepare_capabilities`).
///
/// Without this the storage-backed target lookup evaluates every pane as
/// `PaneCapabilities::unknown`, which makes `prompt_active` preconditions
/// impossible to satisfy from `ft tx run` / `ft tx rollback` no matter what
/// the pane is actually doing.
async fn resolve_tx_contract_capabilities(
    contract: &frankenterm_core::plan::MissionTxContract,
    storage: &frankenterm_core::storage::StorageHandle,
    ipc_socket_path: Option<&Path>,
) -> HashMap<u64, frankenterm_core::policy::PaneCapabilities> {
    let mut capabilities = HashMap::new();
    for pane_id in contract.referenced_pane_ids() {
        let resolution = resolve_pane_capabilities(pane_id, Some(storage), ipc_socket_path).await;
        for warning in &resolution.warnings {
            tracing::debug!(pane_id, %warning, "tx capability resolution warning");
        }
        capabilities.insert(pane_id, resolution.capabilities);
    }
    capabilities
}

async fn derive_osc_state_from_storage(
    storage: &frankenterm_core::storage::StorageHandle,
    pane_id: u64,
) -> Result<Option<frankenterm_core::ingest::Osc133State>, String> {
    let segments = storage
        .get_segments(pane_id, SEND_OSC_SEGMENT_LIMIT)
        .await
        .map_err(|e| bounded_display_diagnostic("failed to read segments: ", &e, 400, 1_600))?;
    if segments.is_empty() {
        return Ok(None);
    }

    let mut state = frankenterm_core::ingest::Osc133State::new();
    for segment in segments.iter().rev() {
        frankenterm_core::ingest::process_osc133_output(&mut state, &segment.content);
    }

    if state.markers_seen == 0 {
        return Ok(None);
    }

    Ok(Some(state))
}

#[cfg(unix)]
async fn fetch_pane_state_from_ipc(
    socket_path: &Path,
    pane_id: u64,
) -> Result<Option<IpcPaneState>, String> {
    let client = frankenterm_core::ipc::IpcClient::new(socket_path);
    // ft-xbnl0.2.3 tick 227: route through pane_state_with_cx so the
    // IPC round-trip observes caller cancellation at the pre-read
    // checkpoint (tick 201) and the mpsc-reserve/response boundaries.
    let cx = frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    match client.pane_state_with_cx(&cx, pane_id).await {
        Ok(response) => {
            if !response.ok {
                let detail = response
                    .error
                    .unwrap_or_else(|| "unknown error".to_string());
                return Err(detail);
            }
            if let Some(data) = response.data {
                serde_json::from_value::<IpcPaneState>(data)
                    .map(Some)
                    .map_err(|e| {
                        bounded_display_diagnostic("invalid pane state payload: ", &e, 400, 1_600)
                    })
            } else {
                Ok(None)
            }
        }
        Err(err) => Err(bounded_display_diagnostic("", &err, 400, 1_600)),
    }
}

#[cfg(not(unix))]
async fn fetch_pane_state_from_ipc(
    _socket_path: &Path,
    _pane_id: u64,
) -> Result<Option<IpcPaneState>, String> {
    Err("IPC not supported on this platform".to_string())
}

fn resolve_alt_screen_state(state: &IpcPaneState) -> Option<bool> {
    if !state.known {
        return None;
    }
    if let Some(cursor_state) = state.cursor_alt_screen {
        return Some(cursor_state);
    }
    if state.last_status_at.is_some() {
        return state.alt_screen;
    }
    None
}

async fn resolve_pane_capabilities(
    pane_id: u64,
    storage: Option<&frankenterm_core::storage::StorageHandle>,
    ipc_socket_path: Option<&Path>,
) -> CapabilityResolution {
    let mut warnings = Vec::new();
    let mut osc_state = None;

    if let Some(storage) = storage {
        match derive_osc_state_from_storage(storage, pane_id).await {
            Ok(state) => osc_state = state,
            Err(err) => warnings.push(bounded_prefixed_diagnostic(
                "OSC 133 state unavailable: ",
                &err,
                400,
                1_600,
            )),
        }
    } else {
        warnings.push("Storage unavailable; prompt state unknown.".to_string());
    }

    let mut alt_screen = None;
    let mut in_gap = true;
    let mut gap_known = false;

    if let Some(socket_path) = ipc_socket_path {
        match fetch_pane_state_from_ipc(socket_path, pane_id).await {
            Ok(Some(state)) => {
                if state.pane_id != pane_id {
                    warnings.push(format!(
                        "Watcher returned state for pane {} (expected {})",
                        state.pane_id, pane_id
                    ));
                }
                if !state.known {
                    let reason = state.reason.as_deref().unwrap_or("unknown");
                    warnings.push(bounded_format_diagnostic(
                        format_args!("Watcher has no state for this pane ({reason})."),
                        400,
                        1_600,
                    ));
                } else if state.observed == Some(false) {
                    warnings.push(
                        "Pane is not observed by watcher; state may be incomplete.".to_string(),
                    );
                }
                alt_screen = resolve_alt_screen_state(&state);
                if state.in_gap.is_some() {
                    gap_known = true;
                    in_gap = state.in_gap.unwrap_or(true);
                }
                if alt_screen.is_none() {
                    warnings
                        .push("Alt-screen state unknown; approval may be required.".to_string());
                }
                if in_gap {
                    if gap_known {
                        warnings.push(
                            "Recent capture gap detected; approval may be required.".to_string(),
                        );
                    } else {
                        warnings.push(
                            "Capture continuity unknown; treating as recent gap.".to_string(),
                        );
                    }
                } else if !gap_known {
                    warnings
                        .push("Capture continuity unknown; treating as recent gap.".to_string());
                }
            }
            Ok(None) => {
                warnings.push("Watcher IPC returned no pane state.".to_string());
            }
            Err(err) => {
                warnings.push(bounded_prefixed_diagnostic(
                    "Watcher IPC unavailable: ",
                    &err,
                    400,
                    1_600,
                ));
            }
        }
    } else {
        warnings.push("IPC socket unavailable; alt-screen/gap unknown.".to_string());
    }

    let capabilities = frankenterm_core::policy::PaneCapabilities::from_ingest_state(
        osc_state.as_ref(),
        alt_screen,
        in_gap,
    );

    CapabilityResolution {
        capabilities,
        warnings,
    }
}

fn build_mux_send_policy_input(
    pane_id: u64,
    pane_info: Option<&frankenterm_core::wezterm::PaneInfo>,
    capabilities: frankenterm_core::policy::PaneCapabilities,
    summary: &str,
    text: &str,
    actor_kind: frankenterm_core::policy::ActorKind,
) -> frankenterm_core::policy::PolicyInput {
    use frankenterm_core::policy::{ActionKind, PolicyInput, PolicySurface};

    let domain = pane_info
        .map(frankenterm_core::wezterm::PaneInfo::inferred_domain)
        .unwrap_or_else(|| "unknown".to_string());

    let mut input = PolicyInput::new(ActionKind::SendText, actor_kind)
        .with_surface(PolicySurface::Mux)
        .with_pane(pane_id)
        .with_domain(domain)
        .with_capabilities(capabilities)
        .with_text_summary(summary)
        .with_command_text(text);

    if let Some(info) = pane_info {
        if let Some(title) = &info.title {
            input = input.with_pane_title(title.clone());
        }
        if let Some(cwd) = &info.cwd {
            input = input.with_pane_cwd(cwd.clone());
        }
    }

    input
}

fn bounded_send_text_summary(
    engine: &frankenterm_core::policy::PolicyEngine,
    text: &str,
) -> String {
    if text.len() > TERMINAL_TEXT_INPUT_MAX_BYTES {
        return format!("payload omitted: {} bytes", text.len());
    }
    frankenterm_core::output::sanitize_redact_truncate_bounded(text, 400, 1_600, |normalized| {
        engine.redact_secrets(normalized)
    })
}

fn requested_submit_guarantee_level(
    verify_submit: bool,
    submit_level: Option<SubmitGuaranteeLevelArg>,
) -> Option<frankenterm_core::robot_types::SubmitGuaranteeLevel> {
    submit_level.map(Into::into).or_else(|| {
        verify_submit.then_some(frankenterm_core::robot_types::SubmitGuaranteeLevel::Submitted)
    })
}

#[derive(Clone, Copy)]
struct SendCommandSummaryOptions {
    dry_run: bool,
    no_paste: bool,
    no_newline: bool,
    has_wait_for: bool,
    wait_for_regex: bool,
    timeout_secs: u64,
    has_approval_code: bool,
    verify_submit: bool,
    submit_level: Option<SubmitGuaranteeLevelArg>,
}

fn build_send_command_summary(
    command_name: &str,
    pane_id: u64,
    text_bytes: usize,
    options: SendCommandSummaryOptions,
) -> String {
    let submit_level = options
        .submit_level
        .map(|level| {
            let core_level: frankenterm_core::robot_types::SubmitGuaranteeLevel = level.into();
            core_level.as_str()
        })
        .unwrap_or("none");
    format!(
        "{command_name} pane_id={pane_id} text_bytes={text_bytes} dry_run={} no_paste={} no_newline={} wait_for={} wait_for_regex={} timeout_secs={} approval_code={} verify_submit={} submit_level={submit_level}",
        options.dry_run,
        options.no_paste,
        options.no_newline,
        options.has_wait_for,
        options.wait_for_regex,
        options.timeout_secs,
        options.has_approval_code,
        options.verify_submit,
    )
}

// Dry-run report construction needs target, policy, command, and wait metadata for a single envelope.
#[allow(clippy::too_many_arguments)]
fn build_send_dry_run_report(
    command_ctx: &frankenterm_core::dry_run::CommandContext,
    pane_id: u64,
    pane_info: Option<&frankenterm_core::wezterm::PaneInfo>,
    capabilities: Option<&frankenterm_core::policy::PaneCapabilities>,
    text: &str,
    no_paste: bool,
    wait_for: Option<&str>,
    timeout_secs: u64,
    config: &frankenterm_core::config::Config,
    actor_kind: frankenterm_core::policy::ActorKind,
) -> frankenterm_core::dry_run::DryRunReport {
    use frankenterm_core::dry_run::{
        PolicyCheck, TargetResolution, build_send_policy_evaluation, create_send_action,
        create_wait_for_action,
    };
    use frankenterm_core::policy::{PaneCapabilities, PolicyEngine};

    let mut ctx = command_ctx.dry_run_context();

    // Target resolution (best-effort)
    let domain = pane_info
        .map(|info| info.inferred_domain())
        .unwrap_or_else(|| "unknown".to_string());
    let domain = bounded_terminal_preview(&domain, 400, 1_600);
    if let Some(info) = pane_info {
        let mut target = TargetResolution::new(pane_id, domain).with_is_active(info.is_active);
        if let Some(title) = &info.title {
            target = target.with_title(bounded_terminal_preview(title, 400, 1_600));
        }
        if let Some(cwd) = &info.cwd {
            target = target.with_cwd(bounded_terminal_preview(cwd, 400, 1_600));
        }
        ctx.set_target(target);
    } else {
        ctx.set_target(TargetResolution::new(pane_id, "unknown"));
        ctx.add_warning(
            "Pane metadata unavailable; ensure the active terminal backend is running and pane exists.",
        );
    }

    // Policy evaluation (best-effort; uses config defaults + assumed prompt state)
    let capabilities_opt = capabilities;
    let capabilities = capabilities_opt
        .cloned()
        .unwrap_or_else(PaneCapabilities::prompt);
    let mut eval = build_send_policy_evaluation(
        (0, config.safety.rate_limit_per_pane),
        capabilities.prompt_active,
        config.safety.require_prompt_active,
        capabilities.has_recent_gap,
    );

    let mut engine = PolicyEngine::new(
        config.safety.rate_limit_per_pane,
        config.safety.rate_limit_global,
        config.safety.require_prompt_active,
    )
    .with_tuning(&config.tuning)
    .with_command_gate_config(config.safety.command_gate.clone())
    .with_policy_rules(config.safety.rules.clone());

    let summary = bounded_send_text_summary(&engine, text);
    let input = build_mux_send_policy_input(
        pane_id,
        pane_info,
        capabilities.clone(),
        &summary,
        text,
        actor_kind,
    );

    let decision = engine.authorize(&input);
    let mut decision_check = PolicyCheck::from(&decision);
    if let Some(rule_id) = decision.rule_id() {
        decision_check = decision_check.with_details(format!("rule: {rule_id}"));
    }
    eval.add_check(decision_check);
    if let Some(context) = decision.context() {
        eval.add_check(PolicyCheck::passed(
            "policy_surface",
            format!("Policy surface: {}", context.surface.as_str()),
        ));
        if let Some(rule) = context
            .rules_evaluated
            .iter()
            .find(|rule| rule.rule_id.starts_with("command."))
        {
            let reason = rule
                .reason
                .as_deref()
                .unwrap_or("Command safety gate triggered");
            let message = match rule.decision.as_deref() {
                Some("require_approval") => format!("Approval required: {reason}"),
                Some("deny") => reason.to_string(),
                Some("allow") => reason.to_string(),
                _ => reason.to_string(),
            };
            let mut check = if matches!(rule.decision.as_deref(), Some("allow")) {
                PolicyCheck::passed("command_safety", message)
            } else {
                PolicyCheck::failed("command_safety", message)
            };
            check = check.with_details(format!("rule: {}", rule.rule_id));
            eval.add_check(check);
        } else if let Some(rule) = context
            .rules_evaluated
            .iter()
            .find(|rule| rule.rule_id == "policy.command_gate")
        {
            let message = rule
                .reason
                .clone()
                .unwrap_or_else(|| "Command gate evaluated".to_string());
            let check = PolicyCheck::passed("command_safety", message)
                .with_details(format!("rule: {}", rule.rule_id));
            eval.add_check(check);
        } else {
            eval.add_check(PolicyCheck::passed(
                "command_safety",
                "Command gate not evaluated (blocked earlier)",
            ));
        }
    } else {
        eval.add_check(PolicyCheck::passed(
            "policy_surface",
            "Policy surface: unknown (context unavailable)",
        ));
        eval.add_check(PolicyCheck::passed(
            "command_safety",
            "Command gate context unavailable",
        ));
    }
    ctx.set_policy_evaluation(eval);

    if let Some(provided_caps) = capabilities_opt {
        if provided_caps.alt_screen == Some(true) {
            ctx.add_warning("Pane is in alt-screen; send will be denied by policy.");
        } else if provided_caps.alt_screen.is_none() {
            ctx.add_warning("Alt-screen state unknown; approval may be required.");
        }
        if provided_caps.has_recent_gap {
            ctx.add_warning("Recent capture gap detected; approval may be required.");
        }
        if config.safety.require_prompt_active && !provided_caps.prompt_active {
            ctx.add_warning("Prompt not active; approval or denial likely.");
        }
    }

    // Expected actions
    ctx.add_action(create_send_action(1, pane_id, text.len()));
    if let Some(pattern) = wait_for {
        let timeout_ms = timeout_secs.saturating_mul(1000);
        ctx.add_action(create_wait_for_action(
            2,
            redact_wait_pattern_for_output(pattern),
            timeout_ms,
        ));
    }

    if no_paste {
        ctx.add_warning("no_paste mode sends characters individually (slower)");
    }

    ctx.take_report()
}

fn send_dry_run_report_for_output(
    mut report: frankenterm_core::dry_run::DryRunReport,
) -> frankenterm_core::dry_run::DryRunReport {
    report.command = bounded_terminal_preview(&report.command, 400, 1_600);

    if let Some(target) = report.target_resolution.as_mut() {
        target.domain = bounded_terminal_preview(&target.domain, 400, 1_600);
        for field in [&mut target.title, &mut target.cwd, &mut target.agent_type] {
            if let Some(value) = field.as_mut() {
                *value = bounded_terminal_preview(value, 400, 1_600);
            }
        }
    }
    if let Some(policy) = report.policy_evaluation.as_mut() {
        for check in &mut policy.checks {
            check.name = bounded_terminal_preview(&check.name, 128, 512);
            check.message = bounded_terminal_diagnostic(&check.message, 400, 1_600);
            if let Some(details) = check.details.as_mut() {
                *details = bounded_terminal_diagnostic(details, 400, 1_600);
            }
        }
    }
    for action in &mut report.expected_actions {
        action.description = bounded_terminal_diagnostic(&action.description, 400, 1_600);
        if let Some(metadata) = action.metadata.as_mut() {
            sanitize_diagnostic_json_strings(metadata);
        }
    }
    for warning in &mut report.warnings {
        *warning = bounded_terminal_diagnostic(warning, 400, 1_600);
    }

    report
}

// Prepare-send plans preserve CLI request fields as explicit plan inputs.
#[allow(clippy::too_many_arguments)]
fn build_prepare_send_plan(
    workspace_id: &str,
    pane_id: u64,
    text: &str,
    no_paste: bool,
    no_newline: bool,
    wait_for: Option<&str>,
    wait_for_regex: bool,
    timeout_secs: u64,
) -> frankenterm_core::plan::ActionPlan {
    use frankenterm_core::plan::{ActionPlan, StepAction, StepPlan};

    let send_step = StepPlan::new(
        1,
        StepAction::Custom {
            action_type: "prepare.send_text".to_string(),
            payload: serde_json::json!({
                "pane_id": pane_id,
                "text": text,
                "no_paste": no_paste,
                "no_newline": no_newline,
            }),
        },
        "Send text to pane",
    )
    .idempotent();

    let mut builder = ActionPlan::builder(
        format!("Send text to pane {pane_id}"),
        workspace_id.to_string(),
    )
    .add_step(send_step)
    .created_at(now_ms_i64());

    if let Some(pattern) = wait_for {
        let wait_step = StepPlan::new(
            2,
            StepAction::Custom {
                action_type: "prepare.wait_for".to_string(),
                payload: serde_json::json!({
                    "pane_id": pane_id,
                    "pattern": pattern,
                    "is_regex": wait_for_regex,
                    "timeout_ms": timeout_secs.saturating_mul(1000),
                }),
            },
            "Wait for verification pattern",
        );
        builder = builder.add_step(wait_step);
    }

    builder.build()
}

fn redact_prepare_plan(
    plan: &frankenterm_core::plan::ActionPlan,
) -> frankenterm_core::plan::ActionPlan {
    let mut redacted = plan.clone();
    let redactor = frankenterm_core::policy::Redactor::new();

    for step in &mut redacted.steps {
        if let frankenterm_core::plan::StepAction::Custom {
            action_type,
            payload,
        } = &mut step.action
        {
            if action_type == "prepare.send_text" {
                redact_payload_field(payload, "text", &redactor);
            } else if action_type == "prepare.wait_for" {
                redact_payload_field(payload, "pattern", &redactor);
            }
        }
    }

    redacted
}

fn prepare_audit_action_kind(action_kind: &str) -> String {
    format!("prepare.{action_kind}")
}

fn commit_audit_action_kind(action_kind: &str) -> String {
    format!("commit.{action_kind}")
}

fn build_plan_audit_context(
    plan_id: &str,
    plan_hash: &str,
    stage: &str,
    action_kind: &str,
    pane_id: Option<u64>,
    timestamp_ms: i64,
) -> Option<String> {
    let action = audit_target_action_kind(action_kind);
    let surface = plan_audit_surface(action);
    let mut context = frankenterm_core::policy::DecisionContext::new_audit(
        timestamp_ms,
        action,
        frankenterm_core::policy::ActorKind::Human,
        surface,
        pane_id,
        None,
        Some(format!("{stage} plan for {action_kind}")),
        None,
    );
    let determining_rule = format!("audit.plan.{stage}.{action_kind}");
    context.record_rule(
        &determining_rule,
        true,
        Some("allow"),
        Some("plan audit action recorded".to_string()),
    );
    context.set_determining_rule(&determining_rule);
    context.add_evidence("stage", "plan_audit");
    context.add_evidence("plan_stage", stage);
    context.add_evidence("plan_action_kind", action_kind);
    context.add_evidence("plan_surface", surface.as_str());
    context.add_evidence("correlation_id", plan_hash);
    context.add_evidence("plan_id", plan_id);
    context.add_evidence("plan_hash", plan_hash);
    if let Some(pane_id) = pane_id {
        context.add_evidence("plan_pane_id", pane_id.to_string());
    }
    serde_json::to_string(&context).ok()
}

fn redact_payload_field(
    payload: &mut serde_json::Value,
    field: &str,
    redactor: &frankenterm_core::policy::Redactor,
) {
    let Some(obj) = payload.as_object_mut() else {
        return;
    };
    let Some(value) = obj.get_mut(field) else {
        return;
    };
    let Some(text) = value.as_str() else {
        return;
    };

    let len = serde_json::Number::from(text.len() as u64);
    let redacted = redactor.redact(text);
    *value = serde_json::Value::String(redacted);
    obj.insert(format!("{field}_len"), serde_json::Value::Number(len));
}

async fn generate_workflow_plan(
    storage: &std::sync::Arc<frankenterm_core::storage::StorageHandle>,
    workflow: &std::sync::Arc<dyn frankenterm_core::workflows::Workflow>,
    workspace_id: &str,
    pane_id: u64,
    execution_id: &str,
) -> frankenterm_core::plan::ActionPlan {
    use frankenterm_core::workflows::{PaneMetadata, WorkflowContext, workflow_to_action_plan};

    let mut ctx = WorkflowContext::new(
        std::sync::Arc::clone(storage),
        pane_id,
        frankenterm_core::policy::PaneCapabilities::default(),
        execution_id,
    );
    // ft-xbnl0.2.3 tick 235: cx-first storage read.
    let storage_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    if let Ok(Some(record)) = storage.get_pane_with_cx(&storage_cx, pane_id).await {
        ctx.set_pane_meta(PaneMetadata {
            domain: Some(record.domain),
            title: record.title,
            cwd: record.cwd,
        });
    }

    if let Some(plan) = workflow.to_action_plan(&ctx, execution_id) {
        plan
    } else {
        workflow_to_action_plan(workflow.as_ref(), workspace_id, pane_id, execution_id)
    }
}

fn build_workflow_by_name(
    name: &str,
    config: &frankenterm_core::config::Config,
) -> Option<std::sync::Arc<dyn frankenterm_core::workflows::Workflow>> {
    resolve_workflow(name, &config.workflows)
        .filter(|workflow| workflow_enabled(workflow.name(), &config.workflows))
}

fn now_ms_i64() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_millis() as i64)
}

type RobotJsonResponse = RobotResponse<serde_json::Value>;
type RobotJsonResult<T> = Result<T, Box<RobotJsonResponse>>;

#[derive(Debug, Clone)]
struct RobotWorkRow {
    claim_id: String,
    state: String,
    owner: Option<String>,
    pane_id: Option<u64>,
    priority: i64,
    labels_json: String,
    created_at_ms: i64,
    updated_at_ms: i64,
    claimed_at_ms: Option<i64>,
    completed_at_ms: Option<i64>,
    summary: Option<String>,
    evidence_json: String,
    blocked_by_count: i64,
    unblocks_count: i64,
    last_reason: Option<String>,
}

fn robot_work_error_response(
    code: &str,
    message: impl Into<String>,
    hint: Option<String>,
    elapsed_ms: u64,
) -> RobotJsonResponse {
    RobotResponse::<serde_json::Value>::error_with_code(code, message, hint, elapsed_ms)
}

fn robot_work_backend_error(err: impl std::fmt::Display, elapsed_ms: u64) -> RobotJsonResponse {
    robot_work_error_response(
        ROBOT_ERR_STORAGE,
        format!("Failed to update native work queue: {err}"),
        Some("Check the workspace database path and permissions.".to_string()),
        elapsed_ms,
    )
}

fn robot_work_not_found(item_id: &str, elapsed_ms: u64) -> RobotResponse<serde_json::Value> {
    robot_work_error_response(
        ROBOT_ERR_WORK_ITEM_NOT_FOUND,
        format!("Work item `{item_id}` was not found."),
        Some(
            "Use `ft robot work list` or `ft robot work ready` to inspect native work items."
                .to_string(),
        ),
        elapsed_ms,
    )
}

fn robot_work_conflict(
    item_id: &str,
    reason: &str,
    current_owner: Option<&str>,
    elapsed_ms: u64,
) -> RobotJsonResponse {
    let mut message = format!("Work item `{item_id}` cannot transition: {reason}.");
    if let Some(owner) = current_owner {
        message.push_str(&format!(" Current owner: {owner}."));
    }
    robot_work_error_response(
        ROBOT_ERR_WORK_ITEM_CONFLICT,
        message,
        Some(
            "Inspect the item with `ft robot work list --status claimed` before retrying."
                .to_string(),
        ),
        elapsed_ms,
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RobotWorkPaneLimit {
    reset_at_ms: i64,
    reset_known: bool,
}

fn robot_work_pane_rate_limited(
    item_id: &str,
    pane_id: u64,
    limit: RobotWorkPaneLimit,
    elapsed_ms: u64,
) -> RobotJsonResponse {
    let reset_state = if limit.reset_known {
        "known reset"
    } else {
        "conservative reset estimate"
    };
    robot_work_error_response(
        ROBOT_ERR_PANE_RATE_LIMITED,
        format!(
            "Work item `{item_id}` cannot be assigned to pane {pane_id}: pane has an active limit window ({reset_state} at {}).",
            limit.reset_at_ms
        ),
        Some("Wait for the reset time or assign the work to an unlimited pane.".to_string()),
        elapsed_ms,
    )
}

fn robot_work_validate_id(kind: &str, value: &str, elapsed_ms: u64) -> RobotJsonResult<()> {
    if value.trim().is_empty() {
        return Err(Box::new(robot_work_error_response(
            ROBOT_ERR_INVALID_ARGS,
            format!("{kind} must not be empty."),
            None,
            elapsed_ms,
        )));
    }
    if value.len() > 256 {
        return Err(Box::new(robot_work_error_response(
            ROBOT_ERR_INVALID_ARGS,
            format!("{kind} is too long; maximum is 256 bytes."),
            None,
            elapsed_ms,
        )));
    }
    Ok(())
}

fn robot_work_limit_windows_table_exists(tx: &rusqlite::Transaction<'_>) -> anyhow::Result<bool> {
    tx.query_row(
        "SELECT EXISTS(
            SELECT 1 FROM sqlite_master
            WHERE type = 'table' AND name = 'limit_windows'
        )",
        [],
        |row| row.get::<_, bool>(0),
    )
    .map_err(Into::into)
}

fn robot_work_active_limit_for_pane_tx(
    tx: &rusqlite::Transaction<'_>,
    pane_id: u64,
    now_ms: i64,
) -> anyhow::Result<Option<RobotWorkPaneLimit>> {
    use rusqlite::OptionalExtension as _;

    if !robot_work_limit_windows_table_exists(tx)? {
        return Ok(None);
    }

    let pane_id = robot_work_pane_id_to_i64(pane_id)?;
    tx.query_row(
        "SELECT COALESCE(reset_at, last_seen_at + conservative_ttl_ms) AS effective_reset_at,
                CASE WHEN reset_at IS NULL THEN 0 ELSE 1 END AS reset_known
         FROM limit_windows
         WHERE pane_id = ?1
           AND COALESCE(reset_at, last_seen_at + conservative_ttl_ms) > ?2
         ORDER BY effective_reset_at DESC, last_seen_at DESC
         LIMIT 1",
        rusqlite::params![pane_id, now_ms],
        |row| {
            Ok(RobotWorkPaneLimit {
                reset_at_ms: row.get(0)?,
                reset_known: row.get(1)?,
            })
        },
    )
    .optional()
    .map_err(Into::into)
}

fn robot_work_pane_id_to_i64(pane_id: u64) -> anyhow::Result<i64> {
    i64::try_from(pane_id).map_err(|_| anyhow::anyhow!("pane_id {pane_id} exceeds i64::MAX"))
}

fn robot_work_pane_id_from_agent_id(agent_id: &str) -> Option<u64> {
    agent_id
        .rsplit_once(':')
        .and_then(|(_, pane)| pane.parse::<u64>().ok())
}

fn robot_work_effective_pane_id(
    requested_pane_id: Option<u64>,
    stored_pane_id: Option<u64>,
    agent_id: &str,
) -> Option<u64> {
    requested_pane_id
        .or_else(|| robot_work_pane_id_from_agent_id(agent_id))
        .or(stored_pane_id)
}

fn robot_work_open_conn(db_path: &str) -> anyhow::Result<rusqlite::Connection> {
    let conn = rusqlite::Connection::open(db_path)?;
    conn.busy_timeout(Duration::from_secs(2))?;
    robot_work_ensure_schema(&conn)?;
    Ok(conn)
}

fn robot_work_column_exists(
    conn: &rusqlite::Connection,
    table: &str,
    column: &str,
) -> anyhow::Result<bool> {
    let mut stmt = conn.prepare(&format!("PRAGMA table_info({table})"))?;
    let mut rows = stmt.query([])?;
    while let Some(row) = rows.next()? {
        let name: String = row.get(1)?;
        if name == column {
            return Ok(true);
        }
    }
    Ok(false)
}

fn robot_work_ensure_schema(conn: &rusqlite::Connection) -> anyhow::Result<()> {
    conn.execute_batch(
        r"
        CREATE TABLE IF NOT EXISTS work_claims (
            claim_id TEXT PRIMARY KEY NOT NULL,
            state TEXT NOT NULL CHECK (state IN ('unclaimed', 'claimed', 'completed')),
            owner TEXT,
            pane_id INTEGER,
            priority INTEGER NOT NULL DEFAULT 3,
            labels_json TEXT NOT NULL DEFAULT '[]',
            created_at_ms INTEGER NOT NULL,
            updated_at_ms INTEGER NOT NULL,
            claimed_at_ms INTEGER,
            released_at_ms INTEGER,
            completed_at_ms INTEGER,
            summary TEXT,
            evidence_json TEXT NOT NULL DEFAULT '[]',
            blocked_by_count INTEGER NOT NULL DEFAULT 0,
            unblocks_count INTEGER NOT NULL DEFAULT 0,
            last_reason TEXT,
            assign_strategy TEXT
        );
        CREATE INDEX IF NOT EXISTS idx_work_claims_state ON work_claims(state);
        CREATE INDEX IF NOT EXISTS idx_work_claims_owner ON work_claims(owner);
        ",
    )?;
    if !robot_work_column_exists(conn, "work_claims", "pane_id")? {
        conn.execute_batch("ALTER TABLE work_claims ADD COLUMN pane_id INTEGER;")?;
    }
    conn.execute_batch(
        "CREATE INDEX IF NOT EXISTS idx_work_claims_pane_id ON work_claims(pane_id);",
    )?;
    // ft-tnew9: dependency edges so the work queue's "dependency-aware" fields
    // (blocked_by_count / unblocks_count) carry real data instead of seeded
    // zeros. An edge (claim_id, blocked_by_claim_id) means `claim_id` cannot be
    // worked until `blocked_by_claim_id` completes. Counts are recomputed from
    // this table by `robot_work_recompute_dep_counts`.
    conn.execute_batch(
        r"
        CREATE TABLE IF NOT EXISTS work_claim_deps (
            claim_id TEXT NOT NULL,
            blocked_by_claim_id TEXT NOT NULL,
            PRIMARY KEY (claim_id, blocked_by_claim_id)
        );
        CREATE INDEX IF NOT EXISTS idx_work_claim_deps_blocker
            ON work_claim_deps(blocked_by_claim_id);
        ",
    )?;
    Ok(())
}

/// ft-tnew9: recompute the dependency-aware counts on every `work_claims` row
/// from the `work_claim_deps` edge table and the current item states. An item is
/// "blocked" by each not-yet-`completed` blocker; it "unblocks" each not-yet-
/// `completed` item that lists it as a blocker. Cheap full-table refresh — the
/// robot work queue is small (operator/agent scale, clamped reads at 200).
fn robot_work_recompute_dep_counts(tx: &rusqlite::Transaction<'_>) -> anyhow::Result<()> {
    tx.execute_batch(
        r"
        UPDATE work_claims SET blocked_by_count = (
            SELECT COUNT(*) FROM work_claim_deps d
            JOIN work_claims b ON b.claim_id = d.blocked_by_claim_id
            WHERE d.claim_id = work_claims.claim_id AND b.state != 'completed'
        );
        UPDATE work_claims SET unblocks_count = (
            SELECT COUNT(*) FROM work_claim_deps d
            JOIN work_claims c ON c.claim_id = d.claim_id
            WHERE d.blocked_by_claim_id = work_claims.claim_id AND c.state != 'completed'
        );
        ",
    )?;
    Ok(())
}

fn robot_work_row_from_sql(row: &rusqlite::Row<'_>) -> rusqlite::Result<RobotWorkRow> {
    let pane_id = row
        .get::<_, Option<i64>>(3)?
        .and_then(|value| u64::try_from(value).ok());
    Ok(RobotWorkRow {
        claim_id: row.get(0)?,
        state: row.get(1)?,
        owner: row.get(2)?,
        pane_id,
        priority: row.get(4)?,
        labels_json: row.get(5)?,
        created_at_ms: row.get(6)?,
        updated_at_ms: row.get(7)?,
        claimed_at_ms: row.get(8)?,
        completed_at_ms: row.get(9)?,
        summary: row.get(10)?,
        evidence_json: row.get(11)?,
        blocked_by_count: row.get(12)?,
        unblocks_count: row.get(13)?,
        last_reason: row.get(14)?,
    })
}

const ROBOT_WORK_SELECT_ROW: &str = r"
    SELECT claim_id, state, owner, pane_id, priority, labels_json, created_at_ms, updated_at_ms,
           claimed_at_ms, completed_at_ms, summary, evidence_json, blocked_by_count,
           unblocks_count, last_reason
    FROM work_claims
    WHERE claim_id = ?1
";

fn robot_work_fetch_row_tx(
    tx: &rusqlite::Transaction<'_>,
    item_id: &str,
) -> anyhow::Result<Option<RobotWorkRow>> {
    use rusqlite::OptionalExtension;

    tx.query_row(ROBOT_WORK_SELECT_ROW, [item_id], robot_work_row_from_sql)
        .optional()
        .map_err(Into::into)
}

fn robot_work_parse_string_array(raw: &str) -> Vec<String> {
    serde_json::from_str::<Vec<String>>(raw).unwrap_or_default()
}

fn robot_work_priority(priority: i64) -> u32 {
    u32::try_from(priority).unwrap_or(3)
}

fn robot_work_count(count: i64) -> usize {
    usize::try_from(count).unwrap_or(0)
}

fn robot_work_summary(row: &RobotWorkRow) -> serde_json::Value {
    serde_json::json!({
        "id": row.claim_id,
        "claim_id": row.claim_id,
        "title": row.claim_id,
        "priority": robot_work_priority(row.priority),
        "status": row.state,
        "state": row.state,
        "assigned_to": row.owner,
        "pane_id": row.pane_id,
        "labels": robot_work_parse_string_array(&row.labels_json),
        "blocked_by_count": robot_work_count(row.blocked_by_count),
        "unblocks_count": robot_work_count(row.unblocks_count),
        "created_at_ms": row.created_at_ms,
        "updated_at_ms": row.updated_at_ms,
        "claimed_at_ms": row.claimed_at_ms,
        "completed_at_ms": row.completed_at_ms,
        "summary": row.summary,
        "evidence": robot_work_parse_string_array(&row.evidence_json),
        "last_reason": row.last_reason,
    })
}

fn robot_work_normalize_status_filter(status: Option<&str>) -> Option<String> {
    let status = status?;
    Some(match status.trim().to_ascii_lowercase().as_str() {
        "open" | "ready" | "unclaimed" => "unclaimed".to_string(),
        "in_progress" | "claimed" | "assigned" => "claimed".to_string(),
        "closed" | "done" | "completed" => "completed".to_string(),
        other => other.to_string(),
    })
}

fn robot_work_limit(limit: usize) -> usize {
    limit.clamp(1, 200)
}

fn robot_work_seed_unclaimed_if_missing(
    tx: &rusqlite::Transaction<'_>,
    item_id: &str,
    now_ms: i64,
) -> anyhow::Result<()> {
    tx.execute(
        "INSERT OR IGNORE INTO work_claims
         (claim_id, state, owner, priority, labels_json, created_at_ms, updated_at_ms,
          evidence_json, blocked_by_count, unblocks_count)
         VALUES (?1, 'unclaimed', NULL, 3, '[]', ?2, ?2, '[]', 0, 0)",
        rusqlite::params![item_id, now_ms],
    )?;
    Ok(())
}

fn robot_work_claim_data(
    db_path: &str,
    item_id: &str,
    agent_id: &str,
    pane_id: Option<u64>,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    robot_work_validate_id("item_id", item_id, elapsed_ms)?;
    robot_work_validate_id("agent_id", agent_id, elapsed_ms)?;

    let mut conn =
        robot_work_open_conn(db_path).map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let tx = conn
        .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    let now_ms = now_ms_i64();
    robot_work_seed_unclaimed_if_missing(&tx, item_id, now_ms)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let row = robot_work_fetch_row_tx(&tx, item_id)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?
        .ok_or_else(|| robot_work_not_found(item_id, elapsed_ms))?;
    let effective_pane_id = robot_work_effective_pane_id(pane_id, row.pane_id, agent_id);
    if let Some(pane_id) = effective_pane_id {
        if let Some(limit) = robot_work_active_limit_for_pane_tx(&tx, pane_id, now_ms)
            .map_err(|err| robot_work_backend_error(err, elapsed_ms))?
        {
            return Err(Box::new(robot_work_pane_rate_limited(
                item_id, pane_id, limit, elapsed_ms,
            )));
        }
    }
    let effective_pane_id_sql = effective_pane_id
        .map(robot_work_pane_id_to_i64)
        .transpose()
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    match (row.state.as_str(), row.owner.as_deref()) {
        ("unclaimed", _) => {
            tx.execute(
                "UPDATE work_claims
                 SET state = 'claimed', owner = ?2, claimed_at_ms = ?3, updated_at_ms = ?3,
                     pane_id = ?4, last_reason = NULL
                 WHERE claim_id = ?1",
                rusqlite::params![item_id, agent_id, now_ms, effective_pane_id_sql],
            )
            .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
        }
        ("claimed", Some(owner)) if owner == agent_id => {
            tx.execute(
                "UPDATE work_claims
                 SET pane_id = COALESCE(pane_id, ?2), updated_at_ms = ?3
                 WHERE claim_id = ?1",
                rusqlite::params![item_id, effective_pane_id_sql, now_ms],
            )
            .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
        }
        ("claimed", owner) => {
            return Err(Box::new(robot_work_conflict(
                item_id,
                "already_claimed",
                owner,
                elapsed_ms,
            )));
        }
        ("completed", owner) => {
            return Err(Box::new(robot_work_conflict(
                item_id,
                "already_completed",
                owner,
                elapsed_ms,
            )));
        }
        _ => {
            return Err(Box::new(robot_work_conflict(
                item_id,
                "invalid_state",
                row.owner.as_deref(),
                elapsed_ms,
            )));
        }
    }

    let row = robot_work_fetch_row_tx(&tx, item_id)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?
        .ok_or_else(|| robot_work_not_found(item_id, elapsed_ms))?;
    tx.commit()
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    Ok(serde_json::json!({
        "family": "work",
        "action": "claim",
        "backend": "native_sqlite_work_claims",
        "storage_table": "work_claims",
        "item_id": row.claim_id,
        "claim_id": row.claim_id,
        "agent_id": agent_id,
        "pane_id": row.pane_id,
        "state": row.state,
        "title": row.claim_id,
        "priority": robot_work_priority(row.priority),
        "claimed_at": row.claimed_at_ms.unwrap_or(now_ms),
        "claimed_at_ms": row.claimed_at_ms.unwrap_or(now_ms),
        "audit": {
            "event": "work.claimed",
            "serializable_key": item_id,
        },
    }))
}

fn robot_work_release_data(
    db_path: &str,
    item_id: &str,
    reason: Option<&str>,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    robot_work_validate_id("item_id", item_id, elapsed_ms)?;

    let mut conn =
        robot_work_open_conn(db_path).map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let tx = conn
        .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    let row = robot_work_fetch_row_tx(&tx, item_id)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?
        .ok_or_else(|| robot_work_not_found(item_id, elapsed_ms))?;
    if row.state == "completed" {
        return Err(Box::new(robot_work_conflict(
            item_id,
            "already_completed",
            row.owner.as_deref(),
            elapsed_ms,
        )));
    }

    let now_ms = now_ms_i64();
    tx.execute(
        "UPDATE work_claims
         SET state = 'unclaimed', owner = NULL, released_at_ms = ?2, updated_at_ms = ?2,
             last_reason = ?3
         WHERE claim_id = ?1",
        rusqlite::params![item_id, now_ms, reason],
    )
    .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    tx.commit()
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    Ok(serde_json::json!({
        "family": "work",
        "action": "release",
        "backend": "native_sqlite_work_claims",
        "storage_table": "work_claims",
        "item_id": item_id,
        "claim_id": item_id,
        "new_status": "unclaimed",
        "released_at_ms": now_ms,
        "reason": reason,
        "audit": {
            "event": "work.released",
            "serializable_key": item_id,
        },
    }))
}

/// ft-tnew9: items that are now ready (unclaimed, no remaining open blockers)
/// specifically because `item_id` is one of their blockers. Call after
/// `robot_work_recompute_dep_counts` so `blocked_by_count` is current.
fn robot_work_unblocked_by_tx(
    tx: &rusqlite::Transaction<'_>,
    item_id: &str,
) -> anyhow::Result<Vec<String>> {
    let mut stmt = tx.prepare(
        "SELECT d.claim_id FROM work_claim_deps d
         JOIN work_claims c ON c.claim_id = d.claim_id
         WHERE d.blocked_by_claim_id = ?1 AND c.state = 'unclaimed' AND c.blocked_by_count = 0
         ORDER BY d.claim_id ASC",
    )?;
    let rows = stmt.query_map(rusqlite::params![item_id], |row| row.get::<_, String>(0))?;
    let mut out = Vec::new();
    for row in rows {
        out.push(row?);
    }
    Ok(out)
}

fn robot_work_complete_data(
    db_path: &str,
    item_id: &str,
    summary: Option<&str>,
    evidence: &[String],
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    robot_work_validate_id("item_id", item_id, elapsed_ms)?;

    let mut conn =
        robot_work_open_conn(db_path).map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let tx = conn
        .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    let row = robot_work_fetch_row_tx(&tx, item_id)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?
        .ok_or_else(|| robot_work_not_found(item_id, elapsed_ms))?;
    let already_completed = row.state == "completed";
    let now_ms = row.completed_at_ms.unwrap_or_else(now_ms_i64);
    let evidence_json =
        serde_json::to_string(evidence).map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    if !already_completed {
        tx.execute(
            "UPDATE work_claims
             SET state = 'completed', completed_at_ms = ?2, updated_at_ms = ?2,
                 summary = COALESCE(?3, summary), evidence_json = ?4
             WHERE claim_id = ?1",
            rusqlite::params![item_id, now_ms, summary, evidence_json],
        )
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    }
    // ft-tnew9: completing an item clears it as a blocker — recompute the
    // dependency counts and surface the items that became ready as a result
    // (previously this was a hardcoded empty list).
    robot_work_recompute_dep_counts(&tx)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let unblocked = robot_work_unblocked_by_tx(&tx, item_id)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    tx.commit()
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    Ok(serde_json::json!({
        "family": "work",
        "action": "complete",
        "backend": "native_sqlite_work_claims",
        "storage_table": "work_claims",
        "item_id": item_id,
        "claim_id": item_id,
        "completed_at_ms": now_ms,
        "idempotent_replay": already_completed,
        "unblocked": unblocked,
        "summary": summary,
        "evidence": evidence,
        "audit": {
            "event": if already_completed { "work.completed.replay" } else { "work.completed" },
            "serializable_key": item_id,
        },
    }))
}

fn robot_work_assign_data(
    db_path: &str,
    item_id: &str,
    agent_id: &str,
    pane_id: Option<u64>,
    strategy: Option<&str>,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    robot_work_validate_id("item_id", item_id, elapsed_ms)?;
    robot_work_validate_id("agent_id", agent_id, elapsed_ms)?;

    let strategy_used = strategy.unwrap_or("direct");
    let force = strategy_used.eq_ignore_ascii_case("force");
    let mut conn =
        robot_work_open_conn(db_path).map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let tx = conn
        .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    let now_ms = now_ms_i64();
    robot_work_seed_unclaimed_if_missing(&tx, item_id, now_ms)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let row = robot_work_fetch_row_tx(&tx, item_id)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?
        .ok_or_else(|| robot_work_not_found(item_id, elapsed_ms))?;
    let effective_pane_id = robot_work_effective_pane_id(pane_id, row.pane_id, agent_id);
    if let Some(pane_id) = effective_pane_id {
        if let Some(limit) = robot_work_active_limit_for_pane_tx(&tx, pane_id, now_ms)
            .map_err(|err| robot_work_backend_error(err, elapsed_ms))?
        {
            return Err(Box::new(robot_work_pane_rate_limited(
                item_id, pane_id, limit, elapsed_ms,
            )));
        }
    }
    let effective_pane_id_sql = effective_pane_id
        .map(robot_work_pane_id_to_i64)
        .transpose()
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    if row.state == "completed" {
        return Err(Box::new(robot_work_conflict(
            item_id,
            "already_completed",
            row.owner.as_deref(),
            elapsed_ms,
        )));
    }
    if row.state == "claimed" && row.owner.as_deref() != Some(agent_id) && !force {
        return Err(Box::new(robot_work_conflict(
            item_id,
            "already_claimed",
            row.owner.as_deref(),
            elapsed_ms,
        )));
    }

    tx.execute(
        "UPDATE work_claims
         SET state = 'claimed', owner = ?2, claimed_at_ms = COALESCE(claimed_at_ms, ?3),
             updated_at_ms = ?3, pane_id = ?4, assign_strategy = ?5, last_reason = NULL
         WHERE claim_id = ?1",
        rusqlite::params![
            item_id,
            agent_id,
            now_ms,
            effective_pane_id_sql,
            strategy_used
        ],
    )
    .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    tx.commit()
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    Ok(serde_json::json!({
        "family": "work",
        "action": "assign",
        "backend": "native_sqlite_work_claims",
        "storage_table": "work_claims",
        "item_id": item_id,
        "claim_id": item_id,
        "agent_id": agent_id,
        "pane_id": effective_pane_id,
        "strategy_used": strategy_used,
        "audit": {
            "event": "work.assigned",
            "serializable_key": item_id,
        },
    }))
}

/// ft-tnew9: define (or update) a work item's priority, labels, and dependency
/// edges WITHOUT claiming it, so the queue's dependency-aware surface
/// (`list --label`, priority ordering, `ready` blocked/ready split,
/// `complete` unblocking) operates on real data instead of seeded zeros.
///
/// `blocked_by` replaces the item's edge set (set-semantics): each blocker is
/// seeded if missing, self-edges are skipped, and the counts are recomputed.
/// `priority`/`label` are only written when provided, so a metadata-only update
/// can adjust one facet without clobbering the others.
fn robot_work_define_data(
    db_path: &str,
    item_id: &str,
    priority: Option<i64>,
    labels: Option<&[String]>,
    blocked_by: Option<&[String]>,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    robot_work_validate_id("item_id", item_id, elapsed_ms)?;
    if let Some(blockers) = blocked_by {
        for blocker in blockers {
            robot_work_validate_id("blocked_by", blocker, elapsed_ms)?;
        }
    }

    let mut conn =
        robot_work_open_conn(db_path).map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let tx = conn
        .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    let now_ms = now_ms_i64();
    robot_work_seed_unclaimed_if_missing(&tx, item_id, now_ms)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    if let Some(priority) = priority {
        tx.execute(
            "UPDATE work_claims SET priority = ?2, updated_at_ms = ?3 WHERE claim_id = ?1",
            rusqlite::params![item_id, priority, now_ms],
        )
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    }

    if let Some(labels) = labels {
        let labels_json = serde_json::to_string(labels)
            .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
        tx.execute(
            "UPDATE work_claims SET labels_json = ?2, updated_at_ms = ?3 WHERE claim_id = ?1",
            rusqlite::params![item_id, labels_json, now_ms],
        )
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    }

    if let Some(blockers) = blocked_by {
        // Set-semantics: replace the item's edge set.
        tx.execute(
            "DELETE FROM work_claim_deps WHERE claim_id = ?1",
            rusqlite::params![item_id],
        )
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
        for blocker in blockers {
            // A self-edge would block an item on itself forever; skip it.
            if blocker == item_id {
                continue;
            }
            robot_work_seed_unclaimed_if_missing(&tx, blocker, now_ms)
                .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
            tx.execute(
                "INSERT OR IGNORE INTO work_claim_deps (claim_id, blocked_by_claim_id)
                 VALUES (?1, ?2)",
                rusqlite::params![item_id, blocker],
            )
            .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
        }
    }

    robot_work_recompute_dep_counts(&tx)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    let row = robot_work_fetch_row_tx(&tx, item_id)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?
        .ok_or_else(|| robot_work_not_found(item_id, elapsed_ms))?;
    tx.commit()
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;

    Ok(serde_json::json!({
        "family": "work",
        "action": "define",
        "backend": "native_sqlite_work_claims",
        "storage_table": "work_claims",
        "item_id": item_id,
        "claim_id": item_id,
        "priority": robot_work_priority(row.priority),
        "labels": robot_work_parse_string_array(&row.labels_json),
        "blocked_by_count": robot_work_count(row.blocked_by_count),
        "unblocks_count": robot_work_count(row.unblocks_count),
        "audit": {
            "event": "work.defined",
            "serializable_key": item_id,
        },
    }))
}

fn robot_work_list_rows(
    db_path: &str,
    status: Option<&str>,
    agent: Option<&str>,
    label: Option<&str>,
    limit: usize,
) -> anyhow::Result<(Vec<serde_json::Value>, usize)> {
    let conn = robot_work_open_conn(db_path)?;
    let normalized_status = robot_work_normalize_status_filter(status);
    let limit = robot_work_limit(limit);
    let mut stmt = conn.prepare(
        r"
        SELECT claim_id, state, owner, pane_id, priority, labels_json, created_at_ms, updated_at_ms,
               claimed_at_ms, completed_at_ms, summary, evidence_json, blocked_by_count,
               unblocks_count, last_reason
        FROM work_claims
        ORDER BY priority ASC, updated_at_ms DESC, claim_id ASC
        ",
    )?;
    let rows = stmt.query_map([], robot_work_row_from_sql)?;

    let mut total = 0usize;
    let mut items = Vec::new();
    for row in rows {
        let row = row?;
        if normalized_status
            .as_deref()
            .is_some_and(|status| row.state != status)
        {
            continue;
        }
        if agent.is_some_and(|agent| row.owner.as_deref() != Some(agent)) {
            continue;
        }
        let labels = robot_work_parse_string_array(&row.labels_json);
        if label.is_some_and(|label| !labels.iter().any(|candidate| candidate == label)) {
            continue;
        }
        total += 1;
        if items.len() < limit {
            items.push(robot_work_summary(&row));
        }
    }

    Ok((items, total))
}

fn robot_work_list_data(
    db_path: &str,
    status: Option<&str>,
    agent: Option<&str>,
    label: Option<&str>,
    limit: usize,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    let (items, total) = robot_work_list_rows(db_path, status, agent, label, limit)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    Ok(serde_json::json!({
        "family": "work",
        "action": "list",
        "backend": "native_sqlite_work_claims",
        "storage_table": "work_claims",
        "items": items,
        "total": total,
        "limit": robot_work_limit(limit),
        "filters": {
            "status": robot_work_normalize_status_filter(status),
            "agent": agent,
            "label": label,
        },
    }))
}

fn robot_work_ready_data(
    db_path: &str,
    agent_id: Option<&str>,
    limit: usize,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    let conn =
        robot_work_open_conn(db_path).map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let total_ready: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM work_claims WHERE state = 'unclaimed' AND blocked_by_count = 0",
            [],
            |row| row.get(0),
        )
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let total_blocked: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM work_claims WHERE state = 'unclaimed' AND blocked_by_count > 0",
            [],
            |row| row.get(0),
        )
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    drop(conn);

    let (items, _) = robot_work_list_rows(db_path, Some("unclaimed"), None, None, limit)
        .map_err(|err| robot_work_backend_error(err, elapsed_ms))?;
    let items: Vec<_> = items
        .into_iter()
        .filter(|item| {
            item["blocked_by_count"]
                .as_u64()
                .is_some_and(|count| count == 0)
        })
        .collect();

    Ok(serde_json::json!({
        "family": "work",
        "action": "ready",
        "backend": "native_sqlite_work_claims",
        "storage_table": "work_claims",
        "items": items,
        "total_ready": robot_work_count(total_ready),
        "total_blocked": robot_work_count(total_blocked),
        "agent_id": agent_id,
        "limit": robot_work_limit(limit),
    }))
}

fn robot_work_command_response(
    db_path: &str,
    command: &RobotWorkCommands,
    elapsed_ms: u64,
) -> RobotResponse<serde_json::Value> {
    let result = match command {
        RobotWorkCommands::Claim {
            item_id,
            agent_id,
            pane_id,
        } => robot_work_claim_data(db_path, item_id, agent_id, *pane_id, elapsed_ms),
        RobotWorkCommands::Release { item_id, reason } => {
            robot_work_release_data(db_path, item_id, reason.as_deref(), elapsed_ms)
        }
        RobotWorkCommands::Complete {
            item_id,
            summary,
            evidence,
        } => robot_work_complete_data(
            db_path,
            item_id,
            summary.as_deref(),
            evidence.as_deref().unwrap_or(&[]),
            elapsed_ms,
        ),
        RobotWorkCommands::List {
            status,
            agent,
            label,
            limit,
        } => robot_work_list_data(
            db_path,
            status.as_deref(),
            agent.as_deref(),
            label.as_deref(),
            *limit,
            elapsed_ms,
        ),
        RobotWorkCommands::Ready { agent_id, limit } => {
            robot_work_ready_data(db_path, agent_id.as_deref(), *limit, elapsed_ms)
        }
        RobotWorkCommands::Assign {
            item_id,
            agent_id,
            pane_id,
            strategy,
        } => robot_work_assign_data(
            db_path,
            item_id,
            agent_id,
            *pane_id,
            strategy.as_deref(),
            elapsed_ms,
        ),
        RobotWorkCommands::Define {
            item_id,
            priority,
            label,
            blocked_by,
        } => robot_work_define_data(
            db_path,
            item_id,
            *priority,
            label.as_deref(),
            blocked_by.as_deref(),
            elapsed_ms,
        ),
    };

    match result {
        Ok(data) => RobotResponse::<serde_json::Value>::success(data, elapsed_ms),
        Err(response) => *response,
    }
}

const ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET: i64 = 200_000;

#[derive(Debug, Clone)]
struct RobotContextActiveRow {
    context_id: String,
    depth: i64,
    token_budget: i64,
    tokens_consumed: i64,
}

#[derive(Debug, Clone)]
struct RobotContextRotationRow {
    rotation_id: String,
    pane_id: i64,
    previous_context_id: Option<String>,
    new_context_id: String,
    strategy: String,
    reason: Option<String>,
    caller_idempotency_key: Option<String>,
    rotated_at_ms: i64,
    tokens_before: i64,
    tokens_after: i64,
    tokens_freed: i64,
}

fn robot_context_error_response(
    code: &str,
    message: impl Into<String>,
    hint: Option<String>,
    elapsed_ms: u64,
) -> RobotJsonResponse {
    RobotResponse::<serde_json::Value>::error_with_code(code, message, hint, elapsed_ms)
}

fn robot_context_backend_error(err: impl std::fmt::Display, elapsed_ms: u64) -> RobotJsonResponse {
    robot_context_error_response(
        ROBOT_ERR_STORAGE,
        format!("Failed to update native context registry: {err}"),
        Some("Check the workspace database path and permissions.".to_string()),
        elapsed_ms,
    )
}

fn robot_context_validate_text(
    field: &str,
    value: Option<&str>,
    elapsed_ms: u64,
) -> RobotJsonResult<()> {
    let Some(value) = value else {
        return Ok(());
    };
    if value.trim().is_empty() {
        return Err(Box::new(robot_context_error_response(
            ROBOT_ERR_INVALID_ARGS,
            format!("{field} must not be empty when supplied."),
            None,
            elapsed_ms,
        )));
    }
    if value.len() > 256 {
        return Err(Box::new(robot_context_error_response(
            ROBOT_ERR_INVALID_ARGS,
            format!("{field} is too long; maximum is 256 bytes."),
            None,
            elapsed_ms,
        )));
    }
    Ok(())
}

fn robot_context_open_conn(db_path: &str) -> anyhow::Result<rusqlite::Connection> {
    let conn = rusqlite::Connection::open(db_path)?;
    conn.busy_timeout(Duration::from_secs(2))?;
    robot_context_ensure_schema(&conn)?;
    Ok(conn)
}

fn robot_context_ensure_schema(conn: &rusqlite::Connection) -> anyhow::Result<()> {
    conn.execute_batch(
        r"
        CREATE TABLE IF NOT EXISTS pane_contexts (
            context_id TEXT PRIMARY KEY NOT NULL,
            pane_id INTEGER NOT NULL,
            state TEXT NOT NULL CHECK (state IN ('active', 'archived')),
            depth INTEGER NOT NULL CHECK (depth >= 0),
            created_at_ms INTEGER NOT NULL,
            archived_at_ms INTEGER,
            token_budget INTEGER NOT NULL DEFAULT 200000,
            tokens_consumed INTEGER NOT NULL DEFAULT 0,
            pressure_tier TEXT NOT NULL DEFAULT 'green',
            source TEXT NOT NULL DEFAULT 'robot_context'
        );
        CREATE UNIQUE INDEX IF NOT EXISTS idx_pane_contexts_one_active
            ON pane_contexts(pane_id)
            WHERE state = 'active';
        CREATE INDEX IF NOT EXISTS idx_pane_contexts_pane_state
            ON pane_contexts(pane_id, state);

        CREATE TABLE IF NOT EXISTS context_rotations (
            rotation_id TEXT PRIMARY KEY NOT NULL,
            pane_id INTEGER NOT NULL,
            previous_context_id TEXT,
            new_context_id TEXT NOT NULL,
            strategy TEXT NOT NULL,
            reason TEXT,
            caller_idempotency_key TEXT,
            rotated_at_ms INTEGER NOT NULL,
            tokens_before INTEGER NOT NULL DEFAULT 0,
            tokens_after INTEGER NOT NULL DEFAULT 0,
            tokens_freed INTEGER NOT NULL DEFAULT 0,
            created_at_ms INTEGER NOT NULL,
            FOREIGN KEY(previous_context_id) REFERENCES pane_contexts(context_id),
            FOREIGN KEY(new_context_id) REFERENCES pane_contexts(context_id)
        );
        CREATE INDEX IF NOT EXISTS idx_context_rotations_pane_time
            ON context_rotations(pane_id, rotated_at_ms DESC);
        CREATE UNIQUE INDEX IF NOT EXISTS idx_context_rotations_idempotency
            ON context_rotations(pane_id, caller_idempotency_key)
            WHERE caller_idempotency_key IS NOT NULL;
        ",
    )?;
    Ok(())
}

fn robot_context_active_row_from_sql(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<RobotContextActiveRow> {
    Ok(RobotContextActiveRow {
        context_id: row.get(0)?,
        depth: row.get(1)?,
        token_budget: row.get(2)?,
        tokens_consumed: row.get(3)?,
    })
}

fn robot_context_rotation_row_from_sql(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<RobotContextRotationRow> {
    Ok(RobotContextRotationRow {
        rotation_id: row.get(0)?,
        pane_id: row.get(1)?,
        previous_context_id: row.get(2)?,
        new_context_id: row.get(3)?,
        strategy: row.get(4)?,
        reason: row.get(5)?,
        caller_idempotency_key: row.get(6)?,
        rotated_at_ms: row.get(7)?,
        tokens_before: row.get(8)?,
        tokens_after: row.get(9)?,
        tokens_freed: row.get(10)?,
    })
}

const ROBOT_CONTEXT_SELECT_ACTIVE: &str = r"
    SELECT context_id, depth, token_budget, tokens_consumed
    FROM pane_contexts
    WHERE pane_id = ?1 AND state = 'active'
";

const ROBOT_CONTEXT_SELECT_ROTATION: &str = r"
    SELECT rotation_id, pane_id, previous_context_id, new_context_id, strategy, reason,
           caller_idempotency_key, rotated_at_ms, tokens_before, tokens_after, tokens_freed
    FROM context_rotations
";

fn robot_context_fetch_active_tx(
    tx: &rusqlite::Transaction<'_>,
    pane_id: u64,
) -> anyhow::Result<Option<RobotContextActiveRow>> {
    use rusqlite::OptionalExtension;

    tx.query_row(
        ROBOT_CONTEXT_SELECT_ACTIVE,
        [pane_id as i64],
        robot_context_active_row_from_sql,
    )
    .optional()
    .map_err(Into::into)
}

fn robot_context_fetch_active(
    conn: &rusqlite::Connection,
    pane_id: u64,
) -> anyhow::Result<Option<RobotContextActiveRow>> {
    use rusqlite::OptionalExtension;

    conn.query_row(
        ROBOT_CONTEXT_SELECT_ACTIVE,
        [pane_id as i64],
        robot_context_active_row_from_sql,
    )
    .optional()
    .map_err(Into::into)
}

fn robot_context_fetch_rotation_by_key_tx(
    tx: &rusqlite::Transaction<'_>,
    pane_id: u64,
    idempotency_key: &str,
) -> anyhow::Result<Option<RobotContextRotationRow>> {
    use rusqlite::OptionalExtension;

    let sql = format!(
        "{ROBOT_CONTEXT_SELECT_ROTATION}
         WHERE pane_id = ?1 AND caller_idempotency_key = ?2
         ORDER BY rotated_at_ms DESC
         LIMIT 1"
    );
    tx.query_row(
        &sql,
        rusqlite::params![pane_id as i64, idempotency_key],
        robot_context_rotation_row_from_sql,
    )
    .optional()
    .map_err(Into::into)
}

fn robot_context_normalize_strategy(
    strategy: &str,
    elapsed_ms: u64,
) -> RobotJsonResult<&'static str> {
    match strategy.trim().to_ascii_lowercase().as_str() {
        "agent_default" | "default" | "agent-default" => Ok("agent_default"),
        "aggressive" => Ok("aggressive"),
        "gentle" => Ok("gentle"),
        other => Err(Box::new(robot_context_error_response(
            ROBOT_ERR_INVALID_ARGS,
            format!("Unknown context rotation strategy `{other}`."),
            Some("Use one of: agent_default, aggressive, gentle.".to_string()),
            elapsed_ms,
        ))),
    }
}

fn robot_context_hash(parts: &[&str]) -> String {
    use sha2::{Digest, Sha256};

    let mut hasher = Sha256::new();
    for part in parts {
        hasher.update((part.len() as u64).to_be_bytes());
        hasher.update(part.as_bytes());
    }
    hex::encode(hasher.finalize())
}

fn robot_context_make_id(prefix: &str, parts: &[&str]) -> String {
    let hash = robot_context_hash(parts);
    format!("{prefix}-{}", &hash[..32])
}

fn robot_context_limit(limit: usize) -> usize {
    limit.clamp(1, 200)
}

fn robot_context_utilization(tokens_consumed: i64, token_budget: i64) -> f64 {
    if token_budget <= 0 {
        return if tokens_consumed <= 0 { 0.0 } else { 1.0 };
    }
    ((tokens_consumed.max(0) as f64) / (token_budget as f64)).min(1.0)
}

/// Classify context-window pressure from utilization (ft-mhq10).
///
/// `pressure_tier` is *derived* from real utilization here rather than read
/// from a stored column that the rotate seed hardcoded to `green`. Combined
/// with the `report` writer (which records real `tokens_consumed`), this makes
/// the surfaced tier track actual usage instead of being permanently green.
fn robot_context_pressure_tier(utilization: f64) -> &'static str {
    // Half-open bands: green < 0.6 <= yellow < 0.8 <= red < 0.95 <= black.
    if utilization >= 0.95 {
        "black"
    } else if utilization >= 0.8 {
        "red"
    } else if utilization >= 0.6 {
        "yellow"
    } else {
        "green"
    }
}

fn robot_context_status_for_pane(
    conn: &rusqlite::Connection,
    pane_id: u64,
    now_ms: i64,
) -> anyhow::Result<serde_json::Value> {
    use rusqlite::OptionalExtension;

    let active = robot_context_fetch_active(conn, pane_id)?;
    let depth: i64 = conn.query_row(
        "SELECT COUNT(*) FROM context_rotations WHERE pane_id = ?1",
        [pane_id as i64],
        |row| row.get(0),
    )?;
    let last_rotated_at_ms: Option<i64> = conn
        .query_row(
            "SELECT rotated_at_ms FROM context_rotations
             WHERE pane_id = ?1
             ORDER BY rotated_at_ms DESC
             LIMIT 1",
            [pane_id as i64],
            |row| row.get(0),
        )
        .optional()?;

    let (active_context_id, token_budget, tokens_consumed, active_depth) = active.map_or_else(
        || (String::new(), ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET, 0, depth),
        |row| {
            (
                row.context_id,
                row.token_budget,
                row.tokens_consumed,
                row.depth,
            )
        },
    );
    let utilization = robot_context_utilization(tokens_consumed, token_budget);
    // Derive the tier from live utilization (ft-mhq10): the stored column was
    // a permanent `green` seed, so trusting it made fleet pressure always green.
    let pressure_tier = robot_context_pressure_tier(utilization);
    let ms_since_last_compaction =
        last_rotated_at_ms.map(|last| now_ms.saturating_sub(last).max(0) as u64);
    let active_context_present = !active_context_id.is_empty();

    Ok(serde_json::json!({
        "pane_id": pane_id,
        "active_context_id": active_context_id,
        "active_context_present": active_context_present,
        "depth": depth.max(active_depth),
        "last_rotated_at_ms": last_rotated_at_ms,
        "pressure_tier": pressure_tier,
        "utilization": utilization,
        "tokens_consumed": tokens_consumed.max(0) as u64,
        "token_budget": token_budget.max(0) as u64,
        "compaction_count": depth.max(0) as u64,
        "ms_since_last_compaction": ms_since_last_compaction,
        "raw_context_content_stored": false,
    }))
}

fn robot_context_fleet_pressure(panes: &[serde_json::Value]) -> serde_json::Value {
    let mut green_count = 0usize;
    let mut yellow_count = 0usize;
    let mut red_count = 0usize;
    let mut black_count = 0usize;

    for pane in panes {
        match pane["pressure_tier"].as_str().unwrap_or("green") {
            "black" => black_count += 1,
            "red" => red_count += 1,
            "yellow" => yellow_count += 1,
            _ => green_count += 1,
        }
    }

    serde_json::json!({
        "total_panes": panes.len(),
        "green_count": green_count,
        "yellow_count": yellow_count,
        "red_count": red_count,
        "black_count": black_count,
    })
}

fn robot_context_status_data(
    db_path: &str,
    pane_id: Option<u64>,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    let conn = robot_context_open_conn(db_path)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    let now_ms = now_ms_i64();
    let panes = if let Some(pane_id) = pane_id {
        vec![
            robot_context_status_for_pane(&conn, pane_id, now_ms)
                .map_err(|err| robot_context_backend_error(err, elapsed_ms))?,
        ]
    } else {
        let mut stmt = conn
            .prepare("SELECT DISTINCT pane_id FROM pane_contexts ORDER BY pane_id")
            .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
        let pane_ids = stmt
            .query_map([], |row| row.get::<_, i64>(0))
            .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
        let mut panes = Vec::new();
        for pane_id in pane_ids {
            let pane_id = pane_id.map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
            panes.push(
                robot_context_status_for_pane(&conn, pane_id.max(0) as u64, now_ms)
                    .map_err(|err| robot_context_backend_error(err, elapsed_ms))?,
            );
        }
        panes
    };
    let fleet_pressure = robot_context_fleet_pressure(&panes);

    Ok(serde_json::json!({
        "family": "context",
        "action": "status",
        "backend": "native_sqlite_context",
        "storage_tables": ["pane_contexts", "context_rotations"],
        "scope": if pane_id.is_some() { "pane" } else { "tracked_panes" },
        "panes": panes,
        "fleet_pressure": fleet_pressure,
        "raw_context_content_stored": false,
    }))
}

fn robot_context_horizon_data(
    db_path: &str,
    pane_id: Option<u64>,
    horizon_window_ms: Option<u64>,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    let horizon_window_ms = horizon_window_ms.unwrap_or(15 * 60 * 1000);
    if horizon_window_ms == 0 {
        return Err(Box::new(robot_context_error_response(
            ROBOT_ERR_INVALID_ARGS,
            "horizon_window_ms must be greater than zero.",
            Some("Omit --horizon-window-ms to use the default 15 minute forecast.".to_string()),
            elapsed_ms,
        )));
    }

    let report = predict_context_horizon_from_sqlite(
        Path::new(db_path),
        pane_id,
        now_ms(),
        horizon_window_ms,
        "robot.context.horizon",
    )
    .map_err(|err| {
        robot_context_error_response(
            ROBOT_ERR_STORAGE,
            format!("Failed to build context horizon: {err}"),
            Some(
                "Check the workspace database path; the context horizon read path is non-mutating."
                    .to_string(),
            ),
            elapsed_ms,
        )
    })?;

    serde_json::to_value(report).map_err(|err| {
        Box::new(robot_context_error_response(
            "robot.serialization_error",
            format!("Failed to serialize context horizon: {err}"),
            None,
            elapsed_ms,
        ))
    })
}

fn robot_context_rotation_response(
    row: &RobotContextRotationRow,
    is_replay: bool,
) -> serde_json::Value {
    let utilization_before =
        robot_context_utilization(row.tokens_before, ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET);
    let utilization_after =
        robot_context_utilization(row.tokens_after, ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET);

    serde_json::json!({
        "family": "context",
        "action": "rotate",
        "backend": "native_sqlite_context",
        "storage_tables": ["pane_contexts", "context_rotations"],
        "pane_id": row.pane_id.max(0) as u64,
        "accepted": true,
        "reason": row.reason.clone(),
        "rotation_id": row.rotation_id.clone(),
        "previous_context_id": row.previous_context_id.clone(),
        "new_context_id": row.new_context_id.clone(),
        "rotated_at_ms": row.rotated_at_ms.max(0) as u64,
        "is_replay": is_replay,
        "strategy": row.strategy.clone(),
        "caller_idempotency_key_present": row.caller_idempotency_key.is_some(),
        "tokens_before": row.tokens_before.max(0) as u64,
        "tokens_after": row.tokens_after.max(0) as u64,
        "tokens_freed": row.tokens_freed.max(0) as u64,
        "utilization_before": utilization_before,
        "utilization_after": utilization_after,
        "raw_context_content_stored": false,
        "audit": {
            "event": if is_replay { "context.rotated.replay" } else { "context.rotated" },
            "serializable_key": format!("pane:{}", row.pane_id.max(0)),
        },
    })
}

fn robot_context_rotate_data(
    db_path: &str,
    pane_id: u64,
    strategy: &str,
    reason: Option<&str>,
    idempotency_key: Option<&str>,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    robot_context_validate_text("reason", reason, elapsed_ms)?;
    robot_context_validate_text("idempotency_key", idempotency_key, elapsed_ms)?;
    let strategy = robot_context_normalize_strategy(strategy, elapsed_ms)?;

    let mut conn = robot_context_open_conn(db_path)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    let tx = conn
        .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;

    if let Some(key) = idempotency_key {
        if let Some(existing) = robot_context_fetch_rotation_by_key_tx(&tx, pane_id, key)
            .map_err(|err| robot_context_backend_error(err, elapsed_ms))?
        {
            tx.commit()
                .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
            return Ok(robot_context_rotation_response(&existing, true));
        }
    }

    let now_ms = now_ms_i64();
    let active = robot_context_fetch_active_tx(&tx, pane_id)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    let previous_context_id = active.as_ref().map(|row| row.context_id.clone());
    let previous_depth = active.as_ref().map_or(0, |row| row.depth);
    let tokens_before = active.as_ref().map_or(0, |row| row.tokens_consumed.max(0));
    let new_depth = previous_depth.saturating_add(1);

    let pane_s = pane_id.to_string();
    let now_string = now_ms.to_string();
    let depth_s = new_depth.to_string();
    let previous_s = previous_context_id.as_deref().unwrap_or("");
    let key_s = idempotency_key.unwrap_or("");
    let strategy_s = strategy;
    let new_context_id = robot_context_make_id(
        "ctx",
        &[&pane_s, &now_string, &depth_s, previous_s, strategy_s],
    );
    let rotation_id = robot_context_make_id(
        "rot",
        &[
            &pane_s,
            &now_string,
            &depth_s,
            previous_s,
            &new_context_id,
            key_s,
        ],
    );

    if let Some(previous) = previous_context_id.as_deref() {
        tx.execute(
            "UPDATE pane_contexts
             SET state = 'archived', archived_at_ms = ?2
             WHERE context_id = ?1 AND state = 'active'",
            rusqlite::params![previous, now_ms],
        )
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    }

    tx.execute(
        "INSERT INTO pane_contexts
         (context_id, pane_id, state, depth, created_at_ms, token_budget, tokens_consumed,
          pressure_tier, source)
         VALUES (?1, ?2, 'active', ?3, ?4, ?5, 0, 'green', 'robot_context')",
        rusqlite::params![
            &new_context_id,
            pane_id as i64,
            new_depth,
            now_ms,
            ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET,
        ],
    )
    .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;

    tx.execute(
        "INSERT INTO context_rotations
         (rotation_id, pane_id, previous_context_id, new_context_id, strategy, reason,
         caller_idempotency_key, rotated_at_ms, tokens_before, tokens_after, tokens_freed,
          created_at_ms)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9, 0, ?9, ?8)",
        rusqlite::params![
            &rotation_id,
            pane_id as i64,
            previous_context_id.as_deref(),
            &new_context_id,
            strategy,
            reason,
            idempotency_key,
            now_ms,
            tokens_before,
        ],
    )
    .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;

    let row = tx
        .query_row(
            &format!("{ROBOT_CONTEXT_SELECT_ROTATION} WHERE rotation_id = ?1"),
            rusqlite::params![&rotation_id],
            robot_context_rotation_row_from_sql,
        )
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    tx.commit()
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;

    Ok(robot_context_rotation_response(&row, false))
}

/// Record real per-pane context token consumption (ft-mhq10).
///
/// This is the production writer that was missing: the only prior writer of
/// `pane_contexts` was the rotate seed, which hardcoded `tokens_consumed=0` /
/// `pressure_tier='green'` and never updated them, so `context status` reported
/// permanently-green canned data. `report` UPDATEs the active context's
/// `tokens_consumed` and recomputes `pressure_tier` from utilization. If the
/// pane has no active context yet, a depth-0 active context is seeded so a pane
/// can report pressure without an explicit rotate first.
fn robot_context_report_data(
    db_path: &str,
    pane_id: u64,
    tokens_consumed: u64,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    let mut conn = robot_context_open_conn(db_path)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    let tx = conn
        .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;

    let now_ms = now_ms_i64();
    let tokens_i64 = i64::try_from(tokens_consumed).unwrap_or(i64::MAX);

    let active = robot_context_fetch_active_tx(&tx, pane_id)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    let (context_id, token_budget, depth) = if let Some(row) = active {
        (row.context_id, row.token_budget, row.depth)
    } else {
        let pane_s = pane_id.to_string();
        let now_string = now_ms.to_string();
        let context_id = robot_context_make_id("ctx", &[&pane_s, &now_string, "0", "", "report"]);
        tx.execute(
            "INSERT INTO pane_contexts
             (context_id, pane_id, state, depth, created_at_ms, token_budget, tokens_consumed,
              pressure_tier, source)
             VALUES (?1, ?2, 'active', 0, ?3, ?4, 0, 'green', 'robot_context_report')",
            rusqlite::params![
                &context_id,
                pane_id as i64,
                now_ms,
                ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET,
            ],
        )
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
        (context_id, ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET, 0)
    };

    let utilization = robot_context_utilization(tokens_i64, token_budget);
    let pressure_tier = robot_context_pressure_tier(utilization);

    tx.execute(
        "UPDATE pane_contexts
         SET tokens_consumed = ?2, pressure_tier = ?3
         WHERE context_id = ?1 AND state = 'active'",
        rusqlite::params![&context_id, tokens_i64, pressure_tier],
    )
    .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;

    tx.commit()
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;

    Ok(serde_json::json!({
        "family": "context",
        "action": "report",
        "backend": "native_sqlite_context",
        "storage_tables": ["pane_contexts"],
        "pane_id": pane_id,
        "active_context_id": context_id,
        "depth": depth.max(0) as u64,
        "tokens_consumed": tokens_consumed,
        "token_budget": token_budget.max(0) as u64,
        "utilization": utilization,
        "pressure_tier": pressure_tier,
        "raw_context_content_stored": false,
    }))
}

fn robot_context_history_data(
    db_path: &str,
    pane_id: u64,
    limit: usize,
    elapsed_ms: u64,
) -> RobotJsonResult<serde_json::Value> {
    let conn = robot_context_open_conn(db_path)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    let limit = robot_context_limit(limit);
    let total: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM context_rotations WHERE pane_id = ?1",
            [pane_id as i64],
            |row| row.get(0),
        )
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;

    let sql = format!(
        "{ROBOT_CONTEXT_SELECT_ROTATION}
         WHERE pane_id = ?1
         ORDER BY rotated_at_ms DESC, rotation_id DESC
         LIMIT ?2"
    );
    let mut stmt = conn
        .prepare(&sql)
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    let rows = stmt
        .query_map(
            rusqlite::params![pane_id as i64, limit as i64],
            robot_context_rotation_row_from_sql,
        )
        .map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
    let mut rotations = Vec::new();
    let mut events = Vec::new();
    for row in rows {
        let row = row.map_err(|err| robot_context_backend_error(err, elapsed_ms))?;
        let utilization_before =
            robot_context_utilization(row.tokens_before, ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET);
        let utilization_after =
            robot_context_utilization(row.tokens_after, ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET);
        events.push(serde_json::json!({
            "timestamp_ms": row.rotated_at_ms.max(0) as u64,
            "utilization_before": utilization_before,
            "utilization_after": utilization_after,
            "tokens_freed": row.tokens_freed.max(0) as u64,
            "trigger": row.strategy.clone(),
        }));
        rotations.push(serde_json::json!({
            "rotation_id": row.rotation_id,
            "pane_id": row.pane_id.max(0) as u64,
            "previous_context_id": row.previous_context_id,
            "new_context_id": row.new_context_id,
            "rotated_at_ms": row.rotated_at_ms.max(0) as u64,
            "strategy": row.strategy,
            "reason": row.reason,
            "caller_idempotency_key_present": row.caller_idempotency_key.is_some(),
            "tokens_before": row.tokens_before.max(0) as u64,
            "tokens_after": row.tokens_after.max(0) as u64,
            "tokens_freed": row.tokens_freed.max(0) as u64,
        }));
    }

    Ok(serde_json::json!({
        "family": "context",
        "action": "history",
        "backend": "native_sqlite_context",
        "storage_tables": ["pane_contexts", "context_rotations"],
        "pane_id": pane_id,
        "limit": limit,
        "total": total.max(0) as u64,
        "truncated": total > limit as i64,
        "rotations": rotations,
        "events": events,
        "raw_context_content_stored": false,
    }))
}

fn robot_context_command_response(
    db_path: &str,
    command: &RobotContextCommands,
    elapsed_ms: u64,
) -> RobotResponse<serde_json::Value> {
    let result = match command {
        RobotContextCommands::Status { pane_id } => {
            robot_context_status_data(db_path, *pane_id, elapsed_ms)
        }
        RobotContextCommands::Horizon {
            pane_id,
            horizon_window_ms,
        } => robot_context_horizon_data(db_path, *pane_id, *horizon_window_ms, elapsed_ms),
        RobotContextCommands::Rotate {
            pane_id,
            strategy,
            reason,
            idempotency_key,
        } => robot_context_rotate_data(
            db_path,
            *pane_id,
            strategy,
            reason.as_deref(),
            idempotency_key.as_deref(),
            elapsed_ms,
        ),
        RobotContextCommands::History { pane_id, limit } => {
            robot_context_history_data(db_path, *pane_id, *limit, elapsed_ms)
        }
        RobotContextCommands::Report {
            pane_id,
            tokens_consumed,
        } => robot_context_report_data(db_path, *pane_id, *tokens_consumed, elapsed_ms),
    };

    match result {
        Ok(data) => RobotResponse::<serde_json::Value>::success(data, elapsed_ms),
        Err(response) => *response,
    }
}

#[cfg(test)]
mod robot_context_backend_tests {
    use super::*;

    fn setup_robot_context_test_db() -> (tempfile::TempDir, String) {
        let dir = tempfile::tempdir().expect("create robot context tempdir");
        let db_path = dir.path().join("robot-context.db");
        (dir, db_path.to_string_lossy().to_string())
    }

    fn context_rotation_count(db_path: &str, pane_id: u64) -> i64 {
        let conn = robot_context_open_conn(db_path).expect("open context db");
        conn.query_row(
            "SELECT COUNT(*) FROM context_rotations WHERE pane_id = ?1",
            [pane_id as i64],
            |row| row.get(0),
        )
        .expect("count context rotations")
    }

    fn expect_context_ok(result: RobotJsonResult<serde_json::Value>) -> serde_json::Value {
        match result {
            Ok(value) => value,
            Err(response) => panic!(
                "expected context success, got {}",
                serde_json::to_string(&*response).expect("serialize context response")
            ),
        }
    }

    fn expect_context_error(result: RobotJsonResult<serde_json::Value>) -> RobotJsonResponse {
        match result {
            Ok(value) => panic!("expected context error, got success {value}"),
            Err(response) => *response,
        }
    }

    #[test]
    fn robot_context_status_history_empty_and_populated() {
        let (_dir, db_path) = setup_robot_context_test_db();

        let empty_status = expect_context_ok(robot_context_status_data(&db_path, Some(7), 5));
        assert_eq!(empty_status["family"].as_str(), Some("context"));
        assert_eq!(empty_status["action"].as_str(), Some("status"));
        assert_eq!(empty_status["panes"][0]["pane_id"].as_u64(), Some(7));
        assert_eq!(empty_status["panes"][0]["depth"].as_u64(), Some(0));
        assert_eq!(
            empty_status["panes"][0]["active_context_present"].as_bool(),
            Some(false)
        );

        let empty_history = expect_context_ok(robot_context_history_data(&db_path, 7, 10, 5));
        assert_eq!(empty_history["total"].as_u64(), Some(0));
        assert_eq!(empty_history["events"].as_array().unwrap().len(), 0);

        let rotate = expect_context_ok(robot_context_rotate_data(
            &db_path,
            7,
            "gentle",
            Some("manual compaction"),
            None,
            5,
        ));
        assert_eq!(rotate["family"].as_str(), Some("context"));
        assert_eq!(rotate["action"].as_str(), Some("rotate"));
        assert_eq!(rotate["accepted"].as_bool(), Some(true));
        assert_eq!(rotate["strategy"].as_str(), Some("gentle"));
        assert_eq!(rotate["is_replay"].as_bool(), Some(false));
        assert!(
            rotate["rotation_id"]
                .as_str()
                .is_some_and(|id| id.starts_with("rot-"))
        );
        assert!(
            rotate["new_context_id"]
                .as_str()
                .is_some_and(|id| id.starts_with("ctx-"))
        );

        let status = expect_context_ok(robot_context_status_data(&db_path, Some(7), 5));
        assert_eq!(status["panes"][0]["depth"].as_u64(), Some(1));
        assert_eq!(
            status["panes"][0]["active_context_present"].as_bool(),
            Some(true)
        );
        assert_eq!(status["fleet_pressure"]["total_panes"].as_u64(), Some(1));

        let fleet = expect_context_ok(robot_context_status_data(&db_path, None, 5));
        assert_eq!(fleet["scope"].as_str(), Some("tracked_panes"));
        assert_eq!(fleet["panes"].as_array().unwrap().len(), 1);

        let history = expect_context_ok(robot_context_history_data(&db_path, 7, 10, 5));
        assert_eq!(history["total"].as_u64(), Some(1));
        assert_eq!(history["truncated"].as_bool(), Some(false));
        assert_eq!(history["rotations"][0]["strategy"].as_str(), Some("gentle"));
        assert_eq!(history["events"][0]["trigger"].as_str(), Some("gentle"));
    }

    #[test]
    fn robot_context_pressure_tier_classifies_utilization_bands() {
        // ft-mhq10: tier is derived from utilization, not a stored constant.
        assert_eq!(robot_context_pressure_tier(0.0), "green");
        assert_eq!(robot_context_pressure_tier(0.59), "green");
        assert_eq!(robot_context_pressure_tier(0.6), "yellow");
        assert_eq!(robot_context_pressure_tier(0.79), "yellow");
        assert_eq!(robot_context_pressure_tier(0.8), "red");
        assert_eq!(robot_context_pressure_tier(0.94), "red");
        assert_eq!(robot_context_pressure_tier(0.95), "black");
        assert_eq!(robot_context_pressure_tier(1.0), "black");
    }

    #[test]
    fn robot_context_report_updates_tokens_and_drives_pressure_tier() {
        // ft-mhq10: before this fix the only writer seeded tokens_consumed=0 /
        // pressure_tier='green' and never updated them, so status was always
        // green. `report` is the missing UPDATE path; status must now reflect
        // the reported usage and a derived (non-green) tier.
        let (_dir, db_path) = setup_robot_context_test_db();

        // No active context yet: report seeds one and records usage.
        let budget = ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET as u64; // 200_000
        let report = expect_context_ok(robot_context_report_data(
            &db_path,
            7,
            budget * 85 / 100, // 85% -> red
            5,
        ));
        assert_eq!(report["action"].as_str(), Some("report"));
        assert_eq!(report["pane_id"].as_u64(), Some(7));
        assert_eq!(report["pressure_tier"].as_str(), Some("red"));
        assert!((report["utilization"].as_f64().unwrap() - 0.85).abs() < 1e-9);

        // Status now surfaces the real, non-green signal (the bug was that it
        // was permanently 0/green).
        let status = expect_context_ok(robot_context_status_data(&db_path, Some(7), 5));
        let pane = &status["panes"][0];
        assert_eq!(pane["tokens_consumed"].as_u64(), Some(budget * 85 / 100));
        assert_eq!(pane["pressure_tier"].as_str(), Some("red"));
        assert!((pane["utilization"].as_f64().unwrap() - 0.85).abs() < 1e-9);
        // Fleet pressure reflects the red pane rather than counting it green.
        assert_eq!(status["fleet_pressure"]["red_count"].as_u64(), Some(1));
        assert_eq!(status["fleet_pressure"]["green_count"].as_u64(), Some(0));

        // A subsequent report UPDATEs the same active context in place.
        let lower = expect_context_ok(robot_context_report_data(&db_path, 7, budget / 2, 5));
        assert_eq!(lower["pressure_tier"].as_str(), Some("green")); // 50% -> green
        let status2 = expect_context_ok(robot_context_status_data(&db_path, Some(7), 5));
        assert_eq!(
            status2["panes"][0]["tokens_consumed"].as_u64(),
            Some(budget / 2)
        );
        assert_eq!(status2["panes"][0]["pressure_tier"].as_str(), Some("green"));
        // depth unchanged: report does not rotate.
        assert_eq!(status2["panes"][0]["depth"].as_u64(), Some(0));
    }

    #[test]
    fn robot_context_report_after_rotate_updates_active_context() {
        // report must target the active (post-rotate) context and survive a
        // status read with the derived tier.
        let (_dir, db_path) = setup_robot_context_test_db();
        expect_context_ok(robot_context_rotate_data(
            &db_path,
            3,
            "agent_default",
            None,
            None,
            5,
        ));
        let budget = ROBOT_CONTEXT_DEFAULT_TOKEN_BUDGET as u64;
        expect_context_ok(robot_context_report_data(&db_path, 3, budget, 5)); // 100% -> black

        let status = expect_context_ok(robot_context_status_data(&db_path, Some(3), 5));
        let pane = &status["panes"][0];
        assert_eq!(pane["depth"].as_u64(), Some(1)); // the rotation is intact
        assert_eq!(pane["pressure_tier"].as_str(), Some("black"));
        assert!((pane["utilization"].as_f64().unwrap() - 1.0).abs() < 1e-9);
    }

    #[test]
    fn robot_context_rotate_idempotency_key_replays_without_second_row() {
        let (_dir, db_path) = setup_robot_context_test_db();

        let first = expect_context_ok(robot_context_rotate_data(
            &db_path,
            42,
            "agent_default",
            Some("first"),
            Some("caller-key-1"),
            9,
        ));
        let second = expect_context_ok(robot_context_rotate_data(
            &db_path,
            42,
            "aggressive",
            Some("retry"),
            Some("caller-key-1"),
            9,
        ));

        assert_eq!(first["rotation_id"], second["rotation_id"]);
        assert_eq!(second["is_replay"].as_bool(), Some(true));
        assert_eq!(
            second["caller_idempotency_key_present"].as_bool(),
            Some(true)
        );
        assert_eq!(context_rotation_count(&db_path, 42), 1);

        let third = expect_context_ok(robot_context_rotate_data(
            &db_path,
            42,
            "aggressive",
            None,
            Some("caller-key-2"),
            9,
        ));
        assert_ne!(first["rotation_id"], third["rotation_id"]);
        assert_eq!(third["is_replay"].as_bool(), Some(false));
        assert_eq!(context_rotation_count(&db_path, 42), 2);
    }

    #[test]
    fn robot_context_horizon_emits_v1_contract_without_mutation() {
        let (_dir, db_path) = setup_robot_context_test_db();
        let conn = robot_context_open_conn(&db_path).expect("open context db");
        conn.execute(
            "CREATE TABLE events (
                id INTEGER PRIMARY KEY,
                pane_id INTEGER NOT NULL,
                rule_id TEXT NOT NULL,
                event_type TEXT NOT NULL,
                detected_at INTEGER NOT NULL
            )",
            [],
        )
        .expect("create events table");
        conn.execute(
            "INSERT INTO pane_contexts
             (context_id, pane_id, state, depth, created_at_ms, token_budget,
              tokens_consumed, pressure_tier, source)
             VALUES ('ctx-horizon', 9, 'active', 1, ?1, 1000, 910, 'yellow',
                     'test')",
            [now_ms_i64().saturating_sub(1_000)],
        )
        .expect("insert active context");
        conn.execute(
            "INSERT INTO events (pane_id, rule_id, event_type, detected_at)
             VALUES (9, 'codex.usage.limit', 'rate_limit', ?1)",
            [now_ms_i64().saturating_sub(500)],
        )
        .expect("insert event");
        drop(conn);

        let horizon = expect_context_ok(robot_context_horizon_data(
            &db_path,
            Some(9),
            Some(60_000),
            13,
        ));
        assert_eq!(
            horizon["contract_id"].as_str(),
            Some("ft.context_horizon.v1")
        );
        assert_eq!(horizon["source"].as_str(), Some("robot.context.horizon"));
        assert_eq!(horizon["raw_context_content_stored"].as_bool(), Some(false));
        assert_eq!(horizon["pane_risks"][0]["pane_id"].as_u64(), Some(9));
        assert!(
            horizon["pane_risks"][0]["reason_codes"]
                .as_array()
                .unwrap()
                .iter()
                .any(|reason| reason.as_str() == Some("provider.rate_limit_recent"))
        );
        assert!(
            horizon["recommendations"]
                .as_array()
                .unwrap()
                .iter()
                .all(|row| row["mutation_allowed"].as_bool() == Some(false))
        );

        let response = RobotResponse::success(horizon, 13);
        let encoded = toon_rust::encode(serde_json::to_value(&response).unwrap(), None);
        assert!(encoded.contains("pane_risks"));
        assert!(encoded.contains("reason_codes"));
        assert!(encoded.contains("raw_context_content_stored"));
        let decoded_toon = toon_rust::try_decode(&encoded, None).expect("decode horizon toon");
        let decoded_json =
            toon_rust::cli::json_stringify::json_stringify_lines(&decoded_toon, 0).join("\n");
        let decoded: serde_json::Value =
            serde_json::from_str(&decoded_json).expect("horizon toon roundtrip json");
        assert_eq!(
            decoded["data"]["contract_id"].as_str(),
            Some("ft.context_horizon.v1")
        );
        assert!(decoded["data"]["pane_risks"][0]["reason_codes"][0].is_string());
    }

    #[test]
    fn robot_context_horizon_rejects_zero_window() {
        let (_dir, db_path) = setup_robot_context_test_db();
        let error = expect_context_error(robot_context_horizon_data(&db_path, None, Some(0), 13));
        assert_eq!(error.error_code.as_deref(), Some(ROBOT_ERR_INVALID_ARGS));
    }

    #[test]
    fn robot_context_history_is_bounded_and_strategy_is_validated() {
        let (_dir, db_path) = setup_robot_context_test_db();

        for strategy in ["agent_default", "gentle", "aggressive"] {
            expect_context_ok(robot_context_rotate_data(
                &db_path, 3, strategy, None, None, 11,
            ));
        }

        let history = expect_context_ok(robot_context_history_data(&db_path, 3, 2, 11));
        assert_eq!(history["total"].as_u64(), Some(3));
        assert_eq!(history["limit"].as_u64(), Some(2));
        assert_eq!(history["truncated"].as_bool(), Some(true));
        assert_eq!(history["rotations"].as_array().unwrap().len(), 2);

        let invalid = expect_context_error(robot_context_rotate_data(
            &db_path, 3, "surprise", None, None, 11,
        ));
        assert_eq!(invalid.error_code.as_deref(), Some(ROBOT_ERR_INVALID_ARGS));
    }
}

#[cfg(test)]
mod robot_work_backend_tests {
    use std::sync::{Arc, Barrier};

    use super::*;

    fn temp_work_db() -> (tempfile::TempDir, String) {
        let dir = tempfile::tempdir().expect("create work backend tempdir");
        let db_path = dir.path().join("ft.db");
        let db_path = db_path.to_string_lossy().to_string();
        let conn = robot_work_open_conn(&db_path).expect("initialize work backend schema");
        drop(conn);
        (dir, db_path)
    }

    fn expect_ok(result: RobotJsonResult<serde_json::Value>) -> serde_json::Value {
        match result {
            Ok(value) => value,
            Err(response) => panic!(
                "expected success, got {}",
                serde_json::to_string(&*response).expect("serialize response")
            ),
        }
    }

    fn expect_error_code(result: RobotJsonResult<serde_json::Value>, expected_code: &str) {
        match result {
            Ok(value) => panic!("expected {expected_code}, got success {value}"),
            Err(response) => {
                let value = serde_json::to_value(&*response).expect("serialize response");
                assert_eq!(value["error_code"].as_str(), Some(expected_code));
            }
        }
    }

    fn seed_active_limit_window(db_path: &str, pane_id: u64, reset_at_ms: i64) {
        let conn = rusqlite::Connection::open(db_path).expect("open test db");
        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS limit_windows (
                pane_id INTEGER NOT NULL,
                reset_at INTEGER,
                last_seen_at INTEGER NOT NULL,
                conservative_ttl_ms INTEGER NOT NULL
            );",
        )
        .expect("create limit_windows fixture");
        conn.execute(
            "INSERT INTO limit_windows
             (pane_id, reset_at, last_seen_at, conservative_ttl_ms)
             VALUES (?1, ?2, ?3, ?4)",
            rusqlite::params![
                robot_work_pane_id_to_i64(pane_id).expect("pane id fits"),
                reset_at_ms,
                reset_at_ms - 1_000,
                300_000_i64
            ],
        )
        .expect("insert limit window fixture");
    }

    #[test]
    fn work_claim_rejects_competing_owner_and_preserves_original_claim() {
        let (_dir, db_path) = temp_work_db();

        let first = expect_ok(robot_work_claim_data(
            &db_path,
            "ft-work-a",
            "agent-a",
            None,
            0,
        ));
        assert_eq!(first["state"], "claimed");
        assert_eq!(first["agent_id"], "agent-a");

        expect_error_code(
            robot_work_claim_data(&db_path, "ft-work-a", "agent-b", None, 0),
            ROBOT_ERR_WORK_ITEM_CONFLICT,
        );

        let list = expect_ok(robot_work_list_data(
            &db_path,
            Some("claimed"),
            Some("agent-a"),
            None,
            10,
            0,
        ));
        assert_eq!(list["total"], 1);
        assert_eq!(list["items"][0]["claim_id"], "ft-work-a");
        assert_eq!(list["items"][0]["assigned_to"], "agent-a");
    }

    #[test]
    fn work_claim_infers_and_lists_pane_id_from_agent_owner() {
        let (_dir, db_path) = temp_work_db();

        let claimed = expect_ok(robot_work_claim_data(
            &db_path,
            "ft-pane-a",
            "codex:42",
            None,
            0,
        ));
        assert_eq!(claimed["pane_id"].as_u64(), Some(42));

        let list = expect_ok(robot_work_list_data(
            &db_path,
            Some("claimed"),
            Some("codex:42"),
            None,
            10,
            0,
        ));
        assert_eq!(list["items"][0]["pane_id"].as_u64(), Some(42));
    }

    #[test]
    fn work_assign_declines_active_pane_limit_without_seeding_or_claiming() {
        let (_dir, db_path) = temp_work_db();
        seed_active_limit_window(&db_path, 7, now_ms_i64() + 60_000);

        expect_error_code(
            robot_work_assign_data(
                &db_path,
                "ft-limited-pane",
                "codex:7",
                Some(7),
                Some("direct"),
                0,
            ),
            ROBOT_ERR_PANE_RATE_LIMITED,
        );

        let ready = expect_ok(robot_work_ready_data(&db_path, Some("codex:7"), 10, 0));
        assert_eq!(ready["total_ready"], 0);
        assert_eq!(ready["items"], serde_json::json!([]));
    }

    #[test]
    fn work_release_complete_and_ready_use_durable_states() {
        let (_dir, db_path) = temp_work_db();

        expect_ok(robot_work_assign_data(
            &db_path,
            "ft-ready-a",
            "agent-a",
            None,
            Some("direct"),
            0,
        ));
        expect_ok(robot_work_release_data(
            &db_path,
            "ft-ready-a",
            Some("handoff"),
            0,
        ));
        let ready = expect_ok(robot_work_ready_data(&db_path, Some("agent-b"), 10, 0));
        assert_eq!(ready["total_ready"], 1);
        assert_eq!(ready["items"][0]["state"], "unclaimed");

        expect_ok(robot_work_claim_data(
            &db_path,
            "ft-ready-a",
            "agent-b",
            None,
            0,
        ));
        let completed = expect_ok(robot_work_complete_data(
            &db_path,
            "ft-ready-a",
            Some("shipped"),
            &["abc123".to_string()],
            0,
        ));
        assert_eq!(completed["action"], "complete");
        assert_eq!(completed["idempotent_replay"], false);

        let replay = expect_ok(robot_work_complete_data(
            &db_path,
            "ft-ready-a",
            Some("shipped again"),
            &[],
            0,
        ));
        assert_eq!(replay["idempotent_replay"], true);
        expect_error_code(
            robot_work_release_data(&db_path, "ft-ready-a", None, 0),
            ROBOT_ERR_WORK_ITEM_CONFLICT,
        );
    }

    #[test]
    fn fleet_reassign_work_updates_owner_and_can_compensate_back() {
        let (_dir, db_path) = temp_work_db();
        expect_ok(robot_work_assign_data(
            &db_path,
            "ft-rebalance-a",
            "codex:1",
            None,
            Some("seed"),
            0,
        ));

        let moved = robot_fleet_reassign_work(
            &db_path,
            "ft-rebalance-a",
            Some("codex:1"),
            "codex:2",
            "load_based",
        )
        .expect("reassign work");
        assert_eq!(moved.work_item_id.as_deref(), Some("ft-rebalance-a"));
        assert_eq!(
            moved.details.get("from_agent").map(String::as_str),
            Some("codex:1")
        );
        assert_eq!(
            moved.details.get("to_agent").map(String::as_str),
            Some("codex:2")
        );

        let moved_list = expect_ok(robot_work_list_data(
            &db_path,
            Some("claimed"),
            Some("codex:2"),
            None,
            10,
            0,
        ));
        assert_eq!(moved_list["total"], 1);
        assert_eq!(moved_list["items"][0]["assigned_to"], "codex:2");

        robot_fleet_reassign_work(
            &db_path,
            "ft-rebalance-a",
            Some("codex:2"),
            "codex:1",
            "rollback load_based",
        )
        .expect("compensate reassignment");
        let restored = expect_ok(robot_work_list_data(
            &db_path,
            Some("claimed"),
            Some("codex:1"),
            None,
            10,
            0,
        ));
        assert_eq!(restored["total"], 1);
        assert_eq!(restored["items"][0]["assigned_to"], "codex:1");
    }

    #[test]
    fn work_claim_is_serialized_for_concurrent_callers() {
        let (_dir, db_path) = temp_work_db();
        let db_path = Arc::new(db_path);
        let barrier = Arc::new(Barrier::new(2));
        let mut handles = Vec::new();

        for agent in ["agent-a", "agent-b"] {
            let db_path = Arc::clone(&db_path);
            let barrier = Arc::clone(&barrier);
            let agent = agent.to_string();
            handles.push(std::thread::spawn(move || {
                barrier.wait();
                robot_work_claim_data(db_path.as_str(), "ft-race", &agent, None, 0).is_ok()
            }));
        }

        let successes = handles
            .into_iter()
            .map(|handle| handle.join().expect("thread joins"))
            .filter(|success| *success)
            .count();
        assert_eq!(successes, 1);

        let claimed = expect_ok(robot_work_list_data(
            db_path.as_str(),
            Some("claimed"),
            None,
            None,
            10,
            0,
        ));
        assert_eq!(claimed["total"], 1);
    }
}

fn parse_accounts_caut_service(service: &str) -> Option<frankenterm_core::caut::CautService> {
    frankenterm_core::caut::CautService::from_cli_input(service)
}

fn canonical_accounts_service_key(service: &str) -> String {
    parse_accounts_caut_service(service).map_or_else(
        || service.trim().to_string(),
        |parsed| parsed.as_str().to_string(),
    )
}

fn supported_accounts_services_hint() -> String {
    format!(
        "Supported services: {}",
        frankenterm_core::caut::CautService::supported_cli_inputs().join(", ")
    )
}

/// Parse a human-friendly duration string into milliseconds.
///
/// Supports: "30s", "5m", "1h", "7d", "2w". Returns `None` if the format is invalid.
fn parse_duration_to_ms(s: &str) -> Option<i64> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }
    let (num_str, suffix) = s.split_at(s.len().saturating_sub(1));
    let value: i64 = num_str.parse().ok()?;
    if value < 0 {
        return None;
    }
    let multiplier: i64 = match suffix {
        "s" => 1_000,
        "m" => 60_000,
        "h" => 3_600_000,
        "d" => 86_400_000,
        "w" => 604_800_000,
        _ => return None,
    };
    value.checked_mul(multiplier)
}

fn add_duration_to_timestamp_ms(now_ms: i64, duration_ms: i64) -> Option<i64> {
    if duration_ms < 0 {
        return None;
    }
    now_ms.checked_add(duration_ms)
}

fn parse_prepare_output_format(
    format: &str,
) -> anyhow::Result<frankenterm_core::output::OutputFormat> {
    use frankenterm_core::output::{OutputFormat, detect_format};

    const MAX_OUTPUT_FORMAT_BYTES: usize = 16;
    if format.is_empty() || format.len() > MAX_OUTPUT_FORMAT_BYTES {
        return Err(anyhow::anyhow!(
            "Unknown output format. Use auto, plain, or json."
        ));
    }
    if format.eq_ignore_ascii_case("json") {
        Ok(OutputFormat::Json)
    } else if format.eq_ignore_ascii_case("plain") {
        Ok(OutputFormat::Plain)
    } else if format.eq_ignore_ascii_case("auto") {
        Ok(detect_format())
    } else {
        Err(anyhow::anyhow!(
            "Unknown output format. Use auto, plain, or json."
        ))
    }
}

fn resolve_prepare_output_format(format: &str) -> frankenterm_core::output::OutputFormat {
    match parse_prepare_output_format(format) {
        Ok(format) => format,
        Err(error) => {
            eprintln!("Error: {error}");
            std::process::exit(1);
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SnapshotSessionOutputFormat {
    Plain,
    Json,
    Toon,
}

impl SnapshotSessionOutputFormat {
    fn is_structured(self) -> bool {
        matches!(self, Self::Json | Self::Toon)
    }
}

fn parse_snapshot_session_output_format(
    format: &str,
) -> anyhow::Result<SnapshotSessionOutputFormat> {
    use frankenterm_core::output::{OutputFormat, detect_format};

    const MAX_OUTPUT_FORMAT_BYTES: usize = 16;
    if format.is_empty() || format.len() > MAX_OUTPUT_FORMAT_BYTES {
        return Err(anyhow::anyhow!(
            "Unknown output format. Use auto, plain, json, or toon."
        ));
    }
    if format.eq_ignore_ascii_case("json") {
        Ok(SnapshotSessionOutputFormat::Json)
    } else if format.eq_ignore_ascii_case("plain") {
        Ok(SnapshotSessionOutputFormat::Plain)
    } else if format.eq_ignore_ascii_case("toon") {
        Ok(SnapshotSessionOutputFormat::Toon)
    } else if format.eq_ignore_ascii_case("auto") {
        match detect_format() {
            OutputFormat::Json => Ok(SnapshotSessionOutputFormat::Json),
            _ => Ok(SnapshotSessionOutputFormat::Plain),
        }
    } else {
        Err(anyhow::anyhow!(
            "Unknown output format. Use auto, plain, json, or toon."
        ))
    }
}

fn resolve_snapshot_session_output_format(format: &str) -> SnapshotSessionOutputFormat {
    match parse_snapshot_session_output_format(format) {
        Ok(format) => format,
        Err(err) => {
            eprintln!("Error: {err}");
            std::process::exit(1);
        }
    }
}

fn format_snapshot_session_structured_output<T: serde::Serialize>(
    payload: &T,
    format: SnapshotSessionOutputFormat,
) -> anyhow::Result<Option<String>> {
    match format {
        SnapshotSessionOutputFormat::Plain => Ok(None),
        SnapshotSessionOutputFormat::Json => Ok(Some(serde_json::to_string_pretty(payload)?)),
        SnapshotSessionOutputFormat::Toon => Ok(Some(toon_rust::encode(
            serde_json::to_value(payload)?,
            None,
        ))),
    }
}

fn print_snapshot_session_structured_output<T: serde::Serialize>(
    payload: &T,
    format: SnapshotSessionOutputFormat,
) -> anyhow::Result<bool> {
    if let Some(rendered) = format_snapshot_session_structured_output(payload, format)? {
        let stdout = std::io::stdout();
        let mut stdout = stdout.lock();
        writeln!(stdout, "{rendered}")?;
        stdout.flush()?;
        return Ok(true);
    }

    Ok(false)
}

fn trace_bounded_cli_internal_error(
    operation: &'static str,
    error: &(impl std::fmt::Display + ?Sized),
) {
    let detail = bounded_display_diagnostic("", error, 512, 512);
    tracing::warn!(operation, detail = %detail, "bounded CLI operation failed");
}

fn emit_snapshot_session_error(
    output_format: SnapshotSessionOutputFormat,
    error_code: &'static str,
    message: &'static str,
) -> anyhow::Result<()> {
    if !print_snapshot_session_structured_output(
        &serde_json::json!({
            "ok": false,
            "error_code": error_code,
            "error": message,
        }),
        output_format,
    )? {
        eprintln!("{message}");
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CheckpointResolveScope {
    Snapshot,
    Any,
}

const MAX_CHECKPOINT_RESOLVE_ID_BYTES: usize = 64;

fn parse_bounded_checkpoint_id(value: &str) -> Option<i64> {
    if value.len() > MAX_CHECKPOINT_RESOLVE_ID_BYTES {
        return None;
    }
    value.parse::<i64>().ok().filter(|id| *id > 0)
}

#[derive(Debug)]
enum CheckpointResolveError {
    InvalidId,
    NotFound {
        requested_latest: bool,
        scope: CheckpointResolveScope,
    },
    WrongRole {
        checkpoint_id: i64,
        role: String,
    },
    InvalidStoredRole {
        checkpoint_id: i64,
    },
    Database(rusqlite::Error),
}

impl std::fmt::Display for CheckpointResolveError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidId => formatter.write_str("Invalid snapshot ID."),
            Self::NotFound {
                requested_latest,
                scope,
            } => match (*requested_latest, scope) {
                (true, CheckpointResolveScope::Snapshot) => formatter
                    .write_str("No snapshots found. Capture one first with `ft snapshot save`."),
                (true, CheckpointResolveScope::Any) => formatter.write_str("No checkpoints found."),
                (false, CheckpointResolveScope::Snapshot) => {
                    formatter.write_str("The requested snapshot checkpoint was not found.")
                }
                (false, CheckpointResolveScope::Any) => {
                    formatter.write_str("The requested checkpoint was not found.")
                }
            },
            Self::WrongRole {
                checkpoint_id,
                role,
            } => write!(
                formatter,
                "Checkpoint `{checkpoint_id}` has role `{role}` and cannot be used as a snapshot."
            ),
            Self::InvalidStoredRole { checkpoint_id } => write!(
                formatter,
                "Checkpoint `{checkpoint_id}` has an invalid persisted role."
            ),
            Self::Database(error) => write!(formatter, "Failed to query checkpoints: {error}"),
        }
    }
}

impl std::error::Error for CheckpointResolveError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Database(error) => Some(error),
            Self::InvalidId
            | Self::NotFound { .. }
            | Self::WrongRole { .. }
            | Self::InvalidStoredRole { .. } => None,
        }
    }
}

fn checkpoint_resolve_cli_contract(error: &CheckpointResolveError) -> (&'static str, &'static str) {
    match error {
        CheckpointResolveError::InvalidId => (
            "invalid_snapshot_id",
            "Invalid snapshot ID; expected latest or a positive decimal integer of at most 64 bytes.",
        ),
        CheckpointResolveError::NotFound { .. } => (
            "snapshot_not_found",
            "The requested snapshot was not found.",
        ),
        CheckpointResolveError::WrongRole { .. } => (
            "invalid_checkpoint_role",
            "The requested checkpoint is not a snapshot.",
        ),
        CheckpointResolveError::InvalidStoredRole { .. } | CheckpointResolveError::Database(_) => (
            "checkpoint_resolution_failed",
            "Snapshot checkpoint resolution failed.",
        ),
    }
}

/// Run a synchronous CLI database or short filesystem operation without
/// occupying the async worker. The explicit caller context preserves
/// cancellation and budget propagation. Write-like callers must arrange
/// reconciliation for effects that may settle after mid-flight cancellation;
/// operation-lock acquisition is paired with blocking-pool cleanup below.
async fn run_cli_blocking_with_cx<T, F>(
    cx: &frankenterm_core::cx::Cx,
    operation: &'static str,
    work: F,
) -> anyhow::Result<T>
where
    T: Send + 'static,
    F: FnOnce() -> anyhow::Result<T> + Send + 'static,
{
    frankenterm_core::runtime_async::spawn_blocking_with_cx(cx, work)
        .await
        .map_err(|error| {
            anyhow::anyhow!(
                "{operation} cancelled or failed at the blocking-runtime boundary: {error}"
            )
        })?
}

/// Run a synchronous filesystem effect to an explicit completion receipt.
///
/// Caller cancellation is an admissibility check only before dispatch. Once
/// the blocking closure is admitted, this boundary deliberately does not race
/// its join receipt against the caller Cx: an atomic rename or directory fsync
/// may already have happened, so returning early would turn a settled effect
/// into an ambiguous lost reply.
async fn run_cli_settled_blocking_effect<T, F>(
    cx: &frankenterm_core::cx::Cx,
    operation: &'static str,
    work: F,
) -> anyhow::Result<T>
where
    T: Send + 'static,
    F: FnOnce() -> anyhow::Result<T> + Send + 'static,
{
    anyhow::ensure!(
        cx.checkpoint().is_ok(),
        "{operation} was cancelled before its first filesystem mutation"
    );
    frankenterm_core::runtime_async::spawn_blocking(work)
        .await
        .map_err(|_| anyhow::anyhow!("{operation} failed at the settled blocking boundary"))?
}

async fn check_watcher_running_with_cx(
    cx: &frankenterm_core::cx::Cx,
    lock_path: PathBuf,
    operation: &'static str,
) -> anyhow::Result<frankenterm_core::lock::LockStatus> {
    run_cli_blocking_with_cx(cx, operation, move || {
        Ok(frankenterm_core::lock::check_running(&lock_path))
    })
    .await
}

const WATCHER_CONTROL_QUEUE_CAPACITY: usize = 8;
const WATCHER_CONTROL_REQUEST_TIMEOUT: Duration = Duration::from_secs(2);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WatcherControlAuthSelection {
    Unauthenticated,
    Environment,
    Configured(usize),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WatcherControlRequestFailure {
    IpcDisabled,
    NoWriteCredential,
    NoExecutionBudget,
    Cancelled,
    TimedOut,
    Transport,
    Rejected,
    InvalidAcknowledgement,
}

impl std::fmt::Display for WatcherControlRequestFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let message = match self {
            Self::IpcDisabled => "watcher IPC is disabled by configuration",
            Self::NoWriteCredential => "no current IPC credential authorizes watcher control",
            Self::NoExecutionBudget => "watcher control has no execution budget",
            Self::Cancelled => "watcher control was cancelled",
            Self::TimedOut => "watcher control timed out",
            Self::Transport => "watcher control transport failed",
            Self::Rejected => "watcher rejected the control request",
            Self::InvalidAcknowledgement => "watcher returned an invalid control acknowledgement",
        };
        formatter.write_str(message)
    }
}

fn ipc_token_allows_watcher_control(
    token: &frankenterm_core::config::IpcAuthToken,
    now_ms: u64,
) -> bool {
    !token.token.is_empty()
        && token
            .expires_at_ms
            .is_none_or(|expires_at| now_ms < expires_at)
        && (token.scopes.is_empty()
            || token
                .scopes
                .iter()
                .copied()
                .any(|scope| scope.allows(frankenterm_core::config::IpcScope::Write)))
}

fn select_watcher_control_auth(
    ipc: &frankenterm_core::config::IpcConfig,
    environment_token: Option<&str>,
    now_ms: u64,
) -> Result<WatcherControlAuthSelection, WatcherControlRequestFailure> {
    if !ipc.enabled {
        return Err(WatcherControlRequestFailure::IpcDisabled);
    }

    let environment_token = environment_token.filter(|token| !token.is_empty());
    if ipc.tokens.is_empty() {
        return Ok(if environment_token.is_some() {
            WatcherControlAuthSelection::Environment
        } else {
            WatcherControlAuthSelection::Unauthenticated
        });
    }

    if let Some(presented) = environment_token
        && ipc.tokens.iter().any(|candidate| {
            candidate.token == presented && ipc_token_allows_watcher_control(candidate, now_ms)
        })
    {
        return Ok(WatcherControlAuthSelection::Environment);
    }

    ipc.tokens
        .iter()
        .position(|candidate| ipc_token_allows_watcher_control(candidate, now_ms))
        .map(WatcherControlAuthSelection::Configured)
        .ok_or(WatcherControlRequestFailure::NoWriteCredential)
}

#[derive(Debug, serde::Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct WatcherControlAcknowledgement {
    accepted: bool,
    action: frankenterm_core::ipc::WatcherControlAction,
    instance_id: String,
}

fn validate_watcher_control_acknowledgement(
    response: &frankenterm_core::ipc::IpcResponse,
    expected_action: frankenterm_core::ipc::WatcherControlAction,
    expected_instance_id: &str,
) -> Result<(), WatcherControlRequestFailure> {
    if !response.ok {
        return Err(WatcherControlRequestFailure::Rejected);
    }
    let acknowledgement = response
        .data
        .clone()
        .ok_or(WatcherControlRequestFailure::InvalidAcknowledgement)
        .and_then(|data| {
            serde_json::from_value::<WatcherControlAcknowledgement>(data)
                .map_err(|_| WatcherControlRequestFailure::InvalidAcknowledgement)
        })?;
    if !acknowledgement.accepted
        || acknowledgement.action != expected_action
        || acknowledgement.instance_id != expected_instance_id
    {
        return Err(WatcherControlRequestFailure::InvalidAcknowledgement);
    }
    Ok(())
}

fn admit_watcher_control(
    expected_instance_id: &str,
    invocation: frankenterm_core::ipc::IpcWatcherControlInvocation,
    control_tx: &frankenterm_core::runtime_async::mpsc::Sender<
        frankenterm_core::ipc::WatcherControlAction,
    >,
) -> frankenterm_core::ipc::IpcResponse {
    let frankenterm_core::ipc::IpcWatcherControlInvocation {
        control,
        request_id: _,
    } = invocation;
    if control.expected_instance_id != expected_instance_id {
        return frankenterm_core::ipc::IpcResponse::error_with_code(
            "ipc.watcher_control.instance_mismatch",
            "Watcher control request did not match this watcher instance",
            None,
        );
    }

    match control_tx.try_send(control.action) {
        Ok(()) => frankenterm_core::ipc::IpcResponse::ok_with_data(serde_json::json!({
            "accepted": true,
            "action": control.action,
            "instance_id": expected_instance_id,
        })),
        Err(frankenterm_core::runtime_async::mpsc::SendError::Full(_)) => {
            frankenterm_core::ipc::IpcResponse::error_with_code(
                "ipc.watcher_control.queue_full",
                "Watcher control queue is full",
                None,
            )
        }
        Err(
            frankenterm_core::runtime_async::mpsc::SendError::Disconnected(_)
            | frankenterm_core::runtime_async::mpsc::SendError::Cancelled(_),
        ) => frankenterm_core::ipc::IpcResponse::error_with_code(
            "ipc.watcher_control.unavailable",
            "Watcher control queue is unavailable",
            None,
        ),
    }
}

fn build_watcher_control_handler(
    expected_instance_id: String,
    control_tx: frankenterm_core::runtime_async::mpsc::Sender<
        frankenterm_core::ipc::WatcherControlAction,
    >,
) -> frankenterm_core::ipc::IpcWatcherControlHandler {
    Arc::new(move |invocation| {
        let response = admit_watcher_control(&expected_instance_id, invocation, &control_tx);
        Box::pin(async move { response })
    })
}

#[cfg(any(unix, windows))]
async fn request_watcher_control_with_cx(
    cx: &frankenterm_core::cx::Cx,
    socket_path: &Path,
    ipc: &frankenterm_core::config::IpcConfig,
    action: frankenterm_core::ipc::WatcherControlAction,
    expected_instance_id: &str,
    timeout: Duration,
) -> Result<(), WatcherControlRequestFailure> {
    if timeout.is_zero() {
        return Err(WatcherControlRequestFailure::NoExecutionBudget);
    }
    if cx.checkpoint().is_err() {
        return Err(WatcherControlRequestFailure::Cancelled);
    }

    let environment_token = std::env::var("FT_IPC_TOKEN").ok();
    let auth_selection = select_watcher_control_auth(ipc, environment_token.as_deref(), now_ms())?;
    let client = match auth_selection {
        WatcherControlAuthSelection::Environment => {
            frankenterm_core::ipc::IpcClient::new(socket_path)
        }
        WatcherControlAuthSelection::Configured(index) => {
            frankenterm_core::ipc::IpcClient::with_token(
                socket_path,
                ipc.tokens[index].token.clone(),
            )
        }
        WatcherControlAuthSelection::Unauthenticated => {
            let mut client = frankenterm_core::ipc::IpcClient::new(socket_path);
            client.set_token(None);
            client
        }
    };
    let control = frankenterm_core::ipc::WatcherControlRequest {
        action,
        expected_instance_id: expected_instance_id.to_string(),
    };

    let response = match frankenterm_core::runtime_async::timeout_with_cx(
        cx,
        timeout,
        client.watcher_control_with_cx(cx, control, None),
    )
    .await
    {
        Ok(Ok(response)) => response,
        Ok(Err(_)) => {
            return Err(if cx.checkpoint().is_err() {
                WatcherControlRequestFailure::Cancelled
            } else {
                WatcherControlRequestFailure::Transport
            });
        }
        Err(_) => {
            return Err(if cx.checkpoint().is_err() {
                WatcherControlRequestFailure::Cancelled
            } else {
                WatcherControlRequestFailure::TimedOut
            });
        }
    };
    validate_watcher_control_acknowledgement(&response, action, expected_instance_id)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WatcherStopSettlement {
    Stopped,
    StillHeld,
    ProbeUnavailable,
}

const fn classify_watcher_stop_settlement(
    status: &frankenterm_core::lock::LockStatus,
) -> WatcherStopSettlement {
    match status {
        frankenterm_core::lock::LockStatus::Free => WatcherStopSettlement::Stopped,
        frankenterm_core::lock::LockStatus::HeldKnown(_)
        | frankenterm_core::lock::LockStatus::HeldUnknown => WatcherStopSettlement::StillHeld,
        frankenterm_core::lock::LockStatus::ProbeUnavailable => {
            WatcherStopSettlement::ProbeUnavailable
        }
    }
}

fn same_watcher_identity(
    status: &frankenterm_core::lock::LockStatus,
    expected: &frankenterm_core::lock::LockMetadata,
) -> bool {
    matches!(
        status,
        frankenterm_core::lock::LockStatus::HeldKnown(current)
            if current.instance_id == expected.instance_id && current.pid == expected.pid
    )
}

fn watcher_lock_diagnostic_check(status: &frankenterm_core::lock::LockStatus) -> DiagnosticCheck {
    match status {
        frankenterm_core::lock::LockStatus::HeldKnown(meta) => {
            DiagnosticCheck::ok_with_detail("daemon status", format!("running (PID {})", meta.pid))
        }
        frankenterm_core::lock::LockStatus::Free => {
            DiagnosticCheck::ok_with_detail("daemon status", "not running; watcher lock is free")
        }
        frankenterm_core::lock::LockStatus::HeldUnknown => DiagnosticCheck::warning(
            "daemon status",
            "watcher lock is held; holder identity metadata is unavailable",
            "Restore exact lock-holder authority before using instance-bound cooperative control",
        ),
        frankenterm_core::lock::LockStatus::ProbeUnavailable => DiagnosticCheck::warning(
            "daemon status",
            "watcher lock status could not be probed safely",
            "Review the configured lock and parent directory permissions",
        ),
    }
}

fn open_cli_read_only_connection(db_path: &str) -> rusqlite::Result<rusqlite::Connection> {
    let conn = rusqlite::Connection::open_with_flags(
        db_path,
        rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY | rusqlite::OpenFlags::SQLITE_OPEN_NO_MUTEX,
    )?;
    conn.busy_timeout(std::time::Duration::from_secs(5))?;
    Ok(conn)
}

fn resolve_checkpoint_id(
    db_path: &str,
    snapshot_id: &str,
    scope: CheckpointResolveScope,
) -> Result<i64, CheckpointResolveError> {
    if snapshot_id.len() > MAX_CHECKPOINT_RESOLVE_ID_BYTES {
        return Err(CheckpointResolveError::InvalidId);
    }
    if snapshot_id.eq_ignore_ascii_case("latest") {
        let conn =
            open_cli_read_only_connection(db_path).map_err(CheckpointResolveError::Database)?;
        let latest_id = match scope {
            CheckpointResolveScope::Snapshot => conn.query_row(
                "SELECT id
                 FROM session_checkpoints
                 WHERE checkpoint_role = 'snapshot' AND id > 0
                 ORDER BY CASE
                              WHEN typeof(checkpoint_at) = 'integer'
                               AND checkpoint_at >= 0
                              THEN checkpoint_at
                          END DESC,
                          id DESC
                 LIMIT 1",
                [],
                |row| row.get::<_, i64>(0),
            ),
            CheckpointResolveScope::Any => conn.query_row(
                "SELECT id
                 FROM session_checkpoints
                 WHERE id > 0
                 ORDER BY CASE
                              WHEN typeof(checkpoint_at) = 'integer'
                               AND checkpoint_at >= 0
                              THEN checkpoint_at
                          END DESC,
                          id DESC
                 LIMIT 1",
                [],
                |row| row.get::<_, i64>(0),
            ),
        };
        return latest_id.map_err(|error| match error {
            rusqlite::Error::QueryReturnedNoRows => CheckpointResolveError::NotFound {
                requested_latest: true,
                scope,
            },
            other => CheckpointResolveError::Database(other),
        });
    }

    let checkpoint_id =
        parse_bounded_checkpoint_id(snapshot_id).ok_or(CheckpointResolveError::InvalidId)?;
    if scope == CheckpointResolveScope::Any {
        return Ok(checkpoint_id);
    }

    let conn = open_cli_read_only_connection(db_path).map_err(CheckpointResolveError::Database)?;
    let checkpoint_role = conn.query_row(
        "SELECT CASE
                    WHEN typeof(checkpoint_role) = 'text'
                         AND length(CAST(checkpoint_role AS BLOB)) BETWEEN 1 AND ?2
                    THEN checkpoint_role
                END
         FROM session_checkpoints
         WHERE id = ?1",
        rusqlite::params![
            checkpoint_id,
            i64::try_from(MAX_ROBOT_CHECKPOINT_ROLE_BYTES).unwrap_or(i64::MAX),
        ],
        |row| row.get::<_, Option<String>>(0),
    );
    match checkpoint_role {
        Ok(Some(role)) if role == "snapshot" => Ok(checkpoint_id),
        Ok(Some(role)) if matches!(role.as_str(), "restore_intent" | "restore_receipt") => {
            Err(CheckpointResolveError::WrongRole {
                checkpoint_id,
                role,
            })
        }
        Ok(Some(_) | None) => Err(CheckpointResolveError::InvalidStoredRole { checkpoint_id }),
        Err(rusqlite::Error::QueryReturnedNoRows) => Err(CheckpointResolveError::NotFound {
            requested_latest: false,
            scope,
        }),
        Err(error) => Err(CheckpointResolveError::Database(error)),
    }
}

#[derive(Debug)]
struct LoadedCheckpointIdentity {
    identity: frankenterm_core::snapshot_engine::SnapshotCheckpointIdentity,
    pane_count: usize,
}

fn load_checkpoint_identity_with_pane_count(
    db_path: &str,
    checkpoint_id: i64,
    scope: CheckpointResolveScope,
) -> anyhow::Result<Option<LoadedCheckpointIdentity>> {
    let conn = open_cli_read_only_connection(db_path)?;
    let role_predicate = match scope {
        CheckpointResolveScope::Snapshot => "AND checkpoint_role = 'snapshot'",
        CheckpointResolveScope::Any => "",
    };
    let row = conn.query_row(
        &format!(
            "SELECT CASE
                        WHEN typeof(session_id) = 'text'
                         AND length(CAST(session_id AS BLOB)) BETWEEN 1 AND ?2
                        THEN session_id
                    END,
                    CASE
                        WHEN typeof(checkpoint_at) = 'integer' AND checkpoint_at >= 0
                        THEN checkpoint_at
                    END,
                    CASE
                        WHEN typeof(checkpoint_role) = 'text'
                         AND length(CAST(checkpoint_role AS BLOB)) BETWEEN 1 AND ?3
                        THEN checkpoint_role
                    END,
                    CASE
                        WHEN typeof(state_hash) = 'text'
                         AND length(CAST(state_hash AS BLOB)) BETWEEN 1 AND ?4
                        THEN state_hash
                    END,
                    CASE
                        WHEN typeof(pane_count) = 'integer' AND pane_count >= 0
                        THEN pane_count
                    END
             FROM session_checkpoints
             WHERE id = ?1 {role_predicate}"
        ),
        rusqlite::params![
            checkpoint_id,
            i64::try_from(MAX_ROBOT_CHECKPOINT_SESSION_ID_BYTES).unwrap_or(i64::MAX),
            i64::try_from(MAX_ROBOT_CHECKPOINT_ROLE_BYTES).unwrap_or(i64::MAX),
            i64::try_from(MAX_ROBOT_CHECKPOINT_STATE_HASH_BYTES).unwrap_or(i64::MAX),
        ],
        |row| {
            Ok((
                row.get::<_, Option<String>>(0)?,
                row.get::<_, Option<i64>>(1)?,
                row.get::<_, Option<String>>(2)?,
                row.get::<_, Option<String>>(3)?,
                row.get::<_, Option<i64>>(4)?,
            ))
        },
    );
    match row {
        Ok((session_id, checkpoint_at, checkpoint_role, state_hash, pane_count)) => {
            let session_id = robot_checkpoint_required_bounded_text(
                session_id,
                "session_id",
                MAX_ROBOT_CHECKPOINT_SESSION_ID_BYTES,
            )?;
            let checkpoint_at = checkpoint_at
                .ok_or_else(|| anyhow::anyhow!("checkpoint identity has invalid checkpoint_at"))
                .and_then(|value| {
                    robot_checkpoint_nonnegative_u64("session_checkpoints.checkpoint_at", value)
                })?;
            let checkpoint_role =
                robot_checkpoint_validate_role(robot_checkpoint_required_bounded_text(
                    checkpoint_role,
                    "checkpoint_role",
                    MAX_ROBOT_CHECKPOINT_ROLE_BYTES,
                )?)?;
            let state_hash = robot_checkpoint_required_bounded_text(
                state_hash,
                "state_hash",
                MAX_ROBOT_CHECKPOINT_STATE_HASH_BYTES,
            )?;
            let pane_count = pane_count
                .ok_or_else(|| anyhow::anyhow!("checkpoint identity has invalid pane_count"))
                .and_then(|value| {
                    usize::try_from(value)
                        .map_err(|_| anyhow::anyhow!("checkpoint pane_count exceeds usize"))
                })?;
            Ok(Some(LoadedCheckpointIdentity {
                identity: frankenterm_core::snapshot_engine::SnapshotCheckpointIdentity {
                    checkpoint_id,
                    session_id,
                    checkpoint_at,
                    checkpoint_role,
                    state_hash,
                },
                pane_count,
            }))
        }
        Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
        Err(error) => Err(error.into()),
    }
}

fn load_checkpoint_identity(
    db_path: &str,
    checkpoint_id: i64,
    scope: CheckpointResolveScope,
) -> anyhow::Result<Option<frankenterm_core::snapshot_engine::SnapshotCheckpointIdentity>> {
    Ok(
        load_checkpoint_identity_with_pane_count(db_path, checkpoint_id, scope)?
            .map(|loaded| loaded.identity),
    )
}

fn robot_checkpoint_error_response(
    code: &str,
    message: impl Into<String>,
    hint: Option<String>,
    elapsed_ms: u64,
) -> RobotResponse<serde_json::Value> {
    RobotResponse::<serde_json::Value>::error_with_code(code, message, hint, elapsed_ms)
}

fn robot_checkpoint_internal_error_response(
    code: &'static str,
    operation: &'static str,
    public_message: &'static str,
    hint: Option<String>,
    error: &(impl std::fmt::Display + ?Sized),
    elapsed_ms: u64,
) -> RobotResponse<serde_json::Value> {
    trace_bounded_cli_internal_error(operation, error);
    robot_checkpoint_error_response(code, public_message, hint, elapsed_ms)
}

fn robot_checkpoint_not_found(
    _checkpoint_id: &str,
    elapsed_ms: u64,
) -> RobotResponse<serde_json::Value> {
    robot_checkpoint_error_response(
        ROBOT_ERR_CHECKPOINT_NOT_FOUND,
        "The requested checkpoint was not found.",
        Some("Use `ft robot checkpoint list` to find available checkpoint IDs.".to_string()),
        elapsed_ms,
    )
}

fn robot_checkpoint_rollback_unavailable(
    checkpoint_id: &str,
    elapsed_ms: u64,
) -> RobotResponse<serde_json::Value> {
    let diagnostic = RestoreDiagnosticCode::SnapshotRestoreUnavailableNoAuthenticatedMuxIdentity;
    let mut response = robot_checkpoint_error_response(
        ROBOT_ERR_FEATURE_NOT_AVAILABLE,
        diagnostic.message(),
        Some(
            "Use the rollback --dry-run plan and snapshot inspection to collect bounded recovery metadata; execution remains disabled until one mux endpoint and process incarnation can be authenticated."
                .to_string(),
        ),
        elapsed_ms,
    );
    response.data = Some(serde_json::json!({
        "family": "checkpoint",
        "action": "rollback",
        "requested_checkpoint_id_supplied": !checkpoint_id.is_empty(),
        "dry_run": false,
        "executable": false,
        "unavailable_reason_code": diagnostic.code(),
        "external_effects_may_have_occurred": false,
    }));
    response
}

fn robot_checkpoint_resolve_id(
    db_path: &str,
    checkpoint_id: &str,
    scope: CheckpointResolveScope,
    elapsed_ms: u64,
) -> RobotJsonResult<i64> {
    resolve_checkpoint_id(db_path, checkpoint_id, scope).map_err(|error| {
        let response = match &error {
            CheckpointResolveError::NotFound { .. } => robot_checkpoint_error_response(
                ROBOT_ERR_CHECKPOINT_NOT_FOUND,
                "The requested checkpoint was not found.",
                None,
                elapsed_ms,
            ),
            CheckpointResolveError::InvalidId => robot_checkpoint_error_response(
                ROBOT_ERR_INVALID_ARGS,
                "The checkpoint ID is invalid.",
                None,
                elapsed_ms,
            ),
            CheckpointResolveError::WrongRole { .. } => robot_checkpoint_error_response(
                ROBOT_ERR_INVALID_ARGS,
                "The requested checkpoint cannot be used for this operation.",
                None,
                elapsed_ms,
            ),
            CheckpointResolveError::Database(_)
            | CheckpointResolveError::InvalidStoredRole { .. } => {
                robot_checkpoint_internal_error_response(
                    ROBOT_ERR_STORAGE,
                    "robot checkpoint resolution",
                    "Checkpoint resolution failed.",
                    None,
                    &error,
                    elapsed_ms,
                )
            }
        };
        Box::new(response)
    })
}

fn robot_checkpoint_nonnegative_u64(field: &str, value: i64) -> anyhow::Result<u64> {
    u64::try_from(value).map_err(|_| anyhow::anyhow!("{field} was negative: {value}"))
}

fn robot_checkpoint_nonnegative_usize(field: &str, value: i64) -> anyhow::Result<usize> {
    usize::try_from(value).map_err(|_| anyhow::anyhow!("{field} was negative: {value}"))
}

const MAX_ROBOT_CHECKPOINT_LIST_LIMIT: usize = 200;
const MAX_ROBOT_CHECKPOINT_LIST_OFFSET: usize = 100_000;
const MAX_ROBOT_CHECKPOINT_TOTAL_SCAN: usize = 100_000;
// Identity and metadata caps mirror the checkpoint witness admission contract.
const MAX_ROBOT_CHECKPOINT_SESSION_ID_BYTES: usize = 256;
const MAX_ROBOT_CHECKPOINT_TYPE_BYTES: usize = 64;
const MAX_ROBOT_CHECKPOINT_ROLE_BYTES: usize = 32;
const MAX_ROBOT_CHECKPOINT_STATE_HASH_BYTES: usize = 256;
const MAX_ROBOT_CHECKPOINT_METADATA_BYTES: usize = 1024 * 1024;
// Robot output intentionally uses tighter presentation admissions/projections
// than the full witnessed snapshot loader: list labels and show cwd/command
// text must remain useful without constructing a worst-case response.
const MAX_ROBOT_CHECKPOINT_LABEL_BYTES: usize = 4 * 1024;
const MAX_ROBOT_CHECKPOINT_PANE_TEXT_BYTES: usize = 8 * 1024;
// Robot checkpoint-show admits a persisted title up to 8 KiB, then keeps a
// separate 1 KiB display projection so an admitted durable row is not rejected
// merely because the human/robot presentation is intentionally smaller.
const MAX_ROBOT_CHECKPOINT_STORED_TITLE_BYTES: usize = 8 * 1024;
const MAX_ROBOT_CHECKPOINT_DISPLAY_TITLE_BYTES: usize = 1024;
const MAX_ROBOT_CHECKPOINT_DISPLAY_TITLE_CELLS: usize = 1024;
const MAX_ROBOT_CHECKPOINT_TERMINAL_JSON_BYTES: usize =
    frankenterm_core::session_pane_state::PANE_STATE_SIZE_BUDGET;

fn robot_checkpoint_validate_list_window(limit: usize, offset: usize) -> anyhow::Result<()> {
    if limit > MAX_ROBOT_CHECKPOINT_LIST_LIMIT {
        return Err(anyhow::anyhow!(
            "checkpoint list limit exceeds the hard maximum of {MAX_ROBOT_CHECKPOINT_LIST_LIMIT}"
        ));
    }
    if offset > MAX_ROBOT_CHECKPOINT_LIST_OFFSET {
        return Err(anyhow::anyhow!(
            "checkpoint list offset exceeds the hard maximum of {MAX_ROBOT_CHECKPOINT_LIST_OFFSET}"
        ));
    }
    Ok(())
}

fn robot_checkpoint_required_bounded_text(
    value: Option<String>,
    field: &'static str,
    max_bytes: usize,
) -> anyhow::Result<String> {
    let value =
        value.ok_or_else(|| anyhow::anyhow!("checkpoint projection contains invalid {field}"))?;
    if value.is_empty() || value.len() > max_bytes {
        return Err(anyhow::anyhow!(
            "checkpoint projection contains invalid {field}"
        ));
    }
    Ok(value)
}

fn robot_checkpoint_optional_bounded_text(
    value: Option<String>,
    field: &'static str,
    max_bytes: usize,
) -> anyhow::Result<Option<String>> {
    let Some(value) = value else {
        return Ok(None);
    };
    if value.len() > max_bytes {
        return Err(anyhow::anyhow!(
            "checkpoint projection contains invalid {field}"
        ));
    }
    Ok(Some(value))
}

fn robot_checkpoint_redacted_bounded_text(
    value: String,
    field: &'static str,
    max_bytes: usize,
) -> anyhow::Result<String> {
    let redacted = redact_single_line_for_output(&value);
    if redacted.len() > max_bytes {
        return Err(anyhow::anyhow!(
            "checkpoint projection contains oversized redacted {field}"
        ));
    }
    Ok(redacted)
}

fn robot_checkpoint_title_for_output(title: String) -> (String, bool) {
    let redacted = redact_single_line_for_output(&title);
    let projected = frankenterm_core::output::truncate_bounded(
        &redacted,
        MAX_ROBOT_CHECKPOINT_DISPLAY_TITLE_CELLS,
        MAX_ROBOT_CHECKPOINT_DISPLAY_TITLE_BYTES,
    );
    let truncated = projected != redacted;
    (projected, truncated)
}

const fn checkpoint_verification_label(
    verification: frankenterm_core::session_restore::CheckpointVerification,
) -> &'static str {
    match verification {
        frankenterm_core::session_restore::CheckpointVerification::VerifiedV2 => "verified_v2",
        frankenterm_core::session_restore::CheckpointVerification::LegacyUnverified => {
            "legacy_unverified"
        }
    }
}

fn checkpoint_label_from_projection(
    metadata_valid: i64,
    robot_label: Option<String>,
    cli_label: Option<String>,
) -> anyhow::Result<Option<String>> {
    if metadata_valid != 1 {
        return Err(anyhow::anyhow!(
            "checkpoint projection contains invalid metadata_json or label"
        ));
    }
    let robot_label = robot_checkpoint_optional_bounded_text(
        robot_label,
        "robot metadata label",
        MAX_ROBOT_CHECKPOINT_LABEL_BYTES,
    )?;
    let cli_label = robot_checkpoint_optional_bounded_text(
        cli_label,
        "CLI metadata label",
        MAX_ROBOT_CHECKPOINT_LABEL_BYTES,
    )?;
    let label = match (robot_label, cli_label) {
        (Some(robot), Some(cli)) if robot != cli => {
            return Err(anyhow::anyhow!(
                "checkpoint projection contains conflicting metadata labels"
            ));
        }
        (Some(robot), _) => Some(robot),
        (_, Some(cli)) => Some(cli),
        (None, None) => None,
    };
    label
        .map(|label| {
            robot_checkpoint_redacted_bounded_text(
                label,
                "metadata label",
                MAX_ROBOT_CHECKPOINT_LABEL_BYTES,
            )
        })
        .transpose()
}

fn robot_checkpoint_validate_type(checkpoint_type: String) -> anyhow::Result<String> {
    if matches!(
        checkpoint_type.as_str(),
        "periodic" | "event" | "shutdown" | "startup"
    ) {
        Ok(checkpoint_type)
    } else {
        Err(anyhow::anyhow!(
            "checkpoint projection contains an unsupported checkpoint_type"
        ))
    }
}

fn robot_checkpoint_validate_role(checkpoint_role: String) -> anyhow::Result<String> {
    if matches!(
        checkpoint_role.as_str(),
        "snapshot" | "restore_intent" | "restore_receipt"
    ) {
        Ok(checkpoint_role)
    } else {
        Err(anyhow::anyhow!(
            "checkpoint projection contains an unsupported checkpoint_role"
        ))
    }
}

fn robot_checkpoint_pane_count(value: i64) -> anyhow::Result<usize> {
    let pane_count = robot_checkpoint_nonnegative_usize("session_checkpoints.pane_count", value)?;
    if pane_count > frankenterm_core::session_topology::MAX_TOPOLOGY_PANES {
        return Err(anyhow::anyhow!(
            "checkpoint pane_count exceeds the supported topology limit"
        ));
    }
    Ok(pane_count)
}

const fn robot_checkpoint_total_summary(observed: usize) -> (Option<usize>, Option<usize>, bool) {
    if observed <= MAX_ROBOT_CHECKPOINT_TOTAL_SCAN {
        (Some(observed), None, true)
    } else {
        (None, Some(MAX_ROBOT_CHECKPOINT_TOTAL_SCAN + 1), false)
    }
}

#[derive(Debug)]
struct BoundedSnapshotListEntry {
    checkpoint_id: i64,
    session_id: String,
    checkpoint_at: u64,
    checkpoint_type: String,
    pane_count: usize,
    pane_state_estimate_bytes: u64,
    state_hash: String,
    label: Option<String>,
}

#[derive(Debug)]
struct BoundedSnapshotListPage {
    entries: Vec<BoundedSnapshotListEntry>,
    has_more: bool,
    limit: usize,
    offset: usize,
}

fn load_bounded_snapshot_list(
    db_path: &str,
    limit: usize,
    offset: usize,
    session_id: Option<&str>,
) -> anyhow::Result<BoundedSnapshotListPage> {
    if limit == 0 {
        return Err(anyhow::anyhow!("snapshot list limit must be at least one"));
    }
    if limit > MAX_ROBOT_CHECKPOINT_LIST_LIMIT {
        return Err(anyhow::anyhow!(
            "snapshot list limit exceeds the hard maximum of {MAX_ROBOT_CHECKPOINT_LIST_LIMIT}"
        ));
    }
    if offset > MAX_ROBOT_CHECKPOINT_LIST_OFFSET {
        return Err(anyhow::anyhow!(
            "snapshot list offset exceeds the hard maximum of {MAX_ROBOT_CHECKPOINT_LIST_OFFSET}"
        ));
    }
    if session_id.is_some_and(|value| {
        value.is_empty() || value.len() > MAX_ROBOT_CHECKPOINT_SESSION_ID_BYTES
    }) {
        return Err(anyhow::anyhow!(
            "snapshot session filter has an invalid byte length"
        ));
    }

    let mut conn = open_cli_read_only_connection(db_path)?;
    let tx = conn.transaction()?;
    let row_limit = limit
        .checked_add(1)
        .ok_or_else(|| anyhow::anyhow!("snapshot list row limit overflowed"))?;
    let row_limit_i64 = i64::try_from(row_limit)
        .map_err(|_| anyhow::anyhow!("snapshot list row limit is invalid"))?;
    let offset_i64 =
        i64::try_from(offset).map_err(|_| anyhow::anyhow!("snapshot list offset is invalid"))?;
    let session_id_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_SESSION_ID_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint session-id cap is invalid"))?;
    let checkpoint_type_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_TYPE_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint type cap is invalid"))?;
    let state_hash_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_STATE_HASH_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint state-hash cap is invalid"))?;
    let metadata_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_METADATA_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint metadata cap is invalid"))?;
    let label_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_LABEL_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint label cap is invalid"))?;
    let entries = {
        let mut stmt = tx.prepare(
            "SELECT CASE WHEN typeof(id) = 'integer' AND id > 0 THEN id END,
                    CASE WHEN typeof(session_id) = 'text'
                               AND length(CAST(session_id AS BLOB)) BETWEEN 1 AND ?4
                         THEN session_id END,
                    CASE WHEN typeof(checkpoint_at) = 'integer' AND checkpoint_at >= 0
                         THEN checkpoint_at END,
                    CASE WHEN typeof(checkpoint_type) = 'text'
                               AND length(CAST(checkpoint_type AS BLOB)) BETWEEN 1 AND ?5
                         THEN checkpoint_type END,
                    CASE WHEN typeof(pane_count) = 'integer' AND pane_count >= 0
                         THEN pane_count END,
                    CASE WHEN typeof(total_bytes) = 'integer' AND total_bytes >= 0
                         THEN total_bytes END,
                    CASE WHEN typeof(state_hash) = 'text'
                               AND length(CAST(state_hash AS BLOB)) BETWEEN 1 AND ?6
                         THEN state_hash END,
                    CASE
                        WHEN metadata_json IS NULL THEN 1
                        WHEN typeof(metadata_json) <> 'text' THEN 0
                        WHEN length(CAST(metadata_json AS BLOB)) > ?7 THEN 0
                        WHEN json_valid(metadata_json) = 0 THEN 0
                        WHEN json_type(metadata_json, '$.robot_checkpoint.label')
                                 NOT IN ('text', 'null')
                             AND json_type(metadata_json, '$.robot_checkpoint.label')
                                 IS NOT NULL THEN 0
                        WHEN json_type(metadata_json, '$.cli_snapshot.label')
                                 NOT IN ('text', 'null')
                             AND json_type(metadata_json, '$.cli_snapshot.label')
                                 IS NOT NULL THEN 0
                        WHEN json_type(metadata_json, '$.robot_checkpoint.label') = 'text'
                             AND length(CAST(json_extract(
                                 metadata_json,
                                 '$.robot_checkpoint.label'
                             ) AS BLOB)) > ?8 THEN 0
                        WHEN json_type(metadata_json, '$.cli_snapshot.label') = 'text'
                             AND length(CAST(json_extract(
                                 metadata_json,
                                 '$.cli_snapshot.label'
                             ) AS BLOB)) > ?8 THEN 0
                        ELSE 1
                    END,
                    CASE
                        WHEN typeof(metadata_json) = 'text'
                         AND length(CAST(metadata_json AS BLOB)) <= ?7
                         AND json_valid(metadata_json) = 1
                         AND json_type(metadata_json, '$.robot_checkpoint.label') = 'text'
                        THEN json_extract(metadata_json, '$.robot_checkpoint.label')
                    END,
                    CASE
                        WHEN typeof(metadata_json) = 'text'
                         AND length(CAST(metadata_json AS BLOB)) <= ?7
                         AND json_valid(metadata_json) = 1
                         AND json_type(metadata_json, '$.cli_snapshot.label') = 'text'
                        THEN json_extract(metadata_json, '$.cli_snapshot.label')
                    END
             FROM session_checkpoints
             WHERE checkpoint_role = 'snapshot'
               AND (?3 IS NULL OR session_id = ?3)
             ORDER BY CASE
                          WHEN typeof(checkpoint_at) = 'integer'
                           AND checkpoint_at >= 0
                          THEN checkpoint_at
                      END DESC,
                      id DESC
             LIMIT ?1 OFFSET ?2",
        )?;
        let rows = stmt.query_map(
            rusqlite::params![
                row_limit_i64,
                offset_i64,
                session_id,
                session_id_cap,
                checkpoint_type_cap,
                state_hash_cap,
                metadata_cap,
                label_cap,
            ],
            |row| {
                Ok((
                    row.get::<_, Option<i64>>(0)?,
                    row.get::<_, Option<String>>(1)?,
                    row.get::<_, Option<i64>>(2)?,
                    row.get::<_, Option<String>>(3)?,
                    row.get::<_, Option<i64>>(4)?,
                    row.get::<_, Option<i64>>(5)?,
                    row.get::<_, Option<String>>(6)?,
                    row.get::<_, i64>(7)?,
                    row.get::<_, Option<String>>(8)?,
                    row.get::<_, Option<String>>(9)?,
                ))
            },
        )?;
        let mut entries = Vec::new();
        for row in rows {
            let (
                checkpoint_id,
                session_id,
                checkpoint_at,
                checkpoint_type,
                pane_count,
                total_bytes,
                state_hash,
                metadata_valid,
                robot_label,
                cli_label,
            ) = row?;
            let checkpoint_id = checkpoint_id
                .filter(|value| *value > 0)
                .ok_or_else(|| anyhow::anyhow!("snapshot list contains an invalid id"))?;
            let session_id = robot_checkpoint_required_bounded_text(
                session_id,
                "session_id",
                MAX_ROBOT_CHECKPOINT_SESSION_ID_BYTES,
            )?;
            let checkpoint_at = checkpoint_at
                .ok_or_else(|| anyhow::anyhow!("snapshot list contains invalid checkpoint_at"))
                .and_then(|value| {
                    robot_checkpoint_nonnegative_u64("session_checkpoints.checkpoint_at", value)
                })?;
            let checkpoint_type =
                robot_checkpoint_validate_type(robot_checkpoint_required_bounded_text(
                    checkpoint_type,
                    "checkpoint_type",
                    MAX_ROBOT_CHECKPOINT_TYPE_BYTES,
                )?)?;
            let pane_count =
                robot_checkpoint_pane_count(pane_count.ok_or_else(|| {
                    anyhow::anyhow!("snapshot list contains invalid pane_count")
                })?)?;
            let total_bytes = total_bytes
                .ok_or_else(|| anyhow::anyhow!("snapshot list contains invalid total_bytes"))
                .and_then(|value| {
                    robot_checkpoint_nonnegative_u64("session_checkpoints.total_bytes", value)
                })?;
            let state_hash = robot_checkpoint_required_bounded_text(
                state_hash,
                "state_hash",
                MAX_ROBOT_CHECKPOINT_STATE_HASH_BYTES,
            )?;
            let label = checkpoint_label_from_projection(metadata_valid, robot_label, cli_label)?;
            entries.push(BoundedSnapshotListEntry {
                checkpoint_id,
                session_id,
                checkpoint_at,
                checkpoint_type,
                pane_count,
                pane_state_estimate_bytes: total_bytes,
                state_hash,
                label,
            });
        }
        entries
    };
    let mut entries = entries;
    let has_more = entries.len() > limit;
    entries.truncate(limit);
    tx.commit()?;
    Ok(BoundedSnapshotListPage {
        entries,
        has_more,
        limit,
        offset,
    })
}

fn checkpoint_label_from_loaded_metadata(
    metadata_json: Option<&str>,
) -> anyhow::Result<Option<String>> {
    let Some(metadata_json) = metadata_json else {
        return Ok(None);
    };
    if metadata_json.len() > MAX_ROBOT_CHECKPOINT_METADATA_BYTES {
        return Err(anyhow::anyhow!(
            "loaded checkpoint metadata exceeds the inspection limit"
        ));
    }
    let metadata: serde_json::Value = serde_json::from_str(metadata_json)
        .map_err(|_| anyhow::anyhow!("loaded checkpoint metadata is invalid JSON"))?;
    let projected_label = |pointer: &str, field: &'static str| match metadata.pointer(pointer) {
        None | Some(serde_json::Value::Null) => Ok(None),
        Some(serde_json::Value::String(label)) => robot_checkpoint_optional_bounded_text(
            Some(label.clone()),
            field,
            MAX_ROBOT_CHECKPOINT_LABEL_BYTES,
        ),
        Some(_) => Err(anyhow::anyhow!(
            "loaded checkpoint metadata contains an invalid label"
        )),
    };
    let robot_label = projected_label("/robot_checkpoint/label", "robot metadata label")?;
    let cli_label = projected_label("/cli_snapshot/label", "CLI metadata label")?;
    checkpoint_label_from_projection(1, robot_label, cli_label)
}

fn load_bounded_snapshot_pane_ids_from_conn(
    conn: &rusqlite::Connection,
    checkpoint_id: i64,
) -> anyhow::Result<Option<Vec<u64>>> {
    let pane_count = match conn.query_row(
        "SELECT CASE
                    WHEN typeof(pane_count) = 'integer' AND pane_count >= 0
                    THEN pane_count
                END
         FROM session_checkpoints
         WHERE id = ?1 AND checkpoint_role = 'snapshot'",
        [checkpoint_id],
        |row| row.get::<_, Option<i64>>(0),
    ) {
        Ok(Some(pane_count)) => robot_checkpoint_pane_count(pane_count)?,
        Ok(None) => {
            return Err(anyhow::anyhow!(
                "snapshot pane-id projection contains invalid pane_count"
            ));
        }
        Err(rusqlite::Error::QueryReturnedNoRows) => return Ok(None),
        Err(error) => return Err(error.into()),
    };
    let row_limit = pane_count
        .checked_add(1)
        .ok_or_else(|| anyhow::anyhow!("snapshot pane-id row limit overflowed"))?;
    let row_limit = i64::try_from(row_limit)
        .map_err(|_| anyhow::anyhow!("snapshot pane-id row limit is invalid"))?;
    let mut stmt = conn.prepare(
        "SELECT CASE
                    WHEN typeof(pane_id) = 'integer' AND pane_id >= 0
                    THEN pane_id
                END
         FROM mux_pane_state
         WHERE checkpoint_id = ?1
         ORDER BY pane_id, id
         LIMIT ?2",
    )?;
    let rows = stmt.query_map(rusqlite::params![checkpoint_id, row_limit], |row| {
        row.get::<_, Option<i64>>(0)
    })?;
    let mut pane_ids = Vec::with_capacity(pane_count);
    let mut previous_pane_id = None;
    for pane_id in rows {
        let pane_id = pane_id?
            .ok_or_else(|| anyhow::anyhow!("snapshot pane-id projection contains invalid id"))
            .and_then(|value| robot_checkpoint_nonnegative_u64("mux_pane_state.pane_id", value))?;
        if previous_pane_id == Some(pane_id) {
            return Err(anyhow::anyhow!(
                "snapshot pane-id projection contains duplicate identities"
            ));
        }
        previous_pane_id = Some(pane_id);
        pane_ids.push(pane_id);
    }
    if pane_ids.len() != pane_count {
        return Err(anyhow::anyhow!(
            "snapshot pane-id row count does not match its declaration"
        ));
    }
    Ok(Some(pane_ids))
}

fn robot_checkpoint_metadata(
    label: Option<&str>,
    include_scrollback: bool,
    pane_ids: &[u64],
) -> serde_json::Value {
    serde_json::json!({
        "robot_checkpoint": {
            "label": label,
            "include_scrollback": include_scrollback,
            "pane_ids": pane_ids,
            "created_by": "ft robot checkpoint save",
        }
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RobotCheckpointLivePaneProjectionError {
    TooManyPanes,
    DuplicatePaneId,
}

fn robot_checkpoint_live_pane_ids(
    panes: &[frankenterm_core::wezterm::PaneInfo],
) -> Result<(), RobotCheckpointLivePaneProjectionError> {
    if panes.len() > frankenterm_core::session_topology::MAX_TOPOLOGY_PANES {
        return Err(RobotCheckpointLivePaneProjectionError::TooManyPanes);
    }
    let pane_ids = panes
        .iter()
        .map(|pane| pane.pane_id)
        .collect::<std::collections::HashSet<_>>();
    if pane_ids.len() != panes.len() {
        return Err(RobotCheckpointLivePaneProjectionError::DuplicatePaneId);
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RobotCheckpointScrollbackCoverage {
    pane_rows: usize,
    panes_with_scrollback: usize,
}

impl RobotCheckpointScrollbackCoverage {
    const fn any(self) -> bool {
        self.panes_with_scrollback > 0
    }

    const fn all(self) -> bool {
        self.pane_rows > 0 && self.panes_with_scrollback == self.pane_rows
    }
}

fn robot_checkpoint_save_response(
    result: &frankenterm_core::snapshot_engine::SnapshotResult,
    label: Option<&str>,
    include_scrollback: bool,
    scrollback_coverage: RobotCheckpointScrollbackCoverage,
    artifact: Option<&frankenterm_core::snapshot_engine::CheckpointScrollbackArtifactPublication>,
) -> serde_json::Value {
    let artifact_payload = artifact.map(|publication| {
        checkpoint_artifact_receipt_json(
            "robot.checkpoint.save",
            &publication.path,
            &publication.receipt,
        )
    });
    let scrollback_complete = artifact.is_some_and(|publication| publication.scrollback_complete());
    serde_json::json!({
        "family": "checkpoint",
        "action": "save",
        "checkpoint_id": result.checkpoint_id.to_string(),
        "numeric_checkpoint_id": result.checkpoint_id,
        "session_id": redact_single_line_for_output(&result.session_id),
        "label": label,
        "pane_count": result.pane_count,
        "pane_state_estimate_bytes": u64::try_from(result.total_bytes).unwrap_or(u64::MAX),
        "persisted_text_bytes": u64::try_from(result.persisted_text_bytes).unwrap_or(u64::MAX),
        "truncated_pane_count": result.truncated_pane_count,
        "projection_complete": result.truncated_pane_count == 0,
        "projection_completeness": if result.truncated_pane_count == 0 {
            "complete"
        } else {
            "truncated"
        },
        "projection_completeness_scope": "persisted_pane_text_budget",
        "verification": "verified_v2",
        "scrollback_requested": include_scrollback,
        "scrollback_included": scrollback_coverage.any(),
        "scrollback_complete": scrollback_complete,
        "scrollback_completeness_scope": if artifact.is_some() {
            "durable_zero_based_contiguous_checkpoint_prefix_without_capture_gaps"
        } else {
            "not_requested"
        },
        "scrollback_panes": scrollback_coverage.panes_with_scrollback,
        "scrollback_reference_coverage_complete": scrollback_coverage.all(),
        "artifact": artifact_payload,
        "created_at": result.checkpoint_at,
        "trigger": "manual",
        "audit_receipt": {
            "operation": "robot.checkpoint.save",
            "target": result.checkpoint_id.to_string(),
        },
    })
}

fn robot_checkpoint_scrollback_coverage(
    db_path: &str,
    checkpoint_id: i64,
    expected_pane_rows: usize,
) -> anyhow::Result<RobotCheckpointScrollbackCoverage> {
    let conn = open_cli_read_only_connection(db_path)?;
    let row_limit = expected_pane_rows
        .checked_add(1)
        .ok_or_else(|| anyhow::anyhow!("checkpoint scrollback row limit overflowed"))?;
    let row_limit = i64::try_from(row_limit)
        .map_err(|_| anyhow::anyhow!("checkpoint scrollback row limit is invalid"))?;
    let (pane_rows, panes_with_scrollback, invalid_sequences): (i64, i64, i64) = conn.query_row(
        "SELECT COUNT(*),
                COALESCE(SUM(CASE
                    WHEN typeof(scrollback_checkpoint_seq) = 'integer'
                     AND scrollback_checkpoint_seq >= 0
                    THEN 1 ELSE 0 END), 0),
                COALESCE(SUM(CASE
                    WHEN scrollback_checkpoint_seq IS NOT NULL
                     AND (typeof(scrollback_checkpoint_seq) <> 'integer'
                          OR scrollback_checkpoint_seq < 0)
                    THEN 1 ELSE 0 END), 0)
         FROM (
             SELECT scrollback_checkpoint_seq
             FROM mux_pane_state
             WHERE checkpoint_id = ?1
             LIMIT ?2
         ) AS bounded_checkpoint_panes",
        rusqlite::params![checkpoint_id, row_limit],
        |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
    )?;
    let pane_rows =
        robot_checkpoint_nonnegative_usize("mux_pane_state.scrollback_coverage_rows", pane_rows)?;
    let panes_with_scrollback = robot_checkpoint_nonnegative_usize(
        "mux_pane_state.scrollback_coverage_present",
        panes_with_scrollback,
    )?;
    if invalid_sequences != 0 {
        return Err(anyhow::anyhow!(
            "checkpoint scrollback coverage contains an invalid sequence"
        ));
    }
    if pane_rows != expected_pane_rows || panes_with_scrollback > pane_rows {
        return Err(anyhow::anyhow!(
            "checkpoint scrollback coverage does not match the declared pane count"
        ));
    }
    Ok(RobotCheckpointScrollbackCoverage {
        pane_rows,
        panes_with_scrollback,
    })
}

fn robot_checkpoint_list_data(
    db_path: &str,
    limit: usize,
    offset: usize,
) -> anyhow::Result<serde_json::Value> {
    robot_checkpoint_validate_list_window(limit, offset)?;
    let mut conn = open_cli_read_only_connection(db_path)?;
    let tx = conn.transaction()?;
    let total_probe_limit = MAX_ROBOT_CHECKPOINT_TOTAL_SCAN
        .checked_add(1)
        .ok_or_else(|| anyhow::anyhow!("checkpoint total probe limit overflowed"))?;
    let total_probe_limit_i64 = i64::try_from(total_probe_limit)
        .map_err(|_| anyhow::anyhow!("checkpoint total probe limit is invalid"))?;
    let total_observed = tx.query_row(
        "SELECT COUNT(*)
         FROM (
             SELECT 1
             FROM session_checkpoints
             LIMIT ?1
         )",
        [total_probe_limit_i64],
        |row| row.get::<_, i64>(0),
    )?;
    let total_observed =
        robot_checkpoint_nonnegative_usize("session_checkpoints.bounded_count", total_observed)?;
    let (total, total_at_least, total_exact) = robot_checkpoint_total_summary(total_observed);

    let row_limit = limit
        .checked_add(1)
        .ok_or_else(|| anyhow::anyhow!("checkpoint list row limit overflowed"))?;
    let row_limit_i64 =
        i64::try_from(row_limit).map_err(|_| anyhow::anyhow!("limit is too large"))?;
    let offset_i64 = i64::try_from(offset).map_err(|_| anyhow::anyhow!("offset is too large"))?;
    let session_id_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_SESSION_ID_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint session-id cap is invalid"))?;
    let checkpoint_type_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_TYPE_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint type cap is invalid"))?;
    let checkpoint_role_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_ROLE_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint role cap is invalid"))?;
    let state_hash_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_STATE_HASH_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint state-hash cap is invalid"))?;
    let metadata_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_METADATA_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint metadata cap is invalid"))?;
    let label_cap = i64::try_from(MAX_ROBOT_CHECKPOINT_LABEL_BYTES)
        .map_err(|_| anyhow::anyhow!("checkpoint label cap is invalid"))?;
    let mut stmt = tx.prepare(
        "SELECT CASE WHEN typeof(id) = 'integer' AND id > 0 THEN id END,
                CASE WHEN typeof(session_id) = 'text'
                           AND length(CAST(session_id AS BLOB)) BETWEEN 1 AND ?3
                     THEN session_id END,
                CASE WHEN typeof(checkpoint_at) = 'integer' AND checkpoint_at >= 0
                     THEN checkpoint_at END,
                CASE WHEN typeof(checkpoint_type) = 'text'
                           AND length(CAST(checkpoint_type AS BLOB)) BETWEEN 1 AND ?4
                     THEN checkpoint_type END,
                CASE WHEN typeof(checkpoint_role) = 'text'
                           AND length(CAST(checkpoint_role AS BLOB)) BETWEEN 1 AND ?5
                     THEN checkpoint_role END,
                CASE WHEN typeof(pane_count) = 'integer' AND pane_count >= 0
                     THEN pane_count END,
                CASE WHEN typeof(total_bytes) = 'integer' AND total_bytes >= 0
                     THEN total_bytes END,
                CASE WHEN typeof(state_hash) = 'text'
                           AND length(CAST(state_hash AS BLOB)) BETWEEN 1 AND ?6
                     THEN state_hash END,
                CASE
                    WHEN metadata_json IS NULL THEN 1
                    WHEN typeof(metadata_json) <> 'text' THEN 0
                    WHEN length(CAST(metadata_json AS BLOB)) > ?7 THEN 0
                    WHEN json_valid(metadata_json) = 0 THEN 0
                    WHEN json_type(metadata_json, '$.robot_checkpoint.label')
                             NOT IN ('text', 'null')
                         AND json_type(metadata_json, '$.robot_checkpoint.label')
                             IS NOT NULL THEN 0
                    WHEN json_type(metadata_json, '$.cli_snapshot.label')
                             NOT IN ('text', 'null')
                         AND json_type(metadata_json, '$.cli_snapshot.label')
                             IS NOT NULL THEN 0
                    WHEN json_type(metadata_json, '$.robot_checkpoint.label') = 'text'
                         AND length(CAST(json_extract(
                             metadata_json,
                             '$.robot_checkpoint.label'
                         ) AS BLOB)) > ?8 THEN 0
                    WHEN json_type(metadata_json, '$.cli_snapshot.label') = 'text'
                         AND length(CAST(json_extract(
                             metadata_json,
                             '$.cli_snapshot.label'
                         ) AS BLOB)) > ?8 THEN 0
                    ELSE 1
                END,
                CASE
                    WHEN metadata_json IS NULL THEN NULL
                    WHEN typeof(metadata_json) <> 'text' THEN NULL
                    WHEN length(CAST(metadata_json AS BLOB)) > ?7 THEN NULL
                    WHEN json_valid(metadata_json) = 0 THEN NULL
                    WHEN json_type(metadata_json, '$.robot_checkpoint.label') = 'text'
                         AND length(CAST(json_extract(
                             metadata_json,
                             '$.robot_checkpoint.label'
                         ) AS BLOB)) <= ?8
                    THEN json_extract(metadata_json, '$.robot_checkpoint.label')
                    ELSE NULL
                END,
                CASE
                    WHEN metadata_json IS NULL THEN NULL
                    WHEN typeof(metadata_json) <> 'text' THEN NULL
                    WHEN length(CAST(metadata_json AS BLOB)) > ?7 THEN NULL
                    WHEN json_valid(metadata_json) = 0 THEN NULL
                    WHEN json_type(metadata_json, '$.cli_snapshot.label') = 'text'
                         AND length(CAST(json_extract(
                             metadata_json,
                             '$.cli_snapshot.label'
                         ) AS BLOB)) <= ?8
                    THEN json_extract(metadata_json, '$.cli_snapshot.label')
                    ELSE NULL
                END
         FROM session_checkpoints
         ORDER BY CASE
                      WHEN typeof(checkpoint_at) = 'integer'
                       AND checkpoint_at >= 0
                      THEN checkpoint_at
                  END DESC,
                  id DESC
         LIMIT ?1 OFFSET ?2",
    )?;
    let rows = stmt.query_map(
        rusqlite::params![
            row_limit_i64,
            offset_i64,
            session_id_cap,
            checkpoint_type_cap,
            checkpoint_role_cap,
            state_hash_cap,
            metadata_cap,
            label_cap,
        ],
        |row| {
            Ok((
                row.get::<_, Option<i64>>(0)?,
                row.get::<_, Option<String>>(1)?,
                row.get::<_, Option<i64>>(2)?,
                row.get::<_, Option<String>>(3)?,
                row.get::<_, Option<String>>(4)?,
                row.get::<_, Option<i64>>(5)?,
                row.get::<_, Option<i64>>(6)?,
                row.get::<_, Option<String>>(7)?,
                row.get::<_, i64>(8)?,
                row.get::<_, Option<String>>(9)?,
                row.get::<_, Option<String>>(10)?,
            ))
        },
    )?;

    let mut checkpoints = Vec::with_capacity(row_limit);
    for row in rows {
        let (
            id,
            session_id,
            checkpoint_at,
            checkpoint_type,
            checkpoint_role,
            pane_count,
            total_bytes,
            state_hash,
            metadata_valid,
            robot_label,
            cli_label,
        ) = row?;
        let id = id
            .filter(|id| *id > 0)
            .ok_or_else(|| anyhow::anyhow!("checkpoint projection contains invalid id"))?;
        let session_id = robot_checkpoint_required_bounded_text(
            session_id,
            "session_id",
            MAX_ROBOT_CHECKPOINT_SESSION_ID_BYTES,
        )?;
        let checkpoint_at = checkpoint_at.ok_or_else(|| {
            anyhow::anyhow!("checkpoint projection contains invalid checkpoint_at")
        })?;
        let checkpoint_type =
            robot_checkpoint_validate_type(robot_checkpoint_required_bounded_text(
                checkpoint_type,
                "checkpoint_type",
                MAX_ROBOT_CHECKPOINT_TYPE_BYTES,
            )?)?;
        let checkpoint_role =
            robot_checkpoint_validate_role(robot_checkpoint_required_bounded_text(
                checkpoint_role,
                "checkpoint_role",
                MAX_ROBOT_CHECKPOINT_ROLE_BYTES,
            )?)?;
        let pane_count = robot_checkpoint_pane_count(pane_count.ok_or_else(|| {
            anyhow::anyhow!("checkpoint projection contains invalid pane_count")
        })?)?;
        let total_bytes = total_bytes
            .ok_or_else(|| anyhow::anyhow!("checkpoint projection contains invalid total_bytes"))?;
        let state_hash = robot_checkpoint_required_bounded_text(
            state_hash,
            "state_hash",
            MAX_ROBOT_CHECKPOINT_STATE_HASH_BYTES,
        )?;
        let label = checkpoint_label_from_projection(metadata_valid, robot_label, cli_label)?;
        checkpoints.push(serde_json::json!({
            "checkpoint_id": id.to_string(),
            "numeric_checkpoint_id": id,
            "session_id": redact_single_line_for_output(&session_id),
            "label": label,
            "pane_count": pane_count,
            "pane_state_estimate_bytes": robot_checkpoint_nonnegative_u64("session_checkpoints.total_bytes", total_bytes)?,
            "created_at": robot_checkpoint_nonnegative_u64("session_checkpoints.checkpoint_at", checkpoint_at)?,
            "checkpoint_type": checkpoint_type,
            "checkpoint_role": checkpoint_role,
            "content_hash": redact_single_line_for_output(&state_hash),
            "verification": "not_computed",
            "projection_verification": "unchecked_projection",
            "projection_scope": "checkpoint_summary",
        }));
    }
    let has_more = checkpoints.len() > limit;
    checkpoints.truncate(limit);
    drop(stmt);

    let response = serde_json::json!({
        "family": "checkpoint",
        "action": "list",
        "checkpoints": checkpoints,
        "total": total,
        "total_at_least": total_at_least,
        "total_exact": total_exact,
        "total_scan_cap": MAX_ROBOT_CHECKPOINT_TOTAL_SCAN,
        "has_more": has_more,
        "limit": limit,
        "offset": offset,
        "verification": "not_computed",
        "projection_verification": "unchecked_projection",
        "projection_scope": "checkpoint_summary",
    });
    tx.commit()?;
    Ok(response)
}

