    #[cfg(unix)]
    #[test]
    fn private_ipc_heartbeat_respects_durable_poll_cadence() {
        assert_eq!(watch_ipc_durable_poll_heartbeat_interval_ms(0, 500), 500);
        assert_eq!(
            watch_ipc_durable_poll_heartbeat_interval_ms(5_000, 500),
            500,
            "the private wakeup must be no slower than the DB poll cadence"
        );
        assert_eq!(
            watch_ipc_durable_poll_heartbeat_interval_ms(100, 500),
            100,
            "a faster user-visible heartbeat cadence remains intact"
        );
        assert_eq!(
            watch_ipc_durable_poll_heartbeat_interval_ms(0, 0),
            WATCH_EVENTS_POLL_INTERVAL_MS_MIN,
            "a zero poll interval still uses the bounded polling floor"
        );

        run_watch_claim_async(async move {
            let cx = frankenterm_core::cx::for_testing();
            let stdout = std::io::stdout();
            let cursor = Some(7);
            let mut last_event_emit = None;
            let mut last_emit = std::time::Instant::now();
            let initial_last_emit = last_emit;
            let line = serde_json::json!({
                "type": "heartbeat",
                "cursor": null,
                "now": 12_345,
            })
            .to_string();

            let action = relay_ipc_event_line(
                &cx,
                &stdout,
                &line,
                cursor,
                Some("0123456789abcdef0123456789abcdef"),
                Some(TEST_CURSOR_SCOPE),
                None,
                &mut last_event_emit,
                0,
                std::time::Duration::ZERO,
                &mut last_emit,
            )
            .await
            .expect("classify private IPC heartbeat");

            assert_eq!(action, IpcRelayAction::DurablePoll);
            assert_eq!(cursor, Some(7), "a heartbeat cannot advance the cursor");
            assert_eq!(last_event_emit, None, "a heartbeat is not an event");
            assert_eq!(
                last_emit, initial_last_emit,
                "output-disabled private heartbeats must not claim a stdout write"
            );
        });
    }

    #[cfg(unix)]
    #[test]
    fn stalled_ipc_read_reaches_independent_durable_poll_deadline() {
        run_watch_claim_async(async move {
            let cx = frankenterm_core::cx::for_testing();
            let read_was_polled = std::cell::Cell::new(false);
            let outcome = read_watch_ipc_line_until_durable_poll(
                &cx,
                std::time::Instant::now(),
                std::time::Duration::ZERO,
                async {
                    read_was_polled.set(true);
                    std::future::pending::<std::io::Result<Option<String>>>().await
                },
            )
            .await
            .expect("deadline is a normal durable-poll wakeup");

            assert_eq!(outcome, WatchIpcStreamRead::DurablePollDeadline);
            assert!(
                !read_was_polled.get(),
                "an already-elapsed window must not depend on a real-time 5 ms timer"
            );

            let ready = read_watch_ipc_line_until_durable_poll(
                &cx,
                std::time::Instant::now(),
                std::time::Duration::from_secs(1),
                std::future::ready(Ok(Some("line".to_string()))),
            )
            .await
            .expect("ready line");
            assert_eq!(ready, WatchIpcStreamRead::Line(Some("line".to_string())));
        });
    }

    #[cfg(unix)]
    #[test]
    fn durable_poll_window_math_is_fixed_and_saturating() {
        let started_at = std::time::Instant::now();
        let interval = std::time::Duration::from_millis(5);
        assert_eq!(
            watch_durable_poll_remaining_at(started_at, interval, started_at),
            interval
        );
        assert_eq!(
            watch_durable_poll_remaining_at(started_at, interval, started_at + interval),
            std::time::Duration::ZERO,
            "ready lines cannot reset the caller-owned start time"
        );
        assert_eq!(
            watch_durable_poll_remaining_at(
                started_at,
                interval,
                started_at + std::time::Duration::from_secs(1),
            ),
            std::time::Duration::ZERO,
            "late observations must saturate instead of underflowing"
        );
    }

    #[cfg(unix)]
    #[test]
    fn completed_ipc_line_is_rejected_if_its_read_cancelled_the_caller() {
        run_watch_claim_async(async move {
            let cx = frankenterm_core::cx::for_testing();
            let cancel_cx = cx.clone();
            let relay_effect_ran = std::cell::Cell::new(false);
            let result = read_watch_ipc_line_until_durable_poll(
                &cx,
                std::time::Instant::now(),
                std::time::Duration::from_secs(1),
                async move {
                    cancel_cx.cancel_with(
                        frankenterm_core::outcome::CancelKind::User,
                        Some("cancelled in ready IPC read"),
                    );
                    Ok(Some("must-not-be-relayed".to_string()))
                },
            )
            .await;
            if result.is_ok() {
                relay_effect_ran.set(true);
            }

            let error = result.expect_err("post-read checkpoint must win over the ready line");
            assert_eq!(error.kind(), std::io::ErrorKind::Interrupted);
            assert!(
                !relay_effect_ran.get(),
                "a line returned concurrently with cancellation must have no relay/output effects"
            );
        });
    }

    #[cfg(unix)]
    #[test]
    fn extreme_poll_interval_is_overflow_free_and_cancellation_bounded() {
        let huge = std::time::Duration::from_millis(u64::MAX);
        let started_at = std::time::Instant::now();

        assert_eq!(
            watch_ipc_read_timeout(huge),
            WATCH_EVENTS_IPC_CANCELLATION_CHECK_INTERVAL,
            "one stalled read may never inherit an effectively unbounded poll interval"
        );
        assert!(
            watch_durable_poll_remaining(started_at, huge) > std::time::Duration::from_secs(60),
            "an unrepresentable Instant deadline must remain a long elapsed window, not collapse to now"
        );
        assert_eq!(
            watch_ipc_timeout_outcome(started_at, huge),
            WatchIpcStreamRead::CancellationCheckpoint,
            "the bounded read slice must not masquerade as the durable poll deadline"
        );

        run_watch_claim_async(async move {
            let healthy = frankenterm_core::cx::for_testing();
            let oversized_error = sleep_watch_delay_with_cx(&healthy, huge, "test delay")
                .await
                .expect_err("an oversized delay must fail before timer registration");
            assert_eq!(
                oversized_error.kind(),
                std::io::ErrorKind::InvalidInput,
                "a permanently unsupported duration must not masquerade as transient capacity"
            );

            let cx = frankenterm_core::cx::for_testing();
            cx.cancel_with(
                frankenterm_core::outcome::CancelKind::User,
                Some("watch-events cancellation regression"),
            );
            let read_was_polled = std::cell::Cell::new(false);
            let read_error = read_watch_ipc_line_until_durable_poll(
                &cx,
                std::time::Instant::now(),
                huge,
                async {
                    read_was_polled.set(true);
                    std::future::pending::<std::io::Result<Option<String>>>().await
                },
            )
            .await
            .expect_err("pre-cancelled IPC read must not wait for its poll interval");
            assert_eq!(read_error.kind(), std::io::ErrorKind::Interrupted);
            assert!(
                !read_was_polled.get(),
                "the pre-flight checkpoint must reject cancellation before polling the read"
            );

            let sleep_error = sleep_watch_delay_with_cx(&cx, huge, "test delay")
                .await
                .expect_err("pre-cancelled delay must not arm a huge timer");
            assert_eq!(sleep_error.kind(), std::io::ErrorKind::Interrupted);
        });
    }

    #[test]
    fn outer_failure_classifier_never_reports_cancellation_as_degradation() {
        let healthy = frankenterm_core::cx::for_testing();
        assert!(matches!(
            classify_watch_outer_failure(
                &healthy,
                "healthy transport failure",
                WatchFailureSource::Degradation,
            ),
            WatchOuterFailure::Degraded
        ));

        let typed = classify_watch_outer_failure(
            &healthy,
            "typed storage cancellation",
            WatchFailureSource::Cancellation,
        );
        let WatchOuterFailure::Cancelled(error) = typed else {
            panic!("typed cancellation was misclassified as degradation");
        };
        assert_eq!(error.kind(), std::io::ErrorKind::Interrupted);

        let cancelled = frankenterm_core::cx::for_testing();
        cancelled.cancel_with(
            frankenterm_core::outcome::CancelKind::User,
            Some("outer-loop cancellation"),
        );
        let flattened = classify_watch_outer_failure(
            &cancelled,
            "flattened IPC failure",
            WatchFailureSource::Degradation,
        );
        let WatchOuterFailure::Cancelled(error) = flattened else {
            panic!("cancelled Cx was misclassified as transport degradation");
        };
        assert_eq!(error.kind(), std::io::ErrorKind::Interrupted);
        assert!(error.to_string().contains("outer-loop cancellation"));

        let secret_cancelled = frankenterm_core::cx::for_testing();
        const SECRET: &str = "sk-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        const SECRET_REASON: &str =
            "operator request carried sk-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        secret_cancelled.cancel_with(
            frankenterm_core::outcome::CancelKind::User,
            Some(SECRET_REASON),
        );
        let secret_error = watch_checkpoint(&secret_cancelled, "secret-bearing cancellation")
            .expect_err("cancelled checkpoint must fail");
        let rendered = secret_error.to_string();
        assert!(
            rendered.contains("[REDACTED]"),
            "the cancellation reason must retain an explicit redaction marker: {rendered}"
        );
        assert!(
            !rendered.contains(SECRET),
            "the raw cancellation reason must not cross the watch output boundary: {rendered}"
        );

        let hostile_cancelled = frankenterm_core::cx::for_testing();
        static HOSTILE_REASON: std::sync::OnceLock<String> = std::sync::OnceLock::new();
        let hostile_reason = HOSTILE_REASON.get_or_init(|| {
            format!(
                "\x1b]0;stolen title\x07{}\nspoofed\u{2028}line\u{202e}direction\u{206a}shape",
                "猫".repeat(5_000)
            )
        });
        hostile_cancelled.cancel_with(
            frankenterm_core::outcome::CancelKind::User,
            Some(hostile_reason.as_str()),
        );
        let hostile_error = watch_checkpoint(&hostile_cancelled, "hostile cancellation")
            .expect_err("hostile cancellation must fail safely")
            .to_string();
        assert!(!hostile_error.contains('\x1b'));
        assert!(!hostile_error.contains('\n'));
        assert!(!hostile_error.contains('\u{2028}'));
        assert!(!hostile_error.contains('\u{202e}'));
        assert!(!hostile_error.contains('\u{206a}'));
        assert!(
            hostile_error.len() <= 2_200,
            "diagnostic was not byte-bounded"
        );

        assert_eq!(
            watch_core_failure_source(&frankenterm_core::Error::Cancelled(
                "storage cancelled".to_string()
            )),
            WatchFailureSource::Cancellation
        );
        assert_eq!(
            watch_core_failure_source(&frankenterm_core::Error::runtime_cancelled(
                "watch-test",
                "runtime cancelled",
            )),
            WatchFailureSource::Cancellation
        );
        assert_eq!(
            watch_core_failure_source(&frankenterm_core::Error::Io(std::io::Error::other(
                "transport failed"
            ))),
            WatchFailureSource::Degradation
        );
    }

    #[test]
    fn watch_delay_uses_one_canonical_timer_path_and_no_blocking_pool() {
        let source = include_str!("main.rs");
        let helper_start = source
            .find("async fn sleep_watch_delay_with_cx(")
            .expect("watch delay helper source");
        let helper_tail = &source[helper_start..];
        let helper_end = helper_tail
            .find("\n}\n\nfn watch_claim_retry_delay(")
            .expect("watch delay helper boundary");
        let helper = &helper_tail[..helper_end];

        assert!(helper.contains("sleep_with_cx_interruptible(cx, delay)"));
        assert!(!helper.contains("spawn_blocking"));
        assert!(!helper.contains("thread::sleep"));
        assert!(!helper.contains("loop {"));
        let operations = [
            ["pac", "ing"].concat(),
            ["lease retry", " delay"].concat(),
            ["idle poll", " delay"].concat(),
            ["await poll", " delay"].concat(),
        ];
        for operation in operations {
            let needle = format!("\"{operation}\"");
            let mut matches = source.match_indices(&needle);
            let (position, _) = matches
                .next()
                .unwrap_or_else(|| panic!("missing production {operation} delay call"));
            assert!(
                matches.next().is_none(),
                "production delay label {operation} must remain unique"
            );
            let line_start = source[..position].rfind('\n').map_or(0, |index| index + 1);
            let line_end = source[position..]
                .find('\n')
                .map_or(source.len(), |index| position + index);
            assert!(
                source[line_start..line_end].contains("sleep_watch_delay_with_cx"),
                "production {operation} delay must call the canonical helper"
            );
        }
    }

