    #[test]
    fn await_condition_matches_storage_quiescence() {
        let config = frankenterm_core::agent_pane_state::AgentDetectionConfig::default();
        let cond = AwaitCondition::Quiescence {
            pane_id: 7,
            idle_ms: Some(500),
        };

        assert_eq!(
            await_condition_matches_quiescence(&cond, Some(1_000), 1_500, &config),
            Some(true)
        );
        assert_eq!(
            await_condition_matches_quiescence(&cond, Some(1_001), 1_500, &config),
            Some(false)
        );
        assert_eq!(
            await_condition_matches_quiescence(&cond, None, 1_500, &config),
            Some(true)
        );
        assert_eq!(
            await_condition_matches_quiescence(&cond, Some(-1), 1_500, &config),
            Some(false),
            "negative authority-bearing timestamps must fail closed"
        );
        assert_eq!(
            await_condition_matches_quiescence(
                &AwaitCondition::Rule("codex.*".to_string()),
                None,
                1_500,
                &config,
            ),
            None
        );
    }

    #[test]
    fn quiescence_state_does_not_latch_after_output_resumes() {
        let config = frankenterm_core::agent_pane_state::AgentDetectionConfig::default();
        let quiescence = AwaitCondition::Quiescence {
            pane_id: 7,
            idle_ms: Some(500),
        };
        let quiet = refresh_await_condition_state(&quiescence, false, Some(1_000), 1_500, &config);
        assert!(quiet);
        let resumed =
            refresh_await_condition_state(&quiescence, quiet, Some(1_499), 1_500, &config);
        assert!(
            !resumed,
            "new pane output must clear a previously met quiescence condition"
        );

        let rule = AwaitCondition::Rule("build.done".to_string());
        assert!(
            refresh_await_condition_state(&rule, true, None, 1_500, &config),
            "historical rule occurrences remain latched"
        );
    }

