/// Parse a period string (e.g. "7d", "30d", "90d", "1d") into milliseconds.
fn parse_period_ms(period: &str) -> i64 {
    let s = period.trim().to_lowercase();
    if let Some(days_str) = s.strip_suffix('d') {
        if let Ok(days) = days_str.parse::<i64>() {
            return days * 86_400_000;
        }
    }
    // Default: 7 days
    7 * 86_400_000
}

/// Format a period string into a human-readable label.
fn format_period_label(period: &str) -> String {
    let s = period.trim().to_lowercase();
    if let Some(days_str) = s.strip_suffix('d') {
        if let Ok(days) = days_str.parse::<i64>() {
            return format!("Last {days} Day{}", if days == 1 { "" } else { "s" });
        }
    }
    "Last 7 Days".to_string()
}

/// Check if a refresh is rate-limited based on the most recent refresh timestamp.
///
/// Returns `Some((seconds_since_last, seconds_to_wait))` if rate-limited,
/// `None` if refresh is allowed.
fn check_refresh_cooldown(
    most_recent_refresh_ms: i64,
    now_ms_val: i64,
    cooldown_ms: i64,
) -> Option<(i64, i64)> {
    if most_recent_refresh_ms <= 0 {
        return None;
    }
    let elapsed = now_ms_val - most_recent_refresh_ms;
    if elapsed < cooldown_ms {
        Some((elapsed / 1000, (cooldown_ms - elapsed) / 1000))
    } else {
        None
    }
}

/// Apply tail truncation to text, returning the truncated text and truncation info
fn apply_tail_truncation(text: &str, tail_lines: usize) -> (String, bool, Option<TruncationInfo>) {
    let lines: Vec<&str> = text.lines().collect();
    let original_lines = lines.len();
    let original_bytes = text.len();

    if lines.len() <= tail_lines {
        // No truncation needed
        return (text.to_string(), false, None);
    }

    // Take the last N lines
    let start_idx = lines.len().saturating_sub(tail_lines);
    let truncated_lines: Vec<&str> = lines[start_idx..].to_vec();
    let truncated_text = truncated_lines.join("\n");
    let returned_bytes = truncated_text.len();
    let returned_lines = truncated_lines.len();

    (
        truncated_text,
        true,
        Some(TruncationInfo {
            original_bytes,
            returned_bytes,
            original_lines,
            returned_lines,
        }),
    )
}

fn dedupe_pane_ids(pane_ids: Vec<u64>) -> Vec<u64> {
    let mut seen = HashSet::new();
    let mut deduped = Vec::with_capacity(pane_ids.len());
    for pane_id in pane_ids {
        if seen.insert(pane_id) {
            deduped.push(pane_id);
        }
    }
    deduped
}

fn pane_matches_agent_filter(agent_filter: &str, pane_title: &str) -> bool {
    let title_lower = pane_title.to_lowercase();
    let filter_lower = agent_filter.to_lowercase();
    match filter_lower.as_str() {
        "codex" => title_lower.contains("codex") || title_lower.contains("openai"),
        "claude_code" | "claude" => title_lower.contains("claude"),
        "gemini" => title_lower.contains("gemini"),
        _ => title_lower.contains(&filter_lower),
    }
}

fn is_distributed_remote_domain(domain: &str) -> bool {
    domain.starts_with("distributed:")
}

/// Fast read-only check for whether any distributed panes exist in the DB.
/// Opens the database in read-only mode (avoiding WAL recovery) and runs a
/// lightweight COUNT query. Returns `false` on any error so the caller
/// gracefully skips the distributed merge path.
fn has_distributed_panes_in_db(db_path: &Path) -> bool {
    let conn = match rusqlite::Connection::open_with_flags(
        db_path,
        rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
    ) {
        Ok(c) => c,
        Err(err) => {
            tracing::debug!(error = %err, "read-only open for distributed pane check failed");
            return false;
        }
    };
    match conn.query_row(
        "SELECT count(*) FROM panes WHERE domain LIKE 'distributed:%'",
        [],
        |row| row.get::<_, i64>(0),
    ) {
        Ok(count) => count > 0,
        Err(err) => {
            tracing::debug!(error = %err, "distributed pane count query failed");
            false
        }
    }
}

fn merge_distributed_remote_records(
    records: &mut Vec<frankenterm_core::storage::PaneRecord>,
    remote_records: Vec<frankenterm_core::storage::PaneRecord>,
    pane_id_filter: Option<u64>,
    domain_filter: Option<&str>,
    agent_filter: Option<&str>,
    bookmark_pane_ids: Option<&HashSet<u64>>,
) {
    let mut existing_pane_ids: HashSet<u64> = records.iter().map(|r| r.pane_id).collect();
    for record in remote_records {
        if existing_pane_ids.contains(&record.pane_id) {
            continue;
        }
        if let Some(filter_pane_id) = pane_id_filter {
            if record.pane_id != filter_pane_id {
                continue;
            }
        }
        if let Some(domain_filter) = domain_filter {
            if !glob_match(domain_filter, &record.domain) {
                continue;
            }
        }
        if let Some(bookmark_filters) = bookmark_pane_ids {
            if !bookmark_filters.contains(&record.pane_id) {
                continue;
            }
        }
        if let Some(agent_filter) = agent_filter {
            let title = record.title.as_deref().unwrap_or("");
            if !pane_matches_agent_filter(agent_filter, title) {
                continue;
            }
        }
        existing_pane_ids.insert(record.pane_id);
        records.push(record);
    }

    records.sort_by_key(|r| r.pane_id);
}

async fn load_distributed_remote_panes(
    db_path: &Path,
) -> Result<Vec<frankenterm_core::storage::PaneRecord>, frankenterm_core::Error> {
    let db_path = db_path.to_string_lossy();
    // ft-xbnl0.2.3 tick 248/300: cx-first storage open + read (shared binding).
    let storage_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    let storage =
        frankenterm_core::storage::StorageHandle::new_with_cx(&storage_cx, &db_path).await?;
    let panes = storage.get_panes_with_cx(&storage_cx).await?;
    if let Err(err) = storage.shutdown().await {
        tracing::warn!(error = %err, "Failed to shutdown storage cleanly after distributed pane query");
    }

    Ok(panes
        .into_iter()
        .filter(|pane| is_distributed_remote_domain(&pane.domain))
        .collect())
}

async fn load_distributed_remote_pane_record(
    storage: Option<&frankenterm_core::storage::StorageHandle>,
    pane_id: u64,
) -> Result<Option<frankenterm_core::storage::PaneRecord>, frankenterm_core::Error> {
    let Some(storage) = storage else {
        return Ok(None);
    };

    Ok(storage
        .get_pane(pane_id)
        .await?
        .filter(|pane| is_distributed_remote_domain(&pane.domain)))
}

fn distributed_remote_pane_text_unavailable_hint() -> String {
    DISTRIBUTED_REMOTE_TEXT_UNAVAILABLE_HINT.to_string()
}

fn distributed_remote_pane_text_unavailable_result() -> RobotPaneTextResult {
    RobotPaneTextResult::Error {
        code: ROBOT_ERR_REMOTE_TEXT_UNAVAILABLE.to_string(),
        message: DISTRIBUTED_REMOTE_TEXT_UNAVAILABLE_MESSAGE.to_string(),
        hint: Some(distributed_remote_pane_text_unavailable_hint()),
    }
}

fn merge_distributed_remote_pane_states(
    states: &mut Vec<PaneState>,
    remote_records: Vec<frankenterm_core::storage::PaneRecord>,
) {
    let mut existing_pane_ids: HashSet<u64> = states.iter().map(|state| state.pane_id).collect();
    for record in remote_records {
        if !existing_pane_ids.insert(record.pane_id) {
            continue;
        }
        states.push(PaneState::from_pane_record(&record));
    }

    states.sort_by_key(|state| state.pane_id);
}

fn add_distributed_remote_pane_text_placeholders(
    states: &[PaneState],
    pane_text: &mut BTreeMap<u64, RobotPaneTextResult>,
) {
    for state in states {
        if !is_distributed_remote_domain(&state.domain) || pane_text.contains_key(&state.pane_id) {
            continue;
        }
        pane_text.insert(
            state.pane_id,
            distributed_remote_pane_text_unavailable_result(),
        );
    }
}

fn runtime_task_join_failure(
    operation: &'static str,
    error: frankenterm_core::runtime_async::task::JoinError,
) -> frankenterm_core::Error {
    let source = runtime_task_join_failure_source(error.kind());
    frankenterm_core::Error::RuntimeOperation { operation, source }
}

fn runtime_task_join_failure_source(
    kind: frankenterm_core::runtime_async::task::JoinErrorKind,
) -> frankenterm_core::error::RuntimeOperationSource {
    use frankenterm_core::error::RuntimeOperationSource;
    use frankenterm_core::runtime_async::task::JoinErrorKind;

    match kind {
        JoinErrorKind::Aborted => {
            RuntimeOperationSource::Cancelled("runtime task aborted".to_string())
        }
        JoinErrorKind::ContextCancelled => RuntimeOperationSource::Cancelled(
            "runtime task cancelled by capability context".to_string(),
        ),
        JoinErrorKind::DeadlineExceeded => RuntimeOperationSource::Backend(
            "capability deadline exceeded at runtime task join".to_string(),
        ),
        JoinErrorKind::PollQuotaExhausted => RuntimeOperationSource::Backend(
            "capability poll quota exhausted at runtime task join".to_string(),
        ),
        JoinErrorKind::CostBudgetExhausted => RuntimeOperationSource::Backend(
            "capability cost budget exhausted at runtime task join".to_string(),
        ),
        JoinErrorKind::ContextFailure => RuntimeOperationSource::Backend(
            "capability context failed at runtime task join".to_string(),
        ),
        JoinErrorKind::TaskFailed => {
            RuntimeOperationSource::Backend("runtime task failed at join boundary".to_string())
        }
        JoinErrorKind::WakerRegistrationFailed => RuntimeOperationSource::Backend(
            "runtime task join waker registration failed".to_string(),
        ),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CapabilityContextSite {
    RobotOperation,
    SemaphoreAcquire,
}

impl CapabilityContextSite {
    const fn cancelled_detail(self) -> &'static str {
        match self {
            Self::RobotOperation => "robot operation cancelled",
            Self::SemaphoreAcquire => "semaphore acquire cancelled",
        }
    }
}

fn capability_context_failure(
    operation: &'static str,
    cx: &frankenterm_core::cx::Cx,
    site: CapabilityContextSite,
) -> frankenterm_core::Error {
    use frankenterm_core::error::RuntimeOperationSource;
    use frankenterm_core::outcome::CancelKind;

    let source = match cx.root_cancel_cause().map(|reason| reason.kind) {
        Some(CancelKind::Deadline | CancelKind::Timeout) => {
            RuntimeOperationSource::Backend("capability deadline exceeded".to_string())
        }
        Some(CancelKind::PollQuota) => {
            RuntimeOperationSource::Backend("capability poll quota exhausted".to_string())
        }
        Some(CancelKind::CostBudget) => {
            RuntimeOperationSource::Backend("capability cost budget exhausted".to_string())
        }
        Some(
            CancelKind::User
            | CancelKind::FailFast
            | CancelKind::RaceLost
            | CancelKind::ParentCancelled
            | CancelKind::ResourceUnavailable
            | CancelKind::Shutdown
            | CancelKind::LinkedExit,
        ) => RuntimeOperationSource::Cancelled(site.cancelled_detail().to_string()),
        None => RuntimeOperationSource::Backend("capability context failed".to_string()),
    };
    frankenterm_core::Error::RuntimeOperation { operation, source }
}

fn runtime_context_preflight(
    operation: &'static str,
    cx: &frankenterm_core::cx::Cx,
    site: CapabilityContextSite,
) -> frankenterm_core::Result<()> {
    cx.checkpoint()
        .map_err(|_| capability_context_failure(operation, cx, site))
}

fn semaphore_acquire_failure(
    operation: &'static str,
    cx: &frankenterm_core::cx::Cx,
    error: frankenterm_core::runtime_async::AcquireError,
) -> frankenterm_core::Error {
    let source = match error {
        frankenterm_core::runtime_async::AcquireError::Closed => {
            frankenterm_core::error::RuntimeOperationSource::Backend("semaphore closed".to_string())
        }
        frankenterm_core::runtime_async::AcquireError::PolledAfterCompletion => {
            frankenterm_core::error::RuntimeOperationSource::Backend(
                "semaphore acquire future polled after completion".to_string(),
            )
        }
        frankenterm_core::runtime_async::AcquireError::Cancelled => {
            return capability_context_failure(
                operation,
                cx,
                CapabilityContextSite::SemaphoreAcquire,
            );
        }
    };
    frankenterm_core::Error::RuntimeOperation { operation, source }
}

#[cfg(test)]
#[test]
fn runtime_task_join_failure_maps_every_finite_class_without_free_text() {
    use frankenterm_core::error::RuntimeOperationSource;
    use frankenterm_core::runtime_async::task::JoinErrorKind;

    let cases = [
        (JoinErrorKind::Aborted, true, "runtime task aborted"),
        (
            JoinErrorKind::ContextCancelled,
            true,
            "runtime task cancelled by capability context",
        ),
        (
            JoinErrorKind::DeadlineExceeded,
            false,
            "capability deadline exceeded at runtime task join",
        ),
        (
            JoinErrorKind::PollQuotaExhausted,
            false,
            "capability poll quota exhausted at runtime task join",
        ),
        (
            JoinErrorKind::CostBudgetExhausted,
            false,
            "capability cost budget exhausted at runtime task join",
        ),
        (
            JoinErrorKind::ContextFailure,
            false,
            "capability context failed at runtime task join",
        ),
        (
            JoinErrorKind::TaskFailed,
            false,
            "runtime task failed at join boundary",
        ),
        (
            JoinErrorKind::WakerRegistrationFailed,
            false,
            "runtime task join waker registration failed",
        ),
    ];

    for (kind, expected_cancelled, expected_detail) in cases {
        let source = runtime_task_join_failure_source(kind);
        let (actual_cancelled, detail) = match source {
            RuntimeOperationSource::Cancelled(detail) => (true, detail),
            RuntimeOperationSource::Backend(detail) => (false, detail),
            other => panic!("join failure must use a finite cancellation/backend class: {other:?}"),
        };
        assert_eq!(actual_cancelled, expected_cancelled, "kind: {kind:?}");
        assert_eq!(detail, expected_detail, "kind: {kind:?}");
        assert!(!detail.contains("SECRET"), "kind: {kind:?}");
    }

    let error = runtime_task_join_failure(
        "test.cancelled",
        frankenterm_core::runtime_async::task::JoinError::aborted(),
    );
    assert!(matches!(
        error,
        frankenterm_core::Error::RuntimeOperation {
            operation: "test.cancelled",
            source: RuntimeOperationSource::Cancelled(detail),
        } if detail == "runtime task aborted"
    ));
}

#[cfg(test)]
#[test]
fn capability_context_failure_maps_every_cancel_kind_without_reason_text() {
    use frankenterm_core::error::RuntimeOperationSource;
    use frankenterm_core::outcome::CancelKind;

    let cases = [
        (CancelKind::Deadline, false, "capability deadline exceeded"),
        (
            CancelKind::PollQuota,
            false,
            "capability poll quota exhausted",
        ),
        (
            CancelKind::CostBudget,
            false,
            "capability cost budget exhausted",
        ),
        (CancelKind::Timeout, false, "capability deadline exceeded"),
        (CancelKind::User, true, "robot operation cancelled"),
        (CancelKind::FailFast, true, "robot operation cancelled"),
        (CancelKind::RaceLost, true, "robot operation cancelled"),
        (
            CancelKind::ParentCancelled,
            true,
            "robot operation cancelled",
        ),
        (
            CancelKind::ResourceUnavailable,
            true,
            "robot operation cancelled",
        ),
        (CancelKind::Shutdown, true, "robot operation cancelled"),
        (CancelKind::LinkedExit, true, "robot operation cancelled"),
    ];

    for (kind, expected_cancelled, expected_detail) in cases {
        let cx = frankenterm_core::cx::for_testing();
        cx.cancel_with(kind, Some("SECRET cancellation reason"));
        let error =
            capability_context_failure("test.context", &cx, CapabilityContextSite::RobotOperation);
        let frankenterm_core::Error::RuntimeOperation { operation, source } = error else {
            panic!("context failure must remain a runtime operation");
        };
        assert_eq!(operation, "test.context");
        let (actual_cancelled, detail) = match source {
            RuntimeOperationSource::Cancelled(detail) => (true, detail),
            RuntimeOperationSource::Backend(detail) => (false, detail),
            other => panic!("context failure must use cancellation/backend: {other:?}"),
        };
        assert_eq!(actual_cancelled, expected_cancelled, "kind: {kind:?}");
        assert_eq!(detail, expected_detail, "kind: {kind:?}");
        assert!(!detail.contains("SECRET"), "kind: {kind:?}");
    }

    let live_cx = frankenterm_core::cx::for_testing();
    let fallback = capability_context_failure(
        "test.fallback",
        &live_cx,
        CapabilityContextSite::RobotOperation,
    );
    assert!(matches!(
        fallback,
        frankenterm_core::Error::RuntimeOperation {
            operation: "test.fallback",
            source: RuntimeOperationSource::Backend(detail),
        } if detail == "capability context failed"
    ));
}

