async fn batch_get_pane_text(
    wezterm: frankenterm_core::wezterm::WeztermHandle,
    pane_ids: &[u64],
    escapes: bool,
    tail_lines: usize,
) -> BTreeMap<u64, RobotPaneTextResult> {
    let parent_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    let semaphore = Arc::new(frankenterm_core::runtime_async::Semaphore::new(
        ROBOT_BATCH_GET_TEXT_MAX_CONCURRENT,
    ));
    let mut tasks = Vec::with_capacity(pane_ids.len());

    for pane_id in pane_ids.iter().copied() {
        let wezterm = wezterm.clone();
        let semaphore = semaphore.clone();
        let task = frankenterm_core::runtime_async::task::spawn_with_cx(
            &parent_cx,
            move |child_cx| async move {
                let _permit =
                    semaphore
                        .acquire_owned_with_cx(&child_cx)
                        .await
                        .map_err(|error| {
                            semaphore_acquire_failure(
                                "batch_get_text.acquire_permit",
                                &child_cx,
                                error,
                            )
                        })?;
                wezterm.get_text_with_cx(&child_cx, pane_id, escapes).await
            },
        );
        tasks.push((pane_id, task));
    }

    let mut results = BTreeMap::new();
    for (pane_id, task) in tasks {
        let result = match task.await {
            Ok(result) => result,
            Err(error) => Err(runtime_task_join_failure(
                "batch_get_text.await_task",
                error,
            )),
        };

        match result {
            Ok(full_text) => {
                let (text, truncated, truncation_info) =
                    apply_tail_truncation(&full_text, tail_lines);
                results.insert(
                    pane_id,
                    RobotPaneTextResult::Ok {
                        text,
                        truncated,
                        truncation_info,
                    },
                );
            }
            Err(error) => {
                let (code, hint) = map_wezterm_error_to_robot(&error);
                results.insert(
                    pane_id,
                    RobotPaneTextResult::Error {
                        code: code.to_string(),
                        message: format!("{error}"),
                        hint,
                    },
                );
            }
        }
    }

    results
}

/// Map every finite mux rejection class to a stable Robot error code.
fn map_mux_rejection_code_to_robot(
    code: frankenterm_core::error::MuxRejectionCode,
) -> (&'static str, Option<String>) {
    use frankenterm_core::error::MuxRejectionCode;

    match code {
        MuxRejectionCode::PaneNotFound => (
            ROBOT_ERR_PANE_NOT_FOUND,
            Some("The requested mux pane no longer exists. Reconcile live mux state.".to_string()),
        ),
        MuxRejectionCode::TabNotFound => (
            ROBOT_ERR_TAB_NOT_FOUND,
            Some("The requested mux tab no longer exists. Reconcile live mux state.".to_string()),
        ),
        MuxRejectionCode::WindowNotFound => (
            ROBOT_ERR_WINDOW_NOT_FOUND,
            Some("The requested mux window no longer exists. Reconcile live mux state.".to_string()),
        ),
        MuxRejectionCode::DomainNotFound => (
            ROBOT_ERR_DOMAIN_NOT_FOUND,
            Some("The requested mux domain no longer exists. Reconcile live mux state.".to_string()),
        ),
        MuxRejectionCode::InvalidRequest => (
            ROBOT_ERR_INVALID_ARGS,
            Some("The mux rejected the request as invalid; correct it before retrying.".to_string()),
        ),
        MuxRejectionCode::PolicyRejected => (
            ROBOT_ERR_POLICY_DENIED,
            Some("Mux policy rejected the operation; review policy and approval state.".to_string()),
        ),
        MuxRejectionCode::Cancelled => (
            ROBOT_ERR_MUX_CANCELLED,
            Some("The mux operation was cancelled before it took effect.".to_string()),
        ),
        MuxRejectionCode::DeadlineExceeded => (
            ROBOT_ERR_TIMEOUT,
            Some("The mux operation exceeded its deadline before it took effect.".to_string()),
        ),
        MuxRejectionCode::QuotaExceeded => (
            ROBOT_ERR_MUX_QUOTA_EXCEEDED,
            Some("The mux operation exceeded a bounded quota; retry only after backoff.".to_string()),
        ),
        MuxRejectionCode::BackendFailure => (
            ROBOT_ERR_MUX_BACKEND_FAILURE,
            Some("The mux backend failed before applying the operation; retry after backoff.".to_string()),
        ),
        MuxRejectionCode::IndeterminateMutation => (
            ROBOT_ERR_WEZTERM_MUTATION_INDETERMINATE,
            Some(
                "The mutation may already have taken effect. Reconcile live mux state and verify the intended postcondition; do not blindly retry."
                    .to_string(),
            ),
        ),
        MuxRejectionCode::UnknownFuture => (
            ROBOT_ERR_MUX_UNKNOWN_FUTURE,
            Some(
                "The mux returned an unknown future rejection. Upgrade FrankenTerm and reconcile live mux state before retrying."
                    .to_string(),
            ),
        ),
    }
}

/// Map frankenterm_core errors to stable Robot error codes.
fn map_wezterm_error_to_robot(error: &frankenterm_core::Error) -> (&'static str, Option<String>) {
    use frankenterm_core::error::WeztermError;

    match error {
        frankenterm_core::Error::Wezterm(wezterm_err) => match wezterm_err {
            WeztermError::CliNotFound => (
                "robot.wezterm_not_found",
                Some(
                    "Install/configure the active backend bridge (current: WezTerm) or ensure 'wezterm' is in PATH."
                        .to_string(),
                ),
            ),
            WeztermError::NotRunning => (
                "robot.wezterm_not_running",
                Some(
                    "Start the active backend bridge (current: WezTerm) before running ft commands."
                        .to_string(),
                ),
            ),
            WeztermError::PaneNotFound(pane_id) => (
                "robot.pane_not_found",
                Some(format!(
                    "Pane {pane_id} does not exist. Use 'ft robot state' to list available panes."
                )),
            ),
            WeztermError::SocketNotFound(_) => (
                "robot.wezterm_socket_not_found",
                Some(
                    "Backend socket not found. Is the active backend bridge (WezTerm) running?"
                        .to_string(),
                ),
            ),
            WeztermError::CommandFailed(_) => (
                "robot.wezterm_command_failed",
                Some(
                    "Backend CLI command failed. Check backend logs (including WezTerm bridge logs) for details."
                        .to_string(),
                ),
            ),
            WeztermError::IndeterminateMutation { .. } => (
                ROBOT_ERR_WEZTERM_MUTATION_INDETERMINATE,
                Some(
                    "The mutation may already have taken effect. Reconcile live mux state and verify the intended postcondition; do not blindly retry."
                        .to_string(),
                ),
            ),
            WeztermError::ParseError(_) => (
                "robot.wezterm_parse_error",
                Some(
                    "Failed to parse WezTerm output. This may indicate a version mismatch."
                        .to_string(),
                ),
            ),
            WeztermError::VersionSkew {
                local_codec,
                remote_codec,
                remote_version,
                ..
            } => (
                "robot.mux_version_skew",
                Some(format!(
                    "This ft speaks codec {local_codec}; the mux at the discovered socket speaks codec {remote_codec} (version {remote_version}). Install matching generations of ft and FrankenTerm.app (`ft doctor --json` shows the socket); retrying cannot help."
                )),
            ),
            WeztermError::OutputTooLarge { .. } => (
                "robot.wezterm_output_too_large",
                Some(
                    "Backend returned an oversized metadata response; the parse was refused to protect memory."
                        .to_string(),
                ),
            ),
            WeztermError::Timeout(_) => (
                ROBOT_ERR_TIMEOUT,
                Some("WezTerm command timed out. The terminal may be unresponsive.".to_string()),
            ),
            WeztermError::CircuitOpen { retry_after_ms } => (
                "robot.circuit_open",
                Some(format!(
                    "WezTerm circuit breaker is open. Retry after {retry_after_ms} ms."
                )),
            ),
            WeztermError::MuxRejection(rejection) => {
                map_mux_rejection_code_to_robot(rejection.code)
            }
        },
        _ => (
            "robot.internal_error",
            Some("An unexpected internal error occurred.".to_string()),
        ),
    }
}

fn init_logging_from_config(
    config: &frankenterm_core::config::Config,
    workspace_root: Option<&Path>,
) -> anyhow::Result<()> {
    let log_file = config
        .general
        .log_file
        .as_ref()
        .map(|path| resolve_log_path(path, workspace_root));

    let log_config = LogConfig {
        level: config.general.log_level.clone(),
        format: config.general.log_format,
        file: log_file,
    };

    match init_logging(&log_config) {
        Ok(()) | Err(LogError::AlreadyInitialized) => {}
        Err(err) => return Err(err.into()),
    }

    if let Some(root) = workspace_root {
        tracing::info!(workspace = %root.display(), "Workspace resolved");
    }

    Ok(())
}

fn resolve_log_path(path: &str, workspace_root: Option<&Path>) -> std::path::PathBuf {
    let candidate = std::path::PathBuf::from(path);
    if candidate.is_absolute() {
        candidate
    } else if let Some(root) = workspace_root {
        root.join(candidate)
    } else {
        candidate
    }
}

fn emit_permission_warnings(warnings: &[frankenterm_core::config::PermissionWarning]) {
    for warning in warnings {
        tracing::warn!(
            label = warning.label,
            path = %warning.path.display(),
            actual_mode = format!("{actual_mode:o}", actual_mode = warning.actual_mode),
            expected_mode = format!("{expected_mode:o}", expected_mode = warning.expected_mode),
            "Permissions too open"
        );
    }
}

/// Simple glob pattern matching for CLI filters.
///
/// Supports `*` for any sequence and `?` for single character.
fn glob_match(pattern: &str, value: &str) -> bool {
    if !pattern.contains('*') && !pattern.contains('?') {
        // Exact match
        return value == pattern;
    }

    // Convert glob to regex-style matching
    let mut regex_pattern = String::from("^");
    for ch in pattern.chars() {
        match ch {
            '*' => regex_pattern.push_str(".*"),
            '?' => regex_pattern.push('.'),
            '.' | '+' | '^' | '$' | '(' | ')' | '[' | ']' | '{' | '}' | '|' | '\\' => {
                regex_pattern.push('\\');
                regex_pattern.push(ch);
            }
            _ => regex_pattern.push(ch),
        }
    }
    regex_pattern.push('$');

    fancy_regex::Regex::new(&regex_pattern).is_ok_and(|re| re.is_match(value).unwrap_or(false))
}

#[cfg(any(unix, test))]
fn is_structured_uservar_name(name: &str) -> bool {
    let lower = name.to_lowercase();
    lower.starts_with("ft-")
        || lower.starts_with("ft_")
        || lower == "ft_event"
        // Backward compat: accept legacy wa_ prefix
        || lower.starts_with("wa-")
        || lower.starts_with("wa_")
        || lower == "wa_event"
}

#[cfg(any(unix, test))]
fn validate_uservar_request(pane_id: u64, name: &str, value: &str) -> Result<(), String> {
    // Use the canonical IPC message size limit from frankenterm-core.
    // Previously duplicated here as 131_072 — now reads from the single source.
    const MAX_MESSAGE_SIZE: usize =
        frankenterm_core::tuning_config::IpcTuning::DEFAULT_MAX_MESSAGE_SIZE;

    if name.trim().is_empty() {
        return Err("user-var name cannot be empty".to_string());
    }
    if value.is_empty() {
        return Err("user-var value cannot be empty".to_string());
    }

    // Estimate request size (JSON overhead is ~50 bytes for field names + pane_id)
    // Format: {"type":"user_var","pane_id":N,"name":"...","value":"..."}
    let request_size = 50 + pane_id.to_string().len() + name.len() + value.len();
    if request_size > MAX_MESSAGE_SIZE {
        return Err(format!(
            "user-var payload too large: {request_size} bytes (max {MAX_MESSAGE_SIZE})"
        ));
    }

    if is_structured_uservar_name(name) {
        frankenterm_core::events::UserVarPayload::decode(value, false)
            .map_err(|e| format!("invalid structured user-var payload for '{name}': {e}"))?;
    }

    Ok(())
}

struct IpcRpcArgError {
    message: String,
    hint: Option<String>,
}

fn sanitize_ipc_rpc_args(args: &[String]) -> Result<Vec<String>, IpcRpcArgError> {
    let mut sanitized = Vec::with_capacity(args.len());
    let mut skip_next = false;

    for arg in args {
        if skip_next {
            skip_next = false;
            continue;
        }

        if arg == "--help" || arg == "-h" {
            return Err(IpcRpcArgError {
                message: "help flags are not supported over IPC".to_string(),
                hint: Some("Use `ft robot help` or the `help` command instead.".to_string()),
            });
        }

        if arg == "--format" || arg == "-f" {
            skip_next = true;
            continue;
        }

        if arg.starts_with("--format=") || arg == "--stats" {
            continue;
        }

        sanitized.push(arg.clone());
    }

    Ok(sanitized)
}

fn build_ipc_rpc_summary(args: &[String]) -> String {
    if args.is_empty() {
        return "ft robot".to_string();
    }

    let redacted: Vec<String> = args.iter().map(|arg| redact_for_output(arg)).collect();
    format!("ft robot {}", redacted.join(" "))
}

async fn run_robot_rpc_via_cli(
    args: &[String],
    config_path: Option<&Path>,
    workspace_root: &Path,
) -> Result<frankenterm_core::ipc::IpcResponse, String> {
    use std::process::Stdio;

    let exe =
        std::env::current_exe().map_err(|e| format!("failed to resolve ft executable: {e}"))?;
    let config_path = config_path.map(PathBuf::from);
    let workspace_root = workspace_root.to_path_buf();
    let args = args.to_vec();

    // Keep subprocess ownership explicit here; the runtime only owns the
    // blocking wait on the child process.
    let output = frankenterm_core::runtime_async::spawn_blocking(move || {
        let mut cmd = std::process::Command::new(exe);

        if let Some(path) = &config_path {
            cmd.arg("--config").arg(path);
        }

        cmd.arg("--workspace").arg(&workspace_root);
        cmd.arg("robot").arg("--format").arg("json");
        cmd.args(&args);
        cmd.stdout(Stdio::piped()).stderr(Stdio::piped());
        cmd.output()
    })
    .await
    .map_err(|e| format!("failed to run ft robot: {e}"))?
    .map_err(|e| format!("failed to run ft robot: {e}"))?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let stdout = String::from_utf8_lossy(&output.stdout);
        let detail = if stderr.trim().is_empty() {
            stdout.trim()
        } else {
            stderr.trim()
        };
        if detail.is_empty() {
            return Err(format!("ft robot exited with status {}", output.status));
        }
        return Err(format!("ft robot failed: {detail}"));
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let payload = stdout.trim();
    if payload.is_empty() {
        return Err("ft robot returned empty output".to_string());
    }

    serde_json::from_str::<frankenterm_core::ipc::IpcResponse>(payload)
        .map_err(|e| format!("invalid ft robot response: {e}"))
}

#[derive(Debug)]
struct NtmParityCliCapture {
    exit_code: Option<i32>,
    duration_ms: u64,
    stdout: String,
    stderr: String,
    execution_error: Option<String>,
}

#[derive(Debug)]
struct NtmParityRunOutcome {
    output_dir: PathBuf,
    resolved_pane_id: Option<u64>,
    summary: frankenterm_core::ntm_parity::NtmParityRunSummary,
}

fn tokenize_cli_words(input: &str) -> Result<Vec<String>, String> {
    let mut words = Vec::new();
    let mut current = String::new();
    let mut chars = input.chars();
    let mut quote: Option<char> = None;

    while let Some(ch) = chars.next() {
        match quote {
            Some(delimiter) => match ch {
                '\\' => {
                    if let Some(next) = chars.next() {
                        current.push(next);
                    } else {
                        current.push('\\');
                    }
                }
                value if value == delimiter => {
                    quote = None;
                }
                _ => current.push(ch),
            },
            None => match ch {
                '\'' | '"' => {
                    quote = Some(ch);
                }
                '\\' => {
                    if let Some(next) = chars.next() {
                        current.push(next);
                    } else {
                        current.push('\\');
                    }
                }
                value if value.is_whitespace() => {
                    if !current.is_empty() {
                        words.push(std::mem::take(&mut current));
                    }
                }
                _ => current.push(ch),
            },
        }
    }

    if let Some(delimiter) = quote {
        return Err(format!("unterminated {delimiter} quote in command"));
    }

    if !current.is_empty() {
        words.push(current);
    }

    Ok(words)
}

fn resolve_path_from_workspace(workspace_root: &Path, path: &Path) -> PathBuf {
    if path.is_absolute() {
        path.to_path_buf()
    } else {
        workspace_root.join(path)
    }
}

fn default_ntm_parity_run_id() -> String {
    format!("ntm-parity-{}", chrono::Utc::now().format("%Y%m%d-%H%M%S"))
}

fn default_ntm_parity_output_dir(
    workspace_root: &Path,
    matrix: &frankenterm_core::ntm_parity::NtmParityAcceptanceMatrix,
    run_id: &str,
) -> PathBuf {
    let root = matrix
        .artifacts_contract
        .artifact_root
        .replace("<run_id>", run_id);
    let root_path = PathBuf::from(root);
    resolve_path_from_workspace(workspace_root, &root_path)
}

fn parse_intentional_deltas(entries: &[String]) -> anyhow::Result<HashMap<String, String>> {
    let mut deltas = HashMap::new();

    for entry in entries {
        let (scenario_id, reason) = entry.split_once('=').ok_or_else(|| {
            anyhow::anyhow!("invalid intentional delta '{entry}'; expected SCENARIO_ID=reason")
        })?;
        let scenario_id = scenario_id.trim();
        let reason = reason.trim();
        if scenario_id.is_empty() || reason.is_empty() {
            return Err(anyhow::anyhow!(
                "invalid intentional delta '{entry}'; scenario id and reason are required"
            ));
        }
        deltas.insert(scenario_id.to_string(), reason.to_string());
    }

    Ok(deltas)
}

async fn run_ft_cli_capture(
    exe: &Path,
    args: &[String],
    config_path: Option<&Path>,
    workspace_root: &Path,
) -> NtmParityCliCapture {
    use std::process::Stdio;

    let exe = exe.to_path_buf();
    let config_path = config_path.map(PathBuf::from);
    let workspace_root = workspace_root.to_path_buf();
    let args = args.to_vec();
    let exe_display = exe.display().to_string();

    let started_at = Instant::now();
    match frankenterm_core::runtime_async::spawn_blocking(move || {
        let mut cmd = std::process::Command::new(&exe);
        if let Some(path) = &config_path {
            cmd.arg("--config").arg(path);
        }
        cmd.arg("--workspace").arg(&workspace_root);
        cmd.args(&args);
        cmd.stdout(Stdio::piped()).stderr(Stdio::piped());
        cmd.output()
    })
    .await
    {
        Ok(Ok(output)) => NtmParityCliCapture {
            exit_code: output.status.code(),
            duration_ms: started_at.elapsed().as_millis() as u64,
            stdout: String::from_utf8_lossy(&output.stdout).to_string(),
            stderr: String::from_utf8_lossy(&output.stderr).to_string(),
            execution_error: None,
        },
        Ok(Err(err)) => NtmParityCliCapture {
            exit_code: None,
            duration_ms: started_at.elapsed().as_millis() as u64,
            stdout: String::new(),
            stderr: String::new(),
            execution_error: Some(format!("failed to execute '{exe_display}': {err}")),
        },
        Err(err) => NtmParityCliCapture {
            exit_code: None,
            duration_ms: started_at.elapsed().as_millis() as u64,
            stdout: String::new(),
            stderr: String::new(),
            execution_error: Some(format!("failed to execute '{exe_display}': {err}")),
        },
    }
}

async fn resolve_ntm_parity_pane_id(
    exe: &Path,
    config_path: Option<&Path>,
    workspace_root: &Path,
) -> anyhow::Result<u64> {
    let args = vec![
        "robot".to_string(),
        "--format".to_string(),
        "json".to_string(),
        "state".to_string(),
    ];
    let capture = run_ft_cli_capture(exe, &args, config_path, workspace_root).await;
    if let Some(error) = capture.execution_error {
        return Err(anyhow::anyhow!(
            "failed to auto-resolve pane id for parity run: {error}"
        ));
    }

    let payload = capture.stdout.trim();
    if payload.is_empty() {
        return Err(anyhow::anyhow!(
            "failed to auto-resolve pane id for parity run: `ft robot state` returned empty output"
        ));
    }

    let value: serde_json::Value = serde_json::from_str(payload).map_err(|err| {
        anyhow::anyhow!("failed to parse `ft robot state` while resolving pane id: {err}")
    })?;
    let data = value.get("data").ok_or_else(|| {
        anyhow::anyhow!("failed to auto-resolve pane id for parity run: missing `data` field")
    })?;
    let panes = data
        .as_array()
        .or_else(|| data.get("panes").and_then(serde_json::Value::as_array))
        .ok_or_else(|| {
            anyhow::anyhow!(
                "failed to auto-resolve pane id for parity run: `data` is neither a pane array nor an object with a `panes` array"
            )
        })?;
    let pane_id = panes
        .first()
        .and_then(|pane| pane.get("pane_id"))
        .and_then(serde_json::Value::as_u64)
        .ok_or_else(|| {
            anyhow::anyhow!(
                "failed to auto-resolve pane id for parity run: no live panes available; pass --pane-id explicitly"
            )
        })?;

    Ok(pane_id)
}

fn write_json_pretty<T: serde::Serialize>(path: &Path, value: &T) -> anyhow::Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|err| {
            anyhow::anyhow!("failed to create directory '{}': {err}", parent.display())
        })?;
    }
    let payload = serde_json::to_string_pretty(value)
        .map_err(|err| anyhow::anyhow!("failed to serialize JSON '{}': {err}", path.display()))?;
    fs::write(path, payload)
        .map_err(|err| anyhow::anyhow!("failed to write '{}': {err}", path.display()))?;
    Ok(())
}

fn write_jsonl<T: serde::Serialize>(path: &Path, rows: &[T]) -> anyhow::Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|err| {
            anyhow::anyhow!("failed to create directory '{}': {err}", parent.display())
        })?;
    }

    let mut payload = String::new();
    for row in rows {
        let line = serde_json::to_string(row).map_err(|err| {
            anyhow::anyhow!(
                "failed to serialize JSONL row for '{}': {err}",
                path.display()
            )
        })?;
        payload.push_str(&line);
        payload.push('\n');
    }

    fs::write(path, payload)
        .map_err(|err| anyhow::anyhow!("failed to write '{}': {err}", path.display()))?;
    Ok(())
}

// NTM parity shadow execution keeps all operator-provided paths, limits, and intent fields explicit.
#[allow(clippy::too_many_arguments)]
async fn run_ntm_parity_shadow(
    workspace_root: &Path,
    config_path: Option<&Path>,
    corpus_path: Option<&Path>,
    matrix_path: Option<&Path>,
    output_dir: Option<&Path>,
    run_id: Option<&str>,
    pane_id: Option<u64>,
    intentional_deltas: &[String],
) -> anyhow::Result<NtmParityRunOutcome> {
    use frankenterm_core::ntm_parity::{
        NtmParityAcceptanceMatrix, NtmParityCommandOutput, NtmParityCorpus,
        build_divergence_report, build_run_summary, evaluate_scenario,
    };

    let corpus_path = corpus_path
        .map(|path| resolve_path_from_workspace(workspace_root, path))
        .unwrap_or_else(|| workspace_root.join("fixtures/e2e/ntm_parity/corpus.v1.json"));
    let matrix_path = matrix_path
        .map(|path| resolve_path_from_workspace(workspace_root, path))
        .unwrap_or_else(|| {
            workspace_root.join("fixtures/e2e/ntm_parity/acceptance_matrix.v1.json")
        });

    let corpus =
        NtmParityCorpus::from_json_str(&fs::read_to_string(&corpus_path).map_err(|err| {
            anyhow::anyhow!("failed to read corpus '{}': {err}", corpus_path.display())
        })?)
        .map_err(|err| {
            anyhow::anyhow!("failed to parse corpus '{}': {err}", corpus_path.display())
        })?;
    let matrix = NtmParityAcceptanceMatrix::from_json_str(
        &fs::read_to_string(&matrix_path).map_err(|err| {
            anyhow::anyhow!(
                "failed to read acceptance matrix '{}': {err}",
                matrix_path.display()
            )
        })?,
    )
    .map_err(|err| anyhow::anyhow!("failed to parse matrix '{}': {err}", matrix_path.display()))?;

    let run_id = run_id
        .map(std::borrow::ToOwned::to_owned)
        .unwrap_or_else(default_ntm_parity_run_id);
    let output_dir = output_dir
        .map(|path| resolve_path_from_workspace(workspace_root, path))
        .unwrap_or_else(|| default_ntm_parity_output_dir(workspace_root, &matrix, &run_id));
    fs::create_dir_all(output_dir.join("scenarios")).map_err(|err| {
        anyhow::anyhow!(
            "failed to create parity artifact directory '{}': {err}",
            output_dir.display()
        )
    })?;

    let intentional_delta_map = parse_intentional_deltas(intentional_deltas)?;
    let exe = std::env::current_exe()
        .map_err(|err| anyhow::anyhow!("failed to resolve current ft executable: {err}"))?;
    let resolved_pane_id = if corpus
        .scenarios
        .iter()
        .any(|scenario| scenario.ft_command.contains("<pane_id>"))
    {
        Some(match pane_id {
            Some(id) => id,
            None => resolve_ntm_parity_pane_id(&exe, config_path, workspace_root).await?,
        })
    } else {
        pane_id
    };

    let mut outputs = Vec::with_capacity(corpus.scenarios.len());
    let mut results = Vec::with_capacity(corpus.scenarios.len());

    for scenario in &corpus.scenarios {
        let expanded_command = match resolved_pane_id {
            Some(id) => scenario.ft_command.replace("<pane_id>", &id.to_string()),
            None => scenario.ft_command.clone(),
        };
        let mut tokens = tokenize_cli_words(&expanded_command).map_err(|err| {
            anyhow::anyhow!("failed to parse command '{expanded_command}': {err}")
        })?;
        if matches!(tokens.first().map(String::as_str), Some("ft")) {
            tokens.remove(0);
        }
        if tokens.is_empty() {
            return Err(anyhow::anyhow!(
                "parity scenario '{}' expanded to an empty command",
                scenario.id
            ));
        }

        let capture = run_ft_cli_capture(&exe, &tokens, config_path, workspace_root).await;
        let output = NtmParityCommandOutput {
            scenario_id: scenario.id.clone(),
            command: scenario.ft_command.clone(),
            expanded_command: expanded_command.clone(),
            exit_code: capture.exit_code,
            duration_ms: capture.duration_ms,
            stdout: capture.stdout,
            stderr: capture.stderr,
            execution_error: capture.execution_error,
        };

        let scenario_artifact_rel =
            PathBuf::from("scenarios").join(format!("{}.json", scenario.id));
        let scenario_artifact = scenario_artifact_rel.to_string_lossy().to_string();
        let result = evaluate_scenario(
            scenario,
            &output,
            vec![scenario_artifact.clone()],
            intentional_delta_map.get(&scenario.id).map(String::as_str),
        );

        write_json_pretty(
            &output_dir.join(&scenario_artifact_rel),
            &serde_json::json!({
                "run_id": run_id.as_str(),
                "generated_at": chrono::Utc::now().to_rfc3339(),
                "scenario": scenario,
                "command_output": &output,
                "result": &result,
            }),
        )?;

        outputs.push(output);
        results.push(result);
    }

    let summary = build_run_summary(&run_id, &matrix, &results);
    let divergence = build_divergence_report(&run_id, &matrix, &results);

    write_json_pretty(&output_dir.join("summary.json"), &summary)?;
    write_jsonl(&output_dir.join("raw_command_outputs.jsonl"), &outputs)?;
    write_json_pretty(&output_dir.join("assertion_results.json"), &results)?;
    write_json_pretty(
        &output_dir.join("shadow_divergence_report.json"),
        &divergence,
    )?;

    Ok(NtmParityRunOutcome {
        output_dir,
        resolved_pane_id,
        summary,
    })
}

async fn record_ipc_rpc_audit(
    storage: &Arc<frankenterm_core::runtime_async::Mutex<frankenterm_core::storage::StorageHandle>>,
    request_id: Option<String>,
    summary: String,
    result: &str,
) {
    let timestamp_ms = now_ms_i64();
    let input_summary = Some(summary);
    let decision_context = build_ipc_rpc_decision_context(
        "robot",
        input_summary.as_deref().unwrap_or_default(),
        result,
        request_id.as_deref(),
        timestamp_ms,
    );
    let audit = frankenterm_core::storage::AuditActionRecord {
        id: 0,
        ts: timestamp_ms,
        actor_kind: "robot".to_string(),
        actor_id: None,
        correlation_id: request_id.clone(),
        pane_id: None,
        domain: None,
        action_kind: "ipc.rpc".to_string(),
        policy_decision: "allow".to_string(),
        decision_reason: None,
        rule_id: None,
        input_summary,
        verification_summary: None,
        decision_context,
        result: result.to_string(),
    };

    // Clone handle under the outer mutex, then perform async I/O without holding the lock.
    let storage_handle = storage.lock().await.clone(); // ubs:ignore
    // ft-xbnl0.2.3 tick 280: cx-first IPC RPC audit write.
    let ipc_audit_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    if let Err(e) = storage_handle
        .record_audit_action_redacted_with_cx(&ipc_audit_cx, audit)
        .await
    {
        tracing::warn!("Failed to record IPC RPC audit: {e}");
    }
}

async fn handle_ipc_rpc_request(
    request: frankenterm_core::ipc::IpcRpcRequest,
    workspace_root: PathBuf,
    config_path: Option<PathBuf>,
    storage: Arc<frankenterm_core::runtime_async::Mutex<frankenterm_core::storage::StorageHandle>>,
) -> frankenterm_core::ipc::IpcResponse {
    let summary = build_ipc_rpc_summary(&request.args);
    tracing::debug!(
        request_id = request.request_id.as_deref(),
        command = %summary,
        "IPC RPC request (redacted)"
    );

    let sanitized = match sanitize_ipc_rpc_args(&request.args) {
        Ok(args) => args,
        Err(err) => {
            let response = frankenterm_core::ipc::IpcResponse::error_with_code(
                "ipc.rpc_invalid_args",
                err.message,
                err.hint,
            );
            record_ipc_rpc_audit(&storage, request.request_id, summary, "error").await;
            return response;
        }
    };

    let response =
        match run_robot_rpc_via_cli(&sanitized, config_path.as_deref(), &workspace_root).await {
            Ok(resp) => resp,
            Err(err) => frankenterm_core::ipc::IpcResponse::error_with_code(
                "ipc.rpc_failed",
                err,
                Some("Ensure 'ft robot' can run and outputs JSON.".to_string()),
            ),
        };

    let result = if response.ok { "success" } else { "error" };
    record_ipc_rpc_audit(&storage, request.request_id, summary, result).await;

    response
}

fn build_ipc_rpc_handler(
    workspace_root: PathBuf,
    config_path: Option<PathBuf>,
    storage: Arc<frankenterm_core::runtime_async::Mutex<frankenterm_core::storage::StorageHandle>>,
) -> frankenterm_core::ipc::IpcRpcHandler {
    Arc::new(move |request: frankenterm_core::ipc::IpcRpcRequest| {
        let workspace_root = workspace_root.clone();
        let config_path = config_path.clone();
        let storage = Arc::clone(&storage);
        Box::pin(async move {
            handle_ipc_rpc_request(request, workspace_root, config_path, storage).await
        })
    })
}

struct AsupersyncWebhookTransport {
    client: frankenterm_core::runtime_async::http::HttpClient,
}

impl AsupersyncWebhookTransport {
    fn new() -> Self {
        Self {
            // Webhook requests routinely carry bearer credentials in headers
            // and sensitive payloads in bodies. Never allow a 307/308 (or any
            // other redirect) to replay that POST automatically elsewhere.
            client: frankenterm_core::runtime_async::http::HttpClient::builder()
                .no_redirects()
                .build(),
        }
    }

    fn capability_failure(
        cx: &frankenterm_core::cx::Cx,
    ) -> Option<frankenterm_core::webhook::DeliveryResult> {
        use frankenterm_core::outcome::CancelKind;
        use frankenterm_core::webhook::DeliveryResult;

        if let Some(reason) = cx.root_cancel_cause() {
            return Some(match reason.kind {
                CancelKind::Timeout | CancelKind::Deadline => DeliveryResult::deadline_exceeded(),
                CancelKind::PollQuota => DeliveryResult::poll_budget_exhausted(),
                CancelKind::CostBudget => DeliveryResult::cost_budget_exhausted(),
                CancelKind::User
                | CancelKind::FailFast
                | CancelKind::RaceLost
                | CancelKind::ParentCancelled
                | CancelKind::ResourceUnavailable
                | CancelKind::Shutdown
                | CancelKind::LinkedExit => DeliveryResult::cancelled(),
            });
        }

        // A Cx-aware HTTP timeout may observe an exhausted budget before a
        // checkpoint has materialized its root cancellation reason. Preserve
        // that finite identity from the content-free budget snapshot.
        let budget = cx.budget_stats();
        if budget.deadline.at.is_some() && budget.deadline.remaining.is_none() {
            Some(DeliveryResult::deadline_exceeded())
        } else if budget.polls.remaining == Some(0) {
            Some(DeliveryResult::poll_budget_exhausted())
        } else if budget.cost.remaining == Some(0) {
            Some(DeliveryResult::cost_budget_exhausted())
        } else {
            None
        }
    }

    fn checkpoint_failure(
        cx: &frankenterm_core::cx::Cx,
        error: &frankenterm_core::runtime_async::ContextError,
    ) -> frankenterm_core::webhook::DeliveryResult {
        use frankenterm_core::runtime_async::ContextErrorKind;
        use frankenterm_core::webhook::DeliveryResult;

        match error.kind() {
            ContextErrorKind::DeadlineExceeded => DeliveryResult::deadline_exceeded(),
            ContextErrorKind::CancelTimeout => DeliveryResult::cancellation_cleanup_timeout(),
            ContextErrorKind::PollQuotaExhausted => DeliveryResult::poll_budget_exhausted(),
            ContextErrorKind::CostQuotaExhausted => DeliveryResult::cost_budget_exhausted(),
            ContextErrorKind::Cancelled => {
                Self::capability_failure(cx).unwrap_or_else(DeliveryResult::cancelled)
            }
            _ => DeliveryResult::context_failure(),
        }
    }

    fn client_failure(
        cx: &frankenterm_core::cx::Cx,
        error: &frankenterm_core::runtime_async::http::ClientError,
    ) -> frankenterm_core::webhook::DeliveryResult {
        use frankenterm_core::runtime_async::http::ClientError;
        use frankenterm_core::webhook::DeliveryResult;

        match error {
            // `DeadlineExceeded` is overloaded: it can mean either the
            // caller's capability deadline (which must stop fanout) or this
            // endpoint's request-local timeout (an ordinary transport failure
            // after which later endpoints must still be attempted). Consult
            // the exact caller Cx instead of treating the client discriminant
            // as authoritative on its own.
            ClientError::DeadlineExceeded => match cx.checkpoint() {
                Ok(()) => {
                    Self::capability_failure(cx).unwrap_or_else(DeliveryResult::transport_failure)
                }
                Err(error) => Self::checkpoint_failure(cx, &error),
            },
            // Cancellation initiated through the Cx may have a more precise
            // finite budget class. Never retain or format its free-text cause.
            ClientError::Cancelled => match cx.checkpoint() {
                Ok(()) => Self::capability_failure(cx).unwrap_or_else(DeliveryResult::cancelled),
                Err(error) => Self::checkpoint_failure(cx, &error),
            },
            // URL, DNS, TLS, protocol, proxy, pool, and I/O details may carry
            // caller-controlled or secret text. Collapse them to the finite
            // transport class without formatting or retaining their payloads.
            ClientError::InvalidUrl(_)
            | ClientError::DnsError(_)
            | ClientError::ConnectError(_)
            | ClientError::TlsError(_)
            | ClientError::HttpError(_)
            | ClientError::TooManyRedirects { .. }
            | ClientError::Io(_)
            | ClientError::ConnectTunnelRefused { .. }
            | ClientError::InvalidConnectInput(_)
            | ClientError::ProxyError(_)
            | ClientError::PoolExhausted { .. } => DeliveryResult::transport_failure(),
        }
    }
}

#[cfg(test)]
#[derive(Clone)]
struct EndpointTimeoutThenSuccessWebhookTransport {
    calls: std::sync::Arc<std::sync::atomic::AtomicUsize>,
}

#[cfg(test)]
impl frankenterm_core::webhook::WebhookTransport for EndpointTimeoutThenSuccessWebhookTransport {
    fn send_with_cx<'a>(
        &'a self,
        cx: &'a frankenterm_core::cx::Cx,
        _url: &'a str,
        _headers: &'a std::collections::HashMap<String, String>,
        _body: &'a serde_json::Value,
    ) -> std::pin::Pin<
        Box<
            dyn std::future::Future<Output = frankenterm_core::webhook::DeliveryResult> + Send + 'a,
        >,
    > {
        let call = self.calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        Box::pin(async move {
            if call == 0 {
                AsupersyncWebhookTransport::client_failure(
                    cx,
                    &frankenterm_core::runtime_async::http::ClientError::DeadlineExceeded,
                )
            } else {
                frankenterm_core::webhook::DeliveryResult::from_http_status(204)
            }
        })
    }
}

impl frankenterm_core::webhook::WebhookTransport for AsupersyncWebhookTransport {
    fn send_with_cx<'a>(
        &'a self,
        cx: &'a frankenterm_core::cx::Cx,
        url: &'a str,
        headers: &'a std::collections::HashMap<String, String>,
        body: &'a serde_json::Value,
    ) -> std::pin::Pin<
        Box<
            dyn std::future::Future<Output = frankenterm_core::webhook::DeliveryResult> + Send + 'a,
        >,
    > {
        Box::pin(async move {
            if let Err(error) = cx.checkpoint() {
                return Self::checkpoint_failure(cx, &error);
            }

            let body_bytes = match serde_json::to_vec(body) {
                Ok(bytes) => bytes,
                Err(_) => {
                    return frankenterm_core::webhook::DeliveryResult::context_failure();
                }
            };

            let mut request_headers = Vec::with_capacity(headers.len() + 1);
            request_headers.push(("Content-Type".to_string(), "application/json".to_string()));
            for (key, value) in headers {
                request_headers.push((key.clone(), value.clone()));
            }

            // Request construction may clone nontrivial caller-owned headers
            // and payload data. Re-check immediately before the HTTP side
            // effect so cancellation during that work cannot start a request.
            if let Err(error) = cx.checkpoint() {
                return Self::checkpoint_failure(cx, &error);
            }

            match self
                .client
                .request(
                    cx,
                    frankenterm_core::runtime_async::http::Method::Post,
                    url,
                    request_headers,
                    body_bytes,
                )
                .await
            {
                // Delivery classification needs only the status. The response
                // body is dropped here without decoding or retaining it.
                Ok(response) => {
                    frankenterm_core::webhook::DeliveryResult::from_http_status(response.status)
                }
                Err(error) => Self::client_failure(cx, &error),
            }
        })
    }
}

#[cfg(test)]
#[test]
fn asupersync_webhook_capability_failure_maps_every_cancel_kind_without_reason_text() {
    use frankenterm_core::outcome::CancelKind;
    use frankenterm_core::webhook::DeliveryFailureClass;

    let cases = [
        (CancelKind::Timeout, DeliveryFailureClass::DeadlineExceeded),
        (CancelKind::Deadline, DeliveryFailureClass::DeadlineExceeded),
        (
            CancelKind::PollQuota,
            DeliveryFailureClass::PollBudgetExhausted,
        ),
        (
            CancelKind::CostBudget,
            DeliveryFailureClass::CostBudgetExhausted,
        ),
        (CancelKind::User, DeliveryFailureClass::Cancelled),
        (CancelKind::FailFast, DeliveryFailureClass::Cancelled),
        (CancelKind::RaceLost, DeliveryFailureClass::Cancelled),
        (CancelKind::ParentCancelled, DeliveryFailureClass::Cancelled),
        (
            CancelKind::ResourceUnavailable,
            DeliveryFailureClass::Cancelled,
        ),
        (CancelKind::Shutdown, DeliveryFailureClass::Cancelled),
        (CancelKind::LinkedExit, DeliveryFailureClass::Cancelled),
    ];

    for (kind, expected) in cases {
        let cx = frankenterm_core::cx::for_testing();
        cx.cancel_with(kind, Some("SECRET webhook cancellation reason"));
        let result = AsupersyncWebhookTransport::capability_failure(&cx)
            .expect("cancelled Cx must have a finite webhook failure");
        assert_eq!(result.status_code(), 0, "kind: {kind:?}");
        assert!(!result.accepted(), "kind: {kind:?}");
        assert_eq!(result.failure_class(), Some(expected), "kind: {kind:?}");
        assert!(!format!("{result:?}").contains("SECRET"), "kind: {kind:?}");
    }
}

#[cfg(test)]
#[test]
fn asupersync_webhook_capability_failure_reads_content_free_budget_state() {
    use frankenterm_core::webhook::DeliveryFailureClass;

    let live = frankenterm_core::cx::for_testing();
    assert!(AsupersyncWebhookTransport::capability_failure(&live).is_none());

    let deadline = frankenterm_core::cx::Cx::for_testing_with_budget(
        frankenterm_core::cx::Budget::new()
            .with_deadline(frankenterm_core::runtime_async::RuntimeTime::ZERO),
    );
    let deadline_result = AsupersyncWebhookTransport::capability_failure(&deadline)
        .expect("expired deadline must be classified");
    assert_eq!(
        deadline_result.failure_class(),
        Some(DeliveryFailureClass::DeadlineExceeded)
    );

    let poll_quota = frankenterm_core::cx::Cx::for_testing_with_budget(
        frankenterm_core::cx::Budget::new().with_poll_quota(0),
    );
    let poll_result = AsupersyncWebhookTransport::capability_failure(&poll_quota)
        .expect("exhausted poll quota must be classified");
    assert_eq!(
        poll_result.failure_class(),
        Some(DeliveryFailureClass::PollBudgetExhausted)
    );

    let cost_budget = frankenterm_core::cx::Cx::for_testing_with_budget(
        frankenterm_core::cx::Budget::new().with_cost_quota(0),
    );
    let cost_result = AsupersyncWebhookTransport::capability_failure(&cost_budget)
        .expect("exhausted cost budget must be classified");
    assert_eq!(
        cost_result.failure_class(),
        Some(DeliveryFailureClass::CostBudgetExhausted)
    );
}

#[cfg(test)]
#[test]
fn asupersync_webhook_checkpoint_failure_preserves_cleanup_timeout_without_details() {
    use frankenterm_core::runtime_async::{ContextError, ContextErrorKind};
    use frankenterm_core::webhook::DeliveryFailureClass;

    let cx = frankenterm_core::cx::for_testing();
    let cleanup_timeout = ContextError::new(ContextErrorKind::CancelTimeout)
        .with_message("SECRET cancellation cleanup diagnostic");
    let result = AsupersyncWebhookTransport::checkpoint_failure(&cx, &cleanup_timeout);
    assert_eq!(
        result.failure_class(),
        Some(DeliveryFailureClass::CancellationCleanupTimeout)
    );
    assert!(!format!("{result:?}").contains("SECRET"));

    let unknown =
        ContextError::new(ContextErrorKind::Internal).with_message("SECRET context diagnostic");
    let result = AsupersyncWebhookTransport::checkpoint_failure(&cx, &unknown);
    assert_eq!(result.failure_class(), Some(DeliveryFailureClass::Context));
    assert!(!format!("{result:?}").contains("SECRET"));
}

#[cfg(test)]
#[test]
fn asupersync_webhook_client_failure_preserves_finite_discriminants_without_details() {
    use frankenterm_core::runtime_async::http::ClientError;
    use frankenterm_core::webhook::DeliveryFailureClass;

    let live = frankenterm_core::cx::for_testing();
    let request_timeout =
        AsupersyncWebhookTransport::client_failure(&live, &ClientError::DeadlineExceeded);
    assert_eq!(
        request_timeout.failure_class(),
        Some(DeliveryFailureClass::Transport)
    );

    let cancelled = AsupersyncWebhookTransport::client_failure(&live, &ClientError::Cancelled);
    assert_eq!(
        cancelled.failure_class(),
        Some(DeliveryFailureClass::Cancelled)
    );

    let deadline = frankenterm_core::cx::Cx::for_testing_with_budget(
        frankenterm_core::cx::Budget::new()
            .with_deadline(frankenterm_core::runtime_async::RuntimeTime::ZERO),
    );
    let caller_deadline =
        AsupersyncWebhookTransport::client_failure(&deadline, &ClientError::DeadlineExceeded);
    assert_eq!(
        caller_deadline.failure_class(),
        Some(DeliveryFailureClass::DeadlineExceeded)
    );
    let cancelled_at_deadline =
        AsupersyncWebhookTransport::client_failure(&deadline, &ClientError::Cancelled);
    assert_eq!(
        cancelled_at_deadline.failure_class(),
        Some(DeliveryFailureClass::DeadlineExceeded)
    );

    let transport = AsupersyncWebhookTransport::client_failure(
        &live,
        &ClientError::InvalidUrl("SECRET webhook URL".to_string()),
    );
    assert_eq!(
        transport.failure_class(),
        Some(DeliveryFailureClass::Transport)
    );
    assert!(!format!("{transport:?}").contains("SECRET"));
}

#[cfg(test)]
#[test]
fn endpoint_local_webhook_timeout_does_not_stop_two_endpoint_fanout() {
    use frankenterm_core::runtime_async::CompatRuntime;
    use frankenterm_core::webhook::{
        DeliveryFailureClass, WebhookDispatcher, WebhookEndpointConfig, WebhookTemplate,
    };

    let runtime = frankenterm_core::runtime_async::RuntimeBuilder::current_thread()
        .enable_all()
        .build()
        .expect("webhook fanout test runtime");
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        runtime.block_on(async {
            let calls = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let transport = EndpointTimeoutThenSuccessWebhookTransport {
                calls: std::sync::Arc::clone(&calls),
            };
            let endpoint = |name: &str| WebhookEndpointConfig {
                name: name.to_string(),
                url: format!("https://{name}.invalid/hook"),
                template: WebhookTemplate::Generic,
                events: Vec::new(),
                headers: std::collections::HashMap::new(),
                enabled: true,
            };
            let dispatcher = WebhookDispatcher::new(
                vec![endpoint("times-out"), endpoint("still-runs")],
                Box::new(transport),
            );
            let payload = frankenterm_core::notifications::NotificationPayload {
                event_type: "test.webhook".to_string(),
                pane_id: 7,
                timestamp: "2026-08-05T00:00:00Z".to_string(),
                summary: "test".to_string(),
                description: "test".to_string(),
                severity: "warning".to_string(),
                agent_type: "test".to_string(),
                confidence: 1.0,
                quick_fix: None,
                suppressed_since_last: 0,
            };
            let cx = frankenterm_core::cx::for_testing();

            let records = dispatcher.dispatch_payload_with_cx(&cx, &payload).await;

            assert_eq!(
                calls.load(std::sync::atomic::Ordering::SeqCst),
                2,
                "a live caller Cx must allow the second endpoint after a request-local timeout"
            );
            assert_eq!(records.len(), 2, "both endpoint attempts must be recorded");
            assert_eq!(records[0].target, "times-out");
            assert_eq!(
                records[0].error.as_deref(),
                Some(DeliveryFailureClass::Transport.code())
            );
            assert_eq!(records[1].target, "still-runs");
            assert!(records[1].accepted);
            assert_eq!(records[1].status_code, 204);
        });
    }));
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| drop(runtime)));
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        frankenterm_core::runtime_async::clear_runtime_handle();
    }));
    if let Err(panic) = result {
        std::panic::resume_unwind(panic);
    }
}

#[cfg(test)]
#[test]
fn webhook_http_client_constructor_pins_redirects_disabled() {
    let source = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"))
        .expect("webhook redirect guard must read the CLI source");
    let impl_start = source
        .find("impl AsupersyncWebhookTransport")
        .expect("webhook transport impl must exist");
    let capability_start = source[impl_start..]
        .find("fn capability_failure")
        .map(|offset| impl_start + offset)
        .expect("webhook capability classifier must follow its constructor");
    let constructor = &source[impl_start..capability_start];
    let builder_call = ["HttpClient", "::", "builder", "()"].concat();
    let builder_position = constructor
        .find(&builder_call)
        .expect("webhook client must use the fluent builder");
    let no_redirects_call = ["no", "_", "redirects", "()"].concat();
    let redirect_disable_position = constructor
        .find(&no_redirects_call)
        .expect("webhook client must disable automatic redirects");
    let build_call = [".", "build", "()"].concat();
    let final_build_position = constructor
        .rfind(&build_call)
        .expect("webhook client builder must be finalized");

    assert!(
        builder_position < redirect_disable_position
            && redirect_disable_position < final_build_position,
        "webhook client construction must call no_redirects() before build()"
    );
}

#[cfg(test)]
#[test]
fn asupersync_webhook_send_with_cx_short_circuits_exact_cancelled_caller() {
    use frankenterm_core::runtime_async::CompatRuntime;
    use frankenterm_core::webhook::{DeliveryFailureClass, WebhookTransport};

    let runtime = frankenterm_core::runtime_async::RuntimeBuilder::current_thread()
        .enable_all()
        .build()
        .expect("webhook test runtime");
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        runtime.block_on(async {
            let transport = AsupersyncWebhookTransport::new();
            let cx = frankenterm_core::cx::for_testing();
            cx.cancel_with(
                frankenterm_core::outcome::CancelKind::User,
                Some("SECRET exact caller cancellation"),
            );
            let headers = std::collections::HashMap::new();
            let body = serde_json::json!({"private": "SECRET body"});

            let result = transport
                .send_with_cx(&cx, "not a valid URL", &headers, &body)
                .await;
            assert_eq!(result.status_code(), 0);
            assert!(!result.accepted());
            assert_eq!(
                result.failure_class(),
                Some(DeliveryFailureClass::Cancelled)
            );
            assert!(!format!("{result:?}").contains("SECRET"));
        });
    }));
    // Runtime::block_on intentionally retains its ambient handle. Test
    // teardown must drop the runtime first and then clear that TLS slot under
    // containment; otherwise a destructor panic can leak into a later test.
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| drop(runtime)));
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        frankenterm_core::runtime_async::clear_runtime_handle();
    }));
    if let Err(panic) = result {
        std::panic::resume_unwind(panic);
    }
}

const WATCHER_CRASH_WINDOW: Duration = Duration::from_secs(5 * 60);
const WATCHER_STABLE_RESET: Duration = Duration::from_secs(5 * 60);
const WATCHER_BASE_BACKOFF: Duration = Duration::from_secs(2);
const WATCHER_MAX_BACKOFF: Duration = Duration::from_secs(60);
const WATCHER_CRASH_LOOP_THRESHOLD: usize = 3;
const RECORDER_BACKEND_MIGRATION_EPOCH: &str = "ft.recorder.backend.v1";

struct WatcherCrashLoop {
    crash_times: VecDeque<Instant>,
}

impl WatcherCrashLoop {
    fn new() -> Self {
        Self {
            crash_times: VecDeque::new(),
        }
    }

    fn register_crash(&mut self, runtime: Duration) -> CrashLoopStatus {
        if runtime >= WATCHER_STABLE_RESET {
            self.crash_times.clear();
        }

        let now = Instant::now();
        self.crash_times.push_back(now);
        while let Some(front) = self.crash_times.front().copied() {
            if now.duration_since(front) > WATCHER_CRASH_WINDOW {
                self.crash_times.pop_front();
            } else {
                break;
            }
        }

        let crash_count = self.crash_times.len();
        let in_loop = crash_count >= WATCHER_CRASH_LOOP_THRESHOLD;
        let backoff = compute_watcher_backoff(crash_count);

        CrashLoopStatus {
            crash_count,
            in_loop,
            backoff,
        }
    }
}

struct CrashLoopStatus {
    crash_count: usize,
    in_loop: bool,
    backoff: Duration,
}

fn compute_watcher_backoff(crash_count: usize) -> Duration {
    let mut backoff_secs = WATCHER_BASE_BACKOFF.as_secs().max(1);
    let mut steps = crash_count.saturating_sub(1);
    while steps > 0 {
        backoff_secs = backoff_secs.saturating_mul(2);
        steps -= 1;
    }
    backoff_secs = backoff_secs.min(WATCHER_MAX_BACKOFF.as_secs().max(1));
    Duration::from_secs(backoff_secs)
}

fn watcher_error_is_non_retryable(err: &anyhow::Error) -> bool {
    let message = err.to_string();
    message.contains("Another watcher is already running")
        || message.contains("Failed to acquire watcher lock")
        || message.contains("non-retryable:")
}

#[derive(Debug, Clone)]
struct RecorderBackendStartupSelection {
    requested_backend: frankenterm_core::recorder_storage::RecorderBackendKind,
    selected_backend: frankenterm_core::recorder_storage::RecorderBackendKind,
}

fn recorder_append_log_storage_config(
    layout: &frankenterm_core::config::WorkspaceLayout,
    config: &frankenterm_core::config::Config,
) -> frankenterm_core::recorder_storage::AppendLogStorageConfig {
    frankenterm_core::recorder_storage::AppendLogStorageConfig {
        data_path: layout.ft_dir.join("recorder-log").join("events.log"),
        state_path: layout.ft_dir.join("recorder-log").join("state.json"),
        queue_capacity: (config.storage.writer_queue_size as usize).max(1),
        ..Default::default()
    }
}

fn recorder_rusqlite_storage_config(
    layout: &frankenterm_core::config::WorkspaceLayout,
    config: &frankenterm_core::config::Config,
) -> frankenterm_core::recorder_storage::RusqliteStorageConfig {
    frankenterm_core::recorder_storage::RusqliteStorageConfig {
        db_path: layout.ft_dir.join("recorder-log").join("events.sqlite3"),
        queue_capacity: (config.storage.writer_queue_size as usize).max(1),
        ..Default::default()
    }
}

fn recorder_startup_health_failure_reason(
    health: &frankenterm_core::recorder_storage::RecorderStorageHealth,
) -> Option<String> {
    if health.degraded {
        Some(
            health
                .last_error
                .clone()
                .unwrap_or_else(|| "backend reported degraded startup health".to_string()),
        )
    } else {
        None
    }
}

async fn bootstrap_recorder_backend_with_probe(
    requested_backend: frankenterm_core::recorder_storage::RecorderBackendKind,
    append_log: frankenterm_core::recorder_storage::AppendLogStorageConfig,
    rusqlite: frankenterm_core::recorder_storage::RusqliteStorageConfig,
) -> std::result::Result<frankenterm_core::recorder_storage::RecorderStorageInstance, anyhow::Error>
{
    use frankenterm_core::recorder_storage::{
        RecorderStorage, RecorderStorageConfig, bootstrap_recorder_storage,
    };

    let recorder_config = RecorderStorageConfig {
        backend: requested_backend,
        append_log,
        rusqlite,
    };
    let storage = bootstrap_recorder_storage(recorder_config).map_err(|error| {
        let detail = error.to_string();
        anyhow::Error::new(error).context(format!(
            "non-retryable: failed to bootstrap recorder backend {}: {detail}",
            requested_backend
        ))
    })?;

    let health = storage.health().await;
    if let Some(reason) = recorder_startup_health_failure_reason(&health) {
        anyhow::bail!(
            "non-retryable: recorder backend {} startup health probe failed: {}",
            requested_backend,
            reason
        );
    }

    Ok(storage)
}

fn recorder_backend_lifecycle_payload(
    selection: &RecorderBackendStartupSelection,
) -> serde_json::Value {
    let mut payload = serde_json::Map::new();
    payload.insert(
        "backend_kind".to_string(),
        serde_json::Value::String(selection.selected_backend.to_string()),
    );
    payload.insert(
        "requested_backend_kind".to_string(),
        serde_json::Value::String(selection.requested_backend.to_string()),
    );
    payload.insert(
        "migration_epoch".to_string(),
        serde_json::Value::String(RECORDER_BACKEND_MIGRATION_EPOCH.to_string()),
    );
    serde_json::Value::Object(payload)
}

fn next_recorder_lifecycle_sequence(
    health: &frankenterm_core::recorder_storage::RecorderStorageHealth,
) -> anyhow::Result<u64> {
    health.latest_offset.as_ref().map_or(Ok(0), |offset| {
        offset.ordinal.checked_add(1).ok_or_else(|| {
            anyhow::anyhow!(
                "non-retryable: recorder lifecycle sequence exhausted at ordinal {}",
                offset.ordinal
            )
        })
    })
}

fn recorder_backend_lifecycle_event(
    selection: &RecorderBackendStartupSelection,
    sequence: u64,
    now_ms: u64,
) -> frankenterm_core::recording::RecorderEvent {
    let mut event = frankenterm_core::recording::RecorderEvent {
        schema_version: frankenterm_core::recording::RECORDER_EVENT_SCHEMA_VERSION_V1.to_string(),
        event_id: String::new(),
        pane_id: 0,
        session_id: None,
        workflow_id: None,
        correlation_id: None,
        source: frankenterm_core::recording::RecorderEventSource::RecoveryFlow,
        occurred_at_ms: now_ms,
        recorded_at_ms: now_ms,
        sequence,
        causality: frankenterm_core::recording::RecorderEventCausality::default(),
        payload: frankenterm_core::recording::RecorderEventPayload::LifecycleMarker {
            lifecycle_phase: frankenterm_core::recording::RecorderLifecyclePhase::CaptureStarted,
            reason: Some("recorder_backend_selected".to_string()),
            details: recorder_backend_lifecycle_payload(selection),
        },
    };
    event.event_id = frankenterm_core::event_id::generate_event_id_v1(&event);
    event
}

async fn emit_recorder_backend_lifecycle_event(
    cx: &frankenterm_core::cx::Cx,
    storage: &frankenterm_core::recorder_storage::RecorderStorageInstance,
    event: frankenterm_core::recording::RecorderEvent,
) -> anyhow::Result<frankenterm_core::recorder_storage::AppendResponse> {
    frankenterm_core::runtime::append_runtime_recorder_event_with_cx(
        cx,
        storage,
        event,
        frankenterm_core::recorder_storage::DurabilityLevel::Fsync,
    )
    .await
    .map_err(anyhow::Error::new)
}

#[cfg(feature = "distributed")]
#[derive(Debug, serde::Deserialize, serde::Serialize)]
struct DistributedHandshake {
    protocol_version: Option<u32>,
    token: Option<String>,
    agent_id: Option<String>,
    session_id: Option<String>,
}

#[cfg(feature = "distributed")]
const DISTRIBUTED_HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(10);

#[cfg(feature = "distributed")]
fn distributed_validate_handshake_protocol_version(
    protocol_version: Option<u32>,
) -> Result<(), frankenterm_core::distributed::DistributedSecurityError> {
    match protocol_version {
        Some(version) if version == frankenterm_core::wire_protocol::PROTOCOL_VERSION => Ok(()),
        Some(got) => Err(
            frankenterm_core::distributed::DistributedSecurityError::ProtocolVersionMismatch {
                expected: frankenterm_core::wire_protocol::PROTOCOL_VERSION,
                got,
            },
        ),
        None => Err(
            frankenterm_core::distributed::DistributedSecurityError::ProtocolVersionMissing {
                expected: frankenterm_core::wire_protocol::PROTOCOL_VERSION,
            },
        ),
    }
}

#[cfg(feature = "distributed")]
#[derive(Debug, Clone)]
struct DistributedSequenceScopeState {
    active_connections: usize,
    replay_id: String,
    inactive_since_ms: Option<i64>,
}

#[cfg(feature = "distributed")]
struct DistributedIngestShared {
    aggregator: frankenterm_core::wire_protocol::Aggregator,
    replay_guard: frankenterm_core::distributed::SessionReplayGuard,
    active_sequence_scopes: std::collections::HashMap<String, DistributedSequenceScopeState>,
    pane_seq_by_sender: std::collections::HashMap<(String, u64), u64>,
    sequence_scope_gates:
        std::collections::HashMap<String, frankenterm_core::runtime_async::OwnedMutex<()>>,
}

#[cfg(feature = "distributed")]
struct DistributedIngestState {
    shared: frankenterm_core::runtime_async::Mutex<DistributedIngestShared>,
}

#[cfg(feature = "distributed")]
struct DistributedAdmission {
    previous_replay_seq: Option<u64>,
    previous_agent_session: Option<frankenterm_core::wire_protocol::AgentSessionSnapshot>,
    ingest_result: Result<
        frankenterm_core::wire_protocol::IngestResult,
        frankenterm_core::wire_protocol::WireProtocolError,
    >,
}

#[cfg(feature = "distributed")]
impl DistributedIngestState {
    fn new(wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits) -> Self {
        Self {
            shared: frankenterm_core::runtime_async::Mutex::new(DistributedIngestShared {
                // Distributed listener cleanup owns session lifetime so reconnect
                // grace and stale pruning stay aligned across all state holders.
                aggregator:
                    frankenterm_core::wire_protocol::Aggregator::with_limits_and_stale_after(
                        4096,
                        wire_limits,
                        0,
                    ),
                replay_guard: frankenterm_core::distributed::SessionReplayGuard::new(8192),
                active_sequence_scopes: std::collections::HashMap::new(),
                pane_seq_by_sender: std::collections::HashMap::new(),
                sequence_scope_gates: std::collections::HashMap::new(),
            }),
        }
    }
}

#[cfg(feature = "distributed")]
async fn distributed_lock_sequence_scope(
    ingest_state: &DistributedIngestState,
    sequence_scope: &str,
) -> frankenterm_core::runtime_async::OwnedMutexGuard<()> {
    let gate = {
        let mut shared = ingest_state.shared.lock().await;
        shared
            .sequence_scope_gates
            .entry(sequence_scope.to_string())
            .or_insert_with(|| frankenterm_core::runtime_async::OwnedMutex::new(()))
            .clone()
    };
    gate.lock_owned().await
}

#[cfg(feature = "distributed")]
fn distributed_admit_envelope(
    shared: &mut DistributedIngestShared,
    replay_id: &str,
    sequence_scope: &str,
    envelope: frankenterm_core::wire_protocol::WireEnvelope,
    activate_sequence_scope: bool,
) -> Result<DistributedAdmission, frankenterm_core::distributed::DistributedSecurityError> {
    let previous_replay_seq = shared.replay_guard.session_last_seq(replay_id);
    shared.replay_guard.validate(replay_id, envelope.seq)?;

    let previous_agent_session = shared.aggregator.agent_session_snapshot(sequence_scope);
    let ingest_result = shared.aggregator.ingest_envelope(envelope);
    if ingest_result.is_err() {
        shared
            .replay_guard
            .restore_session(replay_id, previous_replay_seq);
    } else if activate_sequence_scope {
        distributed_mark_sequence_scope_active(shared, sequence_scope, replay_id);
    }

    Ok(DistributedAdmission {
        previous_replay_seq,
        previous_agent_session,
        ingest_result,
    })
}

#[cfg(feature = "distributed")]
fn distributed_mark_sequence_scope_active(
    shared: &mut DistributedIngestShared,
    sequence_scope: &str,
    replay_id: &str,
) {
    let state = shared
        .active_sequence_scopes
        .entry(sequence_scope.to_string())
        .or_insert_with(|| DistributedSequenceScopeState {
            active_connections: 0,
            replay_id: replay_id.to_string(),
            inactive_since_ms: None,
        });
    state.active_connections = state.active_connections.saturating_add(1);
    state.replay_id = replay_id.to_string();
    state.inactive_since_ms = None;
}

#[cfg(feature = "distributed")]
fn distributed_normalize_identity(value: &str) -> String {
    value.trim().to_ascii_lowercase()
}

#[cfg(feature = "distributed")]
fn distributed_validate_handshake_agent_id(
    agent_id: Option<&str>,
    wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits,
) -> Result<Option<String>, frankenterm_core::distributed::DistributedSecurityError> {
    let Some(agent_id) = agent_id else {
        return Ok(None);
    };
    let trimmed = agent_id.trim();
    if trimmed.is_empty() {
        return Err(frankenterm_core::distributed::DistributedSecurityError::AuthFailed);
    }
    frankenterm_core::wire_protocol::validate_sender_identity_with_limits(trimmed, wire_limits)
        .map_err(|_| frankenterm_core::distributed::DistributedSecurityError::AuthFailed)?;
    Ok(Some(distributed_normalize_identity(trimmed)))
}

#[cfg(feature = "distributed")]
fn distributed_validate_handshake_session_id(
    session_id: Option<&str>,
    wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits,
) -> Result<Option<String>, frankenterm_core::distributed::DistributedSecurityError> {
    let Some(session_id) = session_id else {
        return Ok(None);
    };
    let trimmed = session_id.trim();
    if trimmed.is_empty() {
        return Err(frankenterm_core::distributed::DistributedSecurityError::AuthFailed);
    }

    let max_session_id_len = wire_limits.max_sender_id_len.saturating_add(64);
    if trimmed.len() > max_session_id_len || trimmed.chars().any(char::is_control) {
        return Err(frankenterm_core::distributed::DistributedSecurityError::AuthFailed);
    }

    Ok(Some(trimmed.to_string()))
}

#[cfg(feature = "distributed")]
fn distributed_build_allow_agent_ids(
    distributed_config: &frankenterm_core::config::DistributedConfig,
    wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits,
) -> anyhow::Result<std::collections::HashSet<String>> {
    let mut allow_agent_ids = std::collections::HashSet::new();
    for raw_agent_id in &distributed_config.allow_agent_ids {
        let trimmed = raw_agent_id.trim();
        if trimmed.is_empty() {
            anyhow::bail!("distributed.allow_agent_ids entries must be non-empty");
        }
        frankenterm_core::wire_protocol::validate_sender_identity_with_limits(trimmed, wire_limits)
            .map_err(|err| {
                anyhow::anyhow!(
                    "distributed.allow_agent_ids contains invalid entry {trimmed:?}: {err}"
                )
            })?;

        let normalized = distributed_normalize_identity(trimmed);
        if !allow_agent_ids.insert(normalized.clone()) {
            anyhow::bail!(
                "distributed.allow_agent_ids contains duplicate entry {trimmed:?} after normalization"
            );
        }
    }
    Ok(allow_agent_ids)
}

#[cfg(feature = "distributed")]
const DISTRIBUTED_MESSAGE_TOO_LARGE_IO_ERROR_MARKER: &str = "distributed_message_too_large";

#[cfg(feature = "distributed")]
fn distributed_message_too_large_io_error() -> std::io::Error {
    std::io::Error::new(
        std::io::ErrorKind::InvalidData,
        DISTRIBUTED_MESSAGE_TOO_LARGE_IO_ERROR_MARKER,
    )
}

#[cfg(feature = "distributed")]
fn distributed_is_message_too_large_io_error(err: &std::io::Error) -> bool {
    err.kind() == std::io::ErrorKind::InvalidData
        && err
            .to_string()
            .contains(DISTRIBUTED_MESSAGE_TOO_LARGE_IO_ERROR_MARKER)
}

#[cfg(feature = "distributed")]
fn distributed_sender_hash(sender: &str) -> u64 {
    // Deterministic FNV-1a 64-bit hash for stable remote pane ID mapping.
    let mut hash: u64 = 0xcbf29ce484222325;
    for byte in sender.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

#[cfg(feature = "distributed")]
fn distributed_remote_pane_id(sender: &str, pane_id: u64) -> u64 {
    // Reserve bit 62 for distributed panes while staying within signed i64 range.
    const DISTRIBUTED_PANE_FLAG: u64 = 1 << 62;
    let canonical_sender = distributed_normalize_identity(sender);
    let sender_bits = distributed_sender_hash(&canonical_sender) & 0x3fff_ffff;
    DISTRIBUTED_PANE_FLAG | (sender_bits << 32) | (pane_id & 0xffff_ffff)
}

#[cfg(feature = "distributed")]
fn distributed_remote_domain(sender: &str, domain: &str) -> String {
    let canonical_sender = distributed_normalize_identity(sender);
    format!("distributed:{canonical_sender}:{domain}")
}

#[cfg(feature = "distributed")]
fn distributed_replay_session_key(session_id: &str, sender: &str) -> String {
    let canonical_sender = distributed_normalize_identity(sender);
    format!(
        "{}:{session_id}:{}:{canonical_sender}",
        session_id.len(),
        canonical_sender.len()
    )
}

#[cfg(feature = "distributed")]
fn distributed_resolve_session_id(
    session_id: Option<&str>,
    handshake_agent_id: Option<&str>,
    peer_addr: std::net::SocketAddr,
) -> String {
    session_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .or_else(|| handshake_agent_id.map(distributed_normalize_identity))
        .unwrap_or_else(|| format!("peer-{peer_addr}"))
}

#[cfg(feature = "distributed")]
fn distributed_sender_session_scope(
    session_id: &str,
    sender: &str,
    max_sender_id_len: usize,
) -> String {
    let canonical_sender = distributed_normalize_identity(sender);
    let replay_id = distributed_replay_session_key(session_id, &canonical_sender);
    let suffix = format!(".{:016x}", distributed_sender_hash(&replay_id));
    let max_len = max_sender_id_len;

    if max_len == 0 {
        return String::new();
    }
    if suffix.len() >= max_len {
        let start = suffix.len().saturating_sub(max_len);
        return suffix[start..].to_string();
    }

    if canonical_sender.len() + suffix.len() <= max_len {
        return format!("{canonical_sender}{suffix}");
    }

    let mut prefix_len = max_len.saturating_sub(suffix.len());
    while prefix_len > 0 && !canonical_sender.is_char_boundary(prefix_len) {
        prefix_len -= 1;
    }
    let mut truncated_sender = canonical_sender;
    truncated_sender.truncate(prefix_len);
    format!("{truncated_sender}{suffix}")
}

#[cfg(feature = "distributed")]
const DISTRIBUTED_SEQUENCE_SCOPE_STALE_AFTER_MS: i64 =
    frankenterm_core::wire_protocol::DEFAULT_AGENT_STALE_AFTER_MS;

#[cfg(feature = "distributed")]
fn distributed_inferred_gap_bounds(expected: u64, actual: u64) -> (u64, u64) {
    let seq_before = if expected == 0 {
        0
    } else {
        expected.saturating_sub(1)
    };
    (seq_before, actual)
}

#[cfg(feature = "distributed")]
fn distributed_seq_gap_reason(sender: &str, expected: u64, actual: u64) -> String {
    let (seq_before, seq_after) = distributed_inferred_gap_bounds(expected, actual);
    format!(
        "distributed_gap:distributed_seq_gap:sender={sender}:expected={expected}:actual={actual}:{seq_before}:{seq_after}"
    )
}

#[cfg(all(feature = "distributed", test))]
async fn distributed_register_sequence_scope(
    ingest_state: &DistributedIngestState,
    sequence_scope: &str,
    replay_id: &str,
) {
    let _ = distributed_prune_stale_sequence_scopes(
        ingest_state,
        now_ms_i64(),
        DISTRIBUTED_SEQUENCE_SCOPE_STALE_AFTER_MS,
    )
    .await;

    let mut shared = ingest_state.shared.lock().await;
    distributed_mark_sequence_scope_active(&mut shared, sequence_scope, replay_id);
}

#[cfg(feature = "distributed")]
async fn distributed_prune_stale_sequence_scopes(
    ingest_state: &DistributedIngestState,
    now_ms: i64,
    stale_after_ms: i64,
) -> usize {
    if stale_after_ms <= 0 {
        return 0;
    }

    // These four indexes form one admission/retirement authority. Keeping them
    // behind one mutex makes stale pruning atomic and, critically, avoids
    // suspending a Send task while it owns a !Send asupersync mutex guard.
    let mut shared = ingest_state.shared.lock().await;

    let mut stale_scopes = std::collections::HashSet::new();
    let mut stale_replay_ids = Vec::new();

    shared
        .active_sequence_scopes
        .retain(|sequence_scope, state| {
            let is_stale = state.active_connections == 0
                && state.inactive_since_ms.is_some_and(|inactive_since_ms| {
                    now_ms.saturating_sub(inactive_since_ms) >= stale_after_ms
                });
            if is_stale {
                stale_scopes.insert(sequence_scope.clone());
                stale_replay_ids.push(state.replay_id.clone());
            }
            !is_stale
        });

    // A cloned gate means an admission is holding or waiting for this scope.
    // Keep that exact Arc even if its dormant session metadata was just
    // retired, so a reconnect can never create a second independent gate.
    let DistributedIngestShared {
        active_sequence_scopes,
        sequence_scope_gates,
        ..
    } = &mut *shared;
    sequence_scope_gates.retain(|sequence_scope, gate| {
        active_sequence_scopes.contains_key(sequence_scope) || gate.has_external_owner()
    });

    if stale_scopes.is_empty() {
        return 0;
    }

    for replay_id in &stale_replay_ids {
        shared.replay_guard.remove(replay_id);
    }
    for sequence_scope in &stale_scopes {
        shared.aggregator.remove_agent(sequence_scope);
    }
    shared
        .pane_seq_by_sender
        .retain(|(sequence_scope, _), _| !stale_scopes.contains(sequence_scope));

    stale_scopes.len()
}

#[cfg(feature = "distributed")]
async fn distributed_release_sequence_scopes(
    ingest_state: &DistributedIngestState,
    sequence_scopes: &std::collections::HashSet<String>,
) {
    if sequence_scopes.is_empty() {
        return;
    }

    let now_ms = now_ms_i64();
    {
        let mut shared = ingest_state.shared.lock().await;
        for sequence_scope in sequence_scopes {
            if let Some(state) = shared.active_sequence_scopes.get_mut(sequence_scope) {
                if state.active_connections > 1 {
                    state.active_connections -= 1;
                } else {
                    state.active_connections = 0;
                    state.inactive_since_ms = Some(now_ms);
                }
            }
        }
    }

    let _ = distributed_prune_stale_sequence_scopes(
        ingest_state,
        now_ms,
        DISTRIBUTED_SEQUENCE_SCOPE_STALE_AFTER_MS,
    )
    .await;
}

#[cfg(feature = "distributed")]
async fn distributed_release_unowned_sequence_scope_gate(
    ingest_state: &DistributedIngestState,
    sequence_scope: Option<&str>,
) {
    let Some(sequence_scope) = sequence_scope else {
        return;
    };

    let mut shared = ingest_state.shared.lock().await;
    let should_remove = !shared.active_sequence_scopes.contains_key(sequence_scope)
        && shared
            .sequence_scope_gates
            .get(sequence_scope)
            .is_some_and(|gate| !gate.has_external_owner());
    if should_remove {
        shared.sequence_scope_gates.remove(sequence_scope);
    }
}

#[cfg(feature = "distributed")]
async fn distributed_rollback_failed_persist(
    ingest_state: &DistributedIngestState,
    replay_id: &str,
    previous_replay_seq: Option<u64>,
    sequence_scope: &str,
    previous_agent_session: Option<frankenterm_core::wire_protocol::AgentSessionSnapshot>,
) {
    let mut shared = ingest_state.shared.lock().await;
    shared
        .replay_guard
        .restore_session(replay_id, previous_replay_seq);
    shared
        .aggregator
        .rollback_accepted(sequence_scope, previous_agent_session);
}

#[cfg(feature = "distributed")]
fn distributed_remote_pane_uuid(
    sender: &str,
    pane_id: u64,
    pane_uuid: Option<&str>,
) -> Option<String> {
    let raw = pane_uuid
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("unknown");
    let canonical_sender = distributed_normalize_identity(sender);
    Some(format!("distributed:{canonical_sender}:{pane_id}:{raw}"))
}

#[cfg(feature = "distributed")]
fn distributed_detection_to_stored_event(
    pane_id: u64,
    pane_uuid: Option<&str>,
    detection: &frankenterm_core::patterns::Detection,
    segment_id: Option<i64>,
    detected_at: i64,
) -> frankenterm_core::storage::StoredEvent {
    const EVENT_DEDUPE_BUCKET_MS: i64 = 5 * 60 * 1000;
    let identity_key = frankenterm_core::events::event_identity_key(detection, pane_id, pane_uuid);
    let bucket = if EVENT_DEDUPE_BUCKET_MS > 0 {
        detected_at / EVENT_DEDUPE_BUCKET_MS
    } else {
        0
    };
    let dedupe_key = format!("{identity_key}:{bucket}");

    frankenterm_core::storage::StoredEvent {
        id: 0,
        pane_id,
        rule_id: detection.rule_id.clone(),
        agent_type: detection.agent_type.to_string(),
        event_type: detection.event_type.clone(),
        severity: match detection.severity {
            frankenterm_core::patterns::Severity::Info => "info".to_string(),
            frankenterm_core::patterns::Severity::Warning => "warning".to_string(),
            frankenterm_core::patterns::Severity::Critical => "critical".to_string(),
        },
        confidence: detection.confidence,
        extracted: Some(detection.extracted.clone()),
        matched_text: Some(detection.matched_text.clone()),
        segment_id,
        detected_at,
        dedupe_key: Some(dedupe_key),
        handled_at: None,
        handled_by_workflow_id: None,
        handled_status: None,
    }
}

#[cfg(feature = "distributed")]
// Distributed pane persistence mirrors the wire metadata fields that arrive independently.
#[allow(clippy::too_many_arguments)]
async fn distributed_upsert_pane(
    storage: &frankenterm_core::storage::StorageHandle,
    pane_id: u64,
    pane_uuid: Option<String>,
    domain: String,
    title: Option<String>,
    cwd: Option<String>,
    observed: bool,
    timestamp_ms: i64,
) -> anyhow::Result<()> {
    storage
        .upsert_pane(frankenterm_core::storage::PaneRecord {
            pane_id,
            pane_uuid,
            domain,
            window_id: None,
            tab_id: None,
            title,
            cwd,
            tty_name: None,
            first_seen_at: timestamp_ms,
            last_seen_at: timestamp_ms,
            observed,
            ignore_reason: None,
            last_decision_at: Some(timestamp_ms),
        })
        .await?;
    Ok(())
}

#[cfg(feature = "distributed")]
async fn distributed_publish_security_error<S>(
    reader: &mut runtime_io::BufReader<S>,
    err: frankenterm_core::distributed::DistributedSecurityError,
) where
    S: runtime_io::AsyncRead + runtime_io::AsyncWrite + Unpin,
{
    use runtime_io::AsyncWriteExt;

    let mut payload = serde_json::Map::new();
    payload.insert("ok".to_string(), serde_json::Value::Bool(false));
    if matches!(
        err,
        frankenterm_core::distributed::DistributedSecurityError::ProtocolVersionMissing { .. }
            | frankenterm_core::distributed::DistributedSecurityError::ProtocolVersionMismatch { .. }
    ) {
        payload.insert(
            "protocol_version".to_string(),
            serde_json::Value::from(frankenterm_core::wire_protocol::PROTOCOL_VERSION),
        );
    }
    payload.insert(
        "error".to_string(),
        serde_json::json!({
            "code": err.code(),
            "message": err.to_string()
        }),
    );
    if let Ok(encoded) = serde_json::to_string(&serde_json::Value::Object(payload)) {
        let _ = reader.get_mut().write_all(encoded.as_bytes()).await;
        let _ = reader.get_mut().write_all(b"\n").await;
        let _ = reader.get_mut().flush().await;
    }
}

#[cfg(feature = "distributed")]
fn distributed_wire_error_code(
    err: &frankenterm_core::wire_protocol::WireProtocolError,
) -> &'static str {
    match err {
        frankenterm_core::wire_protocol::WireProtocolError::InvalidJson(_)
        | frankenterm_core::wire_protocol::WireProtocolError::InvalidSender { .. }
        | frankenterm_core::wire_protocol::WireProtocolError::InvalidSequence { .. } => {
            "dist.invalid_message"
        }
        frankenterm_core::wire_protocol::WireProtocolError::MessageTooLarge { .. } => {
            "dist.message_too_large"
        }
        frankenterm_core::wire_protocol::WireProtocolError::VersionMismatch { .. } => {
            "dist.version_mismatch"
        }
        frankenterm_core::wire_protocol::WireProtocolError::TooManyAgents { .. } => {
            "dist.session_limit"
        }
    }
}

#[cfg(feature = "distributed")]
async fn distributed_publish_wire_error<S>(
    reader: &mut runtime_io::BufReader<S>,
    err: &frankenterm_core::wire_protocol::WireProtocolError,
) where
    S: runtime_io::AsyncRead + runtime_io::AsyncWrite + Unpin,
{
    use runtime_io::AsyncWriteExt;

    let mut payload = serde_json::Map::new();
    payload.insert("ok".to_string(), serde_json::Value::Bool(false));
    if matches!(
        err,
        frankenterm_core::wire_protocol::WireProtocolError::VersionMismatch { .. }
    ) {
        payload.insert(
            "protocol_version".to_string(),
            serde_json::Value::from(frankenterm_core::wire_protocol::PROTOCOL_VERSION),
        );
    }
    payload.insert(
        "error".to_string(),
        serde_json::json!({
            "code": distributed_wire_error_code(err),
            "message": err.to_string()
        }),
    );
    if let Ok(encoded) = serde_json::to_string(&serde_json::Value::Object(payload)) {
        let _ = reader.get_mut().write_all(encoded.as_bytes()).await;
        let _ = reader.get_mut().write_all(b"\n").await;
        let _ = reader.get_mut().flush().await;
    }
}

#[cfg(feature = "distributed")]
async fn distributed_publish_handshake_ok<S>(reader: &mut runtime_io::BufReader<S>)
where
    S: runtime_io::AsyncRead + runtime_io::AsyncWrite + Unpin,
{
    use runtime_io::AsyncWriteExt;

    let payload = serde_json::json!({
        "ok": true,
        "protocol_version": frankenterm_core::wire_protocol::PROTOCOL_VERSION,
        "server_version": frankenterm_core::VERSION,
    });
    if let Ok(encoded) = serde_json::to_string(&payload) {
        let _ = reader.get_mut().write_all(encoded.as_bytes()).await;
        let _ = reader.get_mut().write_all(b"\n").await;
        let _ = reader.get_mut().flush().await;
    }
}

#[cfg(feature = "distributed")]
async fn distributed_read_line<S>(
    reader: &mut runtime_io::BufReader<S>,
    line: &mut String,
    max_bytes: usize,
) -> std::io::Result<usize>
where
    S: runtime_io::AsyncRead + Unpin,
{
    use runtime_io::AsyncBufRead;
    use std::future::poll_fn;
    use std::pin::Pin;
    use std::task::Poll;

    line.clear();
    let mut bytes = Vec::new();

    loop {
        let state = poll_fn(|cx| match Pin::new(&mut *reader).poll_fill_buf(cx) {
            Poll::Pending => Poll::Pending,
            Poll::Ready(Err(err)) => Poll::Ready(Err(err)),
            Poll::Ready(Ok(available)) => {
                if available.is_empty() {
                    return Poll::Ready(Ok(None));
                }

                let (consumed, found_newline) =
                    if let Some(pos) = available.iter().position(|&byte| byte == b'\n') {
                        (pos + 1, true)
                    } else {
                        (available.len(), false)
                    };
                bytes.extend_from_slice(&available[..consumed]);
                Pin::new(&mut *reader).consume(consumed);
                if bytes.len() > max_bytes {
                    return Poll::Ready(Err(distributed_message_too_large_io_error()));
                }
                Poll::Ready(Ok(Some(found_newline)))
            }
        })
        .await?;

        match state {
            None => break,
            Some(true) => break,
            Some(false) => {}
        }
    }

    if bytes.is_empty() {
        return Ok(0);
    }

    let parsed = String::from_utf8(bytes)
        .map_err(|err| std::io::Error::new(std::io::ErrorKind::InvalidData, err))?;
    let len = parsed.len();
    line.push_str(&parsed);
    Ok(len)
}

#[cfg(feature = "distributed")]
// Network callers retain the exact sequence-scope OwnedMutexGuard from
// admission through this await and any rollback. That ordering prevents an
// older failed write from restoring replay, aggregator, or pane-sequence state
// over a newer admission for the same scope.
async fn distributed_persist_payload(
    sender: &str,
    sequence_scope: Option<&str>,
    payload: frankenterm_core::wire_protocol::WirePayload,
    storage: &Arc<frankenterm_core::runtime_async::Mutex<frankenterm_core::storage::StorageHandle>>,
    event_bus: &Arc<frankenterm_core::events::EventBus>,
    ingest_state: &DistributedIngestState,
) -> anyhow::Result<()> {
    use frankenterm_core::events::Event;
    use frankenterm_core::wire_protocol::WirePayload;

    // ft-xbnl0.2.3 tick 277: cx-first distributed persistence path.
    let persist_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    let canonical_sender = distributed_normalize_identity(sender);
    let sequence_scope = sequence_scope
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| canonical_sender.clone());

    match payload {
        WirePayload::PaneMeta(meta) => {
            distributed_persist_pane_meta(&canonical_sender, meta, storage, event_bus).await?;
        }
        WirePayload::PaneDelta(delta) => {
            let remote_pane_id = distributed_remote_pane_id(&canonical_sender, delta.pane_id);
            let seq_key = (sequence_scope.clone(), delta.pane_id);
            let mut drop_due_to_reorder = false;
            let mut gap_reason: Option<String> = None;
            let previous_seq;

            {
                let mut shared = ingest_state.shared.lock().await;
                previous_seq = shared.pane_seq_by_sender.get(&seq_key).copied();
                let expected = shared
                    .pane_seq_by_sender
                    .get(&seq_key)
                    .map(|last_seen| last_seen.saturating_add(1))
                    .unwrap_or(0);

                if delta.seq < expected {
                    drop_due_to_reorder = true;
                    gap_reason = Some(format!(
                        "distributed_out_of_order:sender={canonical_sender}:expected={expected}:actual={}",
                        delta.seq
                    ));
                } else {
                    if delta.seq > expected {
                        gap_reason = Some(distributed_seq_gap_reason(
                            &canonical_sender,
                            expected,
                            delta.seq,
                        ));
                    }
                    shared.pane_seq_by_sender.insert(seq_key.clone(), delta.seq);
                }
            }

            let persist_result: anyhow::Result<()> = async {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                if storage_handle
                    .get_pane_with_cx(&persist_cx, remote_pane_id)
                    .await?
                    .is_none()
                {
                    let ts = now_ms_i64();
                    distributed_upsert_pane(
                        &storage_handle,
                        remote_pane_id,
                        distributed_remote_pane_uuid(&canonical_sender, delta.pane_id, None),
                        distributed_remote_domain(&canonical_sender, "unknown"),
                        Some(format!("remote:{canonical_sender}:{}", delta.pane_id)),
                        Some("/remote".to_string()),
                        true,
                        ts,
                    )
                    .await?;
                }

                if let Some(reason) = gap_reason {
                    if let Some(gap) = storage_handle
                        .record_gap_with_cx(&persist_cx, remote_pane_id, &reason)
                        .await?
                    {
                        let _ = event_bus.publish(Event::GapDetected {
                            pane_id: gap.pane_id,
                            seq_before: gap.seq_before,
                            seq_after: gap.seq_after,
                            reason: gap.reason,
                            detected_at_ms: gap.detected_at,
                        });
                    }
                }

                if drop_due_to_reorder {
                    return Ok(());
                }

                // FND-004 / INV-RED-1: redact distributed pane content at the
                // aggregator ingest choke point, mirroring the local capture path
                // (frankenterm-core ingest.rs:1680 `redact_segment_for_persist`).
                // Without this, remote pane content was persisted RAW into
                // `output_segments` — a fail-closed redaction violation at the
                // storage layer (an unredacted DB export or any direct-segment read
                // would leak secrets, even though the standard read APIs redact at
                // output). Redaction is idempotent, so the read-path redactors that
                // run later are unaffected.
                let redacted_content =
                    frankenterm_core::redactor::Redactor::new().redact(&delta.content);
                let segment = storage_handle
                    .append_segment(
                        remote_pane_id,
                        &redacted_content,
                        Some(format!(
                            "remote_sender={canonical_sender};remote_seq={}",
                            delta.seq
                        )),
                    )
                    .await?;
                drop(storage_handle);

                let _ = event_bus.publish(Event::SegmentCaptured {
                    pane_id: remote_pane_id,
                    seq: segment.seq,
                    content_len: segment.content_len,
                });
                Ok(())
            }
            .await;

            if persist_result.is_err() && !drop_due_to_reorder {
                let mut shared = ingest_state.shared.lock().await;
                match previous_seq {
                    Some(previous_seq) => {
                        shared.pane_seq_by_sender.insert(seq_key, previous_seq);
                    }
                    None => {
                        shared.pane_seq_by_sender.remove(&seq_key);
                    }
                }
            }

            persist_result?;
        }
        WirePayload::Gap(gap) => {
            let remote_pane_id = distributed_remote_pane_id(&canonical_sender, gap.pane_id);
            // A GapNotice is forensic evidence from the sender, not proof that
            // all intermediate pane deltas were observed by the aggregator. Keep
            // the delta acceptance frontier driven only by accepted PaneDelta
            // payloads; otherwise a forged high seq_after can silence the pane.

            let persist_result: anyhow::Result<()> = async {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                if storage_handle
                    .get_pane_with_cx(&persist_cx, remote_pane_id)
                    .await?
                    .is_none()
                {
                    let ts = now_ms_i64();
                    distributed_upsert_pane(
                        &storage_handle,
                        remote_pane_id,
                        distributed_remote_pane_uuid(&canonical_sender, gap.pane_id, None),
                        distributed_remote_domain(&canonical_sender, "unknown"),
                        Some(format!("remote:{canonical_sender}:{}", gap.pane_id)),
                        Some("/remote".to_string()),
                        true,
                        ts,
                    )
                    .await?;
                }

                let reason = format!(
                    "distributed_gap:{}:{}:{}",
                    gap.reason, gap.seq_before, gap.seq_after
                );
                if let Some(stored_gap) = storage_handle
                    .record_gap_with_cx(&persist_cx, remote_pane_id, &reason)
                    .await?
                {
                    let _ = event_bus.publish(Event::GapDetected {
                        pane_id: stored_gap.pane_id,
                        seq_before: stored_gap.seq_before,
                        seq_after: stored_gap.seq_after,
                        reason: stored_gap.reason,
                        detected_at_ms: stored_gap.detected_at,
                    });
                }
                Ok(())
            }
            .await;

            persist_result?;
        }
        WirePayload::Detection(detection_notice) => {
            let remote_pane_id =
                distributed_remote_pane_id(&canonical_sender, detection_notice.pane_id);
            let pane_uuid = distributed_remote_pane_uuid(
                &canonical_sender,
                detection_notice.pane_id,
                detection_notice.pane_uuid.as_deref(),
            );
            let detection = frankenterm_core::patterns::Detection {
                rule_id: detection_notice.rule_id,
                agent_type: detection_notice.agent_type,
                event_type: detection_notice.event_type,
                severity: detection_notice.severity,
                confidence: detection_notice.confidence,
                extracted: detection_notice.extracted,
                matched_text: detection_notice.matched_text,
                span: (0, 0),
            };
            // FND-010 / INV-RED-1: redact the inbound distributed detection before
            // it is persisted to the events table or re-broadcast on the event bus.
            // matched_text is the full regex span and can carry a secret; the local
            // path redacts via redact_detection, the distributed path must too.
            let detection = frankenterm_core::runtime::redact_detection(&detection);
            let detected_at = if detection_notice.detected_at_ms > 0 {
                detection_notice.detected_at_ms
            } else {
                now_ms_i64()
            };

            let storage_handle = storage.lock().await.clone(); // ubs:ignore
            if storage_handle
                .get_pane_with_cx(&persist_cx, remote_pane_id)
                .await?
                .is_none()
            {
                distributed_upsert_pane(
                    &storage_handle,
                    remote_pane_id,
                    pane_uuid.clone(),
                    distributed_remote_domain(&canonical_sender, "unknown"),
                    Some(format!(
                        "remote:{canonical_sender}:{}",
                        detection_notice.pane_id
                    )),
                    Some("/remote".to_string()),
                    true,
                    detected_at,
                )
                .await?;
            }
            let stored_event = distributed_detection_to_stored_event(
                remote_pane_id,
                pane_uuid.as_deref(),
                &detection,
                None,
                detected_at,
            );
            let outcome = storage_handle
                .record_event_outcome_with_cx(&persist_cx, stored_event)
                .await?;
            drop(storage_handle);

            if let Some(event_id) = outcome.inserted_event_id() {
                let _ = event_bus.publish(Event::PatternDetected {
                    pane_id: remote_pane_id,
                    pane_uuid,
                    detection,
                    event_id: Some(event_id),
                });
            } else {
                tracing::debug!(
                    pane_id = remote_pane_id,
                    event_id = outcome.event_id(),
                    "Distributed ingest suppressed duplicate detection after durable dedupe"
                );
            }
        }
        WirePayload::PanesMeta(panes_meta) => {
            for pane in panes_meta.panes {
                distributed_persist_pane_meta(&canonical_sender, pane, storage, event_bus).await?;
            }
        }
    }

    Ok(())
}

#[cfg(feature = "distributed")]
async fn distributed_persist_pane_meta(
    sender: &str,
    meta: frankenterm_core::wire_protocol::PaneMeta,
    storage: &Arc<frankenterm_core::runtime_async::Mutex<frankenterm_core::storage::StorageHandle>>,
    event_bus: &Arc<frankenterm_core::events::EventBus>,
) -> anyhow::Result<()> {
    use frankenterm_core::events::Event;

    let canonical_sender = distributed_normalize_identity(sender);
    let remote_pane_id = distributed_remote_pane_id(&canonical_sender, meta.pane_id);
    let pane_uuid =
        distributed_remote_pane_uuid(&canonical_sender, meta.pane_id, meta.pane_uuid.as_deref());
    let domain = distributed_remote_domain(&canonical_sender, &meta.domain);
    let title = meta
        .title
        .clone()
        .or_else(|| Some(format!("remote:{canonical_sender}:{}", meta.pane_id)));

    // ft-xbnl0.2.3 tick 277: cx-first distributed pane-meta persist.
    let meta_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    let storage_handle = storage.lock().await.clone(); // ubs:ignore
    let is_new = storage_handle
        .get_pane_with_cx(&meta_cx, remote_pane_id)
        .await?
        .is_none();
    distributed_upsert_pane(
        &storage_handle,
        remote_pane_id,
        pane_uuid,
        domain.clone(),
        title.clone(),
        meta.cwd.clone(),
        meta.observed,
        meta.timestamp_ms,
    )
    .await?;
    drop(storage_handle);

    if is_new {
        let _ = event_bus.publish(Event::PaneDiscovered {
            pane_id: remote_pane_id,
            domain,
            title: title.unwrap_or_else(|| format!("remote:{canonical_sender}:{}", meta.pane_id)),
        });
    }

    Ok(())
}

#[cfg(feature = "distributed")]
// Listener connection handling threads stream, auth, storage, events, shutdown, and wire limits together.
#[allow(clippy::too_many_arguments)]
async fn distributed_handle_connection<S>(
    stream: S,
    peer_addr: std::net::SocketAddr,
    distributed_config: frankenterm_core::config::DistributedConfig,
    wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits,
    expected_token: Option<String>,
    allow_agent_ids: Arc<HashSet<String>>,
    ingest_state: Arc<DistributedIngestState>,
    storage: Arc<frankenterm_core::runtime_async::Mutex<frankenterm_core::storage::StorageHandle>>,
    event_bus: Arc<frankenterm_core::events::EventBus>,
    shutdown_flag: Arc<std::sync::atomic::AtomicBool>,
) where
    S: runtime_io::AsyncRead + runtime_io::AsyncWrite + Unpin,
{
    let message_timeout = Duration::from_secs(30);
    let mut reader = runtime_io::BufReader::new(stream);
    let mut handshake_line = String::new();

    // ft-xbnl0.2.3 tick 287: cx-first distributed handshake read timeout.
    let handshake_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    let handshake_size = match frankenterm_core::runtime_async::timeout_with_cx(
        &handshake_cx,
        DISTRIBUTED_HANDSHAKE_TIMEOUT,
        distributed_read_line(
            &mut reader,
            &mut handshake_line,
            wire_limits.max_message_size,
        ),
    )
    .await
    {
        Ok(Ok(size)) => size,
        Ok(Err(err)) => {
            if distributed_is_message_too_large_io_error(&err) {
                distributed_publish_security_error(
                    &mut reader,
                    frankenterm_core::distributed::DistributedSecurityError::MessageTooLarge,
                )
                .await;
                return;
            }
            tracing::warn!(peer = %peer_addr, error = %err, "Distributed handshake read failed");
            return;
        }
        Err(_) => {
            distributed_publish_security_error(
                &mut reader,
                frankenterm_core::distributed::DistributedSecurityError::HandshakeTimeout,
            )
            .await;
            return;
        }
    };

    if handshake_size == 0 {
        return;
    }
    if handshake_line.len() > wire_limits.max_message_size {
        distributed_publish_security_error(
            &mut reader,
            frankenterm_core::distributed::DistributedSecurityError::MessageTooLarge,
        )
        .await;
        return;
    }

    let handshake = match serde_json::from_str::<DistributedHandshake>(handshake_line.trim()) {
        Ok(handshake) => handshake,
        Err(err) => {
            tracing::warn!(peer = %peer_addr, error = %err, "Invalid distributed handshake payload");
            distributed_publish_security_error(
                &mut reader,
                frankenterm_core::distributed::DistributedSecurityError::AuthFailed,
            )
            .await;
            return;
        }
    };

    if let Err(err) = distributed_validate_handshake_protocol_version(handshake.protocol_version) {
        distributed_publish_security_error(&mut reader, err).await;
        return;
    }

    let normalized_handshake_agent =
        match distributed_validate_handshake_agent_id(handshake.agent_id.as_deref(), wire_limits) {
            Ok(agent_id) => agent_id,
            Err(err) => {
                distributed_publish_security_error(&mut reader, err).await;
                return;
            }
        };
    let validated_session_id = match distributed_validate_handshake_session_id(
        handshake.session_id.as_deref(),
        wire_limits,
    ) {
        Ok(session_id) => session_id,
        Err(err) => {
            distributed_publish_security_error(&mut reader, err).await;
            return;
        }
    };

    if !allow_agent_ids.is_empty() {
        let Some(agent_id) = normalized_handshake_agent.as_deref() else {
            distributed_publish_security_error(
                &mut reader,
                frankenterm_core::distributed::DistributedSecurityError::AuthFailed,
            )
            .await;
            return;
        };
        if !allow_agent_ids.contains(agent_id) {
            distributed_publish_security_error(
                &mut reader,
                frankenterm_core::distributed::DistributedSecurityError::AuthFailed,
            )
            .await;
            return;
        }
    }

    if let Err(err) = frankenterm_core::distributed::validate_token(
        distributed_config.auth_mode,
        expected_token.as_deref(),
        handshake.token.as_deref(),
        handshake.agent_id.as_deref(),
    ) {
        distributed_publish_security_error(&mut reader, err).await;
        return;
    }

    distributed_publish_handshake_ok(&mut reader).await;

    let session_id = distributed_resolve_session_id(
        validated_session_id.as_deref(),
        normalized_handshake_agent.as_deref(),
        peer_addr,
    );

    let mut rate_limiter = frankenterm_core::distributed::FixedWindowRateLimiter::new(8_000, 1000);
    let message_size_limit = frankenterm_core::distributed::MessageSizeLimit {
        max_bytes: wire_limits.max_message_size,
    };
    let mut connection_sequence_scopes = std::collections::HashSet::new();
    // Authentication pins one sender per connection, so there is exactly one
    // derived scope to retire even when every envelope is rejected.
    let mut connection_sequence_gate = None;
    let mut pinned_connection_sender = normalized_handshake_agent.clone();

    loop {
        use std::sync::atomic::Ordering;

        if shutdown_flag.load(Ordering::SeqCst) {
            break;
        }

        let mut line = String::new();
        // ft-xbnl0.2.3 tick 287: cx-first distributed message read timeout (reuse handshake_cx).
        let read_size = match frankenterm_core::runtime_async::timeout_with_cx(
            &handshake_cx,
            message_timeout,
            distributed_read_line(&mut reader, &mut line, wire_limits.max_message_size),
        )
        .await
        {
            Ok(Ok(size)) => size,
            Ok(Err(err)) => {
                if distributed_is_message_too_large_io_error(&err) {
                    distributed_publish_security_error(
                        &mut reader,
                        frankenterm_core::distributed::DistributedSecurityError::MessageTooLarge,
                    )
                    .await;
                    continue;
                }
                tracing::warn!(peer = %peer_addr, error = %err, "Distributed stream read failed");
                break;
            }
            Err(_) => {
                distributed_publish_security_error(
                    &mut reader,
                    frankenterm_core::distributed::DistributedSecurityError::MessageTimeout,
                )
                .await;
                break;
            }
        };

        if read_size == 0 {
            break;
        }

        let trimmed = line.trim_end_matches(['\n', '\r']);
        if trimmed.is_empty() {
            continue;
        }

        if let Err(err) = message_size_limit.check(trimmed.len()) {
            distributed_publish_security_error(&mut reader, err).await;
            continue;
        }
        if let Err(err) = rate_limiter.allow(now_ms()) {
            distributed_publish_security_error(&mut reader, err).await;
            continue;
        }

        let mut envelope =
            match frankenterm_core::wire_protocol::WireEnvelope::from_json_with_limits(
                trimmed.as_bytes(),
                wire_limits,
            ) {
                Ok(envelope) => envelope,
                Err(err) => {
                    tracing::warn!(peer = %peer_addr, error = %err, "Invalid distributed wire envelope");
                    distributed_publish_wire_error(&mut reader, &err).await;
                    continue;
                }
            };

        let canonical_sender = distributed_normalize_identity(&envelope.sender);
        match pinned_connection_sender.as_deref() {
            Some(sender) if canonical_sender != *sender => {
                distributed_publish_security_error(
                    &mut reader,
                    frankenterm_core::distributed::DistributedSecurityError::AuthFailed,
                )
                .await;
                break;
            }
            Some(_) => {}
            None => {
                pinned_connection_sender = Some(canonical_sender.clone());
            }
        }

        let sender = canonical_sender;
        let replay_id = distributed_replay_session_key(&session_id, &sender);
        let session_scope =
            distributed_sender_session_scope(&session_id, &sender, wire_limits.max_sender_id_len);
        envelope.sender = session_scope.clone();
        if connection_sequence_gate.is_none() {
            connection_sequence_gate = Some(session_scope.clone());
        }
        // Preserve sender order all the way through durable persistence. An
        // older failed write must finish rollback before a concurrent
        // connection can admit a newer envelope for the same logical scope.
        // Other scopes use different gates and remain fully concurrent.
        let sequence_scope_guard =
            distributed_lock_sequence_scope(&ingest_state, &session_scope).await;
        let _ = distributed_prune_stale_sequence_scopes(
            &ingest_state,
            now_ms_i64(),
            DISTRIBUTED_SEQUENCE_SCOPE_STALE_AFTER_MS,
        )
        .await;
        let activate_sequence_scope = !connection_sequence_scopes.contains(&session_scope);
        let admission = {
            let mut shared = ingest_state.shared.lock().await;
            distributed_admit_envelope(
                &mut shared,
                &replay_id,
                &session_scope,
                envelope,
                activate_sequence_scope,
            )
        };
        let (previous_replay_seq, previous_agent_session, ingest_result) = match admission {
            Err(err) => {
                // Rejection has no persistence or rollback transaction to
                // serialize. Never retain this scope's gate while a slow peer
                // backpressures the outbound error response.
                drop(sequence_scope_guard);
                distributed_release_unowned_sequence_scope_gate(
                    &ingest_state,
                    Some(&session_scope),
                )
                .await;
                distributed_publish_security_error(&mut reader, err).await;
                continue;
            }
            Ok(DistributedAdmission {
                previous_replay_seq,
                previous_agent_session,
                ingest_result,
            }) => (previous_replay_seq, previous_agent_session, ingest_result),
        };
        if ingest_result.is_ok() && activate_sequence_scope {
            let inserted = connection_sequence_scopes.insert(session_scope.clone());
            debug_assert!(inserted, "new sequence scope should insert exactly once");
        }

        match ingest_result {
            Ok(frankenterm_core::wire_protocol::IngestResult::Duplicate { sender, seq }) => {
                tracing::debug!(peer = %peer_addr, sender = %sender, seq, "Duplicate distributed envelope skipped");
            }
            Ok(frankenterm_core::wire_protocol::IngestResult::Accepted(payload)) => {
                if let Err(err) = distributed_persist_payload(
                    &sender,
                    Some(&session_scope),
                    payload,
                    &storage,
                    &event_bus,
                    &ingest_state,
                )
                .await
                {
                    distributed_rollback_failed_persist(
                        &ingest_state,
                        &replay_id,
                        previous_replay_seq,
                        &session_scope,
                        previous_agent_session,
                    )
                    .await;
                    tracing::warn!(
                        peer = %peer_addr,
                        sender = %sender,
                        error = %err,
                        "Failed to persist distributed payload; rolled back distributed admission state"
                    );
                }
            }
            Err(err) => {
                // In-memory ingest rejection likewise has no durable work
                // guarded by this lease. Release before awaiting peer I/O.
                drop(sequence_scope_guard);
                distributed_release_unowned_sequence_scope_gate(
                    &ingest_state,
                    Some(&session_scope),
                )
                .await;
                distributed_publish_wire_error(&mut reader, &err).await;
                tracing::warn!(peer = %peer_addr, error = %err, "Distributed ingest rejected envelope");
            }
        }
    }

    distributed_release_sequence_scopes(&ingest_state, &connection_sequence_scopes).await;
    distributed_release_unowned_sequence_scope_gate(
        &ingest_state,
        connection_sequence_gate.as_deref(),
    )
    .await;
}

#[cfg(feature = "distributed")]
async fn spawn_distributed_listener(
    distributed_config: frankenterm_core::config::DistributedConfig,
    wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits,
    storage: Arc<frankenterm_core::runtime_async::Mutex<frankenterm_core::storage::StorageHandle>>,
    event_bus: Arc<frankenterm_core::events::EventBus>,
    shutdown_flag: Arc<std::sync::atomic::AtomicBool>,
) -> anyhow::Result<frankenterm_core::runtime_async::task::JoinHandle<()>> {
    use runtime_net::TcpListener;
    use std::sync::atomic::Ordering;

    let expected_token =
        match frankenterm_core::distributed::resolve_expected_token(&distributed_config) {
            Ok(token) => token,
            Err(err) => anyhow::bail!("Failed to resolve distributed token: {err}"),
        };
    let allow_agent_ids = distributed_build_allow_agent_ids(&distributed_config, wire_limits)?;
    let allow_agent_ids = Arc::new(allow_agent_ids);

    // bind_addr is the server-side listener address (aggregator mode).
    // This is distinct from the agent connect target; see --connect-addr.
    let listener = TcpListener::bind(distributed_config.bind_addr.clone()).await?;
    tracing::info!(bind = %distributed_config.bind_addr, "Distributed listener started");

    let ingest_state = Arc::new(DistributedIngestState::new(wire_limits));
    let connection_limiter = frankenterm_core::distributed::ConnectionLimiter::new(256);
    let tls_acceptor = if distributed_config.tls.enabled {
        let bundle = frankenterm_core::distributed::build_tls_bundle(&distributed_config, None)?;
        Some(bundle.acceptor())
    } else {
        None
    };

    let task = frankenterm_core::runtime_async::task::spawn(async move {
        // ft-xbnl0.2.3 tick 287: cx-first distributed listener accept timeout.
        let accept_cx =
            frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
        let mut connection_tasks = frankenterm_core::runtime_async::task::JoinSet::new();
        loop {
            while let Some(join_result) = connection_tasks.try_join_next() {
                if let Err(error) = join_result {
                    tracing::warn!(
                        failure_class = ?error.kind(),
                        "Distributed connection task failed"
                    );
                }
            }

            if shutdown_flag.load(Ordering::SeqCst) {
                break;
            }

            let accept_result = frankenterm_core::runtime_async::timeout_with_cx(
                &accept_cx,
                Duration::from_millis(500),
                listener.accept(),
            )
            .await;
            let Ok(accept_result) = accept_result else {
                continue;
            };

            let (stream, peer_addr) = match accept_result {
                Ok(result) => result,
                Err(err) => {
                    tracing::warn!(error = %err, "Distributed accept failed");
                    continue;
                }
            };

            let permit = match connection_limiter.try_acquire() {
                Ok(permit) => permit,
                Err(err) => {
                    tracing::warn!(peer = %peer_addr, code = err.code(), "Distributed connection rejected");
                    continue;
                }
            };

            let distributed_config = distributed_config.clone();
            let connection_wire_limits = wire_limits;
            let expected_token = expected_token.clone();
            let allow_agent_ids = Arc::clone(&allow_agent_ids);
            let ingest_state = Arc::clone(&ingest_state);
            let storage = Arc::clone(&storage);
            let event_bus = Arc::clone(&event_bus);
            let shutdown_flag = Arc::clone(&shutdown_flag);
            let tls_acceptor = tls_acceptor.clone();

            connection_tasks.spawn(async move {
                let _permit = permit;
                if let Some(acceptor) = tls_acceptor {
                    match acceptor.accept(stream).await {
                        Ok(tls_stream) => {
                            distributed_handle_connection(
                                tls_stream,
                                peer_addr,
                                distributed_config,
                                connection_wire_limits,
                                expected_token,
                                allow_agent_ids,
                                ingest_state,
                                storage,
                                event_bus,
                                shutdown_flag,
                            )
                            .await;
                        }
                        Err(err) => {
                            tracing::warn!(peer = %peer_addr, error = %err, "Distributed TLS handshake failed");
                        }
                    }
                } else {
                    distributed_handle_connection(
                        stream,
                        peer_addr,
                        distributed_config,
                        connection_wire_limits,
                        expected_token,
                        allow_agent_ids,
                        ingest_state,
                        storage,
                        event_bus,
                        shutdown_flag,
                    )
                    .await;
                }
            });
        }

        // Connection handlers can be blocked on quiet clients or TLS
        // handshakes. Retain every task handle, request cancellation, and
        // bound the terminal-acknowledgement drain so listener shutdown can
        // neither detach work nor wait forever.
        connection_tasks.abort_all();
        let drain_cx = frankenterm_core::cx::for_request();
        let drain_result = frankenterm_core::runtime_async::timeout_with_cx(
            &drain_cx,
            Duration::from_secs(1),
            async {
                loop {
                    match connection_tasks.drain_next_with_cx(&drain_cx).await {
                        Ok(Some(join_result)) => {
                            if let Err(error) = join_result {
                                tracing::debug!(
                                    failure_class = ?error.kind(),
                                    "Distributed connection task stopped during listener shutdown"
                                );
                            }
                        }
                        Ok(None) => return Ok(()),
                        Err(drain_error) => return Err(drain_error),
                    }
                }
            },
        )
        .await;
        if let Ok(Err(drain_error)) = &drain_result {
            tracing::warn!(
                failure_class = ?drain_error.kind(),
                "Distributed connection task drain context failed before terminal settlement"
            );
        }
        match connection_tasks.settlement() {
            frankenterm_core::runtime_async::task::JoinSetSettlement::Settled => {}
            frankenterm_core::runtime_async::task::JoinSetSettlement::Incomplete {
                active_tasks,
                unacknowledged_tasks,
            } if drain_result.is_err() => {
                tracing::warn!(
                    event = "distributed_connection_task_drain_timeout",
                    active_tasks,
                    unacknowledged_tasks,
                    remaining_tasks = connection_tasks.len(),
                    orphan_risk = true,
                    "Distributed connection tasks missed bounded terminal settlement"
                );
            }
            frankenterm_core::runtime_async::task::JoinSetSettlement::Incomplete {
                active_tasks,
                unacknowledged_tasks,
            } => {
                tracing::warn!(
                    event = "distributed_connection_task_settlement_incomplete",
                    active_tasks,
                    unacknowledged_tasks,
                    remaining_tasks = connection_tasks.len(),
                    orphan_risk = true,
                    "Distributed connection task drain ended without terminal settlement"
                );
            }
        }

        tracing::info!("Distributed listener stopped");
    });

    Ok(task)
}

#[cfg(feature = "distributed")]
trait DistributedIo: runtime_io::AsyncRead + runtime_io::AsyncWrite + Unpin + Send {}

#[cfg(feature = "distributed")]
impl<T> DistributedIo for T where T: runtime_io::AsyncRead + runtime_io::AsyncWrite + Unpin + Send {}

#[cfg(feature = "distributed")]
type DistributedIoStream = Box<dyn DistributedIo>;

#[cfg(feature = "distributed")]
fn distributed_agent_default_id() -> String {
    let from_env = std::env::var("FT_AGENT_ID")
        .ok()
        .or_else(|| std::env::var("HOSTNAME").ok())
        .or_else(|| std::env::var("COMPUTERNAME").ok())
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());

    from_env.unwrap_or_else(|| format!("agent-{}", std::process::id()))
}

#[cfg(feature = "distributed")]
fn distributed_agent_resolve_id(explicit_agent_id: Option<String>) -> String {
    explicit_agent_id
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(distributed_agent_default_id)
}

#[cfg(feature = "distributed")]
fn distributed_agent_validate_id(
    agent_id: &str,
    wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits,
) -> anyhow::Result<()> {
    frankenterm_core::wire_protocol::validate_sender_identity_with_limits(agent_id, wire_limits)
        .map_err(|err| anyhow::anyhow!("invalid distributed agent id: {err}"))
}

#[cfg(feature = "distributed")]
fn distributed_tls_domain(connect_addr: &str) -> String {
    let trimmed = connect_addr.trim();
    if let Some(stripped) = trimmed.strip_prefix('[') {
        if let Some(end) = stripped.find(']') {
            let host = stripped[..end].trim();
            if !host.is_empty() {
                return host.to_string();
            }
        }
    }

    let host = trimmed
        .rsplit_once(':')
        .map_or(trimmed, |(host, _)| host)
        .trim();
    if host.is_empty() {
        "localhost".to_string()
    } else {
        host.to_string()
    }
}

#[cfg(feature = "distributed")]
async fn distributed_agent_connect(
    connect_addr: &str,
    distributed_config: &frankenterm_core::config::DistributedConfig,
) -> anyhow::Result<DistributedIoStream> {
    use runtime_net::TcpStream;

    let tcp = TcpStream::connect(connect_addr.to_string()).await?;
    if let Err(err) = tcp.set_nodelay(true) {
        tracing::debug!(error = %err, "Failed to set TCP_NODELAY for distributed agent stream");
    }

    if distributed_config.tls.enabled {
        let tls_bundle = frankenterm_core::distributed::build_tls_bundle(distributed_config, None)?;
        let connector = tls_bundle.connector();
        let tls_domain = distributed_tls_domain(connect_addr);
        let tls_stream = connector.connect(&tls_domain, tcp).await?;
        Ok(Box::new(tls_stream))
    } else {
        Ok(Box::new(tcp))
    }
}

#[cfg(feature = "distributed")]
fn distributed_agent_domain_is_remote(domain: &str) -> bool {
    domain.starts_with("distributed:")
}

#[cfg(feature = "distributed")]
fn distributed_agent_local_pane(record: &frankenterm_core::storage::PaneRecord) -> bool {
    !distributed_agent_domain_is_remote(&record.domain)
}

#[cfg(feature = "distributed")]
async fn distributed_agent_should_skip_remote_pane(
    storage: &Arc<frankenterm_core::runtime_async::Mutex<frankenterm_core::storage::StorageHandle>>,
    pane_id: u64,
) -> anyhow::Result<bool> {
    let storage_handle = storage.lock().await.clone(); // ubs:ignore
    // ft-xbnl0.2.3 tick 277: cx-first distributed remote pane check.
    let check_cx =
        frankenterm_core::cx::Cx::current().unwrap_or_else(frankenterm_core::cx::for_request);
    let pane = storage_handle.get_pane_with_cx(&check_cx, pane_id).await?;
    Ok(matches!(
        pane.as_ref(),
        Some(record) if !distributed_agent_local_pane(record)
    ))
}

#[cfg(feature = "distributed")]
fn distributed_agent_pane_meta(
    record: &frankenterm_core::storage::PaneRecord,
) -> frankenterm_core::wire_protocol::PaneMeta {
    frankenterm_core::wire_protocol::PaneMeta {
        pane_id: record.pane_id,
        pane_uuid: record.pane_uuid.clone(),
        domain: record.domain.clone(),
        title: record.title.clone(),
        cwd: record.cwd.clone(),
        rows: None,
        cols: None,
        observed: record.observed,
        timestamp_ms: record.last_seen_at,
    }
}

#[cfg(feature = "distributed")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DistributedEnvelopeSendOutcome {
    Sent,
    Oversized { size: usize, max: usize },
}

#[cfg(feature = "distributed")]
async fn distributed_agent_send_envelope(
    stream: &mut runtime_io::BufReader<DistributedIoStream>,
    envelope: &frankenterm_core::wire_protocol::WireEnvelope,
    wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits,
) -> anyhow::Result<DistributedEnvelopeSendOutcome> {
    use runtime_io::AsyncWriteExt;

    let bytes = envelope.to_json()?;
    if bytes.len() > wire_limits.max_message_size {
        tracing::warn!(
            sender = %envelope.sender,
            seq = envelope.seq,
            size = bytes.len(),
            max = wire_limits.max_message_size,
            "Skipping oversized distributed envelope"
        );
        return Ok(DistributedEnvelopeSendOutcome::Oversized {
            size: bytes.len(),
            max: wire_limits.max_message_size,
        });
    }

    stream.get_mut().write_all(&bytes).await?;
    stream.get_mut().write_all(b"\n").await?;
    stream.get_mut().flush().await?;
    Ok(DistributedEnvelopeSendOutcome::Sent)
}

#[cfg(feature = "distributed")]
async fn distributed_agent_send_oversized_delta_gap(
    streamer: &mut frankenterm_core::wire_protocol::AgentStreamer,
    stream: &mut runtime_io::BufReader<DistributedIoStream>,
    wire_limits: frankenterm_core::wire_protocol::WireProtocolLimits,
    pane_id: u64,
    seq: u64,
    content_len: usize,
    oversized_frame_size: usize,
    oversized_frame_max: usize,
) -> anyhow::Result<()> {
    use frankenterm_core::events::Event;

    let skipped_seq_after = seq.saturating_add(1);
    let (seq_before, seq_after) = distributed_inferred_gap_bounds(seq, skipped_seq_after);
    let reason = format!(
        "distributed_oversized_delta:pane_id={pane_id}:seq={seq}:content_len={content_len}:frame_size={oversized_frame_size}:max={oversized_frame_max}"
    );
    let Some(gap_envelope) = streamer.event_to_envelope(&Event::GapDetected {
        pane_id,
        seq_before,
        seq_after,
        reason,
        detected_at_ms: now_ms_i64(),
    }) else {
        anyhow::bail!(
            "distributed stream sequence exhausted while reporting oversized pane delta gap"
        );
    };

    match distributed_agent_send_envelope(stream, &gap_envelope, wire_limits).await? {
        DistributedEnvelopeSendOutcome::Sent => Ok(()),
        DistributedEnvelopeSendOutcome::Oversized { size, max } => {
            anyhow::bail!(
                "oversized distributed pane-delta gap marker exceeded wire limit: {size} bytes (max {max})"
            );
        }
    }
}

#[cfg(all(test, feature = "distributed"))]
