    fn sample_restore_summary() -> frankenterm_core::session_restore::RestoreSummary {
        use frankenterm_core::restore_layout::RestoreResult;
        use frankenterm_core::restore_process::{
            LaunchAction, ProcessDispositionReason, ProcessLauncher, ProcessPlan,
        };
        use frankenterm_core::session_restore::{RestoreSummary, RestoredPaneState};
        use std::collections::HashMap;

        let mut pane_id_map = HashMap::new();
        pane_id_map.insert(1, 101);
        pane_id_map.insert(2, 102);

        RestoreSummary {
            session_id: "session-restart".to_string(),
            checkpoint_id: 42,
            intent_checkpoint_id: 43,
            outcome_checkpoint_id: 44,
            layout_result: RestoreResult {
                pane_id_map,
                failed_panes: vec![(3, "split failed".to_string())],
                windows_created: 1,
                tabs_created: 1,
                panes_created: 2,
            },
            pane_states: (1..=3)
                .map(|pane_id| RestoredPaneState {
                    pane_id,
                    cwd: None,
                    command: None,
                    terminal_state: None,
                    agent_metadata: None,
                    scrollback_checkpoint_seq: None,
                    last_output_at: None,
                })
                .collect(),
            process_launch_report: Some(ProcessLauncher::execute(&[
                ProcessPlan {
                    old_pane_id: 1,
                    new_pane_id: 101,
                    action: LaunchAction::Skip(ProcessDispositionReason::DefaultShellCreated),
                },
                ProcessPlan {
                    old_pane_id: 2,
                    new_pane_id: 102,
                    action: LaunchAction::Manual(
                        ProcessDispositionReason::CapturedAgentRequiresManualRecovery,
                    ),
                },
                ProcessPlan {
                    old_pane_id: 3,
                    new_pane_id: 103,
                    action: LaunchAction::Manual(
                        ProcessDispositionReason::CapturedProcessStateUnavailableRequiresManualRecovery,
                    ),
                },
            ])),
            restore_authority_resolved: false,
            elapsed_ms: 2500,
        }
    }

