    #[test]
    fn session_orphan_operational_failures_remain_bounded_json_and_toon() {
        let raw_secret = format!("AKIAIOSFODNN7EXAMPLE {}", "x".repeat(8_192));
        for error_code in [
            "session.orphan_scan_failed",
            "session.orphan_artifact_write_failed",
            "session.orphan_read_failed",
            "session.orphan_discard_failed",
        ] {
            for format in [
                SnapshotSessionOutputFormat::Json,
                SnapshotSessionOutputFormat::Toon,
            ] {
                let (message, rendered) =
                    format_session_export_error(error_code, &raw_secret, format);
                assert!(message.len() <= 4_096);
                assert!(!message.contains("AKIAIOSFODNN7EXAMPLE"));
                assert!(message.contains("[REDACTED]"));
                let rendered = rendered.expect("structured error rendering");
                let payload: serde_json::Value = match format {
                    SnapshotSessionOutputFormat::Json => {
                        serde_json::from_str(&rendered).expect("decode JSON operational error")
                    }
                    SnapshotSessionOutputFormat::Toon => {
                        let decoded = toon_rust::try_decode(&rendered, None)
                            .expect("decode TOON operational error");
                        let json =
                            toon_rust::cli::json_stringify::json_stringify_lines(&decoded, 0)
                                .join("\n");
                        serde_json::from_str(&json).expect("decode TOON error as JSON")
                    }
                    SnapshotSessionOutputFormat::Plain => unreachable!(),
                };
                assert_eq!(payload["ok"], false);
                assert_eq!(payload["error_code"], error_code);
                assert_ne!(payload["error"].as_str().unwrap_or_default(), "");
                assert!(!rendered.contains("AKIAIOSFODNN7EXAMPLE"));
            }
        }
    }

    #[test]
    fn session_mmap_export_json_reports_actual_counts() {
        use frankenterm_core::scrollback_mmap_format::RecordKind;
        use frankenterm_core::scrollback_mmap_recovery::{
            DEFAULT_REPLAY_CHUNK_BYTES, MmapReplayPlan,
        };
        use frankenterm_core::scrollback_mmap_writer::{
            LinearRecordCompleteness, LinearRecordSnapshot, LinearRecordSourceIdentity,
        };

        let plan = MmapReplayPlan::from_snapshot(
            LinearRecordSnapshot {
                header: frankenterm_core::scrollback_mmap_format::ScrollbackHeader::new(
                    [0; 32], 1024, 0,
                ),
                records: vec![
                    (RecordKind::Text, b"hello".to_vec()),
                    (RecordKind::Csi, b"\x1b[0m".to_vec()),
                ],
                payload_bytes: 9,
                source_identity: LinearRecordSourceIdentity {
                    device: 0,
                    inode: 0,
                },
                completeness: LinearRecordCompleteness::Complete,
            },
            DEFAULT_REPLAY_CHUNK_BYTES,
            frankenterm_core::scrollback_mmap_recovery::LegacyRecoveryLimits::DEFAULT,
        )
        .expect("bounded replay plan");
        let payload = session_mmap_export_json(&plan, plan.chunks.len());

        assert_eq!(payload["status"], "replayed");
        assert_eq!(payload["mode"], "mmap_linear_records_export");
        assert_eq!(payload["source_completeness"]["status"], "complete");
        assert_eq!(payload["records_read"], 2);
        assert_eq!(payload["records_replayed"], 2);
        assert_eq!(payload["bytes_read"], 9);
        assert_eq!(payload["bytes_replayed"], 9);
        assert_eq!(payload["chunks_exported"], 2);
        assert_eq!(payload["skipped"].as_array().unwrap().len(), 0);
    }

    #[test]
    fn session_mmap_export_json_never_promotes_an_incomplete_source() {
        use frankenterm_core::scrollback_mmap_format::{RecordKind, ScrollbackHeader};
        use frankenterm_core::scrollback_mmap_recovery::{
            DEFAULT_REPLAY_CHUNK_BYTES, LegacyRecoveryLimits, MmapReplayPlan,
        };
        use frankenterm_core::scrollback_mmap_writer::{
            LinearRecordCompleteness, LinearRecordSnapshot, LinearRecordSourceIdentity,
            LinearRecordTerminalReason,
        };

        let plan = MmapReplayPlan::from_snapshot(
            LinearRecordSnapshot {
                header: ScrollbackHeader::new([0; 32], 1024, 0),
                records: vec![(RecordKind::Text, b"salvaged prefix".to_vec())],
                payload_bytes: 15,
                source_identity: LinearRecordSourceIdentity {
                    device: 7,
                    inode: 11,
                },
                completeness: LinearRecordCompleteness::Incomplete {
                    decoded_cursor_bytes: 31,
                    declared_cursor_bytes: 47,
                    reason: LinearRecordTerminalReason::PhysicalRecordPayloadTruncated,
                },
            },
            DEFAULT_REPLAY_CHUNK_BYTES,
            LegacyRecoveryLimits::DEFAULT,
        )
        .expect("bounded incomplete replay plan");
        let payload = session_mmap_export_json(&plan, plan.chunks.len());

        assert_eq!(payload["status"], "partial");
        assert_eq!(payload["source_completeness"]["status"], "incomplete");
        assert_eq!(payload["source_completeness"]["decoded_cursor_bytes"], 31);
        assert_eq!(payload["source_completeness"]["declared_cursor_bytes"], 47);
        assert_eq!(
            payload["source_completeness"]["reason"],
            "physical_record_payload_truncated"
        );
    }

    #[test]
    fn compatible_client_dump_subcommand_parses_explicit_authorities_and_bounds() {
        let cli = Cli::try_parse_from([
            "ft",
            "session",
            "compatible-client-dump",
            "--client",
            "/Applications/FrankenTerm.app/Contents/MacOS/ft",
            "--expected-client-sha256",
            "2e35331a1c6d7a50384338f4d23a8597ff19d7d9d7176c9792677579a32c91fc",
            "--expected-client-bytes",
            "20179712",
            "--mux-socket",
            "/tmp/frankenterm-gui.sock",
            "--output",
            "/tmp/recovery/mux-dump.json",
            "--max-panes",
            "101",
            "--max-total-bytes",
            "1048576",
            "--batch-size",
            "7",
            "--batch-timeout-secs",
            "41",
            "--max-batch-output-bytes",
            "2097152",
            "--format",
            "json",
        ])
        .expect("compatible-client dump command parses");
        let Some(Commands::Session { command }) = cli.command.map(|command| *command) else {
            panic!("expected session command");
        };
        let SessionCommands::CompatibleClientDump {
            client,
            expected_client_sha256,
            expected_client_bytes,
            mux_socket,
            output,
            max_panes,
            max_total_bytes,
            batch_size,
            batch_timeout_secs,
            max_batch_output_bytes,
            format,
        } = command
        else {
            panic!("expected compatible-client-dump subcommand");
        };
        assert_eq!(
            client,
            PathBuf::from("/Applications/FrankenTerm.app/Contents/MacOS/ft")
        );
        assert_eq!(
            expected_client_sha256,
            "2e35331a1c6d7a50384338f4d23a8597ff19d7d9d7176c9792677579a32c91fc"
        );
        assert_eq!(expected_client_bytes, 20_179_712);
        assert_eq!(mux_socket, PathBuf::from("/tmp/frankenterm-gui.sock"));
        assert_eq!(output, PathBuf::from("/tmp/recovery/mux-dump.json"));
        assert_eq!(max_panes, 101);
        assert_eq!(max_total_bytes, 1_048_576);
        assert_eq!(batch_size, 7);
        assert_eq!(batch_timeout_secs, 41);
        assert_eq!(max_batch_output_bytes, 2_097_152);
        assert_eq!(format, "json");
    }

