    #[test]
    fn compatible_client_command_is_hermetic_and_forces_the_private_workspace() {
        let environment = CompatibleClientEnvironment {
            root: PathBuf::from("/private/recovery"),
            empty_path: PathBuf::from("/private/recovery/empty-path"),
            home: PathBuf::from("/private/recovery/home"),
            config: PathBuf::from("/private/recovery/config"),
            data: PathBuf::from("/private/recovery/data"),
            workspace: PathBuf::from("/private/recovery/workspace"),
            temp: PathBuf::from("/private/recovery/tmp"),
            nonexistent_external_cli: PathBuf::from(
                "/private/recovery/external-wezterm-is-forbidden",
            ),
        };
        let arguments = compatible_client_command_arguments(
            &environment,
            Path::new("/private/recovery/pinned-ft-v0.13.0"),
            CompatibleClientCommandKind::GetText {
                pane_ids: &[7, 9],
                requested_tail: 1025,
            },
        );
        let rendered = arguments
            .iter()
            .map(|argument| argument.to_string_lossy().into_owned())
            .collect::<Vec<_>>();
        assert_eq!(rendered.first().map(String::as_str), Some("-i"));
        assert!(rendered.contains(&"PATH=/private/recovery/empty-path".to_string()));
        assert!(rendered.contains(&"HOME=/private/recovery/home".to_string()));
        assert!(rendered.contains(&"XDG_CONFIG_HOME=/private/recovery/config".to_string()));
        assert!(rendered.contains(&"XDG_DATA_HOME=/private/recovery/data".to_string()));
        assert!(rendered.contains(&"TMPDIR=/private/recovery/tmp".to_string()));
        assert!(rendered.contains(
            &"FT_WEZTERM_CLI=/private/recovery/external-wezterm-is-forbidden".to_string()
        ));
        let workspace = rendered
            .iter()
            .position(|argument| argument == "--workspace")
            .expect("workspace flag is explicit");
        assert_eq!(
            rendered.get(workspace + 1).map(String::as_str),
            Some("/private/recovery/workspace")
        );
        let robot = rendered
            .iter()
            .position(|argument| argument == "robot")
            .expect("robot subcommand is present");
        assert_eq!(
            &rendered[robot..robot + 4],
            ["robot", "--format", "json", "get-text"]
        );
        assert!(rendered.windows(2).any(|pair| pair == ["--panes", "7,9"]));
        assert!(rendered.windows(2).any(|pair| pair == ["--tail", "1025"]));
        for hostile in [
            "WEZTERM_CONFIG_FILE",
            "FRANKENTERM_CONFIG",
            "LD_PRELOAD",
            "DYLD_INSERT_LIBRARIES",
            "LUA_PATH",
            "RUST_LOG",
        ] {
            assert!(
                rendered
                    .iter()
                    .all(|argument| !argument.starts_with(&format!("{hostile}="))),
                "closed env -i allowlist must omit inherited injection knob {hostile}"
            );
        }
    }

    #[cfg(unix)]
    #[test]
    fn compatible_client_source_pin_rejects_mutation_symlinks_and_unsafe_modes() {
        use std::os::unix::fs::{PermissionsExt as _, symlink};

        let directory = tempfile::tempdir().expect("compatible client pin tempdir");
        let client = directory.path().join("ft");
        let bytes = b"#!/bin/sh\nprintf pinned\n";
        std::fs::write(&client, bytes).expect("write compatible client fixture");
        std::fs::set_permissions(&client, std::fs::Permissions::from_mode(0o500))
            .expect("seal compatible client fixture");
        let digest = sha256_hex(bytes);
        let mut pinned = pin_compatible_client(
            &client,
            &digest,
            u64::try_from(bytes.len()).unwrap(),
            "test compatible client",
        )
        .expect("safe owner-executable client is pinned");

        std::fs::set_permissions(&client, std::fs::Permissions::from_mode(0o700))
            .expect("make fixture writable for mutation");
        std::fs::write(&client, b"#!/bin/sh\nprintf forged\n")
            .expect("mutate compatible client fixture");
        assert!(pinned.revalidate("test compatible client").is_err());

        let unsafe_mode = directory.path().join("unsafe-mode-ft");
        std::fs::write(&unsafe_mode, bytes).expect("write unsafe-mode client fixture");
        std::fs::set_permissions(&unsafe_mode, std::fs::Permissions::from_mode(0o4001))
            .expect("set unsupported client mode");
        assert!(
            pin_compatible_client(
                &unsafe_mode,
                &digest,
                u64::try_from(bytes.len()).unwrap(),
                "unsafe-mode compatible client",
            )
            .is_err()
        );

        let alias = directory.path().join("aliased-ft");
        symlink(&unsafe_mode, &alias).expect("create compatible client symlink fixture");
        assert!(
            pin_compatible_client(
                &alias,
                &digest,
                u64::try_from(bytes.len()).unwrap(),
                "symlinked compatible client",
            )
            .is_err()
        );
    }

    #[cfg(unix)]
    #[test]
    fn compatible_client_subprocess_timeout_and_cancellation_settle_before_return() {
        run_async_test(async {
            fn assert_leader_reaped(directory: &Path) {
                let process_id: i64 = std::fs::read_to_string(directory.join("leader.pid"))
                    .expect("compatible-client test child must publish its leader pid")
                    .parse()
                    .expect("compatible-client test leader pid must be numeric");
                let probe = frankenterm_core::runtime_async::process::send_unix_signal_to_pid(
                    process_id, "0",
                )
                .expect("compatible-client leader process-existence probe must execute");
                assert!(
                    !probe.success(),
                    "compatible-client subprocess leader must already be reaped when the wrapper returns"
                );
            }

            async fn exercise(
                cx: &frankenterm_core::cx::Cx,
                directory: &Path,
                timeout: Duration,
            ) -> anyhow::Error {
                let pid = directory.join("leader.pid");
                let marker = directory.join("delayed-marker");
                let arguments = vec![
                    std::ffi::OsString::from("-i"),
                    std::ffi::OsString::from(format!("FT_TEST_PID={}", pid.display())),
                    std::ffi::OsString::from(format!("FT_TEST_MARKER={}", marker.display())),
                    std::ffi::OsString::from("/bin/sh"),
                    std::ffi::OsString::from("-c"),
                    std::ffi::OsString::from(
                        "printf '%s' \"$$\" > \"$FT_TEST_PID\"; (sleep 1; printf leaked > \"$FT_TEST_MARKER\") & wait",
                    ),
                ];
                execute_bounded_compatible_client_command(
                    cx,
                    arguments,
                    Vec::new(),
                    directory,
                    1024,
                    timeout,
                )
                .await
                .expect_err("long-running compatible client must be interrupted")
            }

            let timeout_directory = tempfile::tempdir().expect("timeout fixture");
            let timeout_cx = frankenterm_core::cx::for_testing();
            let timeout_error = exercise(
                &timeout_cx,
                timeout_directory.path(),
                Duration::from_millis(250),
            )
            .await;
            assert!(timeout_error.to_string().contains("wall-clock deadline"));
            assert_leader_reaped(timeout_directory.path());
            frankenterm_core::runtime_async::sleep(Duration::from_millis(900)).await;
            assert!(!timeout_directory.path().join("delayed-marker").exists());

            let cancellation_directory = tempfile::tempdir().expect("cancellation fixture");
            let cancellation_cx = frankenterm_core::cx::for_testing();
            let cancellation_trigger = cancellation_cx.clone();
            frankenterm_core::runtime_async::task::spawn(async move {
                frankenterm_core::runtime_async::sleep(Duration::from_millis(250)).await;
                cancellation_trigger.cancel_with(
                    frankenterm_core::outcome::CancelKind::User,
                    Some("compatible-client wrapper cancellation test"),
                );
            });
            let cancellation_error = exercise(
                &cancellation_cx,
                cancellation_directory.path(),
                Duration::from_secs(5),
            )
            .await;
            assert!(cancellation_error.to_string().contains("was cancelled"));
            assert_leader_reaped(cancellation_directory.path());
            frankenterm_core::runtime_async::sleep(Duration::from_millis(900)).await;
            assert!(
                !cancellation_directory
                    .path()
                    .join("delayed-marker")
                    .exists()
            );
        });
    }

    #[test]
    fn settled_blocking_effect_observes_pre_cancel_but_awaits_midflight_completion() {
        run_async_test(async {
            let pre_cancelled = frankenterm_core::cx::for_testing();
            pre_cancelled.cancel_with(
                frankenterm_core::outcome::CancelKind::User,
                Some("settled effect pre-cancel test"),
            );
            let pre_started = Arc::new(std::sync::atomic::AtomicBool::new(false));
            let closure_started = Arc::clone(&pre_started);
            let error = run_cli_settled_blocking_effect(
                &pre_cancelled,
                "test private artifact publication",
                move || {
                    closure_started.store(true, std::sync::atomic::Ordering::SeqCst);
                    Ok(())
                },
            )
            .await
            .expect_err("pre-cancelled effect must not begin mutation");
            assert!(
                error
                    .to_string()
                    .contains("before its first filesystem mutation")
            );
            assert!(!pre_started.load(std::sync::atomic::Ordering::SeqCst));

            let midflight = frankenterm_core::cx::for_testing();
            let cancel_trigger = midflight.clone();
            frankenterm_core::runtime_async::task::spawn(async move {
                frankenterm_core::runtime_async::sleep(Duration::from_millis(50)).await;
                cancel_trigger.cancel_with(
                    frankenterm_core::outcome::CancelKind::User,
                    Some("settled effect midflight cancellation test"),
                );
            });
            let completed = Arc::new(std::sync::atomic::AtomicBool::new(false));
            let closure_completed = Arc::clone(&completed);
            let started = Instant::now();
            let receipt = run_cli_settled_blocking_effect(
                &midflight,
                "test private artifact publication",
                move || {
                    std::thread::sleep(Duration::from_millis(250));
                    closure_completed.store(true, std::sync::atomic::Ordering::SeqCst);
                    Ok(17_u64)
                },
            )
            .await
            .expect("midflight cancellation must not abandon an admitted effect");
            assert_eq!(receipt, 17);
            assert!(completed.load(std::sync::atomic::Ordering::SeqCst));
            assert!(
                started.elapsed() >= Duration::from_millis(200),
                "settled effect boundary returned before its closure completed"
            );
        });
    }

    #[test]
    fn compatible_client_source_receipt_rejects_zero_or_mismatched_authority() {
        let identity = |mode: u32, bytes: u64| {
            serde_json::json!({
                "device": 1,
                "inode": 2,
                "uid": 501,
                "gid": 80,
                "mode": mode,
                "hard_link_count": 1,
                "byte_len": bytes,
                "modified_seconds": 1,
                "modified_nanoseconds": 2,
                "changed_seconds": 3,
                "changed_nanoseconds": 4,
            })
        };
        let mut client = identity(0o500, 20_179_712);
        client
            .as_object_mut()
            .unwrap()
            .insert("sha256".to_string(), serde_json::json!("1".repeat(64)));
        let mut source = serde_json::json!({
            "kind": "live_mux",
            "ft_version": "0.13.0",
            "git_hash": "3ebd60566",
            "capture_transport": COMPATIBLE_CLIENT_DUMP_CAPTURE_TRANSPORT,
            "backend_constraint": COMPATIBLE_CLIENT_DUMP_BACKEND_CONSTRAINT,
            "client": client,
            "mux_socket": {
                "path_sha256": "2".repeat(64),
                "identity": identity(0o700, 0),
            },
            "recovery_environment": {
                "retained": true,
                "path_sha256": "3".repeat(64),
            },
        });
        let verified = verify_mux_dump_source_metadata(&source)
            .expect("exact compatible-client source authority is accepted")
            .expect("compatible source metadata produces a recovery contract");
        assert_eq!(verified.client_sha256, "1".repeat(64));
        assert_eq!(verified.client_bytes, 20_179_712);
        assert_eq!(verified.mux_socket_path_sha256, "2".repeat(64));

        source["client"]["sha256"] = serde_json::json!("0".repeat(64));
        assert!(verify_mux_dump_source_metadata(&source).is_err());
        source["client"]["sha256"] = serde_json::json!("1".repeat(64));
        source["mux_socket"]["identity"]["uid"] = serde_json::json!(502);
        assert!(verify_mux_dump_source_metadata(&source).is_err());
        source["mux_socket"]["identity"]["uid"] = serde_json::json!(501);
        source["recovery_environment"]["retained"] = serde_json::json!(false);
        assert!(verify_mux_dump_source_metadata(&source).is_err());
    }

    #[test]
    fn private_artifact_write_is_verified_and_never_overwrites() {
        let dir = tempfile::tempdir().expect("artifact tempdir");
        let path = dir.path().join("private").join("mux-dump.json");
        let receipt =
            write_new_private_artifact(&path, b"first\n").expect("first private artifact write");
        assert_eq!(receipt.bytes, 6);
        assert_eq!(receipt.sha256, sha256_hex(b"first\n"));
        assert_eq!(receipt.durability, "file_and_parent_directory_synced");
        assert!(!receipt.recovered_existing);
        assert_eq!(std::fs::read(&path).unwrap(), b"first\n");

        let replay = write_new_private_artifact(&path, b"first\n")
            .expect("an exact existing artifact reconciles as lost success");
        assert!(replay.recovered_existing);
        assert_eq!(replay.sha256, receipt.sha256);

        let error = write_new_private_artifact(&path, b"second\n")
            .expect_err("existing artifact must not be overwritten");
        assert!(error.to_string().contains("never overwritten"));
        assert_eq!(std::fs::read(&path).unwrap(), b"first\n");

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            assert_eq!(
                std::fs::metadata(&path).unwrap().permissions().mode() & 0o777,
                0o600
            );
            assert_eq!(
                std::fs::metadata(path.parent().unwrap())
                    .unwrap()
                    .permissions()
                    .mode()
                    & 0o777,
                0o700
            );
        }
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn private_artifact_publication_recovers_every_crash_cut_without_clobbering() {
        let payload = vec![b'x'; 128 * 1024 + 17];
        let payload_sha256 = sha256_hex(&payload);
        let points = [
            PrivateArtifactPublicationPoint::StageOpened,
            PrivateArtifactPublicationPoint::StagePrefixWritten,
            PrivateArtifactPublicationPoint::StageSynchronized,
            PrivateArtifactPublicationPoint::TargetRenamed,
            PrivateArtifactPublicationPoint::ParentSynchronized,
        ];
        for (index, point) in points.into_iter().enumerate() {
            let directory = tempfile::tempdir().expect("private artifact crash-cut tempdir");
            let parent = directory.path().join("private");
            let path = parent.join(format!("dump-{index}.json"));
            let stage_name =
                private_artifact_stage_name(path.file_name().unwrap().as_ref(), &payload_sha256);
            let stage_path = parent.join(stage_name);
            let mut injected = false;
            let error = write_new_private_artifact_with_hook(&path, &payload, |observed| {
                if observed == point && !injected {
                    injected = true;
                    anyhow::bail!("deterministic private artifact crash cut");
                }
                Ok(())
            })
            .expect_err("selected publication cut must interrupt its first attempt");
            assert!(error.to_string().contains("crash cut"));
            assert!(injected, "the selected publication point must be reached");

            match point {
                PrivateArtifactPublicationPoint::StageOpened
                | PrivateArtifactPublicationPoint::StagePrefixWritten
                | PrivateArtifactPublicationPoint::StageSynchronized => {
                    assert!(
                        !path.exists(),
                        "a partial stage must never expose the target"
                    );
                    assert!(
                        stage_path.exists(),
                        "the deterministic stage must be retained"
                    );
                }
                PrivateArtifactPublicationPoint::TargetRenamed
                | PrivateArtifactPublicationPoint::ParentSynchronized => {
                    assert_eq!(
                        std::fs::read(&path).expect("renamed target remains readable"),
                        payload
                    );
                    assert!(
                        !stage_path.exists(),
                        "successful rename moves the exact stage into the target"
                    );
                }
                PrivateArtifactPublicationPoint::ExistingTargetSynchronized => {
                    unreachable!("the first publication attempt cannot reconcile a final target")
                }
            }

            let retry = write_new_private_artifact(&path, &payload)
                .expect("same payload retry must converge after every crash cut");
            assert_eq!(retry.sha256, payload_sha256);
            assert_eq!(retry.bytes, u64::try_from(payload.len()).unwrap());
            assert_eq!(std::fs::read(&path).unwrap(), payload);
            assert_eq!(
                retry.recovered_existing,
                matches!(
                    point,
                    PrivateArtifactPublicationPoint::TargetRenamed
                        | PrivateArtifactPublicationPoint::ParentSynchronized
                )
            );
            assert!(!stage_path.exists());

            let lost_reply = write_new_private_artifact(&path, &payload)
                .expect("exact final bytes must reconcile as a lost success reply");
            assert!(lost_reply.recovered_existing);
            let conflict = write_new_private_artifact(&path, b"conflicting payload")
                .expect_err("a different payload must never replace the exact target");
            assert!(conflict.to_string().contains("never overwritten"));
            assert_eq!(std::fs::read(&path).unwrap(), payload);
        }
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn private_artifact_existing_final_sync_cut_reconciles_durably() {
        let directory = tempfile::tempdir().expect("private artifact existing-final tempdir");
        let path = directory.path().join("private").join("dump.json");
        let payload = vec![b'y'; 96 * 1024 + 23];
        let initial = write_new_private_artifact(&path, &payload)
            .expect("initial private artifact publication");
        assert_eq!(initial.durability, "file_and_parent_directory_synced");
        assert!(!initial.recovered_existing);

        let mut injected = false;
        let error = write_new_private_artifact_with_hook(&path, &payload, |observed| {
            if observed == PrivateArtifactPublicationPoint::ExistingTargetSynchronized && !injected
            {
                injected = true;
                anyhow::bail!("existing-final reply lost after target synchronization");
            }
            Ok(())
        })
        .expect_err("existing-final synchronization cut must interrupt reconciliation");
        assert!(error.to_string().contains("reply lost"));
        assert!(injected);
        assert_eq!(
            std::fs::read(&path).expect("exact existing final remains readable"),
            payload
        );

        let retry = write_new_private_artifact(&path, &payload)
            .expect("retry must resynchronize and reconcile the exact existing final");
        assert!(retry.recovered_existing);
        assert_eq!(retry.durability, "file_and_parent_directory_synced");
        assert_eq!(retry.sha256, sha256_hex(&payload));
        assert_eq!(retry.bytes, u64::try_from(payload.len()).unwrap());

        let conflict = write_new_private_artifact(&path, b"conflicting artifact")
            .expect_err("a conflicting replay must never replace the durable final");
        assert!(conflict.to_string().contains("never overwritten"));
        assert_eq!(std::fs::read(&path).unwrap(), payload);
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn private_artifact_stages_are_payload_bound_bounded_and_conflict_preserving() {
        use std::os::unix::fs::PermissionsExt as _;

        let directory = tempfile::tempdir().expect("private artifact stage fixture");
        let parent = directory.path().join("private");
        std::fs::create_dir(&parent).expect("create private artifact fixture parent");
        std::fs::set_permissions(&parent, std::fs::Permissions::from_mode(0o700))
            .expect("seal private artifact fixture parent");
        let path = parent.join("dump.json");
        let expected = b"expected artifact bytes";
        let expected_sha256 = sha256_hex(expected);
        let expected_stage =
            private_artifact_stage_name(path.file_name().unwrap().as_ref(), &expected_sha256);
        let other_stage = private_artifact_stage_name(
            path.file_name().unwrap().as_ref(),
            &sha256_hex(b"different artifact bytes"),
        );
        assert_ne!(
            expected_stage, other_stage,
            "stage transaction identity must bind the exact payload digest"
        );

        let stage_path = parent.join(&expected_stage);
        let conflicting_prefix = b"conflicting";
        std::fs::write(&stage_path, conflicting_prefix)
            .expect("plant conflicting deterministic stage");
        std::fs::set_permissions(&stage_path, std::fs::Permissions::from_mode(0o600))
            .expect("seal conflicting deterministic stage");
        let conflict = write_new_private_artifact(&path, expected)
            .expect_err("conflicting retained stage bytes must fail closed");
        assert!(conflict.to_string().contains("conflicts"));
        assert!(!path.exists());
        assert_eq!(std::fs::read(&stage_path).unwrap(), conflicting_prefix);

        for index in 0..PRIVATE_ARTIFACT_MAX_RETAINED_STAGES {
            let residue = parent.join(format!(
                "{PRIVATE_ARTIFACT_STAGE_PREFIX}{index:064x}.pending"
            ));
            if residue == stage_path {
                continue;
            }
            std::fs::write(&residue, []).expect("plant bounded stage census residue");
            std::fs::set_permissions(&residue, std::fs::Permissions::from_mode(0o600))
                .expect("seal bounded stage census residue");
        }
        let parent_cap =
            open_directory_tree_nofollow(&parent).expect("open private stage census parent");
        assert!(
            private_artifact_stage_inventory(&parent_cap).is_err(),
            "more than the retained stage bound must be rejected during streaming census"
        );
    }

