    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_persist_payload_maps_sender_scoped_pane_ids_for_query_visibility() {
        run_async_test(async {
            let (storage_handle, db_path) = setup_storage("distributed_persist_payload_map").await;
            let storage =
                std::sync::Arc::new(frankenterm_core::runtime_async::Mutex::new(storage_handle));
            let event_bus = std::sync::Arc::new(frankenterm_core::events::EventBus::new(64));
            let pane_seq_by_sender = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );

            let sender = "agent-mapped";
            let source_pane_id = 17;
            let remote_pane_id = distributed_remote_pane_id(sender, source_pane_id);
            let marker = "DIST_PERSIST_PAYLOAD_MAP_MARKER";

            distributed_persist_payload(
                sender,
                None,
                frankenterm_core::wire_protocol::WirePayload::PaneMeta(
                    frankenterm_core::wire_protocol::PaneMeta {
                        pane_id: source_pane_id,
                        pane_uuid: Some("pane-uuid-17".to_string()),
                        domain: "prod".to_string(),
                        title: Some("remote-pane".to_string()),
                        cwd: Some("/remote/project".to_string()),
                        rows: Some(24),
                        cols: Some(120),
                        observed: true,
                        timestamp_ms: now_ms(),
                    },
                ),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .unwrap();

            distributed_persist_payload(
                sender,
                None,
                frankenterm_core::wire_protocol::WirePayload::PaneDelta(
                    frankenterm_core::wire_protocol::PaneDelta {
                        pane_id: source_pane_id,
                        seq: 0,
                        content: marker.to_string(),
                        content_len: marker.len(),
                        captured_at_ms: now_ms(),
                    },
                ),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .unwrap();

            {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                let remote = storage_handle.get_pane(remote_pane_id).await.unwrap();
                assert!(remote.is_some());
                assert!(
                    storage_handle
                        .get_pane(source_pane_id)
                        .await
                        .unwrap()
                        .is_none(),
                    "raw source pane_id should not be used for persisted remote panes"
                );
                let remote = remote.unwrap();
                assert_eq!(remote.domain, "distributed:agent-mapped:prod");

                let search_hits = storage_handle.search(marker).await.unwrap();
                assert!(search_hits.iter().any(|seg| seg.pane_id == remote_pane_id));
            }

            {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                storage_handle.shutdown().await.unwrap();
            }
            drop(storage);
            let _ = std::fs::remove_file(&db_path);
            let _ = std::fs::remove_file(format!("{db_path}-wal"));
            let _ = std::fs::remove_file(format!("{db_path}-shm"));
        });
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_detection_dedupe_retry_is_not_republished() {
        run_async_test(async {
            use frankenterm_core::patterns::{AgentType, Severity};
            use frankenterm_core::storage::EventQuery;
            use frankenterm_core::wire_protocol::{DetectionNotice, WirePayload};

            let (storage_handle, db_path) =
                setup_storage("distributed_detection_dedupe_retry").await;
            let storage =
                std::sync::Arc::new(frankenterm_core::runtime_async::Mutex::new(storage_handle));
            let event_bus = std::sync::Arc::new(frankenterm_core::events::EventBus::new(64));
            let mut subscriber = event_bus.subscribe_detections();
            let pane_seq_by_sender = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );

            let sender = "agent-detection-dedupe";
            let source_pane_id = 29;
            let remote_pane_id = distributed_remote_pane_id(sender, source_pane_id);
            let notice = DetectionNotice {
                rule_id: "codex.usage.reached".to_string(),
                agent_type: AgentType::Codex,
                event_type: "usage.reached".to_string(),
                severity: Severity::Warning,
                confidence: 0.95,
                extracted: serde_json::json!({"remaining": 0}),
                matched_text: "usage limit reached".to_string(),
                pane_id: source_pane_id,
                pane_uuid: Some("remote-dedupe-pane".to_string()),
                detected_at_ms: 1_700_000_003_000,
            };

            distributed_persist_payload(
                sender,
                None,
                WirePayload::Detection(notice.clone()),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .unwrap();
            let first = subscriber
                .try_recv()
                .expect("newly inserted distributed detection should be published")
                .expect("event bus delivery should succeed");
            assert!(matches!(
                first,
                frankenterm_core::events::Event::PatternDetected {
                    pane_id,
                    event_id: Some(_),
                    ..
                } if pane_id == remote_pane_id
            ));

            distributed_persist_payload(
                sender,
                None,
                WirePayload::Detection(notice),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .unwrap();
            assert!(
                subscriber.try_recv().is_none(),
                "a deduplicated retry must not masquerade as a new live detection"
            );

            let storage_handle = storage.lock().await.clone(); // ubs:ignore
            let events = storage_handle
                .get_events(EventQuery {
                    pane_id: Some(remote_pane_id),
                    limit: Some(10),
                    ..EventQuery::default()
                })
                .await
                .unwrap();
            assert_eq!(events.len(), 1, "the retry must retain one durable row");
            storage_handle.shutdown().await.unwrap();
            drop(storage);
            let _ = std::fs::remove_file(&db_path);
            let _ = std::fs::remove_file(format!("{db_path}-wal"));
            let _ = std::fs::remove_file(format!("{db_path}-shm"));
        });
    }

    /// FND-004 (gauntlet): the distributed ingest path must redact pane content
    /// BEFORE it lands in storage, so `output_segments.content` never holds a raw
    /// secret (an unredacted DB export or any direct-segment read would otherwise
    /// leak it, even though the higher read APIs redact at output). Plant a known
    /// secret in a remote PaneDelta, persist it through the production
    /// `distributed_persist_payload`, then read the stored segment via the
    /// low-level `StorageHandle::search` (which does NOT redact at read time) and
    /// assert the raw secret is gone + a redaction marker is present. FAILS if the
    /// ingest-side redaction is removed.
    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_persist_payload_redacts_pane_content_at_ingest() {
        run_async_test(async {
            let (storage_handle, db_path) =
                setup_storage("distributed_persist_payload_redact").await;
            let storage =
                std::sync::Arc::new(frankenterm_core::runtime_async::Mutex::new(storage_handle));
            let event_bus = std::sync::Arc::new(frankenterm_core::events::EventBus::new(64));
            let pane_seq_by_sender = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );

            let sender = "agent-secretful";
            let source_pane_id = 23;
            let remote_pane_id = distributed_remote_pane_id(sender, source_pane_id);
            let marker = "DIST_REDACT_MARKER";
            let secret = "sk-proj-abcdefghijklmnopqrstuvwxyz012345";
            let content = format!("{marker} leaked {secret} in remote output");

            distributed_persist_payload(
                sender,
                None,
                frankenterm_core::wire_protocol::WirePayload::PaneDelta(
                    frankenterm_core::wire_protocol::PaneDelta {
                        pane_id: source_pane_id,
                        seq: 0,
                        content: content.clone(),
                        content_len: content.len(),
                        captured_at_ms: now_ms(),
                    },
                ),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .unwrap();

            {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                let hits = storage_handle.search(marker).await.unwrap();
                let seg = hits
                    .iter()
                    .find(|seg| seg.pane_id == remote_pane_id)
                    .expect("planted distributed segment must be searchable by its marker");
                assert!(
                    !seg.content.contains(secret),
                    "raw secret must NOT survive in stored distributed segment content: {}",
                    seg.content
                );
                assert!(
                    seg.content.contains("[REDACTED"),
                    "expected a redaction marker in stored content: {}",
                    seg.content
                );
                assert!(
                    seg.content.contains(marker),
                    "non-secret marker should be preserved: {}",
                    seg.content
                );
            }

            {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                storage_handle.shutdown().await.unwrap();
            }
            drop(storage);
            let _ = std::fs::remove_file(&db_path);
            let _ = std::fs::remove_file(format!("{db_path}-wal"));
            let _ = std::fs::remove_file(format!("{db_path}-shm"));
        });
    }

    /// ft-6k5gh: a forged GapNotice must NOT advance the per-(sender,pane)
    /// delta-acceptance frontier. Before the fix, the Gap branch jammed
    /// `pane_seq_by_sender` to `seq_after - 1`, so a peer sending
    /// `Gap{ seq_before: 0, seq_after: u64::MAX }` permanently silenced its own
    /// pane — every later legitimate PaneDelta then failed `delta.seq < expected`
    /// and was dropped as out-of-order. This drives the exact attack through the
    /// production `distributed_persist_payload` and proves (a) the frontier is
    /// untouched by the gap and (b) a subsequent seq-0 delta is still accepted
    /// and persisted.
    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_forged_gap_does_not_suppress_future_deltas_ft_6k5gh() {
        run_async_test(async {
            let (storage_handle, db_path) = setup_storage("distributed_forged_gap_frontier").await;
            let storage =
                std::sync::Arc::new(frankenterm_core::runtime_async::Mutex::new(storage_handle));
            let event_bus = std::sync::Arc::new(frankenterm_core::events::EventBus::new(64));
            let pane_seq_by_sender = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );

            let sender = "agent-gapper";
            let source_pane_id = 71_u64;
            let remote_pane_id = distributed_remote_pane_id(sender, source_pane_id);
            let seq_key = (sender.to_string(), source_pane_id);

            // Attack A: a forged gap claiming a huge (but i64-representable) span
            // was skipped. This records the gap for forensics but must NOT move
            // the delta frontier — that is the exact ft-6k5gh jam vector.
            let huge_seq_after = i64::MAX as u64;
            distributed_persist_payload(
                sender,
                None,
                frankenterm_core::wire_protocol::WirePayload::Gap(
                    frankenterm_core::wire_protocol::GapNotice {
                        pane_id: source_pane_id,
                        seq_before: 0,
                        seq_after: huge_seq_after,
                        reason: "forged-huge".to_string(),
                        detected_at_ms: now_ms(),
                    },
                ),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .expect("a representable forged gap is recorded without error");

            // The gap must NOT have advanced (or created) the delta frontier.
            {
                let shared = pane_seq_by_sender.shared.lock().await;
                assert!(
                    !shared.pane_seq_by_sender.contains_key(&seq_key),
                    "ft-6k5gh: a GapNotice must not seed/advance the delta frontier, got {:?}",
                    shared.pane_seq_by_sender.get(&seq_key)
                );
            }

            // Attack B: wire validation now rejects an over-i64-range
            // seq_after before persistence. Drive the internal persistence
            // helper directly as a defense-in-depth check: storage must also
            // reject the first value above its durable range, and that failure
            // must still leave the delta frontier untouched.
            let over_range_seq_after = i64::MAX as u64 + 1;
            let over_range_error = distributed_persist_payload(
                sender,
                None,
                frankenterm_core::wire_protocol::WirePayload::Gap(
                    frankenterm_core::wire_protocol::GapNotice {
                        pane_id: source_pane_id,
                        seq_before: 0,
                        seq_after: over_range_seq_after,
                        reason: "forged-overflow".to_string(),
                        detected_at_ms: now_ms(),
                    },
                ),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .expect_err("the first sequence above i64::MAX must not reach durable storage");
            let over_range_diagnostic = format!("{over_range_error:#}");
            assert!(
                over_range_diagnostic.contains("seq_after value")
                    && over_range_diagnostic.contains("exceeds i64 range"),
                "ft-6k5gh: over-range persistence rejection lost its durable-range diagnosis: {over_range_error:#}"
            );
            {
                let shared = pane_seq_by_sender.shared.lock().await;
                assert!(
                    !shared.pane_seq_by_sender.contains_key(&seq_key),
                    "ft-6k5gh: even a rejected over-range gap must not touch the frontier, got {:?}",
                    shared.pane_seq_by_sender.get(&seq_key)
                );
            }

            // A subsequent legitimate seq-0 delta must still be accepted.
            let marker = "DIST_GAP_FRONTIER_MARKER";
            let content = format!("{marker} post-gap delta");
            distributed_persist_payload(
                sender,
                None,
                frankenterm_core::wire_protocol::WirePayload::PaneDelta(
                    frankenterm_core::wire_protocol::PaneDelta {
                        pane_id: source_pane_id,
                        seq: 0,
                        content: content.clone(),
                        content_len: content.len(),
                        captured_at_ms: now_ms(),
                    },
                ),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .unwrap();

            // Frontier now reflects the accepted delta, and the content is stored.
            {
                let shared = pane_seq_by_sender.shared.lock().await;
                assert_eq!(
                    shared.pane_seq_by_sender.get(&seq_key).copied(),
                    Some(0),
                    "ft-6k5gh: the seq-0 delta must be accepted and advance the frontier to 0"
                );
            }
            {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                let hits = storage_handle.search(marker).await.unwrap();
                assert!(
                    hits.iter().any(|seg| seg.pane_id == remote_pane_id),
                    "ft-6k5gh: the post-gap delta must be persisted, not dropped as out-of-order"
                );
            }

            {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                storage_handle.shutdown().await.unwrap();
            }
            drop(storage);
            let _ = std::fs::remove_file(&db_path);
            let _ = std::fs::remove_file(format!("{db_path}-wal"));
            let _ = std::fs::remove_file(format!("{db_path}-shm"));
        });
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_persist_payload_normalizes_sender_case_for_remote_pane_mapping() {
        run_async_test(async {
            let (storage_handle, db_path) =
                setup_storage("distributed_persist_payload_sender_case").await;
            let storage =
                std::sync::Arc::new(frankenterm_core::runtime_async::Mutex::new(storage_handle));
            let event_bus = std::sync::Arc::new(frankenterm_core::events::EventBus::new(64));
            let pane_seq_by_sender = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );

            let canonical_sender = "agent-mapped";
            let meta_sender = "Agent-Mapped";
            let delta_sender = "agent-mapped";
            let source_pane_id = 27_u64;
            let remote_pane_id = distributed_remote_pane_id(canonical_sender, source_pane_id);
            let marker = "DIST_PERSIST_PAYLOAD_CASE_MARKER";

            distributed_persist_payload(
                meta_sender,
                None,
                frankenterm_core::wire_protocol::WirePayload::PaneMeta(
                    frankenterm_core::wire_protocol::PaneMeta {
                        pane_id: source_pane_id,
                        pane_uuid: Some("pane-uuid-27".to_string()),
                        domain: "prod".to_string(),
                        title: Some("remote-pane".to_string()),
                        cwd: Some("/remote/project".to_string()),
                        rows: Some(24),
                        cols: Some(120),
                        observed: true,
                        timestamp_ms: now_ms(),
                    },
                ),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .unwrap();

            distributed_persist_payload(
                delta_sender,
                None,
                frankenterm_core::wire_protocol::WirePayload::PaneDelta(
                    frankenterm_core::wire_protocol::PaneDelta {
                        pane_id: source_pane_id,
                        seq: 0,
                        content: marker.to_string(),
                        content_len: marker.len(),
                        captured_at_ms: now_ms(),
                    },
                ),
                &storage,
                &event_bus,
                &pane_seq_by_sender,
            )
            .await
            .unwrap();

            {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                let remote = storage_handle
                    .get_pane(remote_pane_id)
                    .await
                    .unwrap()
                    .expect("canonical remote pane should exist");
                assert_eq!(remote.domain, "distributed:agent-mapped:prod");

                let distributed_pane_count = storage_handle
                    .get_panes()
                    .await
                    .unwrap()
                    .into_iter()
                    .filter(|pane| pane.domain.starts_with("distributed:"))
                    .count();
                assert_eq!(
                    distributed_pane_count, 1,
                    "case-only sender variants should not fork remote panes"
                );

                let search_hits = storage_handle.search(marker).await.unwrap();
                assert!(search_hits.iter().any(|seg| seg.pane_id == remote_pane_id));
            }

            {
                let storage_handle = storage.lock().await.clone(); // ubs:ignore
                storage_handle.shutdown().await.unwrap();
            }
            drop(storage);
            let _ = std::fs::remove_file(&db_path);
            let _ = std::fs::remove_file(format!("{db_path}-wal"));
            let _ = std::fs::remove_file(format!("{db_path}-shm"));
        });
    }

