    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_validate_handshake_agent_id_rejects_blank_and_invalid_ids() {
        let limits = default_wire_limits();

        assert_eq!(
            distributed_validate_handshake_agent_id(None, limits),
            Ok(None)
        );
        assert_eq!(
            distributed_validate_handshake_agent_id(Some(" Agent-Case "), limits),
            Ok(Some("agent-case".to_string()))
        );

        for agent_id in ["", " \t ", "agent:evil", "agent/evil"] {
            assert_eq!(
                distributed_validate_handshake_agent_id(Some(agent_id), limits),
                Err(frankenterm_core::distributed::DistributedSecurityError::AuthFailed),
                "present-but-invalid handshake agent_id must fail closed: {agent_id:?}",
            );
        }

        let too_long = "a".repeat(limits.max_sender_id_len.saturating_add(1));
        assert_eq!(
            distributed_validate_handshake_agent_id(Some(&too_long), limits),
            Err(frankenterm_core::distributed::DistributedSecurityError::AuthFailed),
            "oversized handshake agent_id must fail closed before acknowledgement",
        );
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_validate_handshake_session_id_rejects_blank_and_unbounded_ids() {
        let limits = default_wire_limits();

        assert_eq!(
            distributed_validate_handshake_session_id(None, limits),
            Ok(None)
        );
        assert_eq!(
            distributed_validate_handshake_session_id(Some(" session:case "), limits),
            Ok(Some("session:case".to_string()))
        );

        for session_id in ["", " \t ", "session\u{0}bad", "session\u{1f}bad"] {
            assert_eq!(
                distributed_validate_handshake_session_id(Some(session_id), limits),
                Err(frankenterm_core::distributed::DistributedSecurityError::AuthFailed),
                "present-but-invalid handshake session_id must fail closed: {session_id:?}",
            );
        }

        let too_long = "s".repeat(limits.max_sender_id_len.saturating_add(65));
        assert_eq!(
            distributed_validate_handshake_session_id(Some(&too_long), limits),
            Err(frankenterm_core::distributed::DistributedSecurityError::AuthFailed),
            "oversized handshake session_id must fail closed before replay-state allocation",
        );
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_build_allow_agent_ids_rejects_blank_invalid_and_duplicate_entries() {
        let limits = default_wire_limits();
        let mut config = frankenterm_core::config::DistributedConfig::default();

        assert!(
            distributed_build_allow_agent_ids(&config, limits)
                .expect("empty allowlist is unrestricted")
                .is_empty()
        );

        config.allow_agent_ids = vec![" Agent-1 ".to_string()];
        let allowlist =
            distributed_build_allow_agent_ids(&config, limits).expect("valid allowlist");
        assert!(allowlist.contains("agent-1"));

        for bad_entries in [
            vec![" \t ".to_string()],
            vec!["agent:bad".to_string()],
            vec!["Agent-1".to_string(), "agent-1".to_string()],
        ] {
            config.allow_agent_ids = bad_entries;
            assert!(
                distributed_build_allow_agent_ids(&config, limits).is_err(),
                "malformed allow_agent_ids must fail closed before listener start"
            );
        }
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_sender_session_scope_normalizes_sender_and_changes_with_session() {
        let first = distributed_sender_session_scope(
            "session-a",
            "Agent-Case",
            frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
        );
        let second = distributed_sender_session_scope(
            "session-a",
            "agent-case",
            frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
        );
        let third = distributed_sender_session_scope(
            "session-b",
            "agent-case",
            frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
        );
        let long_sender = "A".repeat(frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN);
        let long_scope = distributed_sender_session_scope(
            "session-a",
            &long_sender,
            frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
        );
        let tuned_scope = distributed_sender_session_scope("session-a", &long_sender, 32);
        let unicode_scope =
            distributed_sender_session_scope("session-a", "agent-\u{00e9}\u{00e9}", 24);

        assert_eq!(first, second);
        assert_ne!(first, third);
        assert!(first.starts_with("agent-case."));
        assert!(long_scope.len() <= frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN);
        assert_eq!(tuned_scope.len(), 32);
        assert!(unicode_scope.len() <= 24);
        assert!(unicode_scope.starts_with("agent-."));
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_release_sequence_scopes_preserves_state_until_stale_prune() {
        run_async_test(async {
            let ingest_state = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );
            let sequence_scope = distributed_sender_session_scope(
                "session-a",
                "agent-cleanup",
                frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
            );
            let replay_id = distributed_replay_session_key("session-a", "agent-cleanup");
            let mut released_scopes = std::collections::HashSet::new();
            released_scopes.insert(sequence_scope.clone());

            distributed_register_sequence_scope(&ingest_state, &sequence_scope, &replay_id).await;
            distributed_register_sequence_scope(&ingest_state, &sequence_scope, &replay_id).await;

            {
                let mut shared = ingest_state.shared.lock().await;
                shared
                    .aggregator
                    .ingest_envelope(frankenterm_core::wire_protocol::WireEnvelope::new(
                        1,
                        &sequence_scope,
                        frankenterm_core::wire_protocol::WirePayload::Gap(
                            frankenterm_core::wire_protocol::GapNotice {
                                pane_id: 7,
                                seq_before: 0,
                                seq_after: 1,
                                reason: "cleanup-test".to_string(),
                                detected_at_ms: now_ms_i64(),
                            },
                        ),
                    ))
                    .expect("seed aggregator state for cleanup test");
            }
            {
                let mut shared = ingest_state.shared.lock().await;
                shared
                    .replay_guard
                    .validate(&replay_id, 1)
                    .expect("seed replay guard for cleanup test");
            }

            {
                let mut shared = ingest_state.shared.lock().await;
                shared
                    .pane_seq_by_sender
                    .insert((sequence_scope.clone(), 7), 3);
            }

            distributed_release_sequence_scopes(&ingest_state, &released_scopes).await;

            {
                let shared = ingest_state.shared.lock().await;
                assert_eq!(shared.aggregator.agent_last_seq(&sequence_scope), Some(1));
            }
            {
                let shared = ingest_state.shared.lock().await;
                assert_eq!(
                    shared.pane_seq_by_sender.get(&(sequence_scope.clone(), 7)),
                    Some(&3)
                );
            }
            {
                let mut shared = ingest_state.shared.lock().await;
                assert_eq!(
                    shared.replay_guard.validate(&replay_id, 1).expect_err(
                        "released-but-dormant session should still reject stale replay"
                    ),
                    frankenterm_core::distributed::DistributedSecurityError::ReplayDetected
                );
                shared
                    .replay_guard
                    .validate(&replay_id, 2)
                    .expect("dormant session should still advance replay state");
            }

            distributed_release_sequence_scopes(&ingest_state, &released_scopes).await;

            {
                let shared = ingest_state.shared.lock().await;
                assert_eq!(shared.aggregator.agent_last_seq(&sequence_scope), Some(1));
            }
            {
                let shared = ingest_state.shared.lock().await;
                assert_eq!(
                    shared.pane_seq_by_sender.get(&(sequence_scope.clone(), 7)),
                    Some(&3)
                );
            }

            let pruned = distributed_prune_stale_sequence_scopes(
                &ingest_state,
                now_ms_i64() + DISTRIBUTED_SEQUENCE_SCOPE_STALE_AFTER_MS + 1,
                DISTRIBUTED_SEQUENCE_SCOPE_STALE_AFTER_MS,
            )
            .await;
            assert_eq!(pruned, 1);

            {
                let shared = ingest_state.shared.lock().await;
                assert_eq!(shared.aggregator.agent_last_seq(&sequence_scope), None);
                assert_eq!(shared.aggregator.agent_count(), 0);
            }
            {
                let shared = ingest_state.shared.lock().await;
                assert!(shared.pane_seq_by_sender.is_empty());
            }
            {
                let mut shared = ingest_state.shared.lock().await;
                shared
                    .replay_guard
                    .validate(&replay_id, 1)
                    .expect("stale-pruned replay state should accept a fresh session");
            }
        });
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_replay_reject_release_prunes_unowned_scope_gate() {
        run_async_test(async {
            let ingest_state = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );
            let replay_id = distributed_replay_session_key("session-rejected", "agent-rejected");
            let sequence_scope = distributed_sender_session_scope(
                "session-rejected",
                "agent-rejected",
                frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
            );

            let guard = distributed_lock_sequence_scope(&ingest_state, &sequence_scope).await;
            {
                let mut shared = ingest_state.shared.lock().await;
                assert!(shared.sequence_scope_gates.contains_key(&sequence_scope));
                assert!(shared.active_sequence_scopes.is_empty());
                shared
                    .replay_guard
                    .validate(&replay_id, 1)
                    .expect("seed replay frontier");
                let rejection = distributed_admit_envelope(
                    &mut shared,
                    &replay_id,
                    &sequence_scope,
                    frankenterm_core::wire_protocol::WireEnvelope::new(
                        1,
                        &sequence_scope,
                        frankenterm_core::wire_protocol::WirePayload::Gap(
                            frankenterm_core::wire_protocol::GapNotice {
                                pane_id: 1,
                                seq_before: 0,
                                seq_after: 1,
                                reason: "duplicate-replay".to_string(),
                                detected_at_ms: now_ms_i64(),
                            },
                        ),
                    ),
                    false,
                );
                assert!(rejection.is_err(), "duplicate sequence must be rejected");
                assert!(
                    shared.active_sequence_scopes.is_empty(),
                    "replay rejection must not activate the sequence scope"
                );
            }

            distributed_release_unowned_sequence_scope_gate(&ingest_state, Some(&sequence_scope))
                .await;
            {
                let shared = ingest_state.shared.lock().await;
                assert!(
                    shared.sequence_scope_gates.contains_key(&sequence_scope),
                    "cleanup must preserve a gate while its exact guard is live"
                );
            }
            drop(guard);

            distributed_release_unowned_sequence_scope_gate(&ingest_state, Some(&sequence_scope))
                .await;

            let shared = ingest_state.shared.lock().await;
            assert!(shared.sequence_scope_gates.is_empty());
            assert!(shared.active_sequence_scopes.is_empty());
        });
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_admission_activates_scope_in_same_state_cut() {
        run_async_test(async {
            let ingest_state = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );
            let replay_id = distributed_replay_session_key("session-admit", "agent-admit");
            let sequence_scope = distributed_sender_session_scope(
                "session-admit",
                "agent-admit",
                frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
            );

            let admission = {
                let mut shared = ingest_state.shared.lock().await;
                let admission = distributed_admit_envelope(
                    &mut shared,
                    &replay_id,
                    &sequence_scope,
                    frankenterm_core::wire_protocol::WireEnvelope::new(
                        1,
                        &sequence_scope,
                        frankenterm_core::wire_protocol::WirePayload::Gap(
                            frankenterm_core::wire_protocol::GapNotice {
                                pane_id: 7,
                                seq_before: 0,
                                seq_after: 1,
                                reason: "atomic-admission".to_string(),
                                detected_at_ms: now_ms_i64(),
                            },
                        ),
                    ),
                    true,
                );

                assert_eq!(shared.replay_guard.session_last_seq(&replay_id), Some(1));
                assert_eq!(shared.aggregator.agent_last_seq(&sequence_scope), Some(1));
                let scope_state = shared
                    .active_sequence_scopes
                    .get(&sequence_scope)
                    .expect("successful admission must activate its sequence scope");
                assert_eq!(scope_state.active_connections, 1);
                assert_eq!(scope_state.replay_id, replay_id);
                assert_eq!(scope_state.inactive_since_ms, None);
                admission
            };

            assert!(matches!(
                admission,
                Ok(DistributedAdmission {
                    previous_replay_seq: None,
                    previous_agent_session: None,
                    ingest_result: Ok(frankenterm_core::wire_protocol::IngestResult::Accepted(_)),
                })
            ));
        });
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_scope_gate_orders_failed_persist_rollback_before_newer_admission() {
        run_async_test(async {
            use std::future::Future as _;
            use std::task::Poll;

            let ingest_state = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );
            let replay_id = distributed_replay_session_key("session-ordered", "agent-ordered");
            let sequence_scope = distributed_sender_session_scope(
                "session-ordered",
                "agent-ordered",
                frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
            );
            let first_guard = distributed_lock_sequence_scope(&ingest_state, &sequence_scope).await;
            let first_admission = {
                let mut shared = ingest_state.shared.lock().await;
                distributed_admit_envelope(
                    &mut shared,
                    &replay_id,
                    &sequence_scope,
                    frankenterm_core::wire_protocol::WireEnvelope::new(
                        1,
                        &sequence_scope,
                        frankenterm_core::wire_protocol::WirePayload::Gap(
                            frankenterm_core::wire_protocol::GapNotice {
                                pane_id: 9,
                                seq_before: 0,
                                seq_after: 1,
                                reason: "first-persist-fails".to_string(),
                                detected_at_ms: now_ms_i64(),
                            },
                        ),
                    ),
                    false,
                )
            };
            let Ok(DistributedAdmission {
                previous_replay_seq,
                previous_agent_session,
                ingest_result: Ok(frankenterm_core::wire_protocol::IngestResult::Accepted(_)),
            }) = first_admission
            else {
                panic!("first envelope should be admitted");
            };

            let mut second_admission = Box::pin(async {
                let _second_guard =
                    distributed_lock_sequence_scope(&ingest_state, &sequence_scope).await;
                let mut shared = ingest_state.shared.lock().await;
                distributed_admit_envelope(
                    &mut shared,
                    &replay_id,
                    &sequence_scope,
                    frankenterm_core::wire_protocol::WireEnvelope::new(
                        2,
                        &sequence_scope,
                        frankenterm_core::wire_protocol::WirePayload::Gap(
                            frankenterm_core::wire_protocol::GapNotice {
                                pane_id: 9,
                                seq_before: 1,
                                seq_after: 2,
                                reason: "second-waits-for-rollback".to_string(),
                                detected_at_ms: now_ms_i64(),
                            },
                        ),
                    ),
                    false,
                )
            });
            std::future::poll_fn(|cx| match second_admission.as_mut().poll(cx) {
                Poll::Pending => Poll::Ready(()),
                Poll::Ready(_) => panic!("same-scope admission bypassed its held sequence gate"),
            })
            .await;

            distributed_rollback_failed_persist(
                &ingest_state,
                &replay_id,
                previous_replay_seq,
                &sequence_scope,
                previous_agent_session,
            )
            .await;
            drop(first_guard);

            assert!(matches!(
                second_admission.await,
                Ok(DistributedAdmission {
                    previous_replay_seq: None,
                    previous_agent_session: None,
                    ingest_result: Ok(frankenterm_core::wire_protocol::IngestResult::Accepted(_)),
                })
            ));
            let shared = ingest_state.shared.lock().await;
            assert_eq!(shared.replay_guard.session_last_seq(&replay_id), Some(2));
            assert_eq!(shared.aggregator.agent_last_seq(&sequence_scope), Some(2));
        });
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_scope_gates_do_not_serialize_distinct_scopes() {
        run_async_test(async {
            use std::future::Future as _;
            use std::task::Poll;

            let ingest_state = DistributedIngestState::new(
                frankenterm_core::wire_protocol::WireProtocolLimits::default(),
            );
            let first_scope = distributed_sender_session_scope(
                "session-independent-a",
                "agent-independent-a",
                frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
            );
            let second_scope = distributed_sender_session_scope(
                "session-independent-b",
                "agent-independent-b",
                frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
            );
            assert_ne!(first_scope, second_scope);

            let first_guard = distributed_lock_sequence_scope(&ingest_state, &first_scope).await;
            let mut second_acquire = Box::pin(distributed_lock_sequence_scope(
                &ingest_state,
                &second_scope,
            ));
            let second_guard = std::future::poll_fn(|cx| match second_acquire.as_mut().poll(cx) {
                Poll::Ready(guard) => Poll::Ready(guard),
                Poll::Pending => {
                    panic!("holding one sequence-scope gate serialized an unrelated scope")
                }
            })
            .await;

            drop(second_guard);
            drop(first_guard);
        });
    }

    #[cfg(feature = "distributed")]
    #[test]
    fn distributed_capacity_reject_does_not_poison_replay_retry() {
        run_async_test(async {
            let ingest_state = DistributedIngestState {
                shared: frankenterm_core::runtime_async::Mutex::new(DistributedIngestShared {
                    aggregator: frankenterm_core::wire_protocol::Aggregator::with_stale_after(1, 0),
                    replay_guard: frankenterm_core::distributed::SessionReplayGuard::new(8),
                    active_sequence_scopes: std::collections::HashMap::new(),
                    pane_seq_by_sender: std::collections::HashMap::new(),
                    sequence_scope_gates: std::collections::HashMap::new(),
                }),
            };
            let occupied_scope = "occupied.scope";
            let replay_id = distributed_replay_session_key("session-capacity", "agent-capacity");
            let session_scope = distributed_sender_session_scope(
                "session-capacity",
                "agent-capacity",
                frankenterm_core::wire_protocol::MAX_SENDER_ID_LEN,
            );

            {
                let mut shared = ingest_state.shared.lock().await;
                shared
                    .aggregator
                    .ingest_envelope(frankenterm_core::wire_protocol::WireEnvelope::new(
                        1,
                        occupied_scope,
                        frankenterm_core::wire_protocol::WirePayload::Gap(
                            frankenterm_core::wire_protocol::GapNotice {
                                pane_id: 1,
                                seq_before: 0,
                                seq_after: 1,
                                reason: "occupied".to_string(),
                                detected_at_ms: now_ms_i64(),
                            },
                        ),
                    ))
                    .expect("seed aggregator to capacity");
            }

            {
                let mut shared = ingest_state.shared.lock().await;
                shared
                    .replay_guard
                    .validate(&replay_id, 1)
                    .expect("first attempt should reserve replay state");
            }

            let admission = {
                let mut shared = ingest_state.shared.lock().await;
                distributed_admit_envelope(
                    &mut shared,
                    &replay_id,
                    &session_scope,
                    frankenterm_core::wire_protocol::WireEnvelope::new(
                        2,
                        &session_scope,
                        frankenterm_core::wire_protocol::WirePayload::Gap(
                            frankenterm_core::wire_protocol::GapNotice {
                                pane_id: 2,
                                seq_before: 0,
                                seq_after: 1,
                                reason: "capacity".to_string(),
                                detected_at_ms: now_ms_i64(),
                            },
                        ),
                    ),
                    false,
                )
            };

            let Ok(DistributedAdmission {
                previous_replay_seq,
                previous_agent_session,
                ingest_result,
            }) = admission
            else {
                panic!("capacity attempt should pass replay validation");
            };
            assert_eq!(previous_replay_seq, Some(1));
            assert!(previous_agent_session.is_none());
            assert!(matches!(
                ingest_result,
                Err(frankenterm_core::wire_protocol::WireProtocolError::TooManyAgents { .. })
            ));

            {
                let mut shared = ingest_state.shared.lock().await;
                assert_eq!(
                    shared.replay_guard.session_last_seq(&replay_id),
                    Some(1),
                    "capacity rejection must restore the exact prior replay frontier"
                );
                assert!(
                    !shared.active_sequence_scopes.contains_key(&session_scope),
                    "rejected admission must not publish an active sequence scope"
                );
                shared
                    .replay_guard
                    .validate(&replay_id, 2)
                    .expect("capacity rejection rollback should allow retrying the same seq");
            }
        });
    }

    async fn setup_storage(label: &str) -> (StorageHandle, String) {
        let temp_dir = std::env::temp_dir();
        let unique = now_ms();
        let db_path = temp_dir.join(format!(
            "wa_robot_approve_{label}_{}_{}.db",
            std::process::id(),
            unique
        ));
        let db_path_str = db_path.to_string_lossy().to_string();
        let storage = StorageHandle::new(&db_path_str).await.unwrap();
        (storage, db_path_str)
    }

    async fn cleanup_storage(storage: StorageHandle, db_path: &str) {
        let _ = storage.shutdown().await;
        let _ = std::fs::remove_file(db_path);
        let _ = std::fs::remove_file(format!("{db_path}-wal"));
        let _ = std::fs::remove_file(format!("{db_path}-shm"));
    }

    #[cfg(feature = "distributed")]
    fn insert_distributed_replay_test_segment(
        conn: &rusqlite::Connection,
        pane_id: u64,
        seq: u64,
        content: &str,
        captured_at: i64,
    ) -> frankenterm_core::storage::Segment {
        conn.execute(
            "INSERT INTO output_segments (pane_id, seq, content, content_len, content_hash, captured_at)
             VALUES (?1, ?2, ?3, ?4, NULL, ?5)",
            rusqlite::params![
                i64::try_from(pane_id).expect("test pane id should fit in i64"),
                i64::try_from(seq).expect("test seq should fit in i64"),
                content,
                i64::try_from(content.len()).expect("test content len should fit in i64"),
                captured_at,
            ],
        )
        .expect("insert replay test segment");

        frankenterm_core::storage::Segment {
            id: conn.last_insert_rowid(),
            pane_id,
            seq,
            content: content.to_string(),
            content_len: content.len(),
            content_hash: None,
            captured_at,
        }
    }

