    #[cfg(unix)]
    #[test]
    fn remote_setup_stages_release_tag_while_mux_is_live_without_replacing_active_triplet() {
        use std::os::unix::process::ExitStatusExt;
        use std::sync::Mutex;

        if build_meta::GIT_HASH == "unknown" || !build_meta::GIT_DIRTY.is_empty() {
            return;
        }

        let commands = Mutex::new(Vec::new());
        let runner = |_: &str, command: &str, _timeout: std::time::Duration| {
            commands.lock().unwrap().push(command.to_string());
            let stdout = if command.contains("FT_REMOTE_COMMAND_CHANNEL_V1") {
                "FT_REMOTE_COMMAND_CHANNEL_V1\n".to_string()
            } else if command.contains("systemctl --user is-active") {
                "active\n".to_string()
            } else if command.contains("FT_PREUPGRADE_DUMP=") {
                "FT_PREUPGRADE_DUMP=unavailable_legacy_client\n".to_string()
            } else if command.contains("command -v frankenterm-mux-server") {
                "/home/test/.local/bin/frankenterm-mux-server\n".to_string()
            } else if command.contains("FT_REMOTE_SERVICE_STATE_V1") {
                "FT_REMOTE_SERVICE_STATE_V1=missing\n".to_string()
            } else if command.contains("loginctl show-user") {
                "Linger=yes\n".to_string()
            } else if command.contains("FT_RELEASE_COMPONENT_RECEIPT_V2=") {
                format!(
                    "installer output\nFT_RELEASE_COMPONENT_RECEIPT_V2=v0.15.2:ft:101:{}:mux:202:{}:guardian:303:{}\n",
                    "b".repeat(64),
                    "c".repeat(64),
                    "e".repeat(64)
                )
            } else if command.contains("__publish-remote-generation") {
                format!(
                    "FT_REMOTE_GENERATION_PUBLICATION_V2={}:pending_activation_lease\n",
                    "d".repeat(64)
                )
            } else {
                String::new()
            };
            Ok(RemoteCommandOutput {
                status: std::process::ExitStatus::from_raw(0),
                stdout,
                stderr: String::new(),
                duration_ms: 1,
            })
        };
        let options = RemoteSetupOptions {
            apply: true,
            dry_run: false,
            yes: true,
            install_ft: true,
            ft_path: None,
            mux_server_path: None,
            guardian_path: None,
            ft_version: Some("v0.15.2"),
            transaction_id: Some("0123456789abcdef0123456789abcdef"),
            timeout_secs: 5,
            verbose: 0,
        };
        run_remote_setup_with_runner("example", &options, &runner)
            .expect("live mux should admit non-activating release staging");
        let commands = commands.lock().unwrap();
        let fence = commands
            .iter()
            .find(|command| command.contains("pgrep"))
            .expect("live mux process fence command");
        assert!(fence.contains("process_pattern="));
        assert!(fence.contains("[f]ranken''term-mux-server([^/[:space:]]*)"));
        assert!(
            !fence.contains("frankenterm-mux-server"),
            "the probe shell command must not contain the literal process name that pgrep searches for"
        );
        assert_eq!(
            commands
                .iter()
                .filter(|command| command.as_str() == REMOTE_MUX_OWNERSHIP_PROBE_COMMAND)
                .count(),
            2,
            "apply must fence mux ownership before mutation and recheck it before reporting"
        );
        let installer = commands
            .iter()
            .find(|command| command.contains("install-v0.15.2-"))
            .expect("pinned release installer command");
        let dump = commands
            .iter()
            .find(|command| command.contains("session verify-dump"))
            .expect("compatible pre-upgrade dump command");
        let dump_position = commands.iter().position(|command| command == dump).unwrap();
        let installer_position = commands
            .iter()
            .position(|command| command == installer)
            .unwrap();
        assert!(dump_position < installer_position);
        assert!(
            dump.contains("session verify-dump \"$dump\" --require-complete"),
            "pre-upgrade artifact admission must reject an intact partial dump"
        );
        assert!(installer.contains("$HOME/.cache/frankenterm/releases/v0.15.2-"));
        assert!(!installer.contains("--dest \"$HOME/.local/bin\""));
        let pending = commands
            .iter()
            .find(|command| command.contains("__publish-remote-generation"))
            .expect("immutable pending generation publication command");
        assert!(pending.contains("$HOME/.local/share/frankenterm/process-family"));
        assert!(pending.contains("--expected-ft-sha256"));
        assert!(pending.contains("--expected-mux-sha256"));
        assert!(pending.contains("--expected-guardian-sha256"));
        assert!(pending.contains("--transaction-id \"0123456789abcdef0123456789abcdef\""));
        assert!(!pending.contains("--activate-current"));
        assert!(pending.matches(&"b".repeat(64)).count() >= 2);
        assert!(pending.matches(&"c".repeat(64)).count() >= 2);
        assert!(pending.matches(&"e".repeat(64)).count() >= 2);
        assert!(!pending.contains("mv -n"));
        assert!(
            !commands
                .iter()
                .any(|command| command.contains("backup_candidate=\"$service.previous-"))
        );
        assert!(
            !commands
                .iter()
                .any(|command| command.contains("systemctl --user restart"))
        );
        assert!(
            !commands
                .iter()
                .any(|command| command.contains("systemctl --user enable --now"))
        );
        assert!(
            !commands
                .iter()
                .any(|command| command == "systemctl --user enable frankenterm-mux-server")
        );
    }

