    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn atomic_path_metadata_detects_same_inode_same_length_rewrite() {
        use std::io::{Seek as _, Write as _};
        use std::os::unix::fs::PermissionsExt as _;

        let fixture = tempfile::tempdir().expect("create metadata mutation fixture");
        std::fs::set_permissions(fixture.path(), std::fs::Permissions::from_mode(0o700))
            .expect("make mutation parent private");
        let path = fixture.path().join("member");
        std::fs::write(&path, b"same-length-content").expect("write mutation fixture");
        let mut writable = std::fs::OpenOptions::new()
            .write(true)
            .open(&path)
            .expect("pin owner file for planted rewrite");
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o400))
            .expect("seal mutation fixture");
        let parent = cap_std::fs::Dir::from_std_file(
            std::fs::File::open(fixture.path()).expect("open mutation parent"),
        );
        let before = AtomicPathObjectMetadata::from_cap_metadata(
            &parent
                .symlink_metadata("member")
                .expect("capture metadata before rewrite"),
        )
        .expect("normalize metadata before rewrite");
        writable
            .seek(std::io::SeekFrom::Start(0))
            .expect("seek mutation fixture");
        writable
            .write_all(b"same-length-content")
            .expect("rewrite same bytes at same length");
        writable.sync_all().expect("sync planted rewrite");
        let after = AtomicPathObjectMetadata::from_cap_metadata(
            &parent
                .symlink_metadata("member")
                .expect("capture metadata after rewrite"),
        )
        .expect("normalize metadata after rewrite");
        assert_eq!(before.device, after.device);
        assert_eq!(before.inode, after.inode);
        assert_eq!(before.byte_len, after.byte_len);
        assert!(
            before.modified_seconds != after.modified_seconds
                || before.modified_nanoseconds != after.modified_nanoseconds
                || before.changed_seconds != after.changed_seconds
                || before.changed_nanoseconds != after.changed_nanoseconds,
            "mtime/ctime fence must detect an in-place same-inode same-length rewrite"
        );
        assert_ne!(before, after);
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn atomic_path_exchange_serializes_same_transaction_callers() {
        use std::os::unix::fs::PermissionsExt as _;

        let fixture = tempfile::tempdir().expect("create concurrent exchange fixture");
        std::fs::set_permissions(fixture.path(), std::fs::Permissions::from_mode(0o700))
            .expect("make transition parent private");
        let stage = fixture.path().join("stage");
        let target = fixture.path().join("target");
        std::fs::write(&stage, b"new-generation").expect("write staged generation");
        std::fs::write(&target, b"old-generation").expect("write target generation");
        for path in [&stage, &target] {
            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o400))
                .expect("seal transition member");
        }
        let stage_id = inspect_atomic_path_content_id(fixture.path(), "stage")
            .expect("hash staged generation");
        let target_id = inspect_atomic_path_content_id(fixture.path(), "target")
            .expect("hash target generation");
        let barrier = Arc::new(std::sync::Barrier::new(3));
        let mut workers = Vec::new();
        for _ in 0..2 {
            let parent = fixture.path().to_path_buf();
            let stage_id = stage_id.clone();
            let target_id = target_id.clone();
            let barrier = Arc::clone(&barrier);
            workers.push(std::thread::spawn(move || {
                barrier.wait();
                run_atomic_path_transition(
                    &parent,
                    "stage",
                    "target",
                    "fedcba9876543210fedcba9876543210",
                    &stage_id,
                    &target_id,
                    AtomicPathTransitionOperation::Exchange,
                )
            }));
        }
        barrier.wait();
        let mut outcomes = workers
            .into_iter()
            .map(|worker| {
                worker
                    .join()
                    .expect("exchange worker did not panic")
                    .unwrap()
            })
            .collect::<Vec<_>>();
        outcomes.sort_by_key(|outcome| match outcome {
            AtomicPathTransitionOutcome::Applied => 0,
            AtomicPathTransitionOutcome::AlreadyApplied => 1,
        });
        assert_eq!(
            outcomes,
            vec![
                AtomicPathTransitionOutcome::Applied,
                AtomicPathTransitionOutcome::AlreadyApplied,
            ]
        );
        assert_eq!(std::fs::read(&target).unwrap(), b"new-generation");
        assert_eq!(std::fs::read(&stage).unwrap(), b"old-generation");
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn atomic_path_exchange_serializes_distinct_transactions_on_one_parent() {
        use std::os::unix::fs::PermissionsExt as _;

        let fixture = tempfile::tempdir().expect("create cross-transaction exchange fixture");
        std::fs::set_permissions(fixture.path(), std::fs::Permissions::from_mode(0o700))
            .expect("make transition parent private");
        let stage = fixture.path().join("stage");
        let target = fixture.path().join("target");
        std::fs::write(&stage, b"new-generation").expect("write staged generation");
        std::fs::write(&target, b"old-generation").expect("write target generation");
        for path in [&stage, &target] {
            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o400))
                .expect("seal transition member");
        }
        let stage_id = inspect_atomic_path_content_id(fixture.path(), "stage")
            .expect("hash staged generation");
        let target_id = inspect_atomic_path_content_id(fixture.path(), "target")
            .expect("hash target generation");
        let barrier = Arc::new(std::sync::Barrier::new(3));
        let mut workers = Vec::new();
        for transaction_id in [
            "11111111111111111111111111111111",
            "22222222222222222222222222222222",
        ] {
            let parent = fixture.path().to_path_buf();
            let stage_id = stage_id.clone();
            let target_id = target_id.clone();
            let barrier = Arc::clone(&barrier);
            workers.push(std::thread::spawn(move || {
                barrier.wait();
                run_atomic_path_transition(
                    &parent,
                    "stage",
                    "target",
                    transaction_id,
                    &stage_id,
                    &target_id,
                    AtomicPathTransitionOperation::Exchange,
                )
            }));
        }
        barrier.wait();
        let results = workers
            .into_iter()
            .map(|worker| worker.join().expect("exchange worker did not panic"))
            .collect::<Vec<_>>();
        assert_eq!(results.iter().filter(|result| result.is_ok()).count(), 1);
        assert_eq!(results.iter().filter(|result| result.is_err()).count(), 1);
        assert_eq!(std::fs::read(&target).unwrap(), b"new-generation");
        assert_eq!(std::fs::read(&stage).unwrap(), b"old-generation");
    }

