    #[cfg(unix)]
    fn parse_installer_process_family_receipt(stdout: &[u8]) -> serde_json::Value {
        let stdout = std::str::from_utf8(stdout).expect("installer receipt is UTF-8");
        let prefix = "FT_INSTALL_PROCESS_FAMILY_RECEIPT_V1=";
        let records = stdout
            .lines()
            .filter_map(|line| line.strip_prefix(prefix))
            .collect::<Vec<_>>();
        assert_eq!(records.len(), 1, "installer must emit one exact receipt");
        serde_json::from_str(records[0]).expect("installer receipt is canonical JSON")
    }

    #[cfg(unix)]
    fn parse_installer_app_receipt(stdout: &[u8]) -> serde_json::Value {
        let stdout = std::str::from_utf8(stdout).expect("installer app receipt is UTF-8");
        let prefix = "FT_INSTALL_APP_RECEIPT_V2=";
        let records = stdout
            .lines()
            .filter_map(|line| line.strip_prefix(prefix))
            .collect::<Vec<_>>();
        assert_eq!(
            records.len(),
            1,
            "installer must emit one exact app receipt"
        );
        serde_json::from_str(records[0]).expect("installer app receipt is canonical JSON")
    }

    #[cfg(unix)]
    fn activate_installer_test_generation(destination: &Path, family: &InstallerTestFamily) {
        use std::os::unix::fs::symlink;

        let managed = destination.join(".frankenterm-process-family");
        symlink(
            Path::new("generations").join(&family.generation_id),
            managed.join("current"),
        )
        .expect("plant managed test selector");
        for name in ["ft", "frankenterm-mux-server", "frankenterm-pty-guardian"] {
            symlink(
                Path::new(".frankenterm-process-family/current").join(name),
                destination.join(name),
            )
            .expect("plant managed test entrypoint");
        }
    }

    #[cfg(unix)]
    fn family_bytes_match(destination: &Path, family: &InstallerTestFamily) -> bool {
        ["ft", "frankenterm-mux-server", "frankenterm-pty-guardian"]
            .into_iter()
            .all(|name| {
                std::fs::read(destination.join(name)).ok()
                    == std::fs::read(family.root.join(name)).ok()
            })
    }

    #[cfg(unix)]
    fn assert_initial_family_is_uniformly_unavailable(destination: &Path) {
        for name in ["ft", "frankenterm-mux-server", "frankenterm-pty-guardian"] {
            let path = destination.join(name);
            if let Ok(metadata) = std::fs::symlink_metadata(&path) {
                assert!(metadata.file_type().is_symlink());
                assert!(!path.exists(), "first-install link must remain dangling");
            }
            assert!(
                std::process::Command::new(&path)
                    .arg("--version")
                    .status()
                    .is_err(),
                "partial first-install namespace unexpectedly executed {name}"
            );
        }
    }

    #[cfg(unix)]
    fn installer_residue_count(destination: &Path) -> usize {
        let mut count = 0;
        let mut pending = vec![(destination.to_path_buf(), 0usize)];
        while let Some((directory, depth)) = pending.pop() {
            if depth > 4 {
                continue;
            }
            let Ok(entries) = std::fs::read_dir(directory) else {
                continue;
            };
            for entry in entries.filter_map(Result::ok) {
                let name = entry.file_name();
                let name = name.to_string_lossy();
                if name.contains(".installing")
                    || name.starts_with(".ft-entrypoint-")
                    || name.starts_with(".current-")
                    || name.starts_with(".fixture-swap-")
                {
                    count += 1;
                }
                if entry.file_type().is_ok_and(|kind| kind.is_dir()) {
                    pending.push((entry.path(), depth + 1));
                }
            }
        }
        count
    }

    #[cfg(unix)]
    struct InstallerTestApp {
        app_root: std::path::PathBuf,
        archive: std::path::PathBuf,
        checksum: String,
        app_id: String,
        archive_budget: u64,
        expanded_budget: u64,
    }

    #[cfg(unix)]
    fn create_installer_test_app(root: &Path, build_id: &str, target: &str) -> InstallerTestApp {
        use sha2::Digest as _;
        use std::os::unix::fs::PermissionsExt as _;

        let repository = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let verifier_source = repository.join("scripts/atomic-component-manifest.sh");
        let source_revision = build_id
            .get(..40)
            .filter(|revision| {
                revision
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
            })
            .expect("app fixture identity seed must begin with 40 lowercase hex characters");
        let feature_contract =
            "application-family-gui-ft-mux-server-pty-guardian-default-features-v1";
        let derived = std::process::Command::new("bash")
            .arg(&verifier_source)
            .arg("derive-build-id")
            .arg("--source-revision")
            .arg(source_revision)
            .arg("--version")
            .arg("0.15.2")
            .arg("--target")
            .arg(target)
            .arg("--profile")
            .arg("release-interactive")
            .arg("--feature-contract")
            .arg(feature_contract)
            .output()
            .expect("derive app fixture build identity");
        assert!(
            derived.status.success(),
            "app fixture build identity derivation failed: {}",
            String::from_utf8_lossy(&derived.stderr)
        );
        let derived_build_id = String::from_utf8(derived.stdout)
            .expect("derived app fixture build identity must be UTF-8")
            .trim()
            .to_string();
        assert!(
            derived_build_id.len() == 64
                && derived_build_id
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f')),
            "derived app fixture build identity must be canonical SHA-256"
        );

        let app_root = root.join("FrankenTerm.app");
        let macos = app_root.join("Contents/MacOS");
        let resources = app_root.join("Contents/Resources");
        std::fs::create_dir_all(&macos).expect("create app executable directory");
        std::fs::create_dir_all(&resources).expect("create app resource directory");
        write_installer_atomic_helper_fixture(&macos.join("ft"), &derived_build_id, target);
        for (name, component) in [
            ("frankenterm-gui", "frankenterm-gui"),
            ("frankenterm-mux-server", "frankenterm-mux-server"),
            ("frankenterm-pty-guardian", "frankenterm-pty-guardian"),
        ] {
            let path = macos.join(name);
            write_atomic_component_fixture(&path, &derived_build_id, component, target);
            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o555))
                .expect("make app executable fixture runnable");
        }
        let verifier = resources.join("verify-components.sh");
        std::fs::copy(&verifier_source, &verifier).expect("copy app verifier fixture");
        std::fs::set_permissions(&verifier, std::fs::Permissions::from_mode(0o555))
            .expect("make app verifier executable");
        let readiness_harness = resources.join("e2e-native-events.sh");
        std::fs::write(
            &readiness_harness,
            br#"#!/bin/sh
set -eu
test "${FRANKENTERM_ALLOW_GUI_E2E:-}" = 1
test -x "${FRANKENTERM_GUI:?}"
test -x "${FRANKENTERM_CLI:?}"
test -x "${FRANKENTERM_MUX_SERVER:?}"
test -x "${FRANKENTERM_PTY_GUARDIAN:?}"
test -d "${FRANKENTERM_CANDIDATE_ROOT:?}"
test -f "${FRANKENTERM_COMPONENT_MANIFEST:?}"
test -n "${FRANKENTERM_CANDIDATE_SHA:?}"
test "${FRANKENTERM_BUILD_PROFILE:?}" = release-interactive
test -x "${FRANKENTERM_ATOMIC_MANIFEST_TOOL:?}"
test "${FT_INSTALL_TEST_READINESS_FAIL:-0}" != 1
"#,
        )
        .expect("write app readiness fixture");
        std::fs::set_permissions(&readiness_harness, std::fs::Permissions::from_mode(0o555))
            .expect("make app readiness fixture executable");
        let manifest = root.join("FrankenTerm.app.component-manifest.json");
        let generated = std::process::Command::new("bash")
            .arg(&verifier_source)
            .arg("generate")
            .arg("--root")
            .arg(&app_root)
            .arg("--source-root")
            .arg(&repository)
            .arg("--output")
            .arg(&manifest)
            .arg("--build-id")
            .arg(&derived_build_id)
            .arg("--source-revision")
            .arg(source_revision)
            .arg("--version")
            .arg("0.15.2")
            .arg("--target")
            .arg(target)
            .arg("--profile")
            .arg("release-interactive")
            .arg("--feature-contract")
            .arg(feature_contract)
            .arg("--entry")
            .arg("executable:gui:Contents/MacOS/frankenterm-gui:frankenterm-gui")
            .arg("--entry")
            .arg("executable:cli:Contents/MacOS/ft:ft")
            .arg("--entry")
            .arg("executable:mux-server:Contents/MacOS/frankenterm-mux-server:frankenterm-mux-server")
            .arg("--entry")
            .arg("executable:pty-guardian:Contents/MacOS/frankenterm-pty-guardian:frankenterm-pty-guardian")
            .arg("--entry")
            .arg("verifier:offline-verifier:Contents/Resources/verify-components.sh")
            .arg("--entry")
            .arg("verifier:native-readiness-harness:Contents/Resources/e2e-native-events.sh")
            .arg("--source-match")
            .arg("Contents/Resources/verify-components.sh=scripts/atomic-component-manifest.sh")
            .output()
            .expect("execute app manifest generator");
        assert!(
            generated.status.success(),
            "app manifest generation failed: {}",
            String::from_utf8_lossy(&generated.stderr)
        );
        let manifest_value: serde_json::Value =
            serde_json::from_slice(&std::fs::read(&manifest).expect("read generated app manifest"))
                .expect("parse generated app manifest");
        let app_id = manifest_value["manifest_id"]
            .as_str()
            .and_then(|value| value.strip_prefix("sha256:"))
            .filter(|value| value.len() == 64)
            .expect("generated app manifest ID")
            .to_string();
        let inventory_bytes = manifest_value["inventory"]["total_bytes"]
            .as_u64()
            .expect("generated app manifest byte inventory");
        let archive = root.join("FrankenTerm-darwin-arm64.app.tar.xz");
        let archived = std::process::Command::new("tar")
            .env("COPYFILE_DISABLE", "1")
            .arg("-cJf")
            .arg(&archive)
            .arg("-C")
            .arg(root)
            .arg("FrankenTerm.app")
            .arg("FrankenTerm.app.component-manifest.json")
            .output()
            .expect("create installer app archive");
        assert!(
            archived.status.success(),
            "app archive creation failed: {}",
            String::from_utf8_lossy(&archived.stderr)
        );
        let checksum = hex::encode(sha2::Sha256::digest(
            std::fs::read(&archive).expect("read app archive for checksum"),
        ));
        let safety_margin = 1024 * 1024;
        let archive_budget = std::fs::metadata(&archive)
            .expect("read app archive metadata")
            .len()
            .checked_add(safety_margin)
            .expect("bounded app archive fixture budget");
        let expanded_budget = inventory_bytes
            .checked_add(
                std::fs::metadata(&manifest)
                    .expect("read detached app manifest metadata")
                    .len(),
            )
            .and_then(|bytes| bytes.checked_add(safety_margin))
            .expect("bounded expanded app fixture budget");
        InstallerTestApp {
            app_root,
            archive,
            checksum,
            app_id,
            archive_budget,
            expanded_budget,
        }
    }

    #[cfg(unix)]
    fn write_installer_fake_download_tools(directory: &Path) {
        use std::os::unix::fs::PermissionsExt as _;

        std::fs::create_dir_all(directory).expect("create fake app download tool directory");
        let curl = directory.join("curl");
        std::fs::write(
            &curl,
            r#"#!/bin/sh
set -eu
if test "${1:-}" = --help; then
  printf '%s\n' '     --max-filesize <bytes>  Maximum file size to download'
  exit 0
fi
output=""
url=""
while test "$#" -gt 0; do
  case "$1" in
    -o) shift; output=$1 ;;
    http://*|https://*) url=$1 ;;
  esac
  shift
done
case "$url" in
  *.sha256) printf '%s  FrankenTerm-darwin-arm64.app.tar.xz\n' "$FAKE_APP_CHECKSUM" ;;
  *) cat "$FAKE_APP_ARCHIVE" ;;
esac
"#,
        )
        .expect("write fake app curl");
        std::fs::set_permissions(&curl, std::fs::Permissions::from_mode(0o555))
            .expect("make fake app curl executable");
        let codesign = directory.join("codesign");
        std::fs::write(
            &codesign,
            br#"#!/bin/sh
set -eu
state=${FAKE_CODESIGN_STATE:?}
count=0
if test -f "$state"; then
  count=$(cat "$state")
fi
count=$((count + 1))
printf '%s\n' "$count" >"$state"
fail_after=${FAKE_CODESIGN_FAIL_AFTER:-0}
if test "$fail_after" -gt 0 && test "$count" -gt "$fail_after"; then
  exit 1
fi
exit 0
"#,
        )
        .expect("write fake codesign");
        std::fs::set_permissions(&codesign, std::fs::Permissions::from_mode(0o555))
            .expect("make fake codesign executable");
    }

    #[cfg(unix)]
    #[allow(clippy::too_many_arguments)]
    fn run_installer_app_function(
        installer: &Path,
        family: &InstallerTestFamily,
        destination: &Path,
        app: &InstallerTestApp,
        app_destination: &Path,
        scratch: &Path,
        fake_tools: &Path,
        failpoint: Option<&str>,
        tree_fail_after_files: Option<usize>,
        readiness_failure: bool,
        codesign_fail_after: Option<u64>,
    ) -> std::process::Output {
        run_installer_app_function_with_selector_policy(
            installer,
            family,
            destination,
            app,
            app_destination,
            scratch,
            fake_tools,
            failpoint,
            tree_fail_after_files,
            readiness_failure,
            codesign_fail_after,
            true,
        )
    }

    #[cfg(unix)]
    #[allow(clippy::too_many_arguments)]
    fn run_installer_app_function_with_selector_policy(
        installer: &Path,
        family: &InstallerTestFamily,
        destination: &Path,
        app: &InstallerTestApp,
        app_destination: &Path,
        scratch: &Path,
        fake_tools: &Path,
        failpoint: Option<&str>,
        tree_fail_after_files: Option<usize>,
        readiness_failure: bool,
        codesign_fail_after: Option<u64>,
        allow_selector: bool,
    ) -> std::process::Output {
        std::fs::create_dir_all(scratch).expect("create app installer shell scratch");
        let selected_manifest = destination
            .join(".frankenterm-process-family/generations")
            .join(&family.generation_id)
            .join("process-family.component-manifest.json");
        let inherited_path = std::env::var("PATH").expect("test PATH");
        let test_path = format!("{}:{inherited_path}", fake_tools.display());
        let failpoint = failpoint.unwrap_or("");
        let selector_setup = if allow_selector {
            format!(
                "ACTIVATE_IF_IDLE=1\nPROCESS_FAMILY_ACTIVATION_STATE=current\nPROCESS_FAMILY_ACTIVE_AUTHORITY=managed-selector\nPROCESS_FAMILY_ACTIVE_ROOT={}\nPENDING_PROCESS_FAMILY_GENERATION=\n",
                shell_single_quote(
                    &destination
                        .join(".frankenterm-process-family/generations")
                        .join(&family.generation_id)
                        .to_string_lossy()
                )
            )
        } else {
            "ACTIVATE_IF_IDLE=0\n".to_string()
        };
        let script = format!(
            "set -euo pipefail\nexport FT_INSTALL_TEST_LIBRARY_ONLY=1\nsource {}\nDEST={}\nTMP={}\nQUIET=1\nHAS_GUM=0\n{}VERSION=v0.15.2\nOWNER=fixture\nREPO=fixture\nAPP_ASSET=FrankenTerm-darwin-arm64.app.tar.xz\nAPP_DEST={}\nNO_MINISIGN=1\nMAX_APP_ARCHIVE_BYTES={}\nMAX_APP_EXPANDED_BYTES={}\nACTIVE_PROCESS_FAMILY_MANIFEST={}\nACTIVE_PROCESS_FAMILY_VERIFIER={}\nACTIVE_ATOMIC_TRANSITION_HELPER={}\nPUBLISHED_PROCESS_FAMILY_ROOT={}\nPUBLISHED_PROCESS_FAMILY_VERSION=0.15.2\nPUBLISHED_PROCESS_FAMILY_VERIFIER_AUTHORITY={}\nAPP_RECEIPT_REQUESTED=true\nAPP_RECEIPT_RESULT=in_progress\nAPP_RECEIPT_REASON=selected\nexport FT_INSTALL_TEST_ENABLE_FAILPOINTS={}\nexport FT_INSTALL_TEST_FAILPOINT={}\nexport FT_INSTALL_TEST_STAGE_FAIL_AFTER_FILES={}\ninstall_macos_app\nfinalize_app_receipt_state\nemit_app_receipt\n",
            shell_single_quote(&installer.to_string_lossy()),
            shell_single_quote(&destination.to_string_lossy()),
            shell_single_quote(&scratch.to_string_lossy()),
            selector_setup,
            shell_single_quote(&app_destination.to_string_lossy()),
            app.archive_budget,
            app.expanded_budget,
            shell_single_quote(&selected_manifest.to_string_lossy()),
            shell_single_quote(&family.verifier.to_string_lossy()),
            shell_single_quote(
                &destination
                    .join(".frankenterm-process-family/generations")
                    .join(&family.generation_id)
                    .join("ft")
                    .to_string_lossy()
            ),
            shell_single_quote(
                &destination
                    .join(".frankenterm-process-family/generations")
                    .join(&family.generation_id)
                    .to_string_lossy()
            ),
            shell_single_quote(&family.verifier.to_string_lossy()),
            if failpoint.is_empty() && tree_fail_after_files.is_none() {
                "0"
            } else {
                "1"
            },
            shell_single_quote(failpoint),
            tree_fail_after_files.unwrap_or(0),
        );
        let mut command = std::process::Command::new("bash");
        command
            .arg("-c")
            .arg(script)
            .env("PATH", test_path)
            .env("COPYFILE_DISABLE", "1")
            .env("FAKE_APP_ARCHIVE", &app.archive)
            .env("FAKE_APP_CHECKSUM", &app.checksum)
            .env(
                "FT_INSTALL_TEST_READINESS_FAIL",
                if readiness_failure { "1" } else { "0" },
            )
            .env("FAKE_CODESIGN_STATE", scratch.join("codesign-state"))
            .env(
                "FAKE_CODESIGN_FAIL_AFTER",
                codesign_fail_after.unwrap_or(0).to_string(),
            );
        if allow_selector {
            command
                .env("FT_INSTALL_TEST_ALLOW_APP_SELECTOR", "1")
                .env("FT_INSTALL_TEST_MUX_OWNERSHIP_STATE", "inactive");
        } else {
            command
                .env_remove("FT_INSTALL_TEST_ALLOW_APP_SELECTOR")
                .env_remove("FT_INSTALL_TEST_MUX_OWNERSHIP_STATE");
        }
        command
            .output()
            .expect("execute production installer app function")
    }

    #[cfg(unix)]
    fn create_adversarial_installer_archive(path: &Path, case_name: &str) {
        let program = r#"
import io
import sys
import tarfile

path, case_name = sys.argv[1:]

def add_directory(archive, name):
    member = tarfile.TarInfo(name)
    member.type = tarfile.DIRTYPE
    member.mode = 0o755
    archive.addfile(member)

def add_file(archive, name, payload=b"x"):
    member = tarfile.TarInfo(name)
    member.mode = 0o644
    member.size = len(payload)
    archive.addfile(member, io.BytesIO(payload))

with tarfile.open(path, "w") as archive:
    if case_name == "traversal":
        add_file(archive, "../escaped")
    elif case_name == "appledouble":
        add_directory(archive, "FrankenTerm.app")
        add_file(archive, "FrankenTerm.app/Contents/._Info.plist")
        add_file(archive, "FrankenTerm.app.component-manifest.json", b"{}")
    elif case_name == "symlink-ancestor":
        add_directory(archive, "FrankenTerm.app")
        member = tarfile.TarInfo("FrankenTerm.app/Contents")
        member.type = tarfile.SYMTYPE
        member.linkname = "."
        archive.addfile(member)
        add_file(archive, "FrankenTerm.app/Contents/payload")
        add_file(archive, "FrankenTerm.app.component-manifest.json", b"{}")
    elif case_name == "hardlink":
        add_directory(archive, "FrankenTerm.app")
        add_file(archive, "FrankenTerm.app/original")
        member = tarfile.TarInfo("FrankenTerm.app/hardlink")
        member.type = tarfile.LNKTYPE
        member.linkname = "FrankenTerm.app/original"
        archive.addfile(member)
        add_file(archive, "FrankenTerm.app.component-manifest.json", b"{}")
    elif case_name == "duplicate":
        add_directory(archive, "FrankenTerm.app")
        add_file(archive, "FrankenTerm.app/duplicate", b"first")
        add_file(archive, "FrankenTerm.app/duplicate", b"second")
        add_file(archive, "FrankenTerm.app.component-manifest.json", b"{}")
    elif case_name == "absolute-symlink":
        add_directory(archive, "FrankenTerm.app")
        member = tarfile.TarInfo("FrankenTerm.app/escape")
        member.type = tarfile.SYMTYPE
        member.linkname = "/tmp"
        archive.addfile(member)
        add_file(archive, "FrankenTerm.app.component-manifest.json", b"{}")
    elif case_name == "app-valid":
        add_directory(archive, "FrankenTerm.app")
        add_file(archive, "FrankenTerm.app/Contents.txt", b"authenticated app payload")
        add_file(archive, "FrankenTerm.app.component-manifest.json", b"{}")
    elif case_name == "oversized-pax":
        member = tarfile.TarInfo("pax-extension")
        member.type = tarfile.XHDTYPE
        member.size = 1024 * 1024 + 1
        archive.addfile(member, io.BytesIO(b"x" * member.size))
    elif case_name == "oversized-gnu-longname":
        member = tarfile.TarInfo("gnu-long-name-extension")
        member.type = tarfile.GNUTYPE_LONGNAME
        member.size = 1024 * 1024 + 1
        archive.addfile(member, io.BytesIO(b"x" * member.size))
    elif case_name in ("font-valid", "font-valid-replacement"):
        for name in (
            "pragmasevka-nf-regular.ttf",
            "pragmasevka-nf-bold.ttf",
            "pragmasevka-nf-italic.ttf",
            "pragmasevka-nf-bolditalic.ttf",
        ):
            suffix = "replacement" if case_name == "font-valid-replacement" else "authenticated"
            add_file(archive, name, (name + ":" + suffix + "\n").encode("ascii"))
    elif case_name == "font-traversal":
        add_file(archive, "../pragmasevka-nf-regular.ttf")
    elif case_name == "font-symlink":
        member = tarfile.TarInfo("pragmasevka-nf-regular.ttf")
        member.type = tarfile.SYMTYPE
        member.linkname = "/tmp/font"
        archive.addfile(member)
    elif case_name == "font-unexpected":
        add_file(archive, "unexpected-font.ttf")
    elif case_name == "many-app-entries":
        add_directory(archive, "FrankenTerm.app")
        for index in range(2048):
            add_file(archive, "FrankenTerm.app/member-%04d-%s" % (index, "x" * 48))
        add_file(archive, "FrankenTerm.app.component-manifest.json", b"{}")
    else:
        raise SystemExit("unknown adversarial archive case")
"#;
        let output = std::process::Command::new("python3")
            .arg("-c")
            .arg(program)
            .arg(path)
            .arg(case_name)
            .output()
            .expect("create adversarial installer archive");
        assert!(
            output.status.success(),
            "failed to create {case_name} archive: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[cfg(unix)]
    fn create_zstd_adversarial_installer_archive(path: &Path, case_name: &str) {
        let source_tar = path.with_extension("source.tar");
        create_adversarial_installer_archive(&source_tar, case_name);
        let zstd = installer_test_command_path("zstd").expect("real zstd test dependency");
        let output = std::process::Command::new(zstd)
            .arg("-q")
            .arg("-f")
            .arg("-o")
            .arg(path)
            .arg(&source_tar)
            .output()
            .expect("compress adversarial installer archive with zstd");
        assert!(
            output.status.success(),
            "failed to zstd-compress {case_name} archive: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[cfg(unix)]
    fn create_xz_memory_declaration_installer_archive(path: &Path) {
        let program = r#"
import binascii
import io
import lzma
import struct
import sys
import tarfile

path = sys.argv[1]
payload = io.BytesIO()
with tarfile.open(fileobj=payload, mode="w") as archive:
    root = tarfile.TarInfo("FrankenTerm.app")
    root.type = tarfile.DIRTYPE
    root.mode = 0o755
    archive.addfile(root)
    manifest = tarfile.TarInfo("FrankenTerm.app.component-manifest.json")
    manifest.mode = 0o644
    manifest.size = 2
    archive.addfile(manifest, io.BytesIO(b"{}"))

compressed = bytearray(lzma.compress(
    payload.getvalue(),
    format=lzma.FORMAT_XZ,
    filters=[{"id": lzma.FILTER_LZMA2, "dict_size": 1024 * 1024}],
))
if compressed[12:16] != b"\x02\x00\x21\x01":
    raise SystemExit("unexpected single-filter xz block header")
# LZMA2 property 30 declares a 128 MiB dictionary. The payload was encoded
# with a 1 MiB dictionary, so changing only the declaration and its block-
# header CRC yields a small valid stream that must hit the production 64 MiB
# decoder limit without allocating 128 MiB in the test producer.
compressed[16] = 30
compressed[17:21] = struct.pack("<I", binascii.crc32(compressed[12:17]) & 0xffffffff)
with open(path, "wb") as output:
    output.write(compressed)
"#;
        let output = std::process::Command::new("python3")
            .arg("-c")
            .arg(program)
            .arg(path)
            .output()
            .expect("create xz memory-declaration archive");
        assert!(
            output.status.success(),
            "failed to create xz memory-declaration archive: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[cfg(all(unix, target_os = "macos"))]
    fn create_valid_process_family_xz_archive(path: &Path, manifest_name: &str) {
        let program = r#"
import io
import sys
import tarfile

path, manifest_name = sys.argv[1:]
with tarfile.open(path, "w:xz") as archive:
    for name in (
        "ft",
        "frankenterm-mux-server",
        "frankenterm-pty-guardian",
        "verify-components.sh",
        manifest_name,
    ):
        payload = (name + "\n").encode("ascii")
        member = tarfile.TarInfo(name)
        member.mode = 0o755 if name != manifest_name else 0o644
        member.size = len(payload)
        archive.addfile(member, io.BytesIO(payload))
"#;
        let output = std::process::Command::new("python3")
            .arg("-c")
            .arg(program)
            .arg(path)
            .arg(manifest_name)
            .output()
            .expect("create valid process-family xz archive");
        assert!(
            output.status.success(),
            "failed to create valid process-family xz archive: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[cfg(all(unix, target_os = "macos"))]
    fn run_authenticated_process_family_extractor(
        installer: &Path,
        archive: &Path,
        extraction_root: &Path,
        manifest_name: &str,
    ) -> std::process::Output {
        use sha2::Digest as _;

        let checksum = hex::encode(sha2::Sha256::digest(
            std::fs::read(archive).expect("read process-family archive"),
        ));
        let script = format!(
            "set -euo pipefail\nexport FT_INSTALL_TEST_LIBRARY_ONLY=1\nsource {}\nQUIET=1\nHAS_GUM=0\nverify_checksum {} {}\nextract_authenticated_archive {} {} process-family {} \"$VERIFIED_ARCHIVE_IDENTITY\"\n",
            shell_single_quote(&installer.to_string_lossy()),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&checksum),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&extraction_root.to_string_lossy()),
            shell_single_quote(manifest_name),
        );
        std::process::Command::new("bash")
            .arg("-c")
            .arg(script)
            .output()
            .expect("execute production process-family extractor")
    }

    #[cfg(unix)]
    fn run_authenticated_installer_extractor(
        installer: &Path,
        archive: &Path,
        extraction_root: &Path,
    ) -> std::process::Output {
        run_authenticated_installer_extractor_with_metadata_bound(
            installer,
            archive,
            extraction_root,
            None,
        )
    }

    #[cfg(unix)]
    fn run_authenticated_installer_extractor_with_metadata_bound(
        installer: &Path,
        archive: &Path,
        extraction_root: &Path,
        retained_metadata_bytes: Option<usize>,
    ) -> std::process::Output {
        use sha2::Digest as _;

        let checksum = hex::encode(sha2::Sha256::digest(
            std::fs::read(archive).expect("read adversarial archive"),
        ));
        let script = format!(
            "set -euo pipefail\nexport FT_INSTALL_TEST_LIBRARY_ONLY=1\nsource {}\nQUIET=1\nHAS_GUM=0\nverify_checksum {} {}\nextract_authenticated_archive {} {} app FrankenTerm.app.component-manifest.json \"$VERIFIED_ARCHIVE_IDENTITY\"\n",
            shell_single_quote(&installer.to_string_lossy()),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&checksum),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&extraction_root.to_string_lossy()),
        );
        let mut command = std::process::Command::new("bash");
        command.arg("-c").arg(script);
        if let Some(limit) = retained_metadata_bytes {
            command
                .env("FT_INSTALL_TEST_ENABLE_RESOURCE_OVERRIDES", "1")
                .env(
                    "FT_INSTALL_TEST_MAX_RETAINED_METADATA_BYTES",
                    limit.to_string(),
                );
        }
        command
            .output()
            .expect("execute production authenticated extractor")
    }

    #[cfg(unix)]
    fn write_installer_fake_descriptor_zstd(path: &Path) {
        use std::os::unix::fs::PermissionsExt as _;

        std::fs::write(
            path,
            r#"#!/bin/sh
set -eu
input=""
for argument in "$@"; do
  input=$argument
done
test "$input" = -
if test -n "${ATTACK_FONT_ARCHIVE:-}" && test ! -e "$ATTACK_MARKER"; then
  mv "$ATTACK_FONT_ARCHIVE" "$RETAINED_FONT_ARCHIVE"
  cp "$REPLACEMENT_FONT_ARCHIVE" "$ATTACK_FONT_ARCHIVE"
  printf x > "$ATTACK_MARKER"
fi
exec "$REAL_ZSTD" "$@"
"#,
        )
        .expect("write descriptor-fed fake zstd");
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o555))
            .expect("make descriptor-fed fake zstd executable");
    }

    #[cfg(unix)]
    fn run_authenticated_font_extractor(
        installer: &Path,
        archive: &Path,
        extraction_root: &Path,
        fake_tools: &Path,
        replacement: Option<(&Path, &Path, &Path)>,
    ) -> std::process::Output {
        use sha2::Digest as _;

        let checksum = hex::encode(sha2::Sha256::digest(
            std::fs::read(archive).expect("read authenticated font archive"),
        ));
        let script = format!(
            "set -euo pipefail\nexport FT_INSTALL_TEST_LIBRARY_ONLY=1\nsource {}\nQUIET=1\nHAS_GUM=0\nverify_checksum {} {}\nextract_authenticated_archive {} {} font - \"$VERIFIED_ARCHIVE_IDENTITY\"\n",
            shell_single_quote(&installer.to_string_lossy()),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&checksum),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&extraction_root.to_string_lossy()),
        );
        let inherited_path = std::env::var("PATH").expect("test PATH");
        let real_zstd = installer_test_command_path("zstd").expect("real zstd test dependency");
        let mut command = std::process::Command::new("bash");
        command
            .arg("-c")
            .arg(script)
            .env("PATH", format!("{}:{inherited_path}", fake_tools.display()))
            .env("REAL_ZSTD", real_zstd);
        if let Some((replacement_archive, retained_archive, marker)) = replacement {
            command
                .env("ATTACK_FONT_ARCHIVE", archive)
                .env("REPLACEMENT_FONT_ARCHIVE", replacement_archive)
                .env("RETAINED_FONT_ARCHIVE", retained_archive)
                .env("ATTACK_MARKER", marker);
        }
        command
            .output()
            .expect("execute production authenticated font extractor")
    }

