    #[cfg(unix)]
    #[allow(clippy::too_many_arguments)]
    fn run_installer_font_function(
        installer: &Path,
        published_family: &Path,
        verifier: &Path,
        font_archive: &Path,
        data_root: &Path,
        scratch: &Path,
        fake_tools: &Path,
        failpoint: Option<&str>,
        mutate_stage: bool,
    ) -> std::process::Output {
        std::fs::create_dir_all(scratch).expect("create font installer scratch");
        std::fs::create_dir_all(data_root).expect("create font installer data root");
        let archive_budget = std::fs::metadata(font_archive)
            .expect("read font archive metadata")
            .len()
            .checked_add(1024 * 1024)
            .expect("bounded font archive test budget");
        let failpoint = failpoint.unwrap_or("");
        let script = format!(
            "set -euo pipefail\nexport FT_INSTALL_TEST_LIBRARY_ONLY=1\nsource {}\nTMP={}\nQUIET=1\nHAS_GUM=0\nOS=linux\nVERSION=v0.15.2\nOWNER=fixture\nREPO=fixture\nXDG_DATA_HOME={}\nOFFLINE_TARBALL=\nPUBLISHED_PROCESS_FAMILY_ROOT={}\nPUBLISHED_PROCESS_FAMILY_VERSION=0.15.2\nPUBLISHED_PROCESS_FAMILY_VERIFIER_AUTHORITY={}\nMAX_FONT_ARCHIVE_BYTES={}\nMAX_FONT_EXPANDED_BYTES=268435456\nINSTALLER_FREE_SPACE_HEADROOM_BYTES=0\nexport FT_INSTALL_TEST_ENABLE_FAILPOINTS={}\nexport FT_INSTALL_TEST_FAILPOINT={}\nexport FT_INSTALL_TEST_MUTATE_FONT_STAGE={}\ninstall_pragmasevka\nprintf 'FONT_RESULT=%s\\n' \"$FONT_INSTALLED_PATH\"\n",
            shell_single_quote(&installer.to_string_lossy()),
            shell_single_quote(&scratch.to_string_lossy()),
            shell_single_quote(&data_root.to_string_lossy()),
            shell_single_quote(&published_family.to_string_lossy()),
            shell_single_quote(&verifier.to_string_lossy()),
            archive_budget,
            if failpoint.is_empty() && !mutate_stage {
                "0"
            } else {
                "1"
            },
            shell_single_quote(failpoint),
            if mutate_stage { "1" } else { "0" },
        );
        let inherited_path = std::env::var("PATH").expect("test PATH");
        std::process::Command::new("bash")
            .arg("-c")
            .arg(script)
            .env("PATH", format!("{}:{inherited_path}", fake_tools.display()))
            .env("FAKE_FONT_ARCHIVE", font_archive)
            .output()
            .expect("execute production font installer function")
    }

    #[cfg(unix)]
    fn plant_installer_old_font_tree(data_root: &Path, marker: &[u8]) -> std::path::PathBuf {
        use std::os::unix::fs::PermissionsExt as _;

        let font_parent = data_root.join("fonts");
        let target = font_parent.join("pragmasevka");
        std::fs::create_dir_all(&target).expect("create prior font tree");
        std::fs::set_permissions(&font_parent, std::fs::Permissions::from_mode(0o700))
            .expect("make prior font parent private");
        for name in [
            "pragmasevka-nf-regular.ttf",
            "pragmasevka-nf-bold.ttf",
            "pragmasevka-nf-italic.ttf",
            "pragmasevka-nf-bolditalic.ttf",
        ] {
            let path = target.join(name);
            std::fs::write(&path, [marker, name.as_bytes()].concat())
                .expect("write prior font fixture");
            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o444))
                .expect("seal prior font fixture");
        }
        std::fs::set_permissions(&target, std::fs::Permissions::from_mode(0o555))
            .expect("seal prior font tree");
        target
    }

    #[test]
    fn top_level_installer_seals_and_publishes_one_exact_triplet_generation() {
        let installer = include_str!("../../../install.sh");
        let active_start = installer
            .find("install_process_family() {")
            .expect("atomic process-family installer");
        // The function ends at its own column-0 closing brace. Anchoring on the
        // next function's name broke once the activation transaction helpers
        // were inserted between the two (they legitimately publish entrypoints;
        // the atomic installer itself must not).
        let active_end = installer[active_start..]
            .find("\n}\n")
            .map(|offset| active_start + offset)
            .expect("atomic process-family installer end");
        let active = &installer[active_start..active_end];
        let ft_probe = active.find("\"$stage/ft\" --version").expect("ft probe");
        let mux_probe = active
            .find("\"$stage/frankenterm-mux-server\" --version")
            .expect("mux probe");
        let guardian_probe = active
            .find("\"$stage/frankenterm-pty-guardian\" --version")
            .expect("guardian probe");
        let seal = active.find("chmod 0555 \"$stage\"").expect("stage seal");
        let publish = active
            .find("$stage_id\" missing publish-noreplace")
            .expect("atomic generation publish");
        assert!(ft_probe < seal && mux_probe < seal && guardian_probe < seal);
        assert!(seal < publish);
        assert!(active.contains("stage_name=\".generation-${generation_id}.installing\""));
        assert!(!active.contains("stage_name=\".generation-${generation_id}.installing-$$\""));
        assert!(active.contains("validate_installer_stage_inventory \"$stage\" generation"));
        let inactive_mux_census = active
            .find("require_no_live_mux_for_initial_selector")
            .expect("fail-closed initial-selector mux census");
        let pending_boundary = active
            .find("installer_failpoint before-pending-publication-receipt")
            .expect("pending-candidate receipt boundary");
        let pending_receipt = active
            .find("PENDING_PROCESS_FAMILY_GENERATION=\"$generation_id\"")
            .expect("pending-candidate receipt");
        assert!(inactive_mux_census < pending_boundary && pending_boundary < pending_receipt);
        assert!(active.contains(
            "Activation is pending; the existing process-family selector and live mux were left unchanged"
        ));
        assert!(active.contains("Only the future cross-launcher activation transaction may"));
        assert!(active.contains("installer_failpoint after-legacy-recovery-publish"));
        assert!(!active.contains("publish_stable_entrypoint"));
        assert!(!active.contains("before-initial-selector"));
        assert!(!active.contains("after-initial-selector"));
        assert!(!active.contains("before-selector-switch"));
        assert!(!active.contains("after-selector-switch"));
        assert!(!active.contains(" exchange"));
        assert!(active.contains("[ ! -e \"$DEST/$name\" ] || return 1"));
        assert!(active.contains(
            "verify_canonical_generation \"$generation\" \"$version\" \"$verifier_source\""
        ));
        assert!(active.contains(
            "All previous generations and entrypoint authority were retained for recovery"
        ));

        let census_start = installer
            .find("require_no_live_mux_for_initial_selector() {")
            .expect("initial-selector census gate");
        let census_end = installer[census_start..]
            .find("\n}\n\nensure_staged_symlink()")
            .map(|offset| census_start + offset)
            .expect("initial-selector census gate end");
        let census = &installer[census_start..census_end];
        assert!(census.contains("inactive-census-without-shared-launcher-lease"));
        assert!(census.contains("A process census is evidence, not an exclusion primitive"));
        assert!(census.trim_end().ends_with("return 1"));

        assert!(installer.contains("fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)"));
        assert!(installer.contains("The permanent lock inode is never unlinked"));
        assert!(!installer.contains("if mkdir \"$LOCK_DIR\""));
        let lock_acquired = installer
            .find("LOCKED=1")
            .expect("kernel installer lock acquisition");
        let installed_version_check = installer
            .find("&& check_installed_version \"$VERSION\"")
            .expect("installed-version refresh boundary");
        assert!(lock_acquired < installed_version_check);
        let activation_dispatch = installer
            .rfind("activate_process_family_generation \"$ACTIVATE_GENERATION\"")
            .expect("top-level activation dispatch");
        assert!(
            lock_acquired < activation_dispatch && activation_dispatch < installed_version_check,
            "activation must enter the permanent installer lock before any selector mutation"
        );
        let activation_start = installer
            .find("activate_process_family_generation() {")
            .expect("idle-host activation function");
        let activation_end = installer[activation_start..]
            .find("\n}\n\nactivate_published_generation_if_idle()")
            .map(|offset| activation_start + offset)
            .expect("idle-host activation function end");
        let activation = &installer[activation_start..activation_end];
        let last_entrypoint = activation
            .find("after-entrypoint-activation:$name")
            .expect("entrypoint activation boundary");
        let selector_commit = activation
            .find("installer_failpoint before-selector-activation")
            .expect("single selector commit boundary");
        assert!(last_entrypoint < selector_commit);
        assert!(activation.contains("installer_failpoint after-selector-rollback"));
        assert!(activation.contains("installer_failpoint \"after-entrypoint-rollback:$name\""));
        assert!(activation.contains("installer_failpoint after-legacy-selector-rollback"));
        assert!(installer.contains("\"frankenterm-pty-guardian\","));
        assert!(installer.contains("\"ft\","));
        assert!(
            activation
                .contains("for name in ft frankenterm-mux-server frankenterm-pty-guardian; do")
        );
        // The per-entrypoint `--version` probe moved into
        // probe_activated_process_family(); activation must still run it after
        // the selector commit, and it must still probe every stable link.
        assert!(activation.contains("! probe_activated_process_family; then"));
        let probe_start = installer
            .find("probe_activated_process_family() {")
            .expect("activated process-family probe helper");
        let probe_end = installer[probe_start..]
            .find("\n}\n\nactivate_process_family_generation()")
            .map(|offset| probe_start + offset)
            .expect("activated process-family probe helper end");
        let probe = &installer[probe_start..probe_end];
        assert!(probe.contains("timeout_seconds = 10.0"));
        assert!(probe.contains("start_new_session=True"));
        assert!(probe.contains("os.killpg(process.pid, signal.SIGKILL)"));
        assert!(probe.contains("run_bounded([executable, \"--version\"])"));
        assert!(probe.contains("run_bounded([ft, \"doctor\", \"--json\"]"));
        assert!(probe.contains("report.get(\"ok\") is not True"));
        assert!(installer.contains("emit_process_family_receipt silent"));
        assert!(installer.contains("activation-transaction-in-progress"));
        assert!(installer.contains("src_dir_fd=parent_descriptor"));
        assert!(installer.contains("dst_dir_fd=parent_descriptor"));
        assert!(
            installer.contains("published process-family receipt differs from its pinned stage")
        );
        assert!(installer.contains("activation recovery receipt changed while being read"));
        assert!(installer.contains("python3 - \"${SYSTEM_INSTALL:-0}\""));
        assert!(installer.contains("if not all_users and process.stat().st_uid"));
        assert!(installer.contains("ps_command.append(\"-A\")"));
        assert!(
            installer
                .contains("Running pending candidate \\`ft doctor --json\\` by immutable path")
        );
        assert!(installer.contains(
            "Published process-family self-test failed; installation verification did not pass"
        ));
        assert!(installer.contains("json.loads(payload)"));
        assert!(!installer.contains("non-zero exit is OK on first install"));
        assert!(
            !installer
                .contains("Skipping candidate self-test because the candidate is not activated")
        );
        assert!(!installer.contains("sort -u"));
        assert!(installer.contains("GUARDIAN_BIN=\"$PACKAGE_ROOT/frankenterm-pty-guardian\""));
        assert!(installer.contains("-name \"frankenterm-pty-guardian\" -perm -111"));
        assert!(
            installer.contains("install_process_family \"$BIN\" \"$MUX_BIN\" \"$GUARDIAN_BIN\"")
        );
        let offline_verification = installer
            .find("Verifying atomic CLI/mux-server/PTY-guardian build identity")
            .expect("offline archive triplet verification");
        let offline_install = installer
            .find("install_process_family \"$BIN\" \"$MUX_BIN\" \"$GUARDIAN_BIN\"")
            .expect("offline archive triplet installation");
        assert!(offline_verification < offline_install);
        assert!(installer.contains("--no-verify) NO_MINISIGN=1; shift ;;"));
        let minisign_gate = installer
            .find("require_release_minisign || exit 1")
            .expect("mandatory release minisign preflight");
        let release_transfer = installer
            .find("# Download / source build")
            .expect("release artifact transfer section");
        assert!(minisign_gate < release_transfer);
        assert!(installer.contains(
            "DSR release verification is mandatory before any release artifact download."
        ));
        let dsr_minisign_public_key = include_str!("../../../release/minisign.pub");
        let dsr_minisign_public_key = dsr_minisign_public_key
            .lines()
            .nth(1)
            .expect("DSR minisign public key payload");
        assert!(installer.contains(dsr_minisign_public_key));
        assert!(installer.contains("verify_minisign_signature"));
        assert!(installer.contains("offline_minisign=\"${OFFLINE_TARBALL}.minisig\""));
        assert!(installer.contains("\"$VERIFIED_ARCHIVE_IDENTITY\" \"\" \"$offline_minisign\""));
        assert!(!installer.contains("SIGSTORE_BUNDLE_URL"));
        assert!(!installer.contains("NO_CHECKSUM"));
        assert!(installer.contains(
            "Existing ft path detected; it will not be executed before authenticated family verification"
        ));
        assert!(!installer.contains("current=$(\"$DEST/ft\" --version"));
        assert!(!installer.contains("RESOLVED_VERSION=$(\"$DEST/ft\" --version"));
        assert!(installer.contains("RESOLVED_VERSION=\"ft $PUBLISHED_PROCESS_FAMILY_VERSION\""));
        assert!(
            installer.contains("ensure_exact_staged_file \"$OFFLINE_TARBALL\" \"$TMP/$TAR\" 0400")
        );
        assert!(!installer.contains("cp \"$OFFLINE_TARBALL\" \"$TMP/$TAR\""));

        let prebuilt_start = installer
            .find("# The archive-provided verifier is executable code")
            .expect("externally authenticated prebuilt install path");
        let prebuilt_end = installer[prebuilt_start..]
            .find("\n  BIN=\"$PACKAGE_ROOT/ft\"")
            .map(|offset| prebuilt_start + offset)
            .expect("prebuilt component-verification boundary");
        let prebuilt = &installer[prebuilt_start..prebuilt_end];
        let checksum_authority = prebuilt
            .find("verify_archive_checksum_authority \"$TMP/$TAR\" \"$TAR\"")
            .expect("mandatory external SHA-256 authority");
        assert!(installer.contains("--proto '=https' --proto-redir '=https'"));
        assert!(installer.contains("--max-filesize \"$max_bytes\" --max-time \"$max_time\""));
        let streaming_extraction = prebuilt
            .find("extract_authenticated_archive \"$TMP/$TAR\" \"$PACKAGE_ROOT\" process-family")
            .expect("bounded authenticated archive extraction");
        let component_verification = prebuilt
            .find("bash \"$COMPONENT_VERIFIER\" verify")
            .expect("post-extraction component verification");
        assert!(checksum_authority < streaming_extraction);
        assert!(streaming_extraction < component_verification);
        assert!(!prebuilt.contains("tar -x"));
        assert!(!prebuilt.contains("tar xf"));
        assert!(!prebuilt.contains("tar xJf"));

        let extractor_start = installer
            .find("extract_authenticated_archive() {")
            .expect("authenticated extractor function");
        let extractor_end = installer[extractor_start..]
            .find("\n}\n\nverify_minisign_signature()")
            .map(|offset| extractor_start + offset)
            .expect("authenticated extractor function end");
        let extractor = &installer[extractor_start..extractor_end];
        assert_eq!(
            extractor.matches("fileobj=raw, mode=\"r|\"").count(),
            2,
            "archive inventory and extraction must use two bounded streaming passes"
        );
        assert_eq!(extractor.matches("for member in archive:").count(), 2);
        assert!(extractor.contains("archive_identity != expected_values"));
        assert!(
            extractor.contains("archive pathname no longer names the checksum-authenticated inode")
        );
        assert!(extractor.contains("archive_before.st_size > max_archive_bytes"));
        assert!(extractor.contains("first[\"expanded_bytes\"] + free_space_headroom"));
        assert!(extractor.contains("archive contains a forbidden AppleDouble member"));
        assert!(!extractor.contains("getmembers("));
        assert!(!extractor.contains("extractall("));

        let checksum_start = installer
            .find("verify_checksum() {")
            .expect("descriptor-pinned checksum function");
        let checksum_end = installer[checksum_start..]
            .find("\n}\n\nread_sha256_sidecar()")
            .map(|offset| checksum_start + offset)
            .expect("descriptor-pinned checksum function end");
        let checksum = &installer[checksum_start..checksum_end];
        assert!(checksum.contains("fd = os.open(path, flags)"));
        assert!(checksum.contains("VERIFIED_ARCHIVE_IDENTITY=\"$identity\""));
        assert!(!checksum.contains("sha256sum"));
        assert!(!checksum.contains("shasum"));

        let bundle_script = include_str!("../../../scripts/create-macos-bundle.sh");
        for copy in [
            "cp \"$GUI_BINARY\" \"$APP_BUNDLE/Contents/MacOS/frankenterm-gui\"",
            "cp \"$MUX_SERVER_BINARY\" \"$APP_BUNDLE/Contents/MacOS/frankenterm-mux-server\"",
            "cp \"$GUARDIAN_BINARY\" \"$APP_BUNDLE/Contents/MacOS/frankenterm-pty-guardian\"",
            "cp \"$FT_BINARY\" \"$APP_BUNDLE/Contents/MacOS/ft\"",
        ] {
            assert!(
                bundle_script.contains(copy),
                "missing app component copy: {copy}"
            );
        }
        assert!(bundle_script.contains(
            "--entry executable:pty-guardian:Contents/MacOS/frankenterm-pty-guardian:frankenterm-pty-guardian"
        ));
        assert!(bundle_script.contains(
            "--entry verifier:native-readiness-harness:Contents/Resources/e2e-native-events.sh"
        ));
        assert!(bundle_script.contains(
            "--source-match Contents/Resources/e2e-native-events.sh=scripts/e2e_native_events.sh"
        ));
        assert!(
            bundle_script.contains(
                "browser runtime source and app destination must not contain one another"
            )
        );

        let app_start = installer
            .find("install_macos_app() {")
            .expect("macOS app installer");
        let app = &installer[app_start..];
        assert!(app.contains("FrankenTerm.app.component-manifest.json"));
        assert!(app.contains("process_family_manifest_metadata \"$app_manifest\" app"));
        assert!(app.contains("$app_build\" = \"$family_build"));
        assert!(
            app.contains("application-family-gui-ft-mux-server-pty-guardian-default-features-v1")
        );
        assert!(app.contains("before-app-selector-switch"));
        assert!(app.contains("after-app-selector-switch"));
        let readiness = app
            .find("Running non-activating native readiness proof")
            .expect("pre-switch native readiness proof");
        let selector_switch = app
            .find("installer_failpoint before-app-selector-switch")
            .expect("app selector switch boundary");
        assert!(readiness < selector_switch);
        assert!(app.contains("FRANKENTERM_ATOMIC_MANIFEST_TOOL=\"$staged_verifier\""));
        assert!(app.contains(
            "FRANKENTERM_MUX_SERVER=\"$staged_app/Contents/MacOS/frankenterm-mux-server\""
        ));
        assert!(app.contains(
            "FRANKENTERM_PTY_GUARDIAN=\"$staged_app/Contents/MacOS/frankenterm-pty-guardian\""
        ));
        assert!(
            app.contains("Post-switch app verification failed; restoring the prior app authority")
        );
        assert!(app.contains("app-rollback:$dest:$app_id"));
        assert!(app.contains("app-first-publish-rollback:$dest:$app_id"));
        assert!(
            app.contains("Candidate app retained for diagnosis; prior app authority was restored")
        );
        assert!(app.contains("$operation\" || return 0"));
        assert!(!app.contains("move_no_clobber \"$target_app\""));
        assert!(app.contains("dest=\"/Applications\""));
        assert!(app.contains("dest=\"$HOME/Applications\""));
        assert!(app.contains("s.st_uid == os.geteuid() and not (s.st_mode & 0o022)"));
        assert!(app.contains("App destination cannot provide descriptor-pinned atomic authority"));
        assert!(app.contains("ensure_exact_staged_tree \"$extracted_app\" \"$staged_app\""));
        assert!(!app.contains("ditto \"$extracted_app\" \"$staged_app\""));

        let native_readiness = include_str!("../../../scripts/e2e_native_events.sh");
        for role in [
            "FRANKENTERM_CLI",
            "FRANKENTERM_GUI",
            "FRANKENTERM_MUX_SERVER",
            "FRANKENTERM_PTY_GUARDIAN",
        ] {
            assert!(
                native_readiness.contains(role),
                "native readiness omitted the {role} identity"
            );
        }
        assert!(native_readiness.contains("bounded_version_probe \"$FT_MUX_SERVER\""));
        assert!(native_readiness.contains("bounded_version_probe \"$FT_PTY_GUARDIAN\""));
        assert!(native_readiness.contains("private_mux_socket_absent_after_execution"));
        assert!(native_readiness.contains("frankenterm-mux-server--version"));
        assert!(native_readiness.contains("frankenterm-pty-guardian--version"));
        assert!(installer.contains("FT_INSTALL_APP_RECEIPT_V2="));
        assert!(installer.contains("frankenterm.install.app-receipt.v2"));
        assert!(installer.contains("cross_launcher_lifecycle_unproven"));
        assert!(installer.contains("app_isolated_launch_action"));

        let source_build_start = installer
            .find("build_from_source() {")
            .expect("source-build function start");
        let source_build_end = installer[source_build_start..]
            .find("\n}\n\n# Test subprocesses source the exact production functions")
            .map(|relative| source_build_start + relative)
            .expect("source-build function end");
        let source_build = &installer[source_build_start..source_build_end];
        assert!(source_build.contains("scripts/atomic-component-manifest.sh"));
        assert!(source_build.contains(
            "feature_contract=\"process-family-ft-mux-server-pty-guardian-default-features-v1\""
        ));
        assert!(source_build.contains("${VERSION#v}"));
        assert!(source_build.contains("rustc -vV"));
        assert!(source_build.contains("derive-build-id"));
        assert!(source_build.contains("FT_ATOMIC_BUILD_IDENTITY=\"$build_id\""));
        assert!(source_build.contains("FT_ATOMIC_BUILD_PROFILE=\"$build_profile\""));
        assert!(source_build.contains(
            "cargo build --locked --profile \"$build_profile\" --target \"$build_target\""
        ));
        assert!(source_build.contains("--entry executable:cli:ft:ft"));
        assert!(source_build.contains(
            "--entry executable:mux-server:frankenterm-mux-server:frankenterm-mux-server"
        ));
        assert!(source_build.contains(
            "--entry executable:pty-guardian:frankenterm-pty-guardian:frankenterm-pty-guardian"
        ));
        assert!(
            source_build
                .contains("--input font.payload=crates/frankenterm/assets/Pragmasevka_NF.zip.zst")
        );
        assert!(
            source_build.contains("-p frankenterm-pty-guardian --bin frankenterm-pty-guardian")
        );
        assert!(!source_build.contains("install_process_family \"$bin\" \"$mux_bin\""));
        let identity_derivation = source_build
            .find("derive-build-id")
            .expect("canonical build identity derivation");
        let cargo_build = source_build
            .find("cargo build --locked")
            .expect("sealed process-family Cargo build");
        let manifest_generation = source_build
            .find("bash \"$atomic_tool\" generate")
            .expect("source-family manifest generation");
        let manifest_verification = source_build
            .find("bash \"$atomic_tool\" verify")
            .expect("source-family manifest verification");
        let family_install = source_build
            .find(
                "install_process_family \\\n    \"$proof_root/ft\" \\\n    \"$proof_root/frankenterm-mux-server\" \\\n    \"$proof_root/frankenterm-pty-guardian\"",
            )
            .expect("verified process-family installation");
        assert!(identity_derivation < cargo_build);
        assert!(cargo_build < manifest_generation);
        assert!(manifest_generation < manifest_verification);
        assert!(manifest_verification < family_install);
    }

    #[cfg(unix)]
    #[test]
    fn installer_verify_to_extract_path_replacement_cannot_swap_authenticated_bytes() {
        use sha2::Digest as _;
        use std::os::unix::fs::PermissionsExt as _;

        let fixture = InstallerTestDir::new("create archive replacement fixture");
        let installer = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../install.sh");
        let archive = fixture.path().join("authenticated.tar");
        let replacement = fixture.path().join("replacement.tar");
        let retained = fixture.path().join("authenticated-original.tar");
        let extraction_root = fixture.path().join("extract");
        std::fs::write(&archive, b"checksum-authenticated archive inode")
            .expect("write authenticated archive fixture");
        std::fs::write(&replacement, b"different replacement pathname bytes")
            .expect("write archive replacement fixture");
        std::fs::create_dir(&extraction_root).expect("create private extraction root");
        std::fs::set_permissions(&extraction_root, std::fs::Permissions::from_mode(0o700))
            .expect("make extraction root private");
        let checksum = hex::encode(sha2::Sha256::digest(
            std::fs::read(&archive).expect("read authenticated archive fixture"),
        ));
        let script = format!(
            r#"set -euo pipefail
export FT_INSTALL_TEST_LIBRARY_ONLY=1
source {}
QUIET=1
HAS_GUM=0
verify_checksum {} {}
python3 - {} {} {} <<'PY'
import os
import shutil
import sys

archive, replacement, retained = sys.argv[1:]
os.rename(archive, retained)
shutil.copyfile(replacement, archive)
PY
if extract_authenticated_archive {} {} app FrankenTerm.app.component-manifest.json "$VERIFIED_ARCHIVE_IDENTITY"; then
  exit 91
fi
"#,
            shell_single_quote(&installer.to_string_lossy()),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&checksum),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&replacement.to_string_lossy()),
            shell_single_quote(&retained.to_string_lossy()),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&extraction_root.to_string_lossy()),
        );
        let output = std::process::Command::new("bash")
            .arg("-c")
            .arg(script)
            .output()
            .expect("execute verify-to-extract replacement proof");
        assert!(
            output.status.success(),
            "authenticated pathname replacement was not rejected: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(
            String::from_utf8_lossy(&output.stderr)
                .contains("archive pathname no longer names the checksum-authenticated inode")
        );
        assert_eq!(
            std::fs::read_dir(&extraction_root)
                .expect("inspect rejected extraction root")
                .count(),
            0
        );
    }

    #[cfg(unix)]
    #[test]
    fn installer_authenticated_extractor_rejects_adversarial_archive_names_and_links() {
        use std::os::unix::fs::PermissionsExt as _;

        let fixture = InstallerTestDir::new("create adversarial extractor fixture");
        let installer = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../install.sh");
        for (index, (case_name, expected_error)) in [
            ("traversal", "archive contains an unsafe member name"),
            (
                "appledouble",
                "archive contains a forbidden AppleDouble member",
            ),
            (
                "symlink-ancestor",
                "archive member descends through a non-directory member",
            ),
            (
                "hardlink",
                "archive contains a hard link, sparse file, or special file",
            ),
            ("duplicate", "archive contains a duplicate member name"),
            ("absolute-symlink", "archive contains an absolute symlink"),
            (
                "oversized-pax",
                "tar PAX extension header exceeds its per-member bound",
            ),
            (
                "oversized-gnu-longname",
                "tar GNU long-name extension header exceeds its per-member bound",
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let archive = fixture.path().join(format!("{index}-{case_name}.tar"));
            let extraction_root = fixture.path().join(format!("extract-{index}"));
            create_adversarial_installer_archive(&archive, case_name);
            std::fs::create_dir(&extraction_root).expect("create adversarial extraction root");
            std::fs::set_permissions(&extraction_root, std::fs::Permissions::from_mode(0o700))
                .expect("make adversarial extraction root private");
            let output =
                run_authenticated_installer_extractor(&installer, &archive, &extraction_root);
            assert!(
                !output.status.success(),
                "{case_name} archive unexpectedly passed the production extractor"
            );
            assert!(
                String::from_utf8_lossy(&output.stderr).contains(expected_error),
                "{case_name} rejection did not report {expected_error:?}: {}",
                String::from_utf8_lossy(&output.stderr)
            );
            assert_eq!(
                std::fs::read_dir(&extraction_root)
                    .expect("inspect adversarial extraction root")
                    .count(),
                0,
                "{case_name} archive wrote bytes before rejection"
            );
            assert!(
                !fixture.path().join("escaped").exists(),
                "traversal archive escaped its extraction root"
            );
        }
    }

