    #[cfg(unix)]
    #[test]
    fn installer_minisign_verifies_pinned_descriptors_and_fails_closed_on_path_replacement() {
        use sha2::Digest as _;
        use std::os::unix::fs::PermissionsExt as _;

        let fixture = InstallerTestDir::new("create minisign descriptor-race fixture");
        let installer = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../install.sh");
        let fake_tools = fixture.path().join("tools");
        std::fs::create_dir(&fake_tools).expect("create minisign fake tools");
        let fake_curl = fake_tools.join("curl");
        std::fs::write(
            &fake_curl,
            r#"#!/bin/sh
set -eu
if test "${1:-}" = --help; then
  printf '%s\n' '     --max-filesize <bytes>  Maximum file size to download'
  exit 0
fi
printf '%s' 'signed bundle bytes'
"#,
        )
        .expect("write minisign fake curl");
        std::fs::set_permissions(&fake_curl, std::fs::Permissions::from_mode(0o555))
            .expect("make minisign fake curl executable");
        let fake_minisign = fake_tools.join("minisign");
        std::fs::write(
            &fake_minisign,
            r#"#!/bin/sh
set -eu
signature_descriptor=""
archive_descriptor=""
while test "$#" -gt 0; do
  case "$1" in
    -Vm)
      shift
      archive_descriptor=$1
      ;;
    -x)
      shift
      signature_descriptor=$1
      ;;
    -P) shift ;;
  esac
  shift
done
case "$archive_descriptor" in /dev/fd/[0-9]*) ;; *) exit 71 ;; esac
case "$signature_descriptor" in /dev/fd/[0-9]*) ;; *) exit 72 ;; esac
mv "$ATTACK_ARCHIVE" "$RETAINED_ARCHIVE"
cp "$ARCHIVE_REPLACEMENT" "$ATTACK_ARCHIVE"
mv "$ATTACK_SIGNATURE" "$RETAINED_SIGNATURE"
printf '%s' 'replacement signature bytes' > "$ATTACK_SIGNATURE"
cp "$archive_descriptor" "$ARCHIVE_CAPTURE"
cp "$signature_descriptor" "$SIGNATURE_CAPTURE"
cmp "$ARCHIVE_CAPTURE" "$RETAINED_ARCHIVE"
! cmp "$ARCHIVE_CAPTURE" "$ATTACK_ARCHIVE"
cmp "$SIGNATURE_CAPTURE" "$RETAINED_SIGNATURE"
! cmp "$SIGNATURE_CAPTURE" "$ATTACK_SIGNATURE"
printf x > "$MINISIGN_MARKER"
"#,
        )
        .expect("write descriptor-aware fake minisign");
        std::fs::set_permissions(&fake_minisign, std::fs::Permissions::from_mode(0o555))
            .expect("make descriptor-aware fake minisign executable");

        let scratch = fixture.path().join("scratch");
        std::fs::create_dir(&scratch).expect("create minisign scratch directory");
        std::fs::set_permissions(&scratch, std::fs::Permissions::from_mode(0o700))
            .expect("make minisign scratch private");
        let archive = fixture.path().join("archive");
        let archive_replacement = fixture.path().join("archive-replacement");
        let retained_archive = fixture.path().join("archive-authenticated");
        let archive_capture = fixture.path().join("archive-minisign-capture");
        let authenticated_bytes = b"checksum-authenticated bytes\n";
        std::fs::write(&archive, authenticated_bytes).expect("write minisign archive fixture");
        std::fs::write(&archive_replacement, b"swapped archive bytes\n")
            .expect("write minisign archive replacement");
        let checksum = hex::encode(sha2::Sha256::digest(authenticated_bytes));
        let signature = scratch.join("archive.minisig");
        let retained_signature = fixture.path().join("signature-authenticated");
        let signature_capture = fixture.path().join("signature-minisign-capture");
        let minisign_marker = fixture.path().join("minisign-invoked");
        let script = format!(
            "set -euo pipefail\nexport FT_INSTALL_TEST_LIBRARY_ONLY=1\nsource {}\nQUIET=1\nHAS_GUM=0\nTMP={}\nINSTALLER_FREE_SPACE_HEADROOM_BYTES=0\nverify_checksum {} {}\nif verify_minisign_signature {} https://example.invalid/archive; then\n  exit 91\nfi\n",
            shell_single_quote(&installer.to_string_lossy()),
            shell_single_quote(&scratch.to_string_lossy()),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&checksum),
            shell_single_quote(&archive.to_string_lossy()),
        );
        let inherited_path = std::env::var("PATH").expect("test PATH");
        let output = std::process::Command::new("bash")
            .arg("-c")
            .arg(script)
            .env("PATH", format!("{}:{inherited_path}", fake_tools.display()))
            .env("ATTACK_ARCHIVE", &archive)
            .env("ARCHIVE_REPLACEMENT", &archive_replacement)
            .env("RETAINED_ARCHIVE", &retained_archive)
            .env("ARCHIVE_CAPTURE", &archive_capture)
            .env("ATTACK_SIGNATURE", &signature)
            .env("RETAINED_SIGNATURE", &retained_signature)
            .env("SIGNATURE_CAPTURE", &signature_capture)
            .env("MINISIGN_MARKER", &minisign_marker)
            .output()
            .expect("execute minisign descriptor-race proof");
        assert!(
            output.status.success(),
            "minisign pathname replacement was not rejected: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(minisign_marker.is_file(), "fake minisign did not run");
        assert_eq!(
            std::fs::read(&archive_capture).expect("read minisign archive capture"),
            authenticated_bytes
        );
        assert_eq!(
            std::fs::read(&signature_capture).expect("read minisign signature capture"),
            b"signed bundle bytes"
        );
        assert_eq!(
            std::fs::read(&archive).expect("read swapped archive pathname"),
            b"swapped archive bytes\n"
        );
        assert_eq!(
            std::fs::read(&signature).expect("read swapped signature pathname"),
            b"replacement signature bytes"
        );
        assert!(
            String::from_utf8_lossy(&output.stderr)
                .contains("checksum-authenticated archive changed during minisign verification")
        );
    }

    #[cfg(unix)]
    #[test]
    fn installer_minisign_child_is_killed_at_its_finite_wall_clock_bound() {
        use sha2::Digest as _;
        use std::os::unix::fs::PermissionsExt as _;

        let fixture = InstallerTestDir::new("create minisign timeout fixture");
        let installer = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../install.sh");
        let fake_tools = fixture.path().join("tools");
        std::fs::create_dir(&fake_tools).expect("create minisign timeout fake tools");
        let fake_curl = fake_tools.join("curl");
        std::fs::write(
            &fake_curl,
            b"#!/bin/sh\nset -eu\nif test \"${1:-}\" = --help; then printf '%s\\n' ' --max-filesize <bytes>'; exit 0; fi\nprintf '%s' 'bounded bundle'\n",
        )
        .expect("write timeout fake curl");
        std::fs::set_permissions(&fake_curl, std::fs::Permissions::from_mode(0o555))
            .expect("make timeout fake curl executable");
        let fake_minisign = fake_tools.join("minisign");
        std::fs::write(&fake_minisign, b"#!/bin/sh\nset -eu\nsleep 5\n")
            .expect("write blocking fake minisign");
        std::fs::set_permissions(&fake_minisign, std::fs::Permissions::from_mode(0o555))
            .expect("make blocking fake minisign executable");
        let scratch = fixture.path().join("scratch");
        std::fs::create_dir(&scratch).expect("create minisign timeout scratch");
        std::fs::set_permissions(&scratch, std::fs::Permissions::from_mode(0o700))
            .expect("make minisign timeout scratch private");
        let archive = fixture.path().join("archive");
        let archive_bytes = b"checksum-authenticated timeout fixture\n";
        std::fs::write(&archive, archive_bytes).expect("write timeout archive fixture");
        let checksum = hex::encode(sha2::Sha256::digest(archive_bytes));
        let script = format!(
            "set -euo pipefail\nexport FT_INSTALL_TEST_LIBRARY_ONLY=1\nsource {}\nQUIET=1\nHAS_GUM=0\nTMP={}\nINSTALLER_FREE_SPACE_HEADROOM_BYTES=0\nverify_checksum {} {}\nif verify_minisign_signature {} https://example.invalid/archive; then exit 91; fi\n",
            shell_single_quote(&installer.to_string_lossy()),
            shell_single_quote(&scratch.to_string_lossy()),
            shell_single_quote(&archive.to_string_lossy()),
            shell_single_quote(&checksum),
            shell_single_quote(&archive.to_string_lossy()),
        );
        let inherited_path = std::env::var("PATH").expect("test PATH");
        let output = std::process::Command::new("bash")
            .arg("-c")
            .arg(script)
            .env("PATH", format!("{}:{inherited_path}", fake_tools.display()))
            .env("FT_INSTALL_TEST_ENABLE_RESOURCE_OVERRIDES", "1")
            .env("FT_INSTALL_TEST_MINISIGN_TIMEOUT_SECONDS", "1")
            .output()
            .expect("execute minisign timeout proof");
        assert!(
            output.status.success(),
            "minisign timeout did not fail closed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(
            String::from_utf8_lossy(&output.stderr)
                .contains("minisign verifier exceeded its finite wall-clock bound"),
            "minisign timeout lacked its exact diagnosis: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[cfg(unix)]
    #[test]
    fn installer_failpoint_matrix_retries_without_partial_or_mixed_process_family() {
        use std::os::unix::fs::PermissionsExt as _;
        use std::os::unix::process::ExitStatusExt as _;

        let fixture = InstallerTestDir::new("create installer failpoint matrix fixture");
        let installer = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../install.sh");
        let new_family = create_installer_test_family(
            &fixture.path().join("new-family"),
            &"a".repeat(64),
            "x86_64-unknown-linux-gnu",
            "process-family-ft-mux-server-pty-guardian-default-features-v1",
        );
        let old_family = create_installer_test_family(
            &fixture.path().join("old-family"),
            &"b".repeat(64),
            "x86_64-unknown-linux-gnu",
            "process-family-ft-mux-server-pty-guardian-default-features-v1",
        );

        let initial_failpoints = [
            "after-generation-publish",
            "before-pending-publication-receipt",
        ];
        for (index, failpoint) in initial_failpoints.into_iter().enumerate() {
            let destination = fixture.path().join(format!("initial-{index}-{failpoint}"));
            std::fs::create_dir(&destination).expect("create initial-install destination");
            std::fs::set_permissions(&destination, std::fs::Permissions::from_mode(0o700))
                .expect("make initial-install destination private");
            let interrupted = run_installer_family_function(
                &installer,
                &new_family,
                &destination,
                &fixture.path().join(format!("initial-{index}-interrupted")),
                Some(failpoint),
            );
            assert_eq!(
                interrupted.status.signal(),
                Some(9),
                "failpoint {failpoint} did not kill at its intended boundary: {}",
                String::from_utf8_lossy(&interrupted.stderr)
            );
            let generation = destination
                .join(".frankenterm-process-family/generations")
                .join(&new_family.generation_id);
            for name in ["ft", "frankenterm-mux-server", "frankenterm-pty-guardian"] {
                assert_eq!(
                    std::fs::read(generation.join(name)).expect("read published generation member"),
                    std::fs::read(new_family.root.join(name)).expect("read source family member")
                );
            }
            assert_initial_family_is_uniformly_unavailable(&destination);
            assert!(
                installer_residue_count(&destination) <= 1,
                "{failpoint} leaked an unbounded or forked installer stage"
            );

            for retry in 0..2 {
                let replay = run_installer_family_function(
                    &installer,
                    &new_family,
                    &destination,
                    &fixture
                        .path()
                        .join(format!("initial-{index}-retry-{retry}")),
                    None,
                );
                assert!(
                    replay.status.success(),
                    "initial-install retry after {failpoint} failed: {}",
                    String::from_utf8_lossy(&replay.stderr)
                );
                let receipt = parse_installer_process_family_receipt(&replay.stdout);
                assert_eq!(receipt["activation"], "pending");
                assert_eq!(receipt["active_authority"], "none");
                assert!(receipt["active_root"].is_null());
                assert_eq!(
                    receipt["pending_reason"],
                    "inactive-census-without-shared-launcher-lease"
                );
                assert_eq!(
                    receipt["candidate_generation"],
                    new_family.generation_id.as_str()
                );
                assert_initial_family_is_uniformly_unavailable(&destination);
                assert!(installer_residue_count(&destination) <= 1);
            }
        }

        let legacy_failpoints = [
            "after-generation-publish",
            "after-legacy-recovery-publish",
            "before-pending-publication-receipt",
        ];
        for (index, failpoint) in legacy_failpoints.into_iter().enumerate() {
            let destination = fixture.path().join(format!("legacy-{index}-{failpoint}"));
            std::fs::create_dir(&destination).expect("create legacy-install destination");
            std::fs::set_permissions(&destination, std::fs::Permissions::from_mode(0o700))
                .expect("make legacy-install destination private");
            for name in ["ft", "frankenterm-mux-server", "frankenterm-pty-guardian"] {
                std::fs::copy(old_family.root.join(name), destination.join(name))
                    .expect("plant coherent legacy family member");
                std::fs::set_permissions(
                    destination.join(name),
                    std::fs::Permissions::from_mode(0o555),
                )
                .expect("seal coherent legacy family member");
            }
            let interrupted = run_installer_family_function(
                &installer,
                &new_family,
                &destination,
                &fixture.path().join(format!("legacy-{index}-interrupted")),
                Some(failpoint),
            );
            assert_eq!(
                interrupted.status.signal(),
                Some(9),
                "legacy failpoint {failpoint} did not kill at its intended boundary: {}",
                String::from_utf8_lossy(&interrupted.stderr)
            );
            assert!(
                family_bytes_match(&destination, &old_family),
                "legacy failpoint {failpoint} changed the live process family"
            );
            assert!(installer_residue_count(&destination) <= 4);
            let candidate = destination
                .join(".frankenterm-process-family/generations")
                .join(&new_family.generation_id);
            for name in ["ft", "frankenterm-mux-server", "frankenterm-pty-guardian"] {
                assert_eq!(
                    std::fs::read(candidate.join(name))
                        .expect("read immutable pending candidate member"),
                    std::fs::read(new_family.root.join(name))
                        .expect("read source candidate member")
                );
            }

            for retry in 0..2 {
                let replay = run_installer_family_function(
                    &installer,
                    &new_family,
                    &destination,
                    &fixture.path().join(format!("legacy-{index}-retry-{retry}")),
                    None,
                );
                assert!(
                    replay.status.success(),
                    "legacy retry after {failpoint} failed: {}",
                    String::from_utf8_lossy(&replay.stderr)
                );
                let receipt = parse_installer_process_family_receipt(&replay.stdout);
                assert_eq!(receipt["activation"], "pending");
                assert_eq!(receipt["active_authority"], "legacy-direct");
                assert_eq!(
                    receipt["active_root"],
                    destination.to_string_lossy().as_ref()
                );
                assert_eq!(receipt["pending_reason"], "cross-launcher-lease-required");
                assert!(
                    family_bytes_match(&destination, &old_family),
                    "legacy retry activated a candidate without the cross-launcher transaction"
                );
                assert!(installer_residue_count(&destination) <= 4);
            }
        }
    }

    #[cfg(unix)]
    #[test]
    fn installer_idle_activation_has_one_commit_point_and_recovers_every_crash_prefix() {
        use std::os::unix::fs::PermissionsExt as _;
        use std::os::unix::process::ExitStatusExt as _;

        let fixture = InstallerTestDir::new("create activation crash fixture");
        let installer = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../install.sh");
        let family = create_installer_test_family(
            &fixture.path().join("family"),
            &"c".repeat(64),
            "x86_64-unknown-linux-gnu",
            "process-family-ft-mux-server-pty-guardian-default-features-v1",
        );
        for (index, failpoint) in [
            "after-entrypoint-activation:ft",
            "after-entrypoint-activation:frankenterm-mux-server",
            "after-entrypoint-activation:frankenterm-pty-guardian",
            "after-selector-activation",
        ]
        .into_iter()
        .enumerate()
        {
            let destination = fixture.path().join(format!("initial-{index}"));
            std::fs::create_dir(&destination).expect("create activation destination");
            std::fs::set_permissions(&destination, std::fs::Permissions::from_mode(0o700))
                .expect("make activation destination private");
            let staged = run_installer_family_function(
                &installer,
                &family,
                &destination,
                &fixture.path().join(format!("stage-{index}")),
                None,
            );
            assert!(
                staged.status.success(),
                "candidate staging failed: {}",
                String::from_utf8_lossy(&staged.stderr)
            );

            let interrupted = run_installer_activation_function(
                &installer,
                &family,
                &destination,
                &fixture.path().join(format!("interrupt-{index}")),
                Some(failpoint),
                "inactive",
                false,
            );
            assert_eq!(
                interrupted.status.signal(),
                Some(9),
                "activation failpoint {failpoint} did not kill its shell: {}",
                String::from_utf8_lossy(&interrupted.stderr)
            );
            if failpoint == "after-selector-activation" {
                assert!(
                    family_bytes_match(&destination, &family),
                    "the single selector commit must expose all three candidate members"
                );
            } else {
                assert_initial_family_is_uniformly_unavailable(&destination);
            }
            let interrupted_receipt: serde_json::Value = serde_json::from_slice(
                &std::fs::read(
                    destination.join(".frankenterm-process-family/install-receipt.json"),
                )
                .expect("read interrupted activation receipt"),
            )
            .expect("parse interrupted activation receipt");
            assert_eq!(interrupted_receipt["activation"], "pending");
            assert_eq!(
                interrupted_receipt["pending_reason"],
                "activation-transaction-in-progress"
            );
            assert_eq!(
                interrupted_receipt["verification"]["activation_readiness"],
                "running"
            );

            let recovered = run_installer_activation_function(
                &installer,
                &family,
                &destination,
                &fixture.path().join(format!("recover-{index}")),
                None,
                "inactive",
                false,
            );
            assert!(
                recovered.status.success(),
                "activation recovery after {failpoint} failed: {}",
                String::from_utf8_lossy(&recovered.stderr)
            );
            let receipt = parse_installer_process_family_receipt(&recovered.stdout);
            assert_eq!(receipt["activation"], "current");
            assert_eq!(receipt["active_authority"], "managed-selector");
            assert_eq!(receipt["candidate_generation"], serde_json::Value::Null);
            assert!(family_bytes_match(&destination, &family));
        }
    }

