    #[test]
    fn send_dry_run_report_with_wait_for_has_both_actions() {
        let config = frankenterm_core::config::Config::default();
        let command_ctx = frankenterm_core::dry_run::CommandContext::new(
            "ft robot send 0 \"test\" --wait-for READY",
            true,
        );
        let report = build_send_dry_run_report(
            &command_ctx,
            0,
            None,
            None,
            "test",
            false,
            Some("READY"),
            15,
            &config,
            frankenterm_core::policy::ActorKind::Robot,
        );

        assert!(
            report
                .expected_actions
                .iter()
                .any(|a| a.action_type == frankenterm_core::dry_run::ActionType::SendText)
        );
        assert!(
            report
                .expected_actions
                .iter()
                .any(|a| a.action_type == frankenterm_core::dry_run::ActionType::WaitFor)
        );
        // WaitFor description should contain the pattern and timeout
        let wait_action = report
            .expected_actions
            .iter()
            .find(|a| a.action_type == frankenterm_core::dry_run::ActionType::WaitFor)
            .unwrap();
        assert!(wait_action.description.contains("READY"));
        assert!(wait_action.description.contains("15000"));
    }

