    #[test]
    fn builtin_workflow_infos_return_all_builtin_workflows() {
        let workflows =
            builtin_workflow_infos(&frankenterm_core::config::WorkflowsConfig::default());

        assert_eq!(
            workflows.len(),
            BUILTIN_WORKFLOW_NAMES.len(),
            "must list every built-in workflow"
        );
        let names: Vec<&str> = workflows.iter().map(|w| w.name.as_str()).collect();
        for name in BUILTIN_WORKFLOW_NAMES {
            assert!(
                names.contains(name),
                "workflow list should contain '{name}'"
            );
        }
        let enabled_for = |name: &str| {
            workflows
                .iter()
                .find(|wf| wf.name == name)
                .map(|wf| wf.enabled)
                .unwrap_or(false)
        };
        for name in BUILTIN_WORKFLOW_NAMES {
            assert!(enabled_for(name), "default config should enable '{name}'");
        }

        let triggers_for = |name: &str| {
            workflows
                .iter()
                .find(|wf| wf.name == name)
                .and_then(|wf| wf.trigger_event_types.as_ref())
                .cloned()
                .unwrap_or_default()
        };
        assert_eq!(
            triggers_for("handle_compaction"),
            vec!["session.compaction".to_string()]
        );
        assert_eq!(
            triggers_for("handle_usage_limits"),
            vec![
                "usage.reached".to_string(),
                "rate_limit.detected".to_string(),
                "usage_limit".to_string(),
            ]
        );
        assert_eq!(
            triggers_for("handle_session_end"),
            vec!["session.summary".to_string(), "session.end".to_string()]
        );
        assert_eq!(
            triggers_for("handle_auth_required"),
            vec!["auth.device_code".to_string(), "auth.error".to_string()]
        );
        assert_eq!(
            triggers_for("handle_claude_code_limits"),
            vec![
                "usage.warning".to_string(),
                "usage.reached".to_string(),
                "rate_limit.detected".to_string(),
            ]
        );
        assert_eq!(
            triggers_for("handle_gemini_quota"),
            vec![
                "usage.warning".to_string(),
                "usage.reached".to_string(),
                "rate_limit.detected".to_string(),
            ]
        );
    }

