    #[test]
    fn test_robot_fleet_status_and_error_toon_roundtrip() {
        use frankenterm_core::agent_correlator::{DetectionSource, RunningAgentInventoryEntry};

        let tmp = tempfile::tempdir().expect("tempdir");
        let db_path = tmp.path().join("fleet.sqlite3");
        let db_path = db_path.to_str().expect("utf-8 temp path");
        let mut running_agents = BTreeMap::new();
        running_agents.insert(
            9,
            RunningAgentInventoryEntry {
                slug: "codex".to_string(),
                state: "idle".to_string(),
                session_id: None,
                source: DetectionSource::PaneTitle,
            },
        );

        let status_resp = RobotResponse::success(
            robot_fleet_status_data(db_path, false, Vec::new(), None, running_agents, None),
            11,
        );
        let status_json = serde_json::to_value(&status_resp).expect("fleet status json");
        let status_toon = toon_rust::encode(status_json, None);
        let decoded_status =
            toon_rust::try_decode(&status_toon, None).expect("decode fleet status toon");
        let decoded_status_json =
            toon_rust::cli::json_stringify::json_stringify_lines(&decoded_status, 0).join("\n");
        let status_roundtrip: serde_json::Value =
            serde_json::from_str(&decoded_status_json).expect("fleet status json parse");
        assert_eq!(status_roundtrip["ok"].as_bool(), Some(true));
        assert_eq!(status_roundtrip["data"]["family"], "fleet");
        assert_eq!(status_roundtrip["data"]["action"], "status");
        assert_eq!(
            status_roundtrip["data"]["backend"],
            "native_agent_inventory"
        );
        assert_eq!(
            status_roundtrip["data"]["by_program"]["codex"]["idle"].as_f64(),
            Some(1.0)
        );

        let mut ledger = frankenterm_core::fleet_mutation::FleetMutationLedger::new();
        let mut executor = RobotFleetTestExecutor::default();
        let rebalance_data = robot_fleet_test_rebalance_data(
            "load_based",
            true,
            robot_fleet_test_running_agents(&[(1, "codex", "active"), (2, "codex", "idle")]),
            vec![
                robot_fleet_test_work_row("ft-a", "claimed", Some("codex:1"), 1, &[], 0, None),
                robot_fleet_test_work_row("ft-b", "claimed", Some("codex:1"), 2, &[], 0, None),
            ],
            &mut ledger,
            &mut executor,
        );
        let rebalance_resp = RobotResponse::success(rebalance_data, 12);
        let rebalance_json = serde_json::to_value(&rebalance_resp).expect("fleet rebalance json");
        let rebalance_toon = toon_rust::encode(rebalance_json, None);
        let decoded_rebalance =
            toon_rust::try_decode(&rebalance_toon, None).expect("decode fleet rebalance toon");
        let decoded_rebalance_json =
            toon_rust::cli::json_stringify::json_stringify_lines(&decoded_rebalance, 0).join("\n");
        let rebalance_roundtrip: serde_json::Value =
            serde_json::from_str(&decoded_rebalance_json).expect("fleet rebalance json parse");
        assert_eq!(rebalance_roundtrip["ok"].as_bool(), Some(true));
        assert_eq!(rebalance_roundtrip["data"]["family"], "fleet");
        assert_eq!(rebalance_roundtrip["data"]["action"], "rebalance");
        assert_eq!(rebalance_roundtrip["data"]["receipt"]["status"], "dry_run");
        assert_eq!(
            rebalance_roundtrip["data"]["items_reassigned"].as_f64(),
            Some(1.0)
        );
    }

