    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn agent_config_candidate_cap_rejection_creates_no_backup() {
        let root = unique_temp_dir("agent_config_candidate_cap");
        let workspace_root = root.join("workspace");
        make_test_dir(&workspace_root);
        let target = workspace_root.join("AGENTS.md");
        std::fs::write(&target, b"original instructions\n").unwrap();
        let parent = open_agent_config_parent(&target, false).unwrap().unwrap();
        for sequence in 0..AGENT_CONFIG_MAX_TRANSACTION_FAMILIES {
            let transaction = AgentConfigTransaction::from_id(format!("{sequence:032x}")).unwrap();
            let claim = AgentConfigTransactionClaim {
                schema_version: "ft.agent-config-transaction-claim.v1".to_string(),
                transaction_id: transaction.id.clone(),
                parent_device: parent.identity.device,
                parent_inode: parent.identity.inode,
                target_leaf: format!("unrelated-{sequence}"),
                action: "create".to_string(),
                before: None,
                candidate_leaf: transaction.candidate_leaf.display().to_string(),
                candidate_sha256: agent_config_sha256(b""),
                backup_leaf: None,
                backup_sha256: None,
                requested_final_metadata: AgentConfigSecuritySnapshot {
                    uid: nix::unistd::geteuid().as_raw(),
                    gid: nix::unistd::getegid().as_raw(),
                    mode: 0o600,
                },
                durability_contract:
                    "candidate_and_backup_fdatasync_plus_fsync;macos_regular_files_f_fullfsync;namespace_and_journal_parent_fsync"
                        .to_string(),
            };
            let claim_name =
                agent_config_leaf_string(&transaction.claim_leaf, "claim leaf").unwrap();
            write_atomic_path_transition_json(&parent.directory, &parent.file, &claim_name, &claim)
                .unwrap();
        }
        let backups_before = std::fs::read_dir(&workspace_root)
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| {
                entry
                    .file_name()
                    .to_str()
                    .is_some_and(|name| name.ends_with(AGENT_CONFIG_BACKUP_SUFFIX))
            })
            .count();
        let entry = frankenterm_core::agent_correlator::InstalledAgentInventoryEntry {
            slug: "codex".to_string(),
            detected: true,
            evidence: vec![],
            root_paths: vec![root.join(".codex").display().to_string()],
            config_path: None,
            binary_path: None,
            version: None,
        };
        let prepared =
            prepare_agent_config(&entry, RobotAgentConfigScope::Project, &workspace_root).unwrap();

        let error = apply_prepared_agent_config(&prepared)
            .expect_err("full retained-candidate inventory must reject publication");
        assert!(!error.backup_created);
        assert!(error.message.contains("bounded retention limit"));
        assert_eq!(std::fs::read(&target).unwrap(), b"original instructions\n");
        let backups = std::fs::read_dir(&workspace_root)
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| {
                entry
                    .file_name()
                    .to_str()
                    .is_some_and(|name| name.ends_with(AGENT_CONFIG_BACKUP_SUFFIX))
            })
            .count();
        assert_eq!(
            backups, backups_before,
            "capacity rejection must not create a backup"
        );
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn agent_config_unacknowledged_pre_effect_crash_windows_are_no_effect() {
        let create_root = unique_temp_dir("agent_config_create_no_effect_recovery");
        let create_target = create_root.join("AGENTS.md");
        let create_parent = open_agent_config_parent(&create_target, false)
            .unwrap()
            .unwrap();
        let create_transaction = AgentConfigTransaction::new();
        let requested = AgentConfigSecuritySnapshot {
            uid: nix::unistd::geteuid().as_raw(),
            gid: nix::unistd::getegid().as_raw(),
            mode: 0o600,
        };
        let create_claim = build_agent_config_transaction_claim(
            &create_parent,
            &create_target,
            frankenterm_core::agent_config_templates::ConfigAction::Create,
            None,
            b"complete candidate\n",
            requested,
            &create_transaction,
        )
        .unwrap();
        assert_eq!(
            classify_unacknowledged_agent_config_transaction(
                &create_parent,
                &create_target,
                &create_transaction,
                &create_claim,
            )
            .unwrap(),
            AgentConfigTransactionOutcome::NoEffect
        );
        let mut create_candidate =
            create_agent_config_candidate(&create_parent, None, &create_transaction).unwrap();
        create_candidate.file.write_all(b"partial").unwrap();
        assert_eq!(
            classify_unacknowledged_agent_config_transaction(
                &create_parent,
                &create_target,
                &create_transaction,
                &create_claim,
            )
            .unwrap(),
            AgentConfigTransactionOutcome::NoEffect,
            "a private partial candidate cannot imply a target effect"
        );

        let update_root = unique_temp_dir("agent_config_update_no_effect_recovery");
        let update_target = update_root.join("AGENTS.md");
        std::fs::write(&update_target, b"original\n").unwrap();
        let update_parent = open_agent_config_parent(&update_target, false)
            .unwrap()
            .unwrap();
        let update_source = read_open_agent_config_file(
            &update_parent,
            &update_target,
            AgentConfigOpenIntent::Update,
        )
        .unwrap()
        .unwrap();
        let update_security = update_source.security.unwrap();
        let update_transaction = AgentConfigTransaction::new();
        let update_claim = build_agent_config_transaction_claim(
            &update_parent,
            &update_target,
            frankenterm_core::agent_config_templates::ConfigAction::Append,
            Some(&update_source),
            b"complete replacement\n",
            update_security,
            &update_transaction,
        )
        .unwrap();
        let mut update_candidate = create_agent_config_candidate(
            &update_parent,
            Some(update_security),
            &update_transaction,
        )
        .unwrap();
        update_candidate.file.write_all(b"partial").unwrap();
        create_agent_config_backup(
            &update_parent,
            &update_target,
            &update_source,
            &update_transaction,
        )
        .unwrap();
        assert_eq!(
            classify_unacknowledged_agent_config_transaction(
                &update_parent,
                &update_target,
                &update_transaction,
                &update_claim,
            )
            .unwrap(),
            AgentConfigTransactionOutcome::NoEffect,
            "an unchanged target plus safe staged artifacts is retryable no-effect state"
        );
    }

