    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn agent_config_ack_self_sync_milestones_are_promoted_only_after_recovery() {
        let root = unique_temp_dir("agent_config_ack_self_sync");
        let target = root.join("AGENTS.md");
        let parent = open_agent_config_parent(&target, false).unwrap().unwrap();
        let transaction = AgentConfigTransaction::new();
        let claim = build_agent_config_transaction_claim(
            &parent,
            &target,
            frankenterm_core::agent_config_templates::ConfigAction::Create,
            None,
            b"candidate\n",
            AgentConfigSecuritySnapshot {
                uid: nix::unistd::geteuid().as_raw(),
                gid: nix::unistd::getegid().as_raw(),
                mode: 0o600,
            },
            &transaction,
        )
        .unwrap();
        let claim_name = agent_config_leaf_string(&transaction.claim_leaf, "claim leaf").unwrap();
        let claim_bytes =
            write_atomic_path_transition_json(&parent.directory, &parent.file, &claim_name, &claim)
                .unwrap();
        let claim_sha256 = agent_config_sha256(&claim_bytes)
            .strip_prefix("sha256:")
            .unwrap()
            .to_string();
        let immediate_receipt = write_agent_config_transaction_ack(
            &parent,
            &target,
            &transaction,
            &claim,
            &claim_sha256,
            AgentConfigTransactionOutcome::NoEffect,
            false,
            false,
            false,
        )
        .unwrap();
        assert!(immediate_receipt.ack_file_synced);
        assert!(immediate_receipt.ack_parent_synced);

        let ack_name = agent_config_leaf_string(&transaction.ack_leaf, "ack leaf").unwrap();
        let (persisted_ack, _) = read_atomic_path_transition_json::<AgentConfigTransactionAck>(
            &parent.directory,
            &ack_name,
        )
        .unwrap()
        .unwrap();
        assert!(!persisted_ack.ack_file_synced);
        assert!(!persisted_ack.ack_parent_synced);

        let recovered =
            reconcile_agent_config_transactions_for_target(&parent, &target, false).unwrap();
        assert_eq!(recovered.len(), 1);
        assert_eq!(recovered[0].outcome, "no_effect");
        assert!(recovered[0].ack_file_synced);
        assert!(recovered[0].ack_parent_synced);
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn agent_config_update_intent_and_metadata_validators_fail_closed() {
        use frankensearch_index_acl::fd_acl::ExtendedAclPresence;
        use std::os::fd::AsFd as _;
        use std::os::unix::fs::PermissionsExt as _;

        let root = unique_temp_dir("agent_config_update_descriptor");
        let target = root.join("AGENTS.md");
        std::fs::write(&target, b"existing instructions\n").unwrap();
        std::fs::set_permissions(&target, std::fs::Permissions::from_mode(0o600)).unwrap();
        let parent = open_agent_config_parent(&target, false).unwrap().unwrap();
        let snapshot = read_open_agent_config_file(&parent, &target, AgentConfigOpenIntent::Update)
            .unwrap()
            .unwrap();

        let descriptor_flags = rustix::fs::fcntl_getfl(snapshot.file.as_fd()).unwrap();
        assert_eq!(
            descriptor_flags & rustix::fs::OFlags::RWMODE,
            rustix::fs::OFlags::RDWR,
            "the retained update descriptor must prove read/write authorization"
        );

        let mut foreign_owner = snapshot.observation;
        foreign_owner.uid ^= 1;
        let owner_error = agent_config_security_snapshot_for_uid(
            foreign_owner,
            snapshot.observation.uid,
            &target,
        )
        .expect_err("a foreign owner must fail closed");
        assert!(owner_error.contains("not the effective uid"));

        let source_security = snapshot.security.unwrap();
        let wrong_group = AgentConfigSecuritySnapshot {
            gid: source_security.gid ^ 1,
            mode: 0o600,
            ..source_security
        };
        let group_error =
            validate_fresh_agent_config_security(wrong_group, Some(source_security), &target)
                .expect_err("a fresh artifact with the wrong group must fail closed");
        assert!(group_error.contains("owner/group"));

        let acl_error = validate_agent_config_acl_presence(ExtendedAclPresence::Present, &target)
            .expect_err("an extended ACL must fail closed");
        assert!(acl_error.contains("extended ACL"));

        #[cfg(target_os = "linux")]
        {
            assert!(
                validate_linux_agent_config_flags(
                    rustix::fs::IFlags::from_bits_retain(0x0008_0000),
                    &target,
                )
                .is_ok(),
                "the kernel-managed extents marker is not preservation policy"
            );
            assert!(
                validate_linux_agent_config_flags(rustix::fs::IFlags::NODUMP, &target)
                    .unwrap_err()
                    .contains("inode flags")
            );
        }
        #[cfg(target_os = "macos")]
        assert!(
            validate_macos_agent_config_flags(1, &target)
                .unwrap_err()
                .contains("file flags")
        );
    }

    #[cfg(any(target_os = "linux", target_os = "macos"))]
    #[test]
    fn apply_agent_config_rejects_source_xattrs_before_artifacts() {
        use std::os::fd::AsFd as _;

        let root = unique_temp_dir("agent_config_source_xattr");
        let workspace_root = root.join("workspace");
        let global_root = root.join(".cursor");
        make_test_dir(&workspace_root);
        make_test_dir(&global_root);
        let target = global_root.join(".cursorrules");
        let original = b"# existing cursor rules\n";
        std::fs::write(&target, original).unwrap();
        let source = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .open(&target)
            .unwrap();
        #[cfg(target_os = "linux")]
        let xattr_name = "user.frankenterm-test";
        #[cfg(target_os = "macos")]
        let xattr_name = "com.frankenterm.test";
        rustix::fs::fsetxattr(
            source.as_fd(),
            xattr_name,
            b"present",
            rustix::fs::XattrFlags::CREATE,
        )
        .unwrap();

        let entry = frankenterm_core::agent_correlator::InstalledAgentInventoryEntry {
            slug: "cursor".to_string(),
            detected: true,
            evidence: vec![],
            root_paths: vec![global_root.display().to_string()],
            config_path: None,
            binary_path: None,
            version: None,
        };
        let prepared =
            prepare_agent_config(&entry, RobotAgentConfigScope::Global, &workspace_root).unwrap();
        let error = apply_prepared_agent_config(&prepared)
            .expect_err("source xattrs must be rejected before publication artifacts");

        assert!(!error.backup_created);
        assert!(error.message.contains("extended attributes"));
        assert_eq!(std::fs::read(&target).unwrap(), original);
        let publication_artifacts = std::fs::read_dir(&global_root)
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| {
                let name = entry.file_name();
                let name = name.to_string_lossy();
                name.starts_with(AGENT_CONFIG_TRANSACTION_PREFIX)
            })
            .count();
        assert_eq!(publication_artifacts, 0);
    }

    #[test]
    fn project_scope_agent_config_write_is_idempotent() {
        let root = unique_temp_dir("agent_config_project");
        let workspace_root = root.join("workspace");
        make_test_dir(&workspace_root);
        let entry = frankenterm_core::agent_correlator::InstalledAgentInventoryEntry {
            slug: "codex".to_string(),
            detected: true,
            evidence: vec![],
            root_paths: vec![root.join(".codex").display().to_string()],
            config_path: None,
            binary_path: None,
            version: None,
        };

        let prepared =
            prepare_agent_config(&entry, RobotAgentConfigScope::Project, &workspace_root).unwrap();
        assert_eq!(
            prepared.target_path,
            workspace_root.join("AGENTS.md"),
            "project scope should target workspace root"
        );
        assert_eq!(
            prepared.action,
            frankenterm_core::agent_config_templates::ConfigAction::Create
        );

        let result = apply_prepared_agent_config(&prepared).unwrap();
        assert_eq!(result.action, "create");
        let created = std::fs::read_to_string(workspace_root.join("AGENTS.md")).unwrap();
        assert!(created.contains("frankenterm:start"));

        let prepared_again =
            prepare_agent_config(&entry, RobotAgentConfigScope::Project, &workspace_root).unwrap();
        assert_eq!(
            prepared_again.action,
            frankenterm_core::agent_config_templates::ConfigAction::Skip
        );
        let skipped = apply_prepared_agent_config(&prepared_again).unwrap();
        assert_eq!(skipped.action, "skip");
        assert!(!skipped.backup_created);
    }

    #[test]
    fn global_scope_agent_config_targets_detected_root_and_creates_backup() {
        #[cfg(unix)]
        use std::os::unix::fs::{MetadataExt as _, PermissionsExt as _};

        let root = unique_temp_dir("agent_config_global");
        let workspace_root = root.join("workspace");
        let global_root = root.join(".cursor");
        make_test_dir(&workspace_root);
        make_test_dir(&global_root);
        let target = global_root.join(".cursorrules");
        write_file(&target, "# existing cursor rules\n");
        #[cfg(unix)]
        std::fs::set_permissions(&target, std::fs::Permissions::from_mode(0o640)).unwrap();
        #[cfg(unix)]
        let source_metadata = std::fs::metadata(&target).unwrap();

        let entry = frankenterm_core::agent_correlator::InstalledAgentInventoryEntry {
            slug: "cursor".to_string(),
            detected: true,
            evidence: vec![],
            root_paths: vec![global_root.display().to_string()],
            config_path: None,
            binary_path: None,
            version: None,
        };

        let prepared =
            prepare_agent_config(&entry, RobotAgentConfigScope::Global, &workspace_root).unwrap();
        assert_eq!(prepared.target_path, target);
        assert_eq!(
            prepared.action,
            frankenterm_core::agent_config_templates::ConfigAction::Append
        );

        let result = apply_prepared_agent_config(&prepared).unwrap();
        assert_eq!(result.action, "append");
        assert!(result.backup_created);

        let updated = std::fs::read_to_string(&target).unwrap();
        assert!(updated.contains("existing cursor rules"));
        assert!(updated.contains("FrankenTerm Integration"));

        let prepared_again =
            prepare_agent_config(&entry, RobotAgentConfigScope::Global, &workspace_root).unwrap();
        assert_eq!(
            prepared_again.action,
            frankenterm_core::agent_config_templates::ConfigAction::Skip
        );
        let skipped = apply_prepared_agent_config(&prepared_again).unwrap();
        assert_eq!(skipped.action, "skip");
        assert!(!skipped.backup_created);
        assert_eq!(
            skipped.transactions.len(),
            1,
            "a repeated update must reconcile its retained claim and acknowledgement"
        );
        assert_eq!(skipped.transactions[0].outcome, "applied");

        let backups: Vec<_> = std::fs::read_dir(&global_root)
            .unwrap()
            .filter_map(|entry| entry.ok())
            .map(|entry| entry.path())
            .filter(|path| {
                path.file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| name.ends_with(AGENT_CONFIG_BACKUP_SUFFIX))
            })
            .collect();
        assert_eq!(backups.len(), 1, "expected exactly one backup file");
        #[cfg(unix)]
        for published_path in [&target, &backups[0]] {
            let metadata = std::fs::metadata(published_path).unwrap();
            assert_eq!(metadata.uid(), source_metadata.uid());
            assert_eq!(metadata.gid(), source_metadata.gid());
            assert_eq!(metadata.permissions().mode() & 0o7777, 0o640);
        }
        #[cfg(unix)]
        assert_ne!(
            std::fs::metadata(&backups[0]).unwrap().ino(),
            source_metadata.ino(),
            "the retained backup must be a distinct single-link byte copy"
        );
    }

    // Linux only: `nix::unistd::getgroups` is not provided on macOS, so this
    // test target did not compile there (`cargo test -p frankenterm` on a Mac).
    #[cfg(target_os = "linux")]
    #[test]
    fn global_scope_agent_config_preserves_a_supplementary_source_gid() {
        use std::os::fd::AsFd as _;
        use std::os::unix::fs::MetadataExt as _;

        let effective_gid = nix::unistd::getegid();
        let Some(alternate_gid) = nix::unistd::getgroups()
            .unwrap()
            .into_iter()
            .find(|gid| *gid != effective_gid)
        else {
            return;
        };
        let root = unique_temp_dir("agent_config_supplementary_gid");
        let workspace_root = root.join("workspace");
        let global_root = root.join(".cursor");
        make_test_dir(&workspace_root);
        make_test_dir(&global_root);
        let target = global_root.join(".cursorrules");
        std::fs::write(&target, b"# existing cursor rules\n").unwrap();
        let source = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .open(&target)
            .unwrap();
        rustix::fs::fchown(
            source.as_fd(),
            None,
            Some(rustix::process::Gid::from_raw(alternate_gid.as_raw())),
        )
        .unwrap();
        drop(source);

        let entry = frankenterm_core::agent_correlator::InstalledAgentInventoryEntry {
            slug: "cursor".to_string(),
            detected: true,
            evidence: vec![],
            root_paths: vec![global_root.display().to_string()],
            config_path: None,
            binary_path: None,
            version: None,
        };
        let prepared =
            prepare_agent_config(&entry, RobotAgentConfigScope::Global, &workspace_root).unwrap();
        let result = apply_prepared_agent_config(&prepared).unwrap();
        assert!(result.backup_created);

        let backup = std::fs::read_dir(&global_root)
            .unwrap()
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .find(|path| {
                path.file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| name.ends_with(AGENT_CONFIG_BACKUP_SUFFIX))
            })
            .unwrap();
        assert_eq!(
            std::fs::metadata(&target).unwrap().gid(),
            alternate_gid.as_raw()
        );
        assert_eq!(
            std::fs::metadata(backup).unwrap().gid(),
            alternate_gid.as_raw()
        );
    }

