    #[test]
    fn robot_dom_payload_serializes_json_and_toon_matrix() {
        use frankenterm_core::robot_types::DomQueryKind;
        use frankenterm_core::wezterm::{
            MuxSemanticSnapshot, MuxSemanticZone, MuxSemanticZoneKind,
        };

        let snapshot = MuxSemanticSnapshot {
            zones: vec![
                MuxSemanticZone {
                    start_y: 10,
                    start_x: 0,
                    end_y: 10,
                    end_x: 1,
                    semantic_type: MuxSemanticZoneKind::Prompt,
                    text: "$ ".to_string(),
                },
                MuxSemanticZone {
                    start_y: 10,
                    start_x: 2,
                    end_y: 10,
                    end_x: 12,
                    semantic_type: MuxSemanticZoneKind::Input,
                    text: "cargo check".to_string(),
                },
                MuxSemanticZone {
                    start_y: 11,
                    start_x: 0,
                    end_y: 11,
                    end_x: 4,
                    semantic_type: MuxSemanticZoneKind::Output,
                    text: "done".to_string(),
                },
            ],
            last_exit_code: Some(0),
        };

        let output = build_robot_dom_data(7, DomQueryKind::OutputOf, Some(-1), snapshot.clone());
        assert!(!output.semantic_data_unavailable);
        assert_eq!(output.source, "osc133");
        assert_eq!(output.command.as_ref().unwrap().text, "cargo check");
        assert_eq!(output.output.as_ref().unwrap().text, "done");

        let exit_code = build_robot_dom_data(7, DomQueryKind::ExitCode, Some(-1), snapshot);
        assert_eq!(exit_code.exit_code.as_ref().unwrap().code, 0);

        let response = RobotResponse::success(output, 3);
        let json_value = serde_json::to_value(&response).unwrap();
        assert_eq!(json_value["data"]["source"], "osc133");
        assert_eq!(json_value["data"]["semantic_data_unavailable"], false);
        assert_eq!(json_value["data"]["output"]["text"], "done");

        let toon = toon_rust::encode(json_value.clone(), None);
        let decoded_toon = toon_rust::try_decode(&toon, None).expect("decode robot dom toon");
        let decoded_json =
            toon_rust::cli::json_stringify::json_stringify_lines(&decoded_toon, 0).join("\n");
        let decoded_value: serde_json::Value =
            serde_json::from_str(&decoded_json).expect("toon roundtrip json");
        assert_eq!(decoded_value["data"]["query"], "output_of");
        assert_eq!(decoded_value["data"]["zones"][1]["text"], "cargo check");

        let unavailable = build_robot_dom_data(
            8,
            DomQueryKind::Zones,
            None,
            MuxSemanticSnapshot {
                zones: vec![MuxSemanticZone {
                    start_y: 0,
                    start_x: 0,
                    end_y: 0,
                    end_x: 5,
                    semantic_type: MuxSemanticZoneKind::Output,
                    text: "plain".to_string(),
                }],
                last_exit_code: None,
            },
        );
        assert!(unavailable.semantic_data_unavailable);
        assert_eq!(unavailable.source, "unavailable");
        assert!(unavailable.zones.is_empty());
    }

    #[test]
    fn batch_get_pane_text_returns_requested_panes_with_tail_metadata() {
        run_async_test(async {
            use frankenterm_core::wezterm::{MockWezterm, WeztermHandle};

            let mock = std::sync::Arc::new(MockWezterm::new());
            mock.add_default_pane(7).await;
            mock.add_default_pane(11).await;
            mock.inject_output(7, "alpha\nbeta\ngamma\n")
                .await
                .expect("inject pane 7 text");
            mock.inject_output(11, "one\ntwo\n")
                .await
                .expect("inject pane 11 text");

            let handle: WeztermHandle = mock.clone();
            let results = batch_get_pane_text(handle, &[11, 7], false, 1).await;

            assert_eq!(
                results.keys().copied().collect::<Vec<_>>(),
                vec![7, 11],
                "batch results should contain every requested pane keyed by pane id"
            );

            match results.get(&7).expect("pane 7 result") {
                RobotPaneTextResult::Ok {
                    text,
                    truncated,
                    truncation_info,
                } => {
                    assert_eq!(text, "gamma");
                    assert!(*truncated, "tail=1 should truncate pane 7");
                    let info = truncation_info
                        .as_ref()
                        .expect("pane 7 truncation metadata");
                    assert_eq!(info.original_lines, 3);
                    assert_eq!(info.returned_lines, 1);
                }
                RobotPaneTextResult::Error { .. } => {
                    panic!("pane 7 should have succeeded")
                }
            }

            match results.get(&11).expect("pane 11 result") {
                RobotPaneTextResult::Ok {
                    text,
                    truncated,
                    truncation_info,
                } => {
                    assert_eq!(text, "two");
                    assert!(*truncated, "tail=1 should truncate pane 11");
                    let info = truncation_info
                        .as_ref()
                        .expect("pane 11 truncation metadata");
                    assert_eq!(info.original_lines, 2);
                    assert_eq!(info.returned_lines, 1);
                }
                RobotPaneTextResult::Error { .. } => {
                    panic!("pane 11 should have succeeded")
                }
            }
        });
    }

    #[test]
    fn batch_get_pane_text_isolates_missing_pane_errors() {
        run_async_test(async {
            use frankenterm_core::wezterm::{MockWezterm, WeztermHandle};

            let mock = std::sync::Arc::new(MockWezterm::new());
            mock.add_default_pane(1).await;
            mock.add_default_pane(2).await;
            mock.inject_output(1, "ready pane one\n")
                .await
                .expect("inject pane 1 text");
            mock.inject_output(2, "ready pane two\n")
                .await
                .expect("inject pane 2 text");

            let handle: WeztermHandle = mock.clone();
            let results = batch_get_pane_text(handle, &[1, 999, 2], false, 50).await;

            assert_eq!(
                results.keys().copied().collect::<Vec<_>>(),
                vec![1, 2, 999],
                "one pane failure must not drop neighboring pane results"
            );

            match results.get(&1).expect("pane 1 result") {
                RobotPaneTextResult::Ok { text, .. } => assert_eq!(text, "ready pane one\n"),
                RobotPaneTextResult::Error { .. } => {
                    panic!("pane 1 should have succeeded")
                }
            }

            match results.get(&2).expect("pane 2 result") {
                RobotPaneTextResult::Ok { text, .. } => assert_eq!(text, "ready pane two\n"),
                RobotPaneTextResult::Error { .. } => {
                    panic!("pane 2 should have succeeded")
                }
            }

            match results.get(&999).expect("pane 999 result") {
                RobotPaneTextResult::Error {
                    code,
                    message,
                    hint,
                } => {
                    assert_eq!(code, "robot.pane_not_found");
                    assert!(
                        message.contains("999"),
                        "missing-pane message should mention the failing pane"
                    );
                    assert!(
                        hint.as_deref()
                            .is_some_and(|value| value.contains("Pane 999")),
                        "missing-pane hint should help operators identify the bad selector"
                    );
                }
                RobotPaneTextResult::Ok { .. } => {
                    panic!("pane 999 should have failed")
                }
            }
        });
    }

